var documenterSearchIndex = {"docs":
[{"category":"section","location":"cookbook/11-architectural-patterns/#Recipe-11-—-Architectural-Patterns","page":"Architectural Patterns","text":"Difficulty: Intermediate What you will build: Production project structure with modular commands, middleware, error handling, config management, and database integration.\n\nPrerequisites: Recipe 03, Recipe 04\n\n","title":"Recipe 11 — Architectural Patterns"},{"category":"section","location":"cookbook/11-architectural-patterns/#1.-Production-Project-Structure","page":"Architectural Patterns","text":"tip: Recommended Project Structure\nOrganize your bot into logical modules: commands, handlers, services, and utilities. This makes testing easier and allows multiple developers to work on different features simultaneously. Keep configuration separate from code, and never commit secrets.\n\nMyBot/\n├── Project.toml\n├── Manifest.toml\n├── .env                    # tokens (never commit)\n├── .gitignore\n├── config.toml             # bot configuration\n├── src/\n│   ├── MyBot.jl            # main module\n│   ├── commands/\n│   │   ├── general.jl      # /ping, /help, /info\n│   │   ├── moderation.jl   # /ban, /kick, /warn\n│   │   └── fun.jl          # /poll, /roll, /quote\n│   ├── handlers/\n│   │   ├── messages.jl     # MessageCreate handlers\n│   │   └── members.jl      # GuildMemberAdd/Remove handlers\n│   ├── services/\n│   │   ├── database.jl     # database access layer\n│   │   └── api.jl          # external API clients\n│   └── utils/\n│       ├── config.jl       # config loading\n│       ├── embeds.jl       # embed templates\n│       └── checks.jl       # permission checks\n├── bin/\n│   └── run.jl              # entry point\n└── test/\n    └── runtests.jl","title":"1. Production Project Structure"},{"category":"section","location":"cookbook/11-architectural-patterns/#2.-Main-Module-Pattern","page":"Architectural Patterns","text":"# src/MyBot.jl\nmodule MyBot\n\nusing Accord\nusing Dates\n\n# Configuration\ninclude(\"utils/config.jl\")\n\n# Utilities\ninclude(\"utils/embeds.jl\")\ninclude(\"utils/checks.jl\")\n\n# Services\ninclude(\"services/database.jl\")\n\n# Commands\ninclude(\"commands/general.jl\")\ninclude(\"commands/moderation.jl\")\ninclude(\"commands/fun.jl\")\n\n# Event handlers\ninclude(\"handlers/messages.jl\")\ninclude(\"handlers/members.jl\")\n\n# Bot setup\nfunction create_bot(config)\n    client = Client(config[\"token\"];\n        intents = IntentGuilds | IntentGuildMessages | IntentMessageContent | IntentGuildMembers,\n        user_strategy = CacheLRU(config[\"cache\"][\"max_users\"]),\n    )\n\n    # Register all commands (macros will register them to client.command_tree)\n    register_general_commands!(client, config)\n    register_moderation_commands!(client, config)\n    register_fun_commands!(client, config)\n\n    # Register event handlers\n    register_message_handlers!(client, config)\n    register_member_handlers!(client, config)\n\n    # Sync commands on ready\n    Accord.on(client, [`ReadyEvent`](@ref)) do c, event\n        sync_commands!(c, c.command_tree; guild_id=get(config, \"dev_guild_id\", nothing))\n        @info \"Bot ready!\" user=event.user.username\n    end\n\n    # Note: Client automatically routes interactions to c.command_tree\n\n    return client\nend\n\nend # module","title":"2. Main Module Pattern"},{"category":"section","location":"cookbook/11-architectural-patterns/#3.-Modular-Command-Registration","page":"Architectural Patterns","text":"# src/commands/general.jl\n\nfunction register_general_commands!(client, config)\n\n    @slash_command client \"ping\" \"Check bot latency\" function(ctx)\n        t = time()\n        Accord.defer(ctx)\n        ms = round(Int, (time() - t) * 1000)\n        e = Accord.embed(title=\"Pong!\", description=\"Latency: **$(ms) ms**\", color=0x57F287)\n        Accord.respond(ctx; embeds=[e])\n    end\n\n    @slash_command client \"info\" \"Bot information\" function(ctx)\n        guilds = length(ctx.client.state.guilds)\n        e = Accord.embed(\n            title=\"Bot Info\",\n            color=0x5865F2,\n            fields=[\n                Dict(\"name\" => \"Guilds\", \"value\" => string(guilds), \"inline\" => true),\n                Dict(\"name\" => \"Julia\", \"value\" => string(VERSION), \"inline\" => true),\n                Dict(\"name\" => \"Accord.jl\", \"value\" => string(Accord.ACCORD_VERSION), \"inline\" => true),\n            ]\n        )\n        Accord.respond(ctx; embeds=[e])\n    end\n\nend\n\n# src/commands/moderation.jl\n\nfunction register_moderation_commands!(client, config)\n\n    options = [\n        Accord.command_option(type=ApplicationCommandOptionTypes.USER, name=\"user\", description=\"User to kick\", required=true),\n        Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"reason\", description=\"Reason for kick\"),\n    ]\n\n    # Clean: guards are declared outside the handler\n    @check Accord.has_permissions(:KICK_MEMBERS)\n    @slash_command client \"kick\" \"Kick a member\" options function(ctx)\n        target = Snowflake(Accord.get_option(ctx, \"user\", \"\"))\n        reason = Accord.get_option(ctx, \"reason\", \"No reason\")\n\n        Accord.remove_guild_member(ctx.client, ctx.interaction.guild_id, target;\n            reason=reason)\n\n        Accord.respond(ctx; content=\"Kicked <@$(target)>. Reason: $reason\")\n    end\n\nend","title":"3. Modular Command Registration"},{"category":"section","location":"cookbook/11-architectural-patterns/#4.-Error-Handling","page":"Architectural Patterns","text":"","title":"4. Error Handling"},{"category":"section","location":"cookbook/11-architectural-patterns/#Global-Error-Handler","page":"Architectural Patterns","text":"note: Slow handlers and threads\nEach event's handlers already run in their own task on Julia's default threads, so a slow handler does not block the event loop. Start Julia with -t auto,1 so the gateway and heartbeat get the interactive thread and long computations in handlers can't delay them. Handlers run in parallel: protect state they share with a ReentrantLock or Threads.Atomic.\n\nAccord.on_error(client) do c, event, error\n    # Log the error with full context\n    @error \"Handler error\" event_type=typeof(event) exception=(error, catch_backtrace())\n\n    # Optionally notify a channel\n    ERROR_CHANNEL = [`Snowflake`](@ref)(config[\"error_channel_id\"])\n    try\n        e = Accord.embed(\n            title=\"Bot Error\",\n            description=\"```\\n$(sprint(showerror, error))\\n```\",\n            color=0xED4245,\n            fields=[\n                Dict(\"name\" => \"Event\", \"value\" => string(typeof(event))),\n            ],\n            footer=Dict(\"text\" => string(now())),\n        )\n        create_message(c, ERROR_CHANNEL; embeds=[e])\n    catch\n        # Don't let error reporting errors crash the bot\n    end\nend","title":"Global Error Handler"},{"category":"section","location":"cookbook/11-architectural-patterns/#Per-Handler-Try-Catch","page":"Architectural Patterns","text":"@slash_command client \"risky\" \"A command that might fail\" function(ctx)\n    try\n        result = some_external_api_call()\n        Accord.respond(ctx; content=\"Result: $result\")\n    catch e\n        @error \"Command failed\" exception=e\n        Accord.respond(ctx; content=\"Something went wrong. Please try again later.\", ephemeral=true)\n    end\nend","title":"Per-Handler Try-Catch"},{"category":"section","location":"cookbook/11-architectural-patterns/#Structured-Logging","page":"Architectural Patterns","text":"using Logging\n\n# Set up logging with timestamps\nlogger = ConsoleLogger(stderr, Logging.Info)\nglobal_logger(logger)\n\n# Enable debug logging for Accord\nENV[\"JULIA_DEBUG\"] = \"Accord\"","title":"Structured Logging"},{"category":"section","location":"cookbook/11-architectural-patterns/#5.-Middleware","page":"Architectural Patterns","text":"Middleware runs before every event handler. Return the event to continue, nothing to cancel.\n\n# Logging middleware\nregister_middleware!(client.event_handler) do client, event\n    @debug \"Event received\" type=typeof(event)\n    return event  # pass through\nend\n\n# Ignore list middleware\nconst IGNORED_USERS = Set{[`Snowflake`](@ref)}()\n\nregister_middleware!(client.event_handler) do client, event\n    if event isa [`MessageCreate`](@ref)\n        user_id = ismissing(event.message.author) ? nothing : event.message.author.id\n        if !isnothing(user_id) && user_id in IGNORED_USERS\n            return nothing  # cancel event\n        end\n    end\n    return event\nend\n\n# Rate limiting middleware\nconst user_cooldowns = Dict{[`Snowflake`](@ref), Float64}()\nconst COOLDOWN_SECONDS = 2.0\n\nregister_middleware!(client.event_handler) do client, event\n    if event isa [`InteractionCreate`](@ref)\n        user_id = event.interaction.member.user.id\n        last_use = get(user_cooldowns, user_id, 0.0)\n        if time() - last_use < COOLDOWN_SECONDS\n            return nothing  # too fast, ignore\n        end\n        user_cooldowns[user_id] = time()\n    end\n    return event\nend","title":"5. Middleware"},{"category":"section","location":"cookbook/11-architectural-patterns/#6.-Configuration-with-TOML","page":"Architectural Patterns","text":"# config.toml\n[bot]\nprefix = \"!\"\ndev_guild_id = \"123456789012345678\"\nerror_channel_id = \"987654321098765432\"\n\n[cache]\nmax_users = 50000\nmax_members = 50000\n\n[features]\nenable_logging = true\nenable_moderation = true\nenable_fun = true\n\n# src/utils/config.jl\nimport TOML\n\nfunction load_config(path=\"config.toml\")\n    config = TOML.parsefile(path)\n\n    # Merge with env vars (env takes precedence)\n    config[\"token\"] = ENV[\"DISCORD_TOKEN\"]\n\n    return config\nend","title":"6. Configuration with TOML"},{"category":"section","location":"cookbook/11-architectural-patterns/#7.-Entry-Point","page":"Architectural Patterns","text":"# bin/run.jl\nusing Pkg\nPkg.activate(joinpath(@__DIR__, \"..\"))\n\n# Load .env\nfor line in eachline(\".env\")\n    stripped = strip(line)\n    (isempty(stripped) || startswith(stripped, '#')) && continue\n    key, value = split(stripped, '='; limit=2)\n    ENV[strip(key)] = strip(value)\nend\n\nusing MyBot\n\nconfig = MyBot.load_config()\nclient = MyBot.create_bot(config)\n\n@info \"Starting bot...\"\nAccord.start(client)","title":"7. Entry Point"},{"category":"section","location":"cookbook/11-architectural-patterns/#8.-Database-Integration-Pattern","page":"Architectural Patterns","text":"# src/services/database.jl\nimport SQLite\n\nconst db = Ref{SQLite.DB}()\n\nfunction init_db(path=\"bot.db\")\n    db[] = SQLite.DB(path)\n\n    SQLite.execute(db[], \"\"\"\n        CREATE TABLE IF NOT EXISTS warnings (\n            id INTEGER PRIMARY KEY AUTOINCREMENT,\n            guild_id TEXT NOT NULL,\n            user_id TEXT NOT NULL,\n            moderator_id TEXT NOT NULL,\n            reason TEXT NOT NULL,\n            created_at TEXT NOT NULL\n        )\n    \"\"\")\nend\n\nfunction add_warning(guild_id, user_id, moderator_id, reason)\n    SQLite.execute(db[], \"\"\"\n        INSERT INTO warnings (guild_id, user_id, moderator_id, reason, created_at)\n        VALUES (?, ?, ?, ?, ?)\n    \"\"\", [string(guild_id), string(user_id), string(moderator_id), reason, string(now())])\nend\n\nfunction get_warnings(guild_id, user_id)\n    SQLite.DBInterface.execute(db[], \"\"\"\n        SELECT * FROM warnings WHERE guild_id = ? AND user_id = ? ORDER BY created_at DESC\n    \"\"\", [string(guild_id), string(user_id)]) |> collect\nend","title":"8. Database Integration Pattern"},{"category":"section","location":"cookbook/11-architectural-patterns/#9.-Idiomatic-Julia-Patterns","page":"Architectural Patterns","text":"","title":"9. Idiomatic Julia Patterns"},{"category":"section","location":"cookbook/11-architectural-patterns/#Multiple-Dispatch-for-Event-Routing","page":"Architectural Patterns","text":"# Julia's type system naturally routes events\nfunction handle_event(client, event::[`GuildMemberAdd`](@ref))\n    @info \"Welcome!\" user=event.member.user.username\nend\n\nfunction handle_event(client, event::[`GuildMemberRemove`](@ref))\n    @info \"Goodbye!\" user=event.user.username\nend\n\nfunction handle_event(client, event::[`AbstractEvent`](@ref))\n    # fallback — nothing\nend","title":"Multiple Dispatch for Event Routing"},{"category":"section","location":"cookbook/11-architectural-patterns/#Type-Stable-Option-Extraction","page":"Architectural Patterns","text":"# Annotate types when extracting options\nfunction handle_greet(ctx)\n    name = Accord.get_option(ctx, \"name\", \"World\")::String\n    times = Accord.get_option(ctx, \"times\", 1)::Int\n    Accord.respond(ctx; content=join(fill(\"Hello, $name!\", times), \"\\n\"))\nend","title":"Type-Stable Option Extraction"},{"category":"section","location":"cookbook/11-architectural-patterns/#Avoid-Global-Mutable-State","page":"Architectural Patterns","text":"# ✅ Preferred: inject state via Client's state parameter\nstruct BotState\n    warnings::Dict{[`Snowflake`](@ref), Vector{String}}\n    config::Dict{String, Any}\n    db::Any\nend\n\n# State is accessible from handlers via ctx.state\nbot_state = BotState(Dict(), config, db_conn)\nclient = Client(token; state=bot_state)\n\nfunction register_commands!(client)\n    @slash_command client \"warn\" \"Warn a user\" function(ctx)\n        # ctx.state is the BotState struct — no globals!\n        warns = get!(ctx.state.warnings, ctx.interaction.guild_id, String[])\n        push!(warns, \"warning\")\n        Accord.respond(ctx; content=\"Warning recorded ($(length(warns)) total)\")\n    end\n\n    # Access database cleanly\n    @slash_command client \"stats\" \"Show stats\" function(ctx)\n        count = query_count(ctx.state.db, ctx.guild_id)\n        Accord.respond(ctx; content=\"Total: $count\")\n    end\nend\n\n\n\nNext steps: Recipe 12 — Performance for Julia-specific optimizations.","title":"Avoid Global Mutable State"},{"category":"section","location":"cookbook/16-ai-agent/#Recipe-16-—-AI-Agent-Bot","page":"AI Agent Bot","text":"Difficulty: Advanced What you will build: A Discord bot that connects to LLM APIs (OpenAI, Anthropic Claude, Ollama) with streaming responses, tool use, conversation memory, and rate limiting.\n\nPrerequisites: Recipe 03, Recipe 04\n\n","title":"Recipe 16 — AI Agent Bot"},{"category":"section","location":"cookbook/16-ai-agent/#1.-Architecture","page":"AI Agent Bot","text":"User message → Discord → Accord.jl → LLM API → Discord\n                             ↑                    ↓\n                      Conversation memory    Streaming edits\n                      Tool execution         Followup messages\n\nwarning: API Key Management\nNever hardcode API keys in your source code. Use environment variables:api_key = ENV[\"OPENAI_API_KEY\"]  # Not a literal string!If you accidentally commit an API key:Revoke the key immediately via the provider's dashboard\nGenerate a new key\nUpdate your .env file\nAdd .env to .gitignore if not already there","title":"1. Architecture"},{"category":"section","location":"cookbook/16-ai-agent/#2.-Calling-LLM-APIs-from-Julia","page":"AI Agent Bot","text":"All three major providers work via HTTP.jl.","title":"2. Calling LLM APIs from Julia"},{"category":"section","location":"cookbook/16-ai-agent/#OpenAI","page":"AI Agent Bot","text":"import HTTP\nimport JSON3\n\nfunction openai_chat(messages::Vector{Dict}; model=\"gpt-4o\", api_key=ENV[\"OPENAI_API_KEY\"])\n    body = Dict(\n        \"model\" => model,\n        \"messages\" => messages,\n        \"max_tokens\" => 1024,\n    )\n\n    resp = HTTP.post(\n        \"https://api.openai.com/v1/chat/completions\",\n        [\"Authorization\" => \"Bearer \\$api_key\", \"Content-Type\" => \"application/json\"],\n        JSON3.write(body)\n    )\n\n    data = JSON3.read(resp.body)\n    return data[\"choices\"][1][\"message\"][\"content\"]\nend","title":"OpenAI"},{"category":"section","location":"cookbook/16-ai-agent/#Anthropic-Claude","page":"AI Agent Bot","text":"function claude_chat(messages::Vector{Dict}; model=\"claude-sonnet-4-5-20250929\", api_key=ENV[\"ANTHROPIC_API_KEY\"])\n    body = Dict(\n        \"model\" => model,\n        \"max_tokens\" => 1024,\n        \"messages\" => messages,\n    )\n\n    resp = HTTP.post(\n        \"https://api.anthropic.com/v1/messages\",\n        [\n            \"x-api-key\" => \\$api_key,\n            \"anthropic-version\" => \"2023-06-01\",\n            \"Content-Type\" => \"application/json\",\n        ],\n        JSON3.write(body)\n    )\n\n    data = JSON3.read(resp.body)\n    return data[\"content\"][1][\"text\"]\nend","title":"Anthropic Claude"},{"category":"section","location":"cookbook/16-ai-agent/#Local-Ollama","page":"AI Agent Bot","text":"function ollama_chat(messages::Vector{Dict}; model=\"llama3.1\", base_url=\"http://localhost:11434\")\n    body = Dict(\n        \"model\" => model,\n        \"messages\" => messages,\n        \"stream\" => false,\n    )\n\n    resp = HTTP.post(\n        \"\\$base_url/api/chat\",\n        [\"Content-Type\" => \"application/json\"],\n        JSON3.write(body)\n    )\n\n    data = JSON3.read(resp.body)\n    return data[\"message\"][\"content\"]\nend\n\ntip: Streaming Response Pattern\nFor better UX, stream LLM responses by editing the Discord message as tokens arrive. Throttle edits to ~1 per second to avoid rate limits and reduce visual flicker. Always truncate to 2000 characters (Discord's message limit).","title":"Local Ollama"},{"category":"section","location":"cookbook/16-ai-agent/#3.-Streaming-Responses","page":"AI Agent Bot","text":"Show the LLM's response progressively by editing the message:\n\nfunction openai_chat_stream(messages::Vector{Dict}, update_fn::Function;\n        model=\"gpt-4o\", api_key=ENV[\"OPENAI_API_KEY\"])\n    body = Dict(\n        \"model\" => model,\n        \"messages\" => messages,\n        \"max_tokens\" => 1024,\n        \"stream\" => true,\n    )\n\n    buffer = IOBuffer()\n    last_edit = Ref(0.0)\n    full_text = Ref(\"\")\n\n    HTTP.open(\"POST\", \"https://api.openai.com/v1/chat/completions\",\n        [\"Authorization\" => \"Bearer \\$api_key\", \"Content-Type\" => \"application/json\"],\n    ) do io\n        write(io, JSON3.write(body))\n        HTTP.closewrite(io)\n\n        while !eof(io)\n            line = readline(io)\n            startswith(line, \"data: \") || continue\n            data_str = line[7:end]\n            data_str == \"[DONE]\" && break\n\n            try\n                chunk = JSON3.read(data_str)\n                delta = get(chunk[\"choices\"][1][\"delta\"], \"content\", nothing)\n                if !isnothing(delta)\n                    full_text[] *= delta\n\n                    # Throttle edits to 1 per second\n                    if time() - last_edit[] >= 1.0\n                        update_fn(full_text[])\n                        last_edit[] = time()\n                    end\n                end\n            catch\n                continue\n            end\n        end\n    end\n\n    # Final update\n    update_fn(full_text[])\n    return full_text[]\nend","title":"3. Streaming Responses"},{"category":"section","location":"cookbook/16-ai-agent/#Using-with-Discord","page":"AI Agent Bot","text":"options_chat = [\n    Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"message\", description=\"Your message\", required=true),\n]\n\n@slash_command client \"chat\" \"Chat with AI\" options_chat function(ctx)\n    user_msg = Accord.get_option(ctx, \"message\", \"\")\n    Accord.defer(ctx)\n\n    messages = [\n        Dict(\"role\" => \"system\", \"content\" => \"You are a helpful assistant in a Discord server. Keep responses under 2000 characters.\"),\n        Dict(\"role\" => \"user\", \"content\" => user_msg),\n    ]\n\n    openai_chat_stream(messages, text -> begin\n        try\n            truncated = length(text) > 1990 ? text[1:1990] * \"...\" : text\n            edit_response(ctx; content=truncated)\n        catch e\n            @warn \"Edit failed\" exception=e\n        end\n    end)\nend","title":"Using with Discord"},{"category":"section","location":"cookbook/16-ai-agent/#4.-Tool-Use-/-Function-Calling","page":"AI Agent Bot","text":"Let the LLM call functions your bot defines:\n\n# Define available tools\nconst TOOLS = [\n    Dict(\n        \"type\" => \"function\",\n        \"function\" => Dict(\n            \"name\" => \"get_weather\",\n            \"description\" => \"Get current weather for a city\",\n            \"parameters\" => Dict(\n                \"type\" => \"object\",\n                \"properties\" => Dict(\n                    \"city\" => Dict(\"type\" => \"string\", \"description\" => \"City name\"),\n                ),\n                \"required\" => [\"city\"],\n            ),\n        ),\n    ),\n    Dict(\n        \"type\" => \"function\",\n        \"function\" => Dict(\n            \"name\" => \"roll_dice\",\n            \"description\" => \"Roll dice in NdM format\",\n            \"parameters\" => Dict(\n                \"type\" => \"object\",\n                \"properties\" => Dict(\n                    \"notation\" => Dict(\"type\" => \"string\", \"description\" => \"Dice notation like 2d6\"),\n                ),\n                \"required\" => [\"notation\"],\n            ),\n        ),\n    ),\n]\n\n# Tool implementations\nfunction execute_tool(name::String, args::Dict)\n    if name == \"get_weather\"\n        city = args[\"city\"]\n        # Simulated — replace with real API\n        return \"\"\"{\"city\": \"\\$city\", \"temp\": \"22°C\", \"condition\": \"Sunny\"}\"\"\"\n    elseif name == \"roll_dice\"\n        notation = args[\"notation\"]\n        m = match(r\"(\\d+)d(\\d+)\", notation)\n        isnothing(m) && return \"\"\"{\"error\": \"Invalid notation\"}\"\"\"\n        n, sides = parse(Int, m[1]), parse(Int, m[2])\n        rolls = [rand(1:sides) for _ in 1:n]\n        return \"\"\"{\"rolls\": \\$rolls, \"total\": \\$(sum(rolls))}\"\"\"\n    end\n    return \"\"\"{\"error\": \"Unknown tool\"}\"\"\"\nend","title":"4. Tool Use / Function Calling"},{"category":"section","location":"cookbook/16-ai-agent/#Agent-Loop","page":"AI Agent Bot","text":"function agent_chat(messages::Vector{Dict}; model=\"gpt-4o\", api_key=ENV[\"OPENAI_API_KEY\"], max_iterations=5)\n    for _ in 1:max_iterations\n        body = Dict(\n            \"model\" => model,\n            \"messages\" => messages,\n            \"tools\" => TOOLS,\n            \"max_tokens\" => 1024,\n        )\n\n        resp = HTTP.post(\n            \"https://api.openai.com/v1/chat/completions\",\n            [\"Authorization\" => \"Bearer \\$api_key\", \"Content-Type\" => \"application/json\"],\n            JSON3.write(body)\n        )\n\n        data = JSON3.read(resp.body)\n        choice = data[\"choices\"][1]\n        msg = choice[\"message\"]\n\n        # Add assistant message to history\n        push!(messages, Dict(pairs(msg)))\n\n        # Check for tool calls\n        if choice[\"finish_reason\"] == \"tool_calls\" && haskey(msg, \"tool_calls\")\n            for tool_call in msg[\"tool_calls\"]\n                func = tool_call[\"function\"]\n                name = func[\"name\"]\n                args = JSON3.read(func[\"arguments\"], Dict{String, Any})\n\n                @info \"Tool call\" name=name args=args\n                result = execute_tool(name, args)\n\n                push!(messages, Dict(\n                    \"role\" => \"tool\",\n                    \"tool_call_id\" => tool_call[\"id\"],\n                    \"content\" => result,\n                ))\n            end\n            continue  # Loop back for LLM to process results\n        end\n\n        # No tool calls — return the response\n        return get(msg, \"content\", \"\")\n    end\n\n    return \"I ran out of steps trying to answer that.\"\nend","title":"Agent Loop"},{"category":"section","location":"cookbook/16-ai-agent/#5.-Conversation-Memory","page":"AI Agent Bot","text":"Per-channel conversation history with a sliding window:\n\nconst MAX_HISTORY = 20\nconst conversations = Dict{[`Snowflake`](@ref), Vector{Dict{String,String}}}()\n\nfunction get_history(channel_id::[`Snowflake`](@ref))\n    get!(conversations, channel_id) do\n        Dict{String,String}[]\n    end\nend\n\nfunction add_message!(channel_id::[`Snowflake`](@ref), role::String, content::String)\n    history = get_history(channel_id)\n    push!(history, Dict(\"role\" => role, \"content\" => content))\n\n    # Sliding window: keep last MAX_HISTORY messages\n    while length(history) > MAX_HISTORY\n        popfirst!(history)\n    end\nend\n\nfunction clear_history!(channel_id::Snowflake)\n    conversations[channel_id] = Dict{String,String}[]\nend","title":"5. Conversation Memory"},{"category":"section","location":"cookbook/16-ai-agent/#6.-Per-User-Rate-Limiting","page":"AI Agent Bot","text":"Token bucket pattern to prevent API abuse:\n\nmutable struct TokenBucket\n    tokens::Float64\n    max_tokens::Float64\n    refill_rate::Float64  # tokens per second\n    last_refill::Float64\nend\n\nTokenBucket(max_tokens, refill_rate) = TokenBucket(max_tokens, max_tokens, refill_rate, time())\n\nfunction try_consume!(bucket::TokenBucket, n::Float64=1.0)\n    now_t = time()\n    elapsed = now_t - bucket.last_refill\n    bucket.tokens = min(bucket.max_tokens, bucket.tokens + elapsed * bucket.refill_rate)\n    bucket.last_refill = now_t\n\n    if bucket.tokens >= n\n        bucket.tokens -= n\n        return true\n    end\n    return false\nend\n\n# Per-user rate limits: 5 requests, refill 1 per 10 seconds\nconst user_buckets = Dict{Snowflake, TokenBucket}()\n\nfunction check_rate_limit(user_id::Snowflake)\n    bucket = get!(user_buckets, user_id) do\n        TokenBucket(5.0, 0.1)  # 5 requests max, 1 every 10 seconds\n    end\n    return try_consume!(bucket)\nend","title":"6. Per-User Rate Limiting"},{"category":"section","location":"cookbook/16-ai-agent/#7.-Complete-Working-Bot","page":"AI Agent Bot","text":"using Accord\nimport HTTP\nimport JSON3\n\ntoken = ENV[\"DISCORD_TOKEN\"]\nclient = Client(token; intents=IntentGuilds)\ntree = CommandTree()\n\n# --- Configuration ---\nconst SYSTEM_PROMPT = \"\"\"You are a helpful AI assistant in a Discord server.\nKeep responses concise (under 1800 characters).\nYou can use markdown formatting.\nIf asked to do something you can't, explain why.\"\"\"\n\nconst MAX_HISTORY = 20\nconst conversations = Dict{Snowflake, Vector{Dict{String,String}}}()\nconst user_buckets = Dict{Snowflake, TokenBucket}()\n\n# --- Helpers ---\nfunction get_history(channel_id)\n    get!(conversations, channel_id, Dict{String,String}[])\nend\n\nfunction add_to_history!(channel_id, role, content)\n    history = get_history(channel_id)\n    push!(history, Dict(\"role\" => role, \"content\" => content))\n    while length(history) > MAX_HISTORY\n        popfirst!(history)\n    end\nend\n\nmutable struct TokenBucket\n    tokens::Float64\n    max_tokens::Float64\n    refill_rate::Float64\n    last_refill::Float64\nend\nTokenBucket(max_t, rate) = TokenBucket(max_t, max_t, rate, time())\n\nfunction try_consume!(b::TokenBucket)\n    elapsed = time() - b.last_refill\n    b.tokens = min(b.max_tokens, b.tokens + elapsed * b.refill_rate)\n    b.last_refill = time()\n    b.tokens >= 1.0 || return false\n    b.tokens -= 1.0\n    return true\nend\n\nfunction check_rate_limit(user_id)\n    bucket = get!(user_buckets, user_id) do; TokenBucket(5.0, 0.1) end\n    try_consume!(bucket)\nend\n\n# --- API Call ---\nfunction call_llm(messages; api_key=ENV[\"OPENAI_API_KEY\"])\n    body = Dict(\n        \"model\" => \"gpt-4o\",\n        \"messages\" => messages,\n        \"max_tokens\" => 1024,\n        \"stream\" => false,\n    )\n    resp = HTTP.post(\n        \"https://api.openai.com/v1/chat/completions\",\n        [\"Authorization\" => \"Bearer \\$api_key\", \"Content-Type\" => \"application/json\"],\n        JSON3.write(body)\n    )\n    data = JSON3.read(resp.body)\n    return data[\"choices\"][1][\"message\"][\"content\"]\nend\n\n# --- Commands ---\n\n# /chat <message>\noptions_chat = [\n    Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"message\", description=\"Your message\", required=true),\n]\n\n@slash_command client \"chat\" \"Chat with the AI\" options_chat function(ctx)\n    user_id = ctx.interaction.member.user.id\n    channel_id = ctx.interaction.channel_id\n\n    # Rate limit check\n    if !check_rate_limit(user_id)\n        Accord.respond(ctx; content=\"You're sending messages too fast. Please wait a moment.\", ephemeral=true)\n        return\n    end\n\n    user_msg = Accord.get_option(ctx, \"message\", \"\")::String\n    Accord.defer(ctx)\n\n    # Build messages with history\n    add_to_history!(channel_id, \"user\", user_msg)\n    messages = vcat(\n        [Dict(\"role\" => \"system\", \"content\" => SYSTEM_PROMPT)],\n        get_history(channel_id)\n    )\n\n    try\n        response = call_llm(messages)\n\n        # Truncate if needed\n        if length(response) > 1990\n            response = response[1:1990] * \"...\"\n        end\n\n        add_to_history!(channel_id, \"assistant\", response)\n        Accord.respond(ctx; content=response)\n    catch e\n        @error \"LLM call failed\" exception=e\n        Accord.respond(ctx; content=\"Sorry, I couldn't process that request. Please try again.\")\n    end\nend\n\n# /clear-history\n@slash_command client \"clear-history\" \"Clear conversation history\" function(ctx)\n    channel_id = ctx.interaction.channel_id\n    conversations[channel_id] = Dict{String,String}[]\n    Accord.respond(ctx; content=\"Conversation history cleared.\", ephemeral=true)\nend\n\n# /model-info\n@slash_command client \"model-info\" \"Show AI model info\" function(ctx)\n    channel_id = ctx.interaction.channel_id\n    history_len = length(get_history(channel_id))\n\n    e = Accord.embed(\n        title=\"AI Assistant Info\",\n        color=0x5865F2,\n        fields=[\n            Dict(\"name\" => \"Model\", \"value\" => \"GPT-4o\", \"inline\" => true),\n            Dict(\"name\" => \"History\", \"value\" => \"\\$history_len / \\$MAX_HISTORY messages\", \"inline\" => true),\n            Dict(\"name\" => \"Rate Limit\", \"value\" => \"5 requests / 50 seconds\", \"inline\" => true),\n        ]\n    )\n    Accord.respond(ctx; embeds=[e], ephemeral=true)\nend\n\n# --- Wiring ---\nAccord.on(client, [`InteractionCreate`](@ref)) do c, event\n    dispatch_interaction!(tree, c, event.interaction)\nend\n\nAccord.on(client, [`ReadyEvent`](@ref)) do c, event\n    sync_commands!(c, tree)\n    @info \"AI Agent bot ready!\" user=event.user.username\nend\n\nAccord.start(client)","title":"7. Complete Working Bot"},{"category":"section","location":"cookbook/16-ai-agent/#8.-Advanced:-Voice-Commanded-AI-Agent","page":"AI Agent Bot","text":"Combine Recipe 05 (Voice) with this recipe for a voice-commanded agent:\n\n# Architecture:\n# 1. User speaks in voice channel\n# 2. Capture audio → PCM buffer\n# 3. Detect silence → trim audio\n# 4. pcm_to_wav() → WAV bytes\n# 5. Whisper API → transcript text\n# 6. Send transcript to LLM\n# 7. LLM response → text channel (or TTS → voice playback)\n\n# The voice capture code from Recipe 05 feeds into:\nfunction handle_voice_transcript(client, channel_id, transcript)\n    # Add to conversation and get AI response\n    add_to_history!(channel_id, \"user\", \"[Voice] \\$transcript\")\n\n    messages = vcat(\n        [Dict(\"role\" => \"system\", \"content\" => SYSTEM_PROMPT)],\n        get_history(channel_id)\n    )\n\n    response = call_llm(messages)\n    add_to_history!(channel_id, \"assistant\", response)\n\n    create_message(client, channel_id; content=response)\nend","title":"8. Advanced: Voice-Commanded AI Agent"},{"category":"section","location":"cookbook/16-ai-agent/#9.-Choosing-an-LLM-Provider","page":"AI Agent Bot","text":"Provider Strengths Cost Local?\nOpenAI GPT-4o Tool calling, streaming, function calling $$$ No\nAnthropic Claude Long context, careful reasoning $$$ No\nOllama (Llama 3) Free, private, no rate limits Free Yes\nOllama (Mistral) Fast, good quality/speed ratio Free Yes\n\nFor development, start with Ollama (free, no API key needed). For production, choose based on your quality/cost requirements.\n\n\n\nThis recipe brings together everything in the cookbook: slash commands, embeds, async patterns, and external API integration. You now have all the tools to build production Discord bots in Julia.\n\nBack to: Cookbook Index","title":"9. Choosing an LLM Provider"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#Recipe-04-—-Buttons,-Selects-and-Modals","page":"Buttons, Selects & Modals","text":"Difficulty: Intermediate What you will build: Interactive buttons, select menus, modal dialogs, and a complete ticket system workflow.\n\nPrerequisites: Recipe 03\n\n","title":"Recipe 04 — Buttons, Selects & Modals"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#1.-Buttons","page":"Buttons, Selects & Modals","text":"","title":"1. Buttons"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#Button-Styles","page":"Buttons, Selects & Modals","text":"Style Constant Color Requires\nPrimary ButtonStyles.PRIMARY Blurple custom_id\nSecondary ButtonStyles.SECONDARY Grey custom_id\nSuccess ButtonStyles.SUCCESS Green custom_id\nDanger ButtonStyles.DANGER Red custom_id\nLink ButtonStyles.LINK Grey url (no handler)","title":"Button Styles"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#Sending-Buttons","page":"Buttons, Selects & Modals","text":"@slash_command client \"buttons\" \"Show some buttons\" function(ctx)\n    components = [\n        Accord.action_row([\n            Accord.button(label=\"Click me!\", custom_id=\"btn_click\", style=ButtonStyles.PRIMARY),\n            Accord.button(label=\"Danger!\", custom_id=\"btn_danger\", style=ButtonStyles.DANGER),\n            Accord.button(label=\"Visit Site\", url=\"https://julialang.org\", style=ButtonStyles.LINK),\n        ])\n    ]\n    Accord.respond(ctx; content=\"Choose a button:\", components=components)\nend","title":"Sending Buttons"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#Handling-Button-Clicks","page":"Buttons, Selects & Modals","text":"warning: 3-Second Interaction Response Deadline\nDiscord requires an initial response to button clicks, select menu choices, and modal submissions within 3 seconds. If your handler performs slow operations, call defer(ctx) first to acknowledge the interaction, then follow up with the actual response.\n\n@button_handler client \"btn_click\" function(ctx)\n    Accord.respond(ctx; content=\"You clicked the button!\", ephemeral=true)\nend\n\n@button_handler client \"btn_danger\" function(ctx)\n    Accord.respond(ctx; content=\"Danger zone!\", ephemeral=true)\nend","title":"Handling Button Clicks"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#Buttons-with-Emoji","page":"Buttons, Selects & Modals","text":"Accord.button(\n    label=\"Approve\",\n    custom_id=\"approve\",\n    style=ButtonStyles.SUCCESS,\n    emoji=Dict(\"name\" => \"✅\"),\n)","title":"Buttons with Emoji"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#Disabling-Buttons-After-Click","page":"Buttons, Selects & Modals","text":"@button_handler client \"confirm_action\" function(ctx)\n    # Respond with disabled buttons (UPDATE_MESSAGE for component interactions)\n    components = [\n        Accord.action_row([\n            Accord.button(label=\"Confirmed\", custom_id=\"confirm_action\", style=ButtonStyles.SUCCESS, disabled=true),\n        ])\n    ]\n    Accord.respond(ctx; content=\"Action confirmed!\", components=components)\nend","title":"Disabling Buttons After Click"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#2.-String-Select-Menus","page":"Buttons, Selects & Modals","text":"@slash_command client \"colors\" \"Pick your favorite colors\" function(ctx)\n    sel = Accord.string_select(\n        custom_id=\"color_select\",\n        placeholder=\"Choose up to 3 colors...\",\n        min_values=1,\n        max_values=3,\n        options=[\n            Accord.select_option(label=\"Red\", value=\"red\", description=\"The color of fire\", emoji=Dict(\"name\" => \"🔴\")),\n            Accord.select_option(label=\"Green\", value=\"green\", description=\"The color of nature\", emoji=Dict(\"name\" => \"🟢\")),\n            Accord.select_option(label=\"Blue\", value=\"blue\", description=\"The color of sky\", emoji=Dict(\"name\" => \"🔵\")),\n            Accord.select_option(label=\"Yellow\", value=\"yellow\", description=\"The color of sun\", emoji=Dict(\"name\" => \"🟡\")),\n        ]\n    )\n    Accord.respond(ctx; content=\"Pick your colors:\", components=[Accord.action_row([sel])])\nend\n\n@select_handler client \"color_select\" function(ctx)\n    values = Accord.selected_values(ctx)\n    Accord.respond(ctx; content=\"You picked: **$(join(values, \", \"))**\", ephemeral=true)\nend","title":"2. String Select Menus"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#3.-Specialized-Select-Menus","page":"Buttons, Selects & Modals","text":"","title":"3. Specialized Select Menus"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#User-Select","page":"Buttons, Selects & Modals","text":"sel = user_select(custom_id=\"pick_user\", placeholder=\"Select a user\")\nAccord.respond(ctx; content=\"Pick a user:\", components=[Accord.action_row([sel])])","title":"User Select"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#Role-Select","page":"Buttons, Selects & Modals","text":"sel = role_select(custom_id=\"pick_role\", placeholder=\"Select a role\")\nAccord.respond(ctx; content=\"Pick a role:\", components=[Accord.action_row([sel])])","title":"Role Select"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#Mentionable-Select-(Users-Roles)","page":"Buttons, Selects & Modals","text":"sel = mentionable_select(custom_id=\"pick_mention\", placeholder=\"Select user or role\")\nAccord.respond(ctx; content=\"Pick someone:\", components=[Accord.action_row([sel])])","title":"Mentionable Select (Users + Roles)"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#Channel-Select","page":"Buttons, Selects & Modals","text":"sel = channel_select(\n    custom_id=\"pick_channel\",\n    placeholder=\"Select a channel\",\n    channel_types=[[`ChannelTypes`](@ref).GUILD_TEXT, [`ChannelTypes`](@ref).GUILD_VOICE]\n)\nAccord.respond(ctx; content=\"Pick a channel:\", components=[Accord.action_row([sel])])\n\nAll specialized selects use @select_handler and selected_values returns Snowflake ID strings.","title":"Channel Select"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#4.-Modals-(Popup-Forms)","page":"Buttons, Selects & Modals","text":"","title":"4. Modals (Popup Forms)"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#Showing-a-Modal","page":"Buttons, Selects & Modals","text":"@slash_command client \"feedback\" \"Give feedback\" function(ctx)\n    show_modal(ctx;\n        title=\"Feedback Form\",\n        custom_id=\"feedback_modal\",\n        components=[\n            Accord.label(\"Subject\",\n                Accord.text_input(\n                    custom_id=\"fb_subject\",\n                    style=TextInputStyles.SHORT,\n                    placeholder=\"Brief summary...\",\n                    max_length=100,\n                )),\n            Accord.label(\"Details\",\n                Accord.text_input(\n                    custom_id=\"fb_body\",\n                    style=TextInputStyles.PARAGRAPH,\n                    placeholder=\"Tell us more...\",\n                    min_length=10,\n                    max_length=2000,\n                );\n                description=\"What happened, and what you expected\"),\n        ]\n    )\nend","title":"Showing a Modal"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#Handling-Modal-Submissions","page":"Buttons, Selects & Modals","text":"@modal_handler client \"feedback_modal\" function(ctx)\n    values = Accord.modal_values(ctx)  # Dict{String, Any}: custom_id => value\n    subject = values[\"fb_subject\"]\n    body = values[\"fb_body\"]\n\n    e = Accord.embed(\n        title=\"Feedback Received\",\n        color=0x57F287,\n        fields=[\n            Dict(\"name\" => \"Subject\", \"value\" => subject),\n            Dict(\"name\" => \"Details\", \"value\" => body),\n        ]\n    )\n    Accord.respond(ctx; embeds=[e], ephemeral=true)\nend\n\nnote: Labels\nDiscord now wants every modal input wrapped in a label, which holds the question and an optional description. The older layout, a text_input with its own label= inside an action_row, still works but is deprecated.","title":"Handling Modal Submissions"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#Choices,-Checkboxes-and-File-Uploads","page":"Buttons, Selects & Modals","text":"Besides text and select menus, a modal can hold radio buttons, checkboxes and file pickers. modal_values returns each in its natural type.\n\n@slash_command client \"signup\" \"Sign up for the event\" function(ctx)\n    show_modal(ctx;\n        title=\"Event Signup\",\n        custom_id=\"signup_modal\",\n        components=[\n            Accord.label(\"Which day?\", Accord.radio_group(custom_id=\"day\", options=[\n                Accord.select_option(label=\"Saturday\", value=\"sat\"),\n                Accord.select_option(label=\"Sunday\", value=\"sun\"),\n            ])),\n            Accord.label(\"Sessions\", Accord.checkbox_group(custom_id=\"sessions\", options=[\n                Accord.select_option(label=\"Workshop\", value=\"workshop\"),\n                Accord.select_option(label=\"Talks\", value=\"talks\"),\n                Accord.select_option(label=\"Dinner\", value=\"dinner\"),\n            ]; min_values=0)),\n            Accord.label(\"Send me reminders\", Accord.checkbox(custom_id=\"remind\", default=true)),\n            Accord.label(\"Photo for your badge\",\n                Accord.file_upload(custom_id=\"photo\", required=false, file_types=[\"image\"])),\n        ]\n    )\nend\n\n@modal_handler client \"signup_modal\" function(ctx)\n    v = Accord.modal_values(ctx)\n    day      = v[\"day\"]          # \"sat\", \"sun\" (or nothing if the group is optional)\n    sessions = v[\"sessions\"]     # Vector{String}, possibly empty\n    remind   = v[\"remind\"]       # Bool\n    photos   = Accord.modal_files(ctx, \"photo\")   # Vector{Attachment}\n    Accord.respond(ctx; content=\"Signed up for $(day): $(join(sessions, \", \")); \" *\n        \"reminders $(remind ? \"on\" : \"off\"); $(length(photos)) photo(s)\", ephemeral=true)\nend","title":"Choices, Checkboxes and File Uploads"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#5.-Button-Modal-Flow","page":"Buttons, Selects & Modals","text":"A button click can open a modal:\n\n@slash_command client \"report\" \"Report an issue\" function(ctx)\n    components = [\n        Accord.action_row([\n            Accord.button(label=\"Report Bug\", custom_id=\"report_bug\", style=ButtonStyles.DANGER, emoji=Dict(\"name\" => \"🐛\")),\n        ])\n    ]\n    Accord.respond(ctx; content=\"Click to report an issue:\", components=components)\nend\n\n@button_handler client \"report_bug\" function(ctx)\n    show_modal(ctx;\n        title=\"Bug Report\",\n        custom_id=\"bug_report_modal\",\n        components=[\n            Accord.label(\"Bug Title\", Accord.text_input(custom_id=\"bug_title\", style=TextInputStyles.SHORT)),\n            Accord.label(\"Description\", Accord.text_input(custom_id=\"bug_desc\", style=TextInputStyles.PARAGRAPH)),\n        ]\n    )\nend\n\n@modal_handler client \"bug_report_modal\" function(ctx)\n    values = Accord.modal_values(ctx)\n    e = Accord.embed(\n        title=\"Bug Report: $(values[\"bug_title\"])\",\n        description=values[\"bug_desc\"],\n        color=0xED4245,\n        footer=Dict(\"text\" => \"Reported by $(ctx.interaction.member.user.username)\")\n    )\n    Accord.respond(ctx; content=\"Bug report submitted!\", embeds=[e])\nend\n\nnote: Custom ID 100-Character Limit\nDiscord limits custom_id to 100 characters. Keep IDs short and use prefixes/suffixes efficiently. For complex state, store data in your bot's memory and reference it with a short ID.","title":"5. Button → Modal Flow"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#6.-Dynamic-Custom-IDs","page":"Buttons, Selects & Modals","text":"Use prefixed custom IDs to pass data through interactions:\n\n# When creating buttons, encode data in the custom_id\n@slash_command client \"poll_quick\" \"Quick yes/no poll\" function(ctx)\n    question = Accord.get_option(ctx, \"question\", \"Agree?\")\n    components = [\n        Accord.action_row([\n            Accord.button(label=\"Yes (0)\", custom_id=\"vote:yes:0\", style=ButtonStyles.SUCCESS),\n            Accord.button(label=\"No (0)\", custom_id=\"vote:no:0\", style=ButtonStyles.DANGER),\n        ])\n    ]\n    Accord.respond(ctx; content=\"**$question**\", components=components)\nend\n\n# Handle all \"vote:\" prefixed buttons (prefix matching)\n@button_handler client \"vote:\" function(ctx)\n    cid = Accord.custom_id(ctx)\n    parts = split(cid, \":\")\n    choice = parts[2]  # \"yes\" or \"no\"\n    count = parse(Int, parts[3]) + 1\n\n    # Update the button with incremented count\n    new_id = \"vote:$(choice):$(count)\"\n    Accord.respond(ctx; content=\"You voted **$choice**! (Total: $count)\", ephemeral=true)\nend","title":"6. Dynamic Custom IDs"},{"category":"section","location":"cookbook/04-buttons-selects-modals/#7.-Complete-Example:-Ticket-System","page":"Buttons, Selects & Modals","text":"A full workflow: slash command → button → modal → ticket channel.\n\nusing Accord\n\ntoken = ENV[\"DISCORD_TOKEN\"]\nclient = Client(token; intents=IntentGuilds)\n\n# Step 1: Post the ticket panel\n@slash_command client \"ticket_setup\" \"Set up a ticket panel\" function(ctx)\n    e = Accord.embed(\n        title=\"Support Tickets\",\n        description=\"Click the button below to create a support ticket.\",\n        color=0x5865F2,\n    )\n    components = [\n        Accord.action_row([\n            Accord.button(label=\"Create Ticket\", custom_id=\"ticket_create\", style=ButtonStyles.PRIMARY, emoji=Dict(\"name\" => \"🎫\")),\n        ])\n    ]\n    Accord.respond(ctx; embeds=[e], components=components)\nend\n\n# Step 2: Button opens a modal\n@button_handler client \"ticket_create\" function(ctx)\n    show_modal(ctx;\n        title=\"Create Support Ticket\",\n        custom_id=\"ticket_modal\",\n        components=[\n            Accord.label(\"Subject\", Accord.text_input(custom_id=\"ticket_subject\", style=TextInputStyles.SHORT, placeholder=\"Brief description\")),\n            Accord.label(\"Details\", Accord.text_input(custom_id=\"ticket_details\", style=TextInputStyles.PARAGRAPH, placeholder=\"Describe your issue...\")),\n        ]\n    )\nend\n\n# Step 3: Modal submission creates the ticket\n@modal_handler client \"ticket_modal\" function(ctx)\n    values = Accord.modal_values(ctx)\n    user = ctx.interaction.member.user\n\n    e = Accord.embed(\n        title=\"Ticket: $(values[\"ticket_subject\"])\",\n        description=values[\"ticket_details\"],\n        color=0xFEE75C,\n        footer=Dict(\"text\" => \"Opened by $(user.username)\"),\n    )\n    components = [\n        Accord.action_row([\n            Accord.button(label=\"Close Ticket\", custom_id=\"ticket_close\", style=ButtonStyles.DANGER),\n        ])\n    ]\n    Accord.respond(ctx; content=\"Ticket created!\", embeds=[e], components=components, ephemeral=true)\n\n    # Also post in a log channel (optional)\n    # LOG_CHANNEL = Snowflake(999999999999999999)\n    # create_message(ctx.client, LOG_CHANNEL; embeds=[e])\nend\n\n# Step 4: Close the ticket\n@button_handler client \"ticket_close\" function(ctx)\n    Accord.respond(ctx; content=\"Ticket closed by <@$(ctx.interaction.member.user.id)>.\")\nend\n\n# Wiring\nAccord.on(client, [`ReadyEvent`](@ref)) do c, event\n    sync_commands!(c, c.command_tree)\n    @info \"Ticket bot ready!\"\nend\n\nAccord.start(client)\n\n\n\nNext steps: Recipe 05 — Voice for audio playback and recording, or Recipe 10 — Polls for Discord's native poll system.","title":"7. Complete Example: Ticket System"},{"category":"section","location":"cookbook/02-messages-and-embeds/#Recipe-02-—-Rich-Messages","page":"Rich Messages","text":"Difficulty: Beginner What you will build: Embeds with all fields, reactions, file attachments, message editing/deletion, and a reaction-role system.\n\nPrerequisites: Recipe 01\n\n","title":"Recipe 02 — Rich Messages"},{"category":"section","location":"cookbook/02-messages-and-embeds/#1.-Simple-Messages","page":"Rich Messages","text":"# Plain text\ncreate_message(client, channel_id; content=\"Hello, world!\")\n\n# With a reply reference\ncreate_message(client, channel_id;\n    content=\"Replying to you!\",\n    message_reference=Dict(\n        \"message_id\" => string(original_message_id)\n    )\n)","title":"1. Simple Messages"},{"category":"section","location":"cookbook/02-messages-and-embeds/#2.-Building-Embeds","page":"Rich Messages","text":"The easiest way to build embeds is using the @embed macro, which provides a declarative DSL:\n\ne = Accord.@embed begin\n    title \"My Embed\"\n    description \"A rich embed built with the Accord.@embed macro.\"\n    url \"https://github.com/manelsen/Accord.jl\"\n    color :blurple\n    field \"Performance\" \"283k msg/s\" inline=true\n    field \"Ergonomics\" \"Macros & DSLs\" inline=true\n    footer \"Accord.jl v0.3.0\"\n    timestamp\nend\n\ncreate_message(client, channel_id; embeds=[e])\n\nAlternatively, the embed() helper returns a Dict if you prefer a standard function call:\n\ne = Accord.embed(\n    title=\"Legacy Style\",\n    description=\"Using the functional helper.\",\n    color=0x5865F2\n)","title":"2. Building Embeds"},{"category":"section","location":"cookbook/02-messages-and-embeds/#Color-Reference","page":"Rich Messages","text":"The @embed macro supports symbols for common Discord colors:\n\n# Supported symbols:\n# :blurple, :green, :yellow, :fuchsia, :red, :white, :black, :gold, :orange, :blue","title":"Color Reference"},{"category":"section","location":"cookbook/02-messages-and-embeds/#3.-Multiple-Embeds","page":"Rich Messages","text":"note: Embed Limits\nDiscord imposes limits on embeds:Total characters: 6000 across all embeds in a message\nFields: Maximum 25 per embed\nField name: 256 characters maximum\nField value: 1024 characters maximum\nDescription: 4096 characters maximum\nUp to 10 embeds per message\n\nembeds = [\n    Accord.embed(title=\"Embed 1\", description=\"First\", color=0xED4245),\n    Accord.embed(title=\"Embed 2\", description=\"Second\", color=0x57F287),\n    Accord.embed(title=\"Embed 3\", description=\"Third\", color=0x5865F2),\n]\n\ncreate_message(client, channel_id; embeds=embeds)","title":"3. Multiple Embeds"},{"category":"section","location":"cookbook/02-messages-and-embeds/#4.-Reactions","page":"Rich Messages","text":"# Unicode emoji\ncreate_reaction(client, channel_id, message_id, \"👍\")\n\n# Custom emoji — use format name:id\ncreate_reaction(client, channel_id, message_id, \"custom_emoji:123456789012345678\")","title":"4. Reactions"},{"category":"section","location":"cookbook/02-messages-and-embeds/#Reaction-Role-System","page":"Rich Messages","text":"# Map emoji to role IDs\nconst REACTION_ROLES = Dict(\n    \"🎮\" => [`Snowflake`](@ref)(111111111111111111),  # Gamer role\n    \"🎨\" => [`Snowflake`](@ref)(222222222222222222),  # Artist role\n    \"🎵\" => [`Snowflake`](@ref)(333333333333333333),  # Music role\n)\n\nconst ROLE_MESSAGE_ID = [`Snowflake`](@ref)(444444444444444444)  # the message to watch\n\nAccord.on(client, [`MessageReactionAdd`](@ref)) do c, event\n    event.message_id != ROLE_MESSAGE_ID && return\n    ismissing(event.member) && return\n\n    # Get emoji name\n    emoji_name = event.emoji.name\n    ismissing(emoji_name) && return\n\n    role_id = get(REACTION_ROLES, emoji_name, nothing)\n    isnothing(role_id) && return\n    ismissing(event.guild_id) && return\n\n    Accord.add_guild_member_role(c, event.guild_id, event.member.user.id, role_id)\n    @info \"Added role\" role=role_id user=event.member.user.id\nend\n\nAccord.on(client, [`MessageReactionRemove`](@ref)) do c, event\n    event.message_id != ROLE_MESSAGE_ID && return\n\n    emoji_name = event.emoji.name\n    ismissing(emoji_name) && return\n\n    role_id = get(REACTION_ROLES, emoji_name, nothing)\n    isnothing(role_id) && return\n    ismissing(event.guild_id) && return\n\n    Accord.remove_guild_member_role(c, event.guild_id, event.user_id, role_id)\n    @info \"Removed role\" role=role_id user=event.user_id\nend","title":"Reaction-Role System"},{"category":"section","location":"cookbook/02-messages-and-embeds/#5.-Editing-and-Deleting-Messages","page":"Rich Messages","text":"# Edit a message\nedit_message(client, channel_id, message_id;\n    content=\"Updated content!\",\n    embeds=[Accord.embed(title=\"Updated\", color=0x57F287)]\n)\n\n# Delete a single message\ndelete_message(client, channel_id, message_id)\n\n# Bulk delete messages\nmessage_ids = [Snowflake(id1), Snowflake(id2), Snowflake(id3)]\nAccord.bulk_delete_messages(client, channel_id;\n    message_ids=message_ids)\n\n!!! warning \"bulk_delete_messages Constraints\"\n    - Must delete between **2 and 100 messages** at a time\n    - Messages must be **less than 14 days old**\n    - Messages older than 14 days must be deleted individually with [`delete_message`](@ref)","title":"5. Editing and Deleting Messages"},{"category":"section","location":"cookbook/02-messages-and-embeds/#6.-File-Attachments","page":"Rich Messages","text":"Send files using the files parameter as a vector of (filename, data) tuples:\n\n# Send a text file\ncreate_message(client, channel_id;\n    content=\"Here's a log file:\",\n    files=[(\"log.txt\", Vector{UInt8}(codeunits(\"Line 1\\nLine 2\\nLine 3\")))]\n)\n\n# Send an image from disk\nimg_data = read(\"chart.png\")\ncreate_message(client, channel_id;\n    content=\"Today's chart:\",\n    files=[(\"chart.png\", img_data)]\n)\n\n# Multiple files\ncreate_message(client, channel_id;\n    content=\"Multiple attachments:\",\n    files=[\n        (\"data.csv\", Vector{UInt8}(codeunits(\"a,b,c\\n1,2,3\"))),\n        (\"readme.txt\", Vector{UInt8}(codeunits(\"See attached data.\"))),\n    ]\n)","title":"6. File Attachments"},{"category":"section","location":"cookbook/02-messages-and-embeds/#7.-Embed-with-Attached-Image","page":"Rich Messages","text":"Reference an attached image inside an embed using attachment://filename:\n\nimg_data = read(\"banner.png\")\ne = Accord.embed(\n    title=\"Welcome!\",\n    image=Dict(\"url\" => \"attachment://banner.png\"),\n    color=0x5865F2,\n)\ncreate_message(client, channel_id;\n    embeds=[e],\n    files=[(\"banner.png\", img_data)]\n)","title":"7. Embed with Attached Image"},{"category":"section","location":"cookbook/02-messages-and-embeds/#8.-Practical-Example:-Info-Command","page":"Rich Messages","text":"using Dates\n\nAccord.on(client, MessageCreate) do c, event\n    msg = event.message\n    ismissing(msg.author) && return\n    ismissing(msg.content) && return\n    !ismissing(msg.author.bot) && msg.author.bot == true && return\n\n    if msg.content == \"!serverinfo\"\n        ismissing(msg.guild_id) && return\n\n        guild = get_guild(c, msg.guild_id)\n        member_count = ismissing(guild.approximate_member_count) ? \"N/A\" : string(guild.approximate_member_count)\n\n        e = Accord.embed(\n            title=guild.name,\n            description=\"Server information\",\n            color=0x5865F2,\n            thumbnail=isnothing(guild.icon) ? nothing : Dict(\n                \"url\" => \"https://cdn.discordapp.com/icons/$(guild.id)/$(guild.icon).png\"\n            ),\n            fields=[\n                Dict(\"name\" => \"Owner\", \"value\" => \"<@$(guild.owner_id)>\", \"inline\" => true),\n                Dict(\"name\" => \"ID\", \"value\" => string(guild.id), \"inline\" => true),\n                Dict(\"name\" => \"Created\", \"value\" => string(Accord.timestamp(guild.id)), \"inline\" => true),\n                Dict(\"name\" => \"Verification\", \"value\" => string(guild.verification_level), \"inline\" => true),\n            ],\n            footer=Dict(\"text\" => \"Requested at $(Dates.format(now(), \"HH:MM:SS\"))\"),\n        )\n        create_message(c, msg.channel_id; embeds=[e])\n    end\nend\n\n\n\nNext steps: Recipe 03 — Slash Commands to replace prefix commands with Discord's native slash commands.","title":"8. Practical Example: Info Command"},{"category":"section","location":"cookbook/12-performance/#Recipe-12-—-Performance","page":"Performance","text":"Difficulty: Advanced What you will build: Optimized bots using Julia-specific techniques: type stability, precompilation, async patterns, and profiling.\n\nPrerequisites: Recipe 11\n\n","title":"Recipe 12 — Performance"},{"category":"section","location":"cookbook/12-performance/#1.-Type-Stability-in-Handlers","page":"Performance","text":"tip: Type Stability for Performance\nJulia's JIT compiler generates fast code when types are predictable. Always annotate types when extracting options from get_option, which returns Any. Use @code_warntype to identify type instabilities (look for red \"Any\" in the output).\n\nJulia's JIT compiler generates fast code when types are predictable. The get_option function returns Any — annotate it:\n\n# Slow: compiler doesn't know the type\n@slash_command client \"compute\" \"Do math\" function(ctx)\n    x = Accord.get_option(ctx, \"x\", 0)      # returns Any\n    y = Accord.get_option(ctx, \"y\", 0)      # returns Any\n    Accord.respond(ctx; content=\"Result: $(x + y)\")  # dynamic dispatch\nend\n\n# Fast: annotate types\n@slash_command client \"compute\" \"Do math\" function(ctx)\n    x = Accord.get_option(ctx, \"x\", 0)::Number\n    y = Accord.get_option(ctx, \"y\", 0)::Number\n    Accord.respond(ctx; content=\"Result: $(x + y)\")  # static dispatch\nend","title":"1. Type Stability in Handlers"},{"category":"section","location":"cookbook/12-performance/#Verify-with-@code_warntype","page":"Performance","text":"function handle_compute(ctx)\n    x = Accord.get_option(ctx, \"x\", 0)::Number\n    y = Accord.get_option(ctx, \"y\", 0)::Number\n    return x + y\nend\n\n# In the REPL (with a mock context):\n# @code_warntype handle_compute(ctx)\n# Look for red \"Any\" — those are type instabilities","title":"Verify with @code_warntype"},{"category":"section","location":"cookbook/12-performance/#2.-Precompilation","page":"Performance","text":"","title":"2. Precompilation"},{"category":"section","location":"cookbook/12-performance/#SnoopCompile-for-Precompile-Statements","page":"Performance","text":"# precompile_script.jl\nusing SnoopCompile\n\ntinf = @snoopi_deep begin\n    using Accord\n\n    # Simulate typical operations\n    client = Client(\"Bot fake_token\"; intents=IntentGuilds)\n    tree = CommandTree()\n    Accord.embed(title=\"Test\", color=0x5865F2)\n    Accord.button(label=\"Test\", custom_id=\"test\")\n    Accord.action_row([Accord.button(label=\"X\", custom_id=\"x\")])\n    Accord.command_option(type=3, name=\"test\", description=\"test\")\nend\n\n# Generate precompile statements\npc = SnoopCompile.parcel(tinf)\nSnoopCompile.write(\"precompile\", pc)","title":"SnoopCompile for Precompile Statements"},{"category":"section","location":"cookbook/12-performance/#PackageCompiler.jl-System-Image","page":"Performance","text":"Create a custom sysimage for near-instant startup:\n\nusing PackageCompiler\n\ncreate_sysimage(\n    [\"Accord\", \"HTTP\", \"JSON3\"],\n    sysimage_path=\"bot_sysimage.so\",\n    precompile_execution_file=\"precompile_script.jl\",\n)\n\nRun with the sysimage:\n\njulia --sysimage=bot_sysimage.so --project=. bin/run.jl\n\nStartup goes from ~10s to ~1s.","title":"PackageCompiler.jl System Image"},{"category":"section","location":"cookbook/12-performance/#3.-Async-Patterns","page":"Performance","text":"","title":"3. Async Patterns"},{"category":"section","location":"cookbook/12-performance/#Threads","page":"Performance","text":"Accord already runs each event's handlers in a task on Julia's default threadpool, in parallel up to handler_concurrency, and its own I/O loops (gateway, heartbeat, rate limiter, voice) on the interactive threadpool. Start Julia with several default threads and one interactive thread:\n\njulia -t auto,1 --project=. bin/run.jl\n\nYou don't need to wrap handler bodies in @async or Threads.@spawn. What you do need is to protect state shared between handlers, because two handlers can now touch it at the same time:\n\nconst counts = Dict{Snowflake, Int}()\nconst counts_lock = ReentrantLock()\n\nAccord.on(client, MessageCreate) do c, event\n    author = event.message.author.id\n    lock(counts_lock) do\n        counts[author] = get(counts, author, 0) + 1\n    end\nend\n\n# For a plain counter, an atomic is enough\nconst messages_seen = Threads.Atomic{Int}(0)\nAccord.on(client, MessageCreate) do c, event\n    Threads.atomic_add!(messages_seen, 1)\nend","title":"Threads"},{"category":"section","location":"cookbook/12-performance/#Avoiding-Event-Loop-Blocking","page":"Performance","text":"!!! warning \"Global Variables Cause Type Instability\"\n    Avoid global mutable state. Global variables have unpredictable types, forcing the compiler to use dynamic dispatch. Instead, inject state through `Client(; state=...)` or use `const` globals with concrete types.\n\n# BAD: blocks the event loop\nAccord.on(client, MessageCreate) do c, event\n    sleep(10)  # nothing else processes for 10 seconds!\n    create_message(c, event.message.channel_id; content=\"Done\")\nend\n\n# GOOD: defer to a task\nAccord.on(client, MessageCreate) do c, event\n    @async begin\n        sleep(10)\n        create_message(c, event.message.channel_id; content=\"Done\")\n    end\nend","title":"Avoiding Event Loop Blocking"},{"category":"section","location":"cookbook/12-performance/#Channel-Based-Worker-Pattern","page":"Performance","text":"# Process heavy work in a dedicated worker\nconst work_queue = Channel{Tuple{Client, Snowflake, String}}(100)\n\n# Worker task\n@async begin\n    for (client, channel_id, input) in work_queue\n        try\n            result = expensive_processing(input)\n            create_message(client, channel_id; content=result)\n        catch e\n            @error \"Worker error\" exception=e\n        end\n    end\nend\n\n# Handler just enqueues\nAccord.on(client, MessageCreate) do c, event\n    msg = event.message\n    ismissing(msg.content) && return\n    startswith(msg.content, \"!process \") || return\n    put!(work_queue, (c, msg.channel_id, msg.content[10:end]))\nend","title":"Channel-Based Worker Pattern"},{"category":"section","location":"cookbook/12-performance/#4.-Memory-Management","page":"Performance","text":"","title":"4. Memory Management"},{"category":"section","location":"cookbook/12-performance/#Cache-Sizing","page":"Performance","text":"# Monitor memory usage\nfunction memory_report(client)\n    guilds = length(client.state.guilds)\n    channels = length(client.state.channels)\n    users = length(client.state.users)\n\n    total_mb = Base.summarysize(client.state) / 1024 / 1024\n\n    @info \"Memory report\" guilds channels users total_mb=round(total_mb, digits=1)\nend\n\n# Run periodically\n@async while client.running\n    sleep(300)  # every 5 minutes\n    memory_report(client)\nend","title":"Cache Sizing"},{"category":"section","location":"cookbook/12-performance/#Avoid-String-Allocations-in-Hot-Paths","page":"Performance","text":"# Allocates a new string every call\nfunction make_greeting(name)\n    return \"Hello, $name! Welcome to the server.\"\nend\n\n# Pre-allocate with IOBuffer for complex strings\nfunction make_report(items)\n    io = IOBuffer()\n    for (i, item) in enumerate(items)\n        print(io, i, \". \", item, \"\\n\")\n    end\n    return String(take!(io))\nend","title":"Avoid String Allocations in Hot Paths"},{"category":"section","location":"cookbook/12-performance/#5.-Profiling","page":"Performance","text":"","title":"5. Profiling"},{"category":"section","location":"cookbook/12-performance/#@time-and-@allocated","page":"Performance","text":"# In REPL with non-blocking mode\nAccord.start(client; blocking=false)\n\n# Time a specific operation\n@time create_message(client, channel_id; content=\"test\")\n# 0.052 seconds (423 allocations: 28.5 KiB)\n\n@allocated Accord.embed(title=\"Test\", color=0x5865F2)\n# 1248","title":"@time and @allocated"},{"category":"section","location":"cookbook/12-performance/#Profile.@profile","page":"Performance","text":"using Profile\n\n# Profile event handling\nProfile.@profile begin\n    for i in 1:1000\n        Accord.embed(title=\"Test $i\", color=i, fields=[\n            Dict(\"name\" => \"Field\", \"value\" => \"Value\")\n        ])\n    end\nend\n\nProfile.print(mincount=10)","title":"Profile.@profile"},{"category":"section","location":"cookbook/12-performance/#Allocation-tracking","page":"Performance","text":"# Find where allocations happen\nProfile.Allocs.@profile sample_rate=1.0 begin\n    for i in 1:100\n        Accord.embed(title=\"Test\", fields=[\n            Dict(\"name\" => \"N\", \"value\" => string(i))\n        ])\n    end\nend","title":"Allocation tracking"},{"category":"section","location":"cookbook/12-performance/#6.-Batch-Operations","page":"Performance","text":"Use batch endpoints to reduce API calls:\n\n# Instead of N individual deletes:\nfor id in message_ids\n    delete_message(client, channel_id, id)  # N API calls\nend\n\n# Use bulk delete (1 API call):\nAccord.bulk_delete_messages(client, channel_id;\n    message_ids=message_ids)\n\n# Instead of N individual command creates:\n# Use sync_commands! which calls bulk_overwrite_global_application_commands\nsync_commands!(client, tree)  # 1 API call for all commands","title":"6. Batch Operations"},{"category":"section","location":"cookbook/12-performance/#7.-Connection-Pooling-for-External-Services","page":"Performance","text":"# Reuse HTTP connections for external APIs\nconst http_pool = Ref{HTTP.Pool}()\n\nfunction init_pool()\n    http_pool[] = HTTP.Pool(16)  # 16 connections\nend\n\nfunction call_external_api(endpoint, body)\n    HTTP.post(endpoint, [\"Content-Type\" => \"application/json\"],\n        JSON3.write(body);\n        pool=http_pool[],\n        retry=true,\n        retries=3,\n    )\nend","title":"7. Connection Pooling for External Services"},{"category":"section","location":"cookbook/12-performance/#8.-Benchmark:-Event-Handler-Overhead","page":"Performance","text":"using BenchmarkTools\n\n# Measure handler dispatch overhead\neh = EventHandler()\nregister_handler!(eh, MessageCreate, (c, e) -> nothing)\n\n# Create a fake event\nfake_msg = Message(id=Snowflake(1), channel_id=Snowflake(2))\nfake_event = MessageCreate(fake_msg)\n\n@benchmark dispatch_event!($eh, nothing, $fake_event)\n# Should be < 1μs — handler dispatch is not your bottleneck\n\n\n\nNext steps: Recipe 13 — Deployment for running your bot in production.","title":"8. Benchmark: Event Handler Overhead"},{"category":"section","location":"api/#api-reference","page":"API Reference","text":"Discord API v10 library for Julia. API Base: https://discord.com/api/v10\n\nnote: Calling REST endpoints\nThe REST functions below are documented with their low-level signature, f(rl::RateLimiter, args...; token, kwargs...). Every one of them also accepts a Client in place of the rate limiter and token: Accord.get_guild_member(client, guild_id, user_id). That is the form to use in bots; the RateLimiter form is the internal layer.\n\nnote: Exported vs public names\nusing Accord exports types, events, the command macros and Discord-specific functions. Generic names (start, on, respond, defer, button, embed, …) and the REST endpoints are public but not exported: call them as Accord.respond(...) or import them with using Accord: respond.\n\n\n\nnote: Optional vs Nullable\nAccord.jl uses two distinct type aliases for Discord's optional fields:Optional{T} (Union{T, Missing}): Field may be absent from the JSON entirely. Check with ismissing(). Default value is missing.\nNullable{T} (Union{T, Nothing}): Field is present but may be JSON null. Check with isnothing(). Default value is nothing.This distinction mirrors Discord's API: some fields are omitted when not applicable, others are explicitly set to null.\n\n","title":"Accord.jl — API Reference"},{"category":"section","location":"api/#1.-Client","page":"API Reference","text":"","title":"1. Client"},{"category":"section","location":"api/#2.-Events","page":"API Reference","text":"","title":"2. Events"},{"category":"section","location":"api/#3.-State-and-Caching","page":"API Reference","text":"","title":"3. State & Caching"},{"category":"section","location":"api/#4.-REST-Endpoints","page":"API Reference","text":"","title":"4. REST Endpoints"},{"category":"section","location":"api/#Messages","page":"API Reference","text":"","title":"Messages"},{"category":"section","location":"api/#Channels-and-Guilds","page":"API Reference","text":"","title":"Channels & Guilds"},{"category":"section","location":"api/#Threads","page":"API Reference","text":"","title":"Threads"},{"category":"section","location":"api/#Interactions","page":"API Reference","text":"","title":"Interactions"},{"category":"section","location":"api/#Users-and-Webhooks","page":"API Reference","text":"","title":"Users & Webhooks"},{"category":"section","location":"api/#Emoji-and-Stickers","page":"API Reference","text":"","title":"Emoji & Stickers"},{"category":"section","location":"api/#Invites,-Audit-Log-and-AutoMod","page":"API Reference","text":"","title":"Invites, Audit Log & AutoMod"},{"category":"section","location":"api/#Other-REST","page":"API Reference","text":"","title":"Other REST"},{"category":"section","location":"api/#5.-Interactions-—-DSL-and-Macros","page":"API Reference","text":"","title":"5. Interactions — DSL & Macros"},{"category":"section","location":"api/#Component-and-Embed-Builders","page":"API Reference","text":"","title":"Component & Embed Builders"},{"category":"section","location":"api/#6.-Voice","page":"API Reference","text":"","title":"6. Voice"},{"category":"section","location":"api/#DAVE-(end-to-end-encryption)","page":"API Reference","text":"Voice channels on Discord require DAVE. Accord drives it through libdave, loaded at runtime from the path in ACCORD_LIBDAVE (or LibDave.load!). connect! handles the whole protocol; the items below are the building blocks.","title":"DAVE (end-to-end encryption)"},{"category":"section","location":"api/#7.-Types","page":"API Reference","text":"","title":"7. Types"},{"category":"section","location":"api/#Core","page":"API Reference","text":"","title":"Core"},{"category":"section","location":"api/#Channel-Types","page":"API Reference","text":"","title":"Channel Types"},{"category":"section","location":"api/#Embed-Types","page":"API Reference","text":"","title":"Embed Types"},{"category":"section","location":"api/#Interaction-and-Command-Types","page":"API Reference","text":"","title":"Interaction & Command Types"},{"category":"section","location":"api/#Component-Types","page":"API Reference","text":"","title":"Component Types"},{"category":"section","location":"api/#Guild-Types","page":"API Reference","text":"","title":"Guild Types"},{"category":"section","location":"api/#Activity-and-Presence-Types","page":"API Reference","text":"","title":"Activity & Presence Types"},{"category":"section","location":"api/#Poll-Types","page":"API Reference","text":"","title":"Poll Types"},{"category":"section","location":"api/#Audit-Log-Types","page":"API Reference","text":"","title":"Audit Log Types"},{"category":"section","location":"api/#AutoMod-Types","page":"API Reference","text":"","title":"AutoMod Types"},{"category":"section","location":"api/#Sticker-Types","page":"API Reference","text":"","title":"Sticker Types"},{"category":"section","location":"api/#Invite-and-Webhook-Types","page":"API Reference","text":"","title":"Invite & Webhook Types"},{"category":"section","location":"api/#Voice-Types","page":"API Reference","text":"","title":"Voice Types"},{"category":"section","location":"api/#Stage,-Sound-and-Connection-Types","page":"API Reference","text":"","title":"Stage, Sound & Connection Types"},{"category":"section","location":"api/#Monetization-Types","page":"API Reference","text":"","title":"Monetization Types"},{"category":"section","location":"api/#Scheduled-Event-Types","page":"API Reference","text":"","title":"Scheduled Event Types"},{"category":"section","location":"api/#Integration-Types","page":"API Reference","text":"","title":"Integration Types"},{"category":"section","location":"api/#Onboarding-Types","page":"API Reference","text":"","title":"Onboarding Types"},{"category":"section","location":"api/#8.-Enums,-Flags-and-Permissions","page":"API Reference","text":"","title":"8. Enums, Flags & Permissions"},{"category":"section","location":"api/#Enums","page":"API Reference","text":"","title":"Enums"},{"category":"section","location":"api/#Intents","page":"API Reference","text":"","title":"Intents"},{"category":"section","location":"api/#Permissions-Utilities","page":"API Reference","text":"","title":"Permissions Utilities"},{"category":"section","location":"api/#Message-Flags","page":"API Reference","text":"","title":"Message Flags"},{"category":"section","location":"api/#User-Flags","page":"API Reference","text":"","title":"User Flags"},{"category":"section","location":"api/#Channel-Flags","page":"API Reference","text":"","title":"Channel Flags"},{"category":"section","location":"api/#Guild-Member-Flags","page":"API Reference","text":"","title":"Guild Member Flags"},{"category":"section","location":"api/#System-Channel-Flags","page":"API Reference","text":"","title":"System Channel Flags"},{"category":"section","location":"api/#Role-Flags","page":"API Reference","text":"","title":"Role Flags"},{"category":"section","location":"api/#Attachment-Flags","page":"API Reference","text":"","title":"Attachment Flags"},{"category":"section","location":"api/#SKU-Flags","page":"API Reference","text":"","title":"SKU Flags"},{"category":"section","location":"api/#Macros","page":"API Reference","text":"","title":"Macros"},{"category":"section","location":"api/#9.-Event-System","page":"API Reference","text":"","title":"9. Event System"},{"category":"section","location":"api/#10.-Gateway-and-Internals","page":"API Reference","text":"","title":"10. Gateway & Internals"},{"category":"section","location":"api/#Gateway","page":"API Reference","text":"","title":"Gateway"},{"category":"section","location":"api/#Rate-Limiter","page":"API Reference","text":"","title":"Rate Limiter"},{"category":"section","location":"api/#HTTP-Methods","page":"API Reference","text":"","title":"HTTP Methods"},{"category":"section","location":"api/#Response-Parsing","page":"API Reference","text":"","title":"Response Parsing"},{"category":"section","location":"api/#Voice-Gateway","page":"API Reference","text":"","title":"Voice Gateway"},{"category":"section","location":"api/#RTP-and-Codec","page":"API Reference","text":"","title":"RTP & Codec"},{"category":"section","location":"api/#Encryption","page":"API Reference","text":"","title":"Encryption"},{"category":"section","location":"api/#Heartbeat","page":"API Reference","text":"","title":"Heartbeat"},{"category":"section","location":"api/#Private-Helpers","page":"API Reference","text":"","title":"Private Helpers"},{"category":"section","location":"api/#Additional-Reference","page":"API Reference","text":"","title":"Additional Reference"},{"category":"type","location":"api/#Accord.Client","page":"API Reference","text":"Client\n\nUse this as the main entry point for your Discord bot to manage connections, events, and API calls.\n\nThe main Discord client that orchestrates gateway connections, REST API calls, and state caching.\n\ncompat: Accord 0.1.0\nClient and the full event-driven API are available since Accord 0.1.0.\n\nConstructor\n\nClient(token::String; intents=IntentAllNonPrivileged, num_shards=1, state=nothing, state_options...)\n\n- `state_data` — custom user state, accessible from handlers via `ctx.state`.\n- `handler_concurrency` — controls the number of concurrently executing handlers so slow workflows\n  (e.g. `wait_for`) can't starve the main loop. Increase the value only if you know your handlers\n  are fast and you need extra throughput; keeping the default `16` is enough for most bots.\nHandlers run on Julia's default threadpool, in parallel when Julia has more than\none thread: state shared between handlers must be protected (`ReentrantLock`,\n`Threads.Atomic`). Accord's I/O loops run on the `:interactive` threadpool when\none exists (`julia -t auto,1`), so handlers can't delay heartbeats.\n- `handler_backlog` — maximum number of handler tasks alive at once (running plus queued,\n  default `64 * handler_concurrency`). When it is reached the event loop waits, which applies\n  back-pressure to the gateway instead of growing memory without bound.\n\nExample\n\n# Inject custom state for database, config, etc.\nmy_state = (db=my_database, config=my_config)\nclient = Client(\"Bot YOUR_TOKEN_HERE\";\n    intents=IntentGuilds | IntentGuildMessages,\n    state=my_state\n)\n\non(client, MessageCreate) do c, event\n    event.message.content == \"ping\" && create_message(c, event.message.channel_id; content=\"pong\")\nend\nstart(client)\n\n\n\n\n\n","title":"Accord.Client"},{"category":"function","location":"api/#Accord.start","page":"API Reference","text":"start(client::Client; blocking=true)\n\nUse this to connect your bot to Discord and begin processing events.\n\nConnect to Discord and start processing events. If blocking=true (default), this blocks until the client is stopped.\n\nnote: Note\nIn blocking mode (the default), start will not return until stop is called or the process receives an interrupt (Ctrl-C). Use blocking=false for REPL or script workflows where you need to run code after the bot is online.\n\nExample\n\n# Blocking (default) — blocks until Ctrl-C or stop()\nstart(client)\n\n# Non-blocking — useful in scripts or REPL\nstart(client; blocking=false)\nwait_until_ready(client)\nprintln(\"Bot is online!\")\n\n\n\n\n\n","title":"Accord.start"},{"category":"function","location":"api/#Accord.stop","page":"API Reference","text":"stop(client::Client)\n\nUse this to gracefully shut down your bot and disconnect from Discord.\n\nDisconnect from Discord and stop processing events.\n\nExample\n\n@slash_command client \"shutdown\" \"Shut down the bot\" function(ctx)\n    respond(ctx; content=\"Shutting down...\")\n    stop(ctx.client)\nend\n\n\n\n\n\n","title":"Accord.stop"},{"category":"function","location":"api/#Accord.on","page":"API Reference","text":"on(handler, client, EventType)\n\nUse this to register callbacks that respond to Discord gateway events like messages or reactions.\n\nRegister an event handler. The handler receives (client, event).\n\nExample\n\non(client, MessageCreate) do c, event\n    println(\"Got message: \", event.message.content)\nend\n\n\n\n\n\n","title":"Accord.on"},{"category":"function","location":"api/#Accord.on_error","page":"API Reference","text":"on_error(handler, client)\n\nUse this to customize how your bot handles errors that occur during event processing.\n\nSet a custom error handler. Receives (client, event, error).\n\nwarning: Warning\nIf your custom error handler itself throws, the error will be silently lost. Always wrap your error handler body in a try-catch.\n\nExample\n\non_error(client) do c, event, err\n    @error \"Unhandled error\" event_type=typeof(event) exception=err\nend\n\n\n\n\n\n","title":"Accord.on_error"},{"category":"function","location":"api/#Accord.wait_until_ready","page":"API Reference","text":"wait_until_ready(client::Client)\n\nUse this to pause execution until your bot is fully connected and ready.\n\nBlock until the client receives the READY event.\n\n\n\n\n\n","title":"Accord.wait_until_ready"},{"category":"function","location":"api/#Accord.wait_for","page":"API Reference","text":"wait_for(check, client, EventType; timeout=30.0)\n\nUse this to pause execution until a specific event occurs, useful for interactive commands or conversations.\n\nWait for a specific gateway event that matches a predicate. Uses Julia's Channel and Timer for an efficient, non-blocking wait that suspends only the current Task, not the entire bot.\n\nReturns the matching event, or nothing on timeout.\n\nArguments\n\ncheck::Function — predicate (event) -> Bool. Only matching events are captured.\nclient::Client — the bot client. See Client.\nEventType — the event type to listen for (e.g., MessageCreate).\ntimeout — seconds to wait before returning nothing (default: 30).\n\nExample\n\n@slash_command client \"quiz\" \"Start a quiz\" function(ctx)\n    respond(ctx; content=\"What color is the sky?\")\n\n    event = wait_for(client, MessageCreate; timeout=30) do evt\n        evt.message.author.id == ctx.user.id &&\n        evt.message.channel_id == ctx.channel_id\n    end\n\n    if isnothing(event)\n        followup(ctx; content=\"⏰ Time's up!\")\n    elseif event.message.content == \"blue\"\n        followup(ctx; content=\"✅ Correct!\")\n    else\n        followup(ctx; content=\"❌ Wrong!\")\n    end\nend\n\n\n\n\n\n","title":"Accord.wait_for"},{"category":"function","location":"api/#Accord.reply","page":"API Reference","text":"reply(client::Client, message::Message; kwargs...) -> Message\n\nUse this to respond to a specific message, creating a threaded conversation.\n\nReply to a message. Automatically sets the channel ID and the message_reference.\n\nExample\n\non(client, MessageCreate) do c, event\n    reply(c, event.message; content=\"Got it!\")\nend\n\n\n\n\n\n","title":"Accord.reply"},{"category":"function","location":"api/#Accord.forward_message","page":"API Reference","text":"forward_message(client::Client, channel_id::Snowflake, message::Message) -> Message\n\nForward message to channel_id. The new message carries a snapshot of the original in message_snapshots; Discord does not allow content alongside it. The bot must be able to read the original message.\n\nExample\n\non(client, MessageCreate) do c, event\n    startswith(something(event.message.content, \"\"), \"!archive\") &&\n        forward_message(c, ARCHIVE_CHANNEL, event.message)\nend\n\n\n\n\n\n","title":"Accord.forward_message"},{"category":"function","location":"api/#Accord.update_presence","page":"API Reference","text":"update_presence(client; status=\"online\", activities=[], afk=false, since=nothing)\n\nUse this to change your bot's online status and activity display.\n\nSend a gateway command to update the bot's presence/status.\n\nExample\n\n# Set \"Playing Accord.jl\" status\nupdate_presence(client; activities=[activity(\"Accord.jl\", ActivityTypes.GAME)])\n\n# Set \"Do Not Disturb\" with custom status\nupdate_presence(client; status=\"dnd\", activities=[activity(\"maintenance\", ActivityTypes.WATCHING)])\n\n\n\n\n\n","title":"Accord.update_presence"},{"category":"function","location":"api/#Accord.request_guild_members","page":"API Reference","text":"request_guild_members(client, guild_id; query=\"\", limit=0, presences=false, user_ids=nothing, nonce=nothing)\n\nUse this to fetch member information for a guild through the gateway.\n\nRequest guild members via the gateway.\n\nExample\n\n# Fetch all members whose name starts with \"J\"\nrequest_guild_members(client, guild_id; query=\"J\", limit=10)\n\n# Fetch specific users by ID\nrequest_guild_members(client, guild_id; user_ids=[Snowflake(\"123456789\")])\n\n\n\n\n\n","title":"Accord.request_guild_members"},{"category":"function","location":"api/#Accord.request_soundboard_sounds","page":"API Reference","text":"request_soundboard_sounds(client::Client, guild_ids)\n\nAsk the gateway for the soundboard sounds of guild_ids; the answer arrives as one SoundboardSounds event per guild.\n\n\n\n\n\n","title":"Accord.request_soundboard_sounds"},{"category":"function","location":"api/#Accord.request_channel_info","page":"API Reference","text":"request_channel_info(client::Client, guild_id; fields=[\"status\", \"voice_start_time\"])\n\nAsk the gateway for the voice status and start time of a guild's channels; the answer arrives as a ChannelInfo event.\n\nExample\n\nrequest_channel_info(client, guild_id)\ninfo = wait_for(e -> e.guild_id == guild_id, client, ChannelInfo; timeout = 10)\n\n\n\n\n\n","title":"Accord.request_channel_info"},{"category":"function","location":"api/#Accord.activity","page":"API Reference","text":"activity(name, type=ActivityTypes.GAME; url=\"\")\n\nUse this to set your bot's status activity that appears below its name.\n\nCreate an activity dict for use with update_presence. The type should be a constant from ActivityTypes (e.g. GAME, STREAMING, LISTENING, WATCHING, COMPETING).\n\nExample\n\nupdate_presence(client; activities=[activity(\"Accord.jl\", ActivityTypes.GAME)])\n\n\n\n\n\n","title":"Accord.activity"},{"category":"type","location":"api/#Accord.AbstractEvent","page":"API Reference","text":"AbstractEvent\n\nBase type for all Discord gateway events. Use this type when registering catch-all event handlers.\n\n\n\n\n\n","title":"Accord.AbstractEvent"},{"category":"type","location":"api/#Accord.ReadyEvent","page":"API Reference","text":"ReadyEvent\n\nSent by Discord when the shard has successfully connected and identified. Contains information about the bot user and the guilds it is in. Discord docs\n\n\n\n\n\n","title":"Accord.ReadyEvent"},{"category":"type","location":"api/#Accord.ResumedEvent","page":"API Reference","text":"ResumedEvent\n\nSent by Discord when a shard has successfully resumed a disconnected session. Discord docs\n\n\n\n\n\n","title":"Accord.ResumedEvent"},{"category":"type","location":"api/#Accord.ChannelCreate","page":"API Reference","text":"ChannelCreate\n\nSent when a new channel is created, relevant to the current user. Discord docs\n\n\n\n\n\n","title":"Accord.ChannelCreate"},{"category":"type","location":"api/#Accord.ChannelUpdate","page":"API Reference","text":"ChannelUpdate\n\nSent when a channel is updated. Discord docs\n\n\n\n\n\n","title":"Accord.ChannelUpdate"},{"category":"type","location":"api/#Accord.ChannelDelete","page":"API Reference","text":"ChannelDelete\n\nSent when a channel relevant to the current user is deleted. Discord docs\n\n\n\n\n\n","title":"Accord.ChannelDelete"},{"category":"type","location":"api/#Accord.ChannelPinsUpdate","page":"API Reference","text":"ChannelPinsUpdate\n\nSent when a message is pinned or unpinned in a text channel. Discord docs\n\n\n\n\n\n","title":"Accord.ChannelPinsUpdate"},{"category":"type","location":"api/#Accord.ThreadCreate","page":"API Reference","text":"ThreadCreate\n\nSent when a thread is created, relevant to the current user, or when the current user is added to a thread. Discord docs\n\n\n\n\n\n","title":"Accord.ThreadCreate"},{"category":"type","location":"api/#Accord.ThreadUpdate","page":"API Reference","text":"ThreadUpdate\n\nSent when a thread is updated. Discord docs\n\n\n\n\n\n","title":"Accord.ThreadUpdate"},{"category":"type","location":"api/#Accord.ThreadDelete","page":"API Reference","text":"ThreadDelete\n\nSent when a thread relevant to the current user is deleted. Discord docs\n\n\n\n\n\n","title":"Accord.ThreadDelete"},{"category":"type","location":"api/#Accord.ThreadListSync","page":"API Reference","text":"ThreadListSync\n\nSent when the current user gains access to a channel, containing all active threads in that channel. Discord docs\n\n\n\n\n\n","title":"Accord.ThreadListSync"},{"category":"type","location":"api/#Accord.ThreadMemberUpdate","page":"API Reference","text":"ThreadMemberUpdate\n\nSent when the thread member object for the current user is updated. Discord docs\n\n\n\n\n\n","title":"Accord.ThreadMemberUpdate"},{"category":"type","location":"api/#Accord.ThreadMembersUpdate","page":"API Reference","text":"ThreadMembersUpdate\n\nSent when anyone is added to or removed from a thread. Discord docs\n\n\n\n\n\n","title":"Accord.ThreadMembersUpdate"},{"category":"type","location":"api/#Accord.GuildCreate","page":"API Reference","text":"GuildCreate\n\nSent when a guild becomes available, or when the bot joins a new guild. Discord docs\n\n\n\n\n\n","title":"Accord.GuildCreate"},{"category":"type","location":"api/#Accord.GuildUpdate","page":"API Reference","text":"GuildUpdate\n\nSent when a guild's properties are updated. Discord docs\n\n\n\n\n\n","title":"Accord.GuildUpdate"},{"category":"type","location":"api/#Accord.GuildDelete","page":"API Reference","text":"GuildDelete\n\nSent when a guild becomes unavailable, or when the bot leaves a guild. Discord docs\n\n\n\n\n\n","title":"Accord.GuildDelete"},{"category":"type","location":"api/#Accord.GuildAuditLogEntryCreate","page":"API Reference","text":"GuildAuditLogEntryCreate\n\nSent when a new audit log entry is created in a guild. Discord docs\n\n\n\n\n\n","title":"Accord.GuildAuditLogEntryCreate"},{"category":"type","location":"api/#Accord.GuildBanAdd","page":"API Reference","text":"GuildBanAdd\n\nSent when a user is banned from a guild. Discord docs\n\n\n\n\n\n","title":"Accord.GuildBanAdd"},{"category":"type","location":"api/#Accord.GuildBanRemove","page":"API Reference","text":"GuildBanRemove\n\nSent when a user is unbanned from a guild. Discord docs\n\n\n\n\n\n","title":"Accord.GuildBanRemove"},{"category":"type","location":"api/#Accord.GuildEmojisUpdate","page":"API Reference","text":"GuildEmojisUpdate\n\nSent when a guild's emojis are updated. Discord docs\n\n\n\n\n\n","title":"Accord.GuildEmojisUpdate"},{"category":"type","location":"api/#Accord.GuildStickersUpdate","page":"API Reference","text":"GuildStickersUpdate\n\nSent when a guild's stickers are updated. Discord docs\n\n\n\n\n\n","title":"Accord.GuildStickersUpdate"},{"category":"type","location":"api/#Accord.GuildIntegrationsUpdate","page":"API Reference","text":"GuildIntegrationsUpdate\n\nSent when a guild's integrations are updated. Discord docs\n\n\n\n\n\n","title":"Accord.GuildIntegrationsUpdate"},{"category":"type","location":"api/#Accord.GuildMemberAdd","page":"API Reference","text":"GuildMemberAdd\n\nSent when a new user joins a guild. Discord docs\n\n\n\n\n\n","title":"Accord.GuildMemberAdd"},{"category":"type","location":"api/#Accord.GuildMemberRemove","page":"API Reference","text":"GuildMemberRemove\n\nSent when a user is removed from a guild (leave/kick/ban). Discord docs\n\n\n\n\n\n","title":"Accord.GuildMemberRemove"},{"category":"type","location":"api/#Accord.GuildMemberUpdate","page":"API Reference","text":"GuildMemberUpdate\n\nSent when a guild member's roles, nickname, avatar, or timeout status is updated. Discord docs\n\n\n\n\n\n","title":"Accord.GuildMemberUpdate"},{"category":"type","location":"api/#Accord.GuildMembersChunk","page":"API Reference","text":"GuildMembersChunk\n\nSent in response to a Request Guild Members command. Discord docs\n\n\n\n\n\n","title":"Accord.GuildMembersChunk"},{"category":"type","location":"api/#Accord.GuildRoleCreate","page":"API Reference","text":"GuildRoleCreate\n\nSent when a guild role is created. Discord docs\n\n\n\n\n\n","title":"Accord.GuildRoleCreate"},{"category":"type","location":"api/#Accord.GuildRoleUpdate","page":"API Reference","text":"GuildRoleUpdate\n\nSent when a guild role is updated. Discord docs\n\n\n\n\n\n","title":"Accord.GuildRoleUpdate"},{"category":"type","location":"api/#Accord.GuildRoleDelete","page":"API Reference","text":"GuildRoleDelete\n\nSent when a guild role is deleted. Discord docs\n\n\n\n\n\n","title":"Accord.GuildRoleDelete"},{"category":"type","location":"api/#Accord.GuildScheduledEventCreate","page":"API Reference","text":"GuildScheduledEventCreate\n\nSent when a guild scheduled event is created. Discord docs\n\n\n\n\n\n","title":"Accord.GuildScheduledEventCreate"},{"category":"type","location":"api/#Accord.GuildScheduledEventUpdate","page":"API Reference","text":"GuildScheduledEventUpdate\n\nSent when a guild scheduled event is updated. Discord docs\n\n\n\n\n\n","title":"Accord.GuildScheduledEventUpdate"},{"category":"type","location":"api/#Accord.GuildScheduledEventDelete","page":"API Reference","text":"GuildScheduledEventDelete\n\nSent when a guild scheduled event is deleted. Discord docs\n\n\n\n\n\n","title":"Accord.GuildScheduledEventDelete"},{"category":"type","location":"api/#Accord.GuildScheduledEventUserAdd","page":"API Reference","text":"GuildScheduledEventUserAdd\n\nSent when a user subscribes to a guild scheduled event. Discord docs\n\n\n\n\n\n","title":"Accord.GuildScheduledEventUserAdd"},{"category":"type","location":"api/#Accord.GuildScheduledEventUserRemove","page":"API Reference","text":"GuildScheduledEventUserRemove\n\nSent when a user unsubscribes from a guild scheduled event. Discord docs\n\n\n\n\n\n","title":"Accord.GuildScheduledEventUserRemove"},{"category":"type","location":"api/#Accord.GuildSoundboardSoundCreate","page":"API Reference","text":"GuildSoundboardSoundCreate\n\nSent when a soundboard sound is created in a guild. Discord docs\n\n\n\n\n\n","title":"Accord.GuildSoundboardSoundCreate"},{"category":"type","location":"api/#Accord.GuildSoundboardSoundUpdate","page":"API Reference","text":"GuildSoundboardSoundUpdate\n\nSent when a soundboard sound is updated in a guild. Discord docs\n\n\n\n\n\n","title":"Accord.GuildSoundboardSoundUpdate"},{"category":"type","location":"api/#Accord.GuildSoundboardSoundDelete","page":"API Reference","text":"GuildSoundboardSoundDelete\n\nSent when a soundboard sound is deleted from a guild. Discord docs\n\n\n\n\n\n","title":"Accord.GuildSoundboardSoundDelete"},{"category":"type","location":"api/#Accord.GuildSoundboardSoundsUpdate","page":"API Reference","text":"GuildSoundboardSoundsUpdate\n\nSent when soundboard sounds are updated in a guild. Discord docs\n\n\n\n\n\n","title":"Accord.GuildSoundboardSoundsUpdate"},{"category":"type","location":"api/#Accord.SoundboardSounds","page":"API Reference","text":"SoundboardSounds\n\nSent when the bot joins a voice channel, containing all soundboard sounds for that guild. Discord docs\n\n\n\n\n\n","title":"Accord.SoundboardSounds"},{"category":"type","location":"api/#Accord.IntegrationCreate","page":"API Reference","text":"IntegrationCreate\n\nSent when an integration is created in a guild. Discord docs\n\n\n\n\n\n","title":"Accord.IntegrationCreate"},{"category":"type","location":"api/#Accord.IntegrationUpdate","page":"API Reference","text":"IntegrationUpdate\n\nSent when an integration is updated in a guild. Discord docs\n\n\n\n\n\n","title":"Accord.IntegrationUpdate"},{"category":"type","location":"api/#Accord.IntegrationDelete","page":"API Reference","text":"IntegrationDelete\n\nSent when an integration is deleted from a guild. Discord docs\n\n\n\n\n\n","title":"Accord.IntegrationDelete"},{"category":"type","location":"api/#Accord.InteractionCreate","page":"API Reference","text":"InteractionCreate\n\nSent when a user uses an application command or message component. Discord docs\n\n\n\n\n\n","title":"Accord.InteractionCreate"},{"category":"type","location":"api/#Accord.InviteCreate","page":"API Reference","text":"InviteCreate\n\nSent when a new invite to a channel is created. Discord docs\n\n\n\n\n\n","title":"Accord.InviteCreate"},{"category":"type","location":"api/#Accord.InviteDelete","page":"API Reference","text":"InviteDelete\n\nSent when an invite is deleted. Discord docs\n\n\n\n\n\n","title":"Accord.InviteDelete"},{"category":"type","location":"api/#Accord.MessageCreate","page":"API Reference","text":"MessageCreate\n\nSent when a message is created in a channel. Discord docs\n\n\n\n\n\n","title":"Accord.MessageCreate"},{"category":"type","location":"api/#Accord.MessageUpdate","page":"API Reference","text":"MessageUpdate\n\nSent when a message is updated (edited). Discord docs\n\n\n\n\n\n","title":"Accord.MessageUpdate"},{"category":"type","location":"api/#Accord.MessageDelete","page":"API Reference","text":"MessageDelete\n\nSent when a message is deleted. Discord docs\n\n\n\n\n\n","title":"Accord.MessageDelete"},{"category":"type","location":"api/#Accord.MessageDeleteBulk","page":"API Reference","text":"MessageDeleteBulk\n\nSent when multiple messages are deleted at once (bulk delete). Discord docs\n\n\n\n\n\n","title":"Accord.MessageDeleteBulk"},{"category":"type","location":"api/#Accord.MessageReactionAdd","page":"API Reference","text":"MessageReactionAdd\n\nSent when a user adds a reaction to a message. Discord docs\n\n\n\n\n\n","title":"Accord.MessageReactionAdd"},{"category":"type","location":"api/#Accord.MessageReactionRemove","page":"API Reference","text":"MessageReactionRemove\n\nSent when a user removes a reaction from a message. Discord docs\n\n\n\n\n\n","title":"Accord.MessageReactionRemove"},{"category":"type","location":"api/#Accord.MessageReactionRemoveAll","page":"API Reference","text":"MessageReactionRemoveAll\n\nSent when a user explicitly removes all reactions from a message. Discord docs\n\n\n\n\n\n","title":"Accord.MessageReactionRemoveAll"},{"category":"type","location":"api/#Accord.MessageReactionRemoveEmoji","page":"API Reference","text":"MessageReactionRemoveEmoji\n\nSent when a bot removes all instances of a given emoji reaction from a message. Discord docs\n\n\n\n\n\n","title":"Accord.MessageReactionRemoveEmoji"},{"category":"type","location":"api/#Accord.MessagePollVoteAdd","page":"API Reference","text":"MessagePollVoteAdd\n\nSent when a user votes in a poll. Discord docs\n\n\n\n\n\n","title":"Accord.MessagePollVoteAdd"},{"category":"type","location":"api/#Accord.MessagePollVoteRemove","page":"API Reference","text":"MessagePollVoteRemove\n\nSent when a user removes their vote from a poll. Discord docs\n\n\n\n\n\n","title":"Accord.MessagePollVoteRemove"},{"category":"type","location":"api/#Accord.PresenceUpdate","page":"API Reference","text":"PresenceUpdate\n\nSent when a user's presence or info (username, avatar) is updated. Discord docs\n\n\n\n\n\n","title":"Accord.PresenceUpdate"},{"category":"type","location":"api/#Accord.StageInstanceCreate","page":"API Reference","text":"StageInstanceCreate\n\nSent when a Stage instance is created. Discord docs\n\n\n\n\n\n","title":"Accord.StageInstanceCreate"},{"category":"type","location":"api/#Accord.StageInstanceUpdate","page":"API Reference","text":"StageInstanceUpdate\n\nSent when a Stage instance is updated. Discord docs\n\n\n\n\n\n","title":"Accord.StageInstanceUpdate"},{"category":"type","location":"api/#Accord.StageInstanceDelete","page":"API Reference","text":"StageInstanceDelete\n\nSent when a Stage instance is deleted (closed). Discord docs\n\n\n\n\n\n","title":"Accord.StageInstanceDelete"},{"category":"type","location":"api/#Accord.TypingStart","page":"API Reference","text":"TypingStart\n\nSent when a user starts typing in a channel. Discord docs\n\n\n\n\n\n","title":"Accord.TypingStart"},{"category":"type","location":"api/#Accord.UserUpdate","page":"API Reference","text":"UserUpdate\n\nSent when properties of the bot's user object change. Discord docs\n\n\n\n\n\n","title":"Accord.UserUpdate"},{"category":"type","location":"api/#Accord.VoiceStateUpdateEvent","page":"API Reference","text":"VoiceStateUpdateEvent\n\nSent when a user joins/leaves/moves voice channels. Discord docs\n\n\n\n\n\n","title":"Accord.VoiceStateUpdateEvent"},{"category":"type","location":"api/#Accord.VoiceServerUpdate","page":"API Reference","text":"VoiceServerUpdate\n\nSent when a guild's voice server is updated. Used for connecting to voice. Discord docs\n\n\n\n\n\n","title":"Accord.VoiceServerUpdate"},{"category":"type","location":"api/#Accord.VoiceChannelEffectSend","page":"API Reference","text":"VoiceChannelEffectSend\n\nSent when a voice channel effect (e.g. emoji, animation) is sent. Discord docs\n\n\n\n\n\n","title":"Accord.VoiceChannelEffectSend"},{"category":"type","location":"api/#Accord.WebhooksUpdate","page":"API Reference","text":"WebhooksUpdate\n\nSent when a guild channel's webhooks are created, updated, or deleted. Discord docs\n\n\n\n\n\n","title":"Accord.WebhooksUpdate"},{"category":"type","location":"api/#Accord.EntitlementCreate","page":"API Reference","text":"EntitlementCreate\n\nSent when an entitlement is created. Discord docs\n\n\n\n\n\n","title":"Accord.EntitlementCreate"},{"category":"type","location":"api/#Accord.EntitlementUpdate","page":"API Reference","text":"EntitlementUpdate\n\nSent when an entitlement is updated. Discord docs\n\n\n\n\n\n","title":"Accord.EntitlementUpdate"},{"category":"type","location":"api/#Accord.EntitlementDelete","page":"API Reference","text":"EntitlementDelete\n\nSent when an entitlement is deleted. Discord docs\n\n\n\n\n\n","title":"Accord.EntitlementDelete"},{"category":"type","location":"api/#Accord.SubscriptionCreate","page":"API Reference","text":"SubscriptionCreate\n\nSent when a subscription is created. Discord docs\n\n\n\n\n\n","title":"Accord.SubscriptionCreate"},{"category":"type","location":"api/#Accord.SubscriptionUpdate","page":"API Reference","text":"SubscriptionUpdate\n\nSent when a subscription is updated. Discord docs\n\n\n\n\n\n","title":"Accord.SubscriptionUpdate"},{"category":"type","location":"api/#Accord.SubscriptionDelete","page":"API Reference","text":"SubscriptionDelete\n\nSent when a subscription is deleted. Discord docs\n\n\n\n\n\n","title":"Accord.SubscriptionDelete"},{"category":"type","location":"api/#Accord.AutoModerationRuleCreate","page":"API Reference","text":"AutoModerationRuleCreate\n\nSent when an AutoMod rule is created. Discord docs\n\n\n\n\n\n","title":"Accord.AutoModerationRuleCreate"},{"category":"type","location":"api/#Accord.AutoModerationRuleUpdate","page":"API Reference","text":"AutoModerationRuleUpdate\n\nSent when an AutoMod rule is updated. Discord docs\n\n\n\n\n\n","title":"Accord.AutoModerationRuleUpdate"},{"category":"type","location":"api/#Accord.AutoModerationRuleDelete","page":"API Reference","text":"AutoModerationRuleDelete\n\nSent when an AutoMod rule is deleted. Discord docs\n\n\n\n\n\n","title":"Accord.AutoModerationRuleDelete"},{"category":"type","location":"api/#Accord.AutoModerationActionExecution","page":"API Reference","text":"AutoModerationActionExecution\n\nSent when an AutoMod rule is triggered and an action is executed. Discord docs\n\n\n\n\n\n","title":"Accord.AutoModerationActionExecution"},{"category":"type","location":"api/#Accord.State","page":"API Reference","text":"State\n\nUse this to access and manage cached Discord objects for your bot.\n\nHolds all cached Discord state. Global resources (guilds, channels, users) use a ShardedStore for thread-safe concurrent access.\n\nExample\n\nclient.state.guilds[id]\nclient.state.me.username\n\n\n\n\n\n","title":"Accord.State"},{"category":"type","location":"api/#Accord.Store","page":"API Reference","text":"Store{T}\n\nUse this to cache Discord objects like guilds, channels, and users with configurable eviction policies.\n\nA cache store for a specific resource type, keyed by Snowflake. Uses LRUCache.LRU for O(1) LRU eviction, plain Dict for other strategies.\n\nExample\n\nstore = Store{User}(CacheLRU(1000))\nstore[id] = user\nuser = store[id]\n\n\n\n\n\n","title":"Accord.Store"},{"category":"type","location":"api/#Accord.ShardedStore","page":"API Reference","text":"ShardedStore{T}\n\nA thread-safe version of Store that uses multiple shards (buckets) to reduce lock contention. Ideal for global resources accessed by many shards/tasks.\n\n\n\n\n\n","title":"Accord.ShardedStore"},{"category":"type","location":"api/#Accord.CacheStrategy","page":"API Reference","text":"Use this abstract type to define how Discord objects are cached in memory.\n\nCache strategy for a resource type.\n\nSubtypes\n\nCacheForever(): Keep entries indefinitely.\nCacheNever(): Do not cache entries.\nCacheLRU(maxsize): Keep only the most recently used entries.\nCacheTTL(ttl_seconds): Expire entries after a certain time.\n\nExample\n\nclient = Client(token; user_strategy=CacheLRU(1000))\n\n\n\n\n\n","title":"Accord.CacheStrategy"},{"category":"type","location":"api/#Accord.CacheForever","page":"API Reference","text":"Keep entries indefinitely in memory.\n\n\n\n\n\n","title":"Accord.CacheForever"},{"category":"type","location":"api/#Accord.CacheNever","page":"API Reference","text":"Do not cache entries (REST fallback on every access).\n\n\n\n\n\n","title":"Accord.CacheNever"},{"category":"type","location":"api/#Accord.CacheLRU","page":"API Reference","text":"Keep only the maxsize most recently used entries.\n\n\n\n\n\n","title":"Accord.CacheLRU"},{"category":"type","location":"api/#Accord.CacheTTL","page":"API Reference","text":"Expire entries after ttl_seconds have passed.\n\n\n\n\n\n","title":"Accord.CacheTTL"},{"category":"function","location":"api/#Accord.update_state!","page":"API Reference","text":"update_state!(state::State, event::AbstractEvent)\n\nUpdate the internal cache based on the incoming gateway event. Accord.jl handles this automatically for you.\n\n\n\n\n\n","title":"Accord.update_state!"},{"category":"function","location":"api/#Accord.create_message","page":"API Reference","text":"create_message(rl::RateLimiter, channel_id::Snowflake; token::String, body::Dict=Dict(), files=nothing) -> Message\n\nSend a message to a channel.\n\nUse this to post content, embeds, or files to a text channel or DM.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\nbody::Dict: JSON body containing content, embeds, components, etc.\nfiles: Vector of File objects or pairs for attachments.\n\nPermissions\n\nRequires SEND_MESSAGES. Requires SEND_TTS_MESSAGES if tts is true.\n\nErrors\n\nHTTP 403 if missing permissions (e.g. strict channel overwrites).\nHTTP 404 if the channel does not exist.\nHTTP 400 if the message is empty or invalid.\n\nDiscord docs\n\n\n\n\n\ncreate_message(client::Client, channel_id::Snowflake; kwargs...) -> Message\n\nUse this to send messages to any channel your bot has access to.\n\nSend a message to a channel.\n\nArguments\n\ncontent::String: Message text content.\nembeds::Vector: Vector of embed dictionaries or objects.\ncomponents::Vector: Vector of action rows/components.\nfiles: Optional files to upload.\ntts::Bool: Whether to send as a text-to-speech message.\nmessage_reference: Optional dictionary to reply to a specific message.\npoll: Optional poll object (see create_poll for a shortcut).\nflags: Optional MessageFlags or integer (e.g. MsgFlagSuppressEmbeds).\nallowed_mentions: Optional allowed-mentions dictionary.\n\nExample\n\ncreate_message(client, channel_id;\n    content=\"Check this out!\",\n    embeds=[embed(title=\"Hello\", description=\"An embed\", color=0x5865F2)],\n    components=[action_row([button(label=\"Click\", custom_id=\"btn\")])]\n)\n\n\n\n\n\n","title":"Accord.create_message"},{"category":"function","location":"api/#Accord.edit_message","page":"API Reference","text":"edit_message(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake; token::String, body::Dict, files=nothing) -> Message\n\nEdit a previously sent message.\n\nUse this to update the content, embeds, or components of a message.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\nmessage_id::Snowflake: The ID of the message.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\nbody::Dict: Fields to update. Set fields to nothing (null) to remove them.\nfiles: New attachments to append or replace.\n\nPermissions\n\nRequires MANAGE_MESSAGES if editing another user's message (which is generally not possible for content, only flags/suppression). You can always edit your own messages.\n\nErrors\n\nHTTP 403 if you try to edit someone else's message.\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\nedit_message(client::Client, channel_id::Snowflake, message_id::Snowflake; kwargs...) -> Message\n\nUse this to modify a message your bot previously sent.\n\nEdit an existing message. kwargs correspond to the Discord API fields (content, embeds, etc.).\n\nExample\n\nedit_message(client, channel_id, message_id; content=\"Updated content!\")\n\n\n\n\n\n","title":"Accord.edit_message"},{"category":"function","location":"api/#Accord.delete_message","page":"API Reference","text":"delete_message(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake; token::String, reason=nothing)\n\nDelete a message.\n\nUse this to remove a message permanently.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\nmessage_id::Snowflake: The ID of the message.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\nreason::String: Audit log reason.\n\nPermissions\n\nRequires MANAGE_MESSAGES to delete other users' messages. You can always delete your own messages.\n\nErrors\n\nHTTP 403 if missing permissions.\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\ndelete_message(client::Client, channel_id::Snowflake, message_id::Snowflake; reason=nothing)\n\nUse this to remove a message from a channel.\n\nDelete a message.\n\nExample\n\ndelete_message(client, channel_id, message_id; reason=\"Spam\")\n\n\n\n\n\n","title":"Accord.delete_message"},{"category":"function","location":"api/#Accord.bulk_delete_messages","page":"API Reference","text":"bulk_delete_messages(rl::RateLimiter, channel_id::Snowflake; token::String, message_ids::Vector{Snowflake}, reason=nothing)\n\nDelete multiple messages in a single request.\n\nUse this for moderation to quickly clear chat history. Can only delete messages that are less than 14 weeks old.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\nmessage_ids::Vector{Snowflake}: List of message IDs to delete (2-100).\nreason::String: Audit log reason.\n\nPermissions\n\nRequires MANAGE_MESSAGES.\n\nErrors\n\nHTTP 403 if missing permissions.\nHTTP 400 if deleting < 2 or > 100 messages, or if messages are too old.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.bulk_delete_messages"},{"category":"function","location":"api/#Accord.get_channel_message","page":"API Reference","text":"get_channel_message(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake; token::String) -> Message\n\nRetrieve a specific message.\n\nUse this to get the current state of a message, including updated edits or reactions.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\nmessage_id::Snowflake: The ID of the message.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\n\nPermissions\n\nRequires READ_MESSAGE_HISTORY.\n\nErrors\n\nHTTP 403 if missing permissions.\nHTTP 404 if the channel or message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_channel_message"},{"category":"function","location":"api/#Accord.get_channel_messages","page":"API Reference","text":"get_channel_messages(rl::RateLimiter, channel_id::Snowflake; token::String, limit::Int=50, around=nothing, before=nothing, after=nothing) -> Vector{Message}\n\nRetrieve a list of messages from a channel.\n\nUse this to fetch message history for logs, analysis, or context.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\nlimit::Int: Max number of messages to return (1-100, default 50).\naround::Snowflake: Get messages around this message ID.\nbefore::Snowflake: Get messages before this message ID.\nafter::Snowflake: Get messages after this message ID.\n\nPermissions\n\nRequires VIEW_CHANNEL and READ_MESSAGE_HISTORY.\n\nErrors\n\nHTTP 403 if missing permissions.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_channel_messages"},{"category":"function","location":"api/#Accord.crosspost_message","page":"API Reference","text":"crosspost_message(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake; token::String) -> Message\n\nPublish a message from an Announcement Channel.\n\nUse this to push a message to all guilds that follow the announcement channel.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the announcement channel.\nmessage_id::Snowflake: The ID of the message to publish.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\n\nPermissions\n\nRequires SEND_MESSAGES and MANAGE_MESSAGES (or SEND_MESSAGES if it's your own message). Actually, for crossposting, it requires SEND_MESSAGES in the channel.\n\nErrors\n\nHTTP 403 if missing permissions.\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.crosspost_message"},{"category":"function","location":"api/#Accord.create_reaction","page":"API Reference","text":"create_reaction(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake, emoji::String; token::String)\n\nAdd a reaction to a message.\n\nUse this to react with a unicode emoji (e.g., \"👍\") or a custom guild emoji.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\nmessage_id::Snowflake: The ID of the message.\nemoji::String: The emoji to react with. For custom emojis, use name:id.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\n\nPermissions\n\nRequires READ_MESSAGE_HISTORY and ADD_REACTIONS.\n\nErrors\n\nHTTP 403 if missing permissions.\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\ncreate_reaction(client::Client, channel_id::Snowflake, message_id::Snowflake, emoji::String)\n\nUse this to add an emoji reaction to a message on behalf of your bot.\n\nCreate a reaction on a message. The emoji parameter should be a URL-encoded string: \"👍\" or \"custom_emoji:123456\".\n\nExample\n\non(client, MessageCreate) do c, event\n    if contains(event.message.content, \"hello\")\n        create_reaction(c, event.message.channel_id, event.message.id, \"👋\")\n    end\nend\n\n\n\n\n\n","title":"Accord.create_reaction"},{"category":"function","location":"api/#Accord.delete_own_reaction","page":"API Reference","text":"delete_own_reaction(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake, emoji::String; token::String)\n\nRemove the bot's own reaction.\n\nUse this to undo a reaction added by the bot.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\nmessage_id::Snowflake: The ID of the message.\nemoji::String: The emoji to remove.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\n\nErrors\n\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_own_reaction"},{"category":"function","location":"api/#Accord.delete_user_reaction","page":"API Reference","text":"delete_user_reaction(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake, emoji::String, user_id::Snowflake; token::String)\n\nRemove a user's reaction.\n\nUse this for moderation to remove inappropriate reactions.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\nmessage_id::Snowflake: The ID of the message.\nemoji::String: The emoji to remove.\nuser_id::Snowflake: The ID of the user whose reaction to remove.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\n\nPermissions\n\nRequires MANAGE_MESSAGES.\n\nErrors\n\nHTTP 403 if missing permissions.\nHTTP 404 if the message or user does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_user_reaction"},{"category":"function","location":"api/#Accord.delete_all_reactions","page":"API Reference","text":"delete_all_reactions(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake; token::String)\n\nRemove all reactions from a message.\n\nUse this to clear a message of all emoji reactions.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\nmessage_id::Snowflake: The ID of the message.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\n\nPermissions\n\nRequires MANAGE_MESSAGES.\n\nErrors\n\nHTTP 403 if missing permissions.\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_all_reactions"},{"category":"function","location":"api/#Accord.delete_all_reactions_for_emoji","page":"API Reference","text":"delete_all_reactions_for_emoji(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake, emoji::String; token::String)\n\nRemove all reactions for a specific emoji.\n\nUse this to clear all votes for a single option or remove a specific emoji entirely.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\nmessage_id::Snowflake: The ID of the message.\nemoji::String: The emoji to remove.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\n\nPermissions\n\nRequires MANAGE_MESSAGES.\n\nErrors\n\nHTTP 403 if missing permissions.\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_all_reactions_for_emoji"},{"category":"function","location":"api/#Accord.get_reactions","page":"API Reference","text":"get_reactions(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake, emoji::String; token::String, limit::Int=25, type::Int=0) -> Vector{User}\n\nGet a list of users that reacted with an emoji.\n\nUse this to see who voted or reacted.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\nmessage_id::Snowflake: The ID of the message.\nemoji::String: The emoji to check.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\nlimit::Int: Max number of users to return (1-100, default 25).\ntype::Int: 0 = normal, 1 = burst.\n\nErrors\n\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_reactions"},{"category":"function","location":"api/#Accord.get_answer_voters","page":"API Reference","text":"get_answer_voters(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake, answer_id::Int; token::String, limit::Int=25) -> Dict\n\nGet users who voted for a specific poll answer.\n\nUse this to retrieve poll results.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\nmessage_id::Snowflake: The ID of the message.\nanswer_id::Int: The ID of the answer choice (1-based index usually, but check Poll object).\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\nlimit::Int: Max number of users to return.\n\nErrors\n\nHTTP 404 if the message or answer does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_answer_voters"},{"category":"function","location":"api/#Accord.end_poll","page":"API Reference","text":"end_poll(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake; token::String) -> Message\n\nImmediately end a poll.\n\nUse this to close voting on a poll before its scheduled duration.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\nmessage_id::Snowflake: The ID of the message.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\n\nPermissions\n\nRequires MANAGE_MESSAGES (if not the author). Always allowed if you are the author.\n\nErrors\n\nHTTP 403 if missing permissions.\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.end_poll"},{"category":"function","location":"api/#Accord.pin_message","page":"API Reference","text":"pin_message(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake; token::String, reason=nothing)\n\nPin a message in a channel.\n\nUse this when a bot needs to highlight important messages, such as pinning announcements or saving key information.\n\nPermissions\n\nRequires PIN_MESSAGES (MANAGE_MESSAGES no longer grants it since February 2026).\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.pin_message"},{"category":"function","location":"api/#Accord.unpin_message","page":"API Reference","text":"unpin_message(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake; token::String, reason=nothing)\n\nUnpin a message in a channel.\n\nUse this when a bot needs to remove a pinned message, such as when unpinning outdated announcements or managing a limited number of pins.\n\nPermissions\n\nRequires PIN_MESSAGES.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.unpin_message"},{"category":"function","location":"api/#Accord.set_voice_channel_status","page":"API Reference","text":"set_voice_channel_status(rl::RateLimiter, channel_id::Snowflake; token::String, status=\"\", reason=nothing)\n\nSet the status text shown under a voice channel (up to 500 characters); an empty status clears it.\n\nPermissions\n\nRequires SET_VOICE_CHANNEL_STATUS, plus MANAGE_CHANNELS when the bot is not connected to that channel.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.set_voice_channel_status"},{"category":"function","location":"api/#Accord.get_pinned_messages","page":"API Reference","text":"get_pinned_messages(rl::RateLimiter, channel_id::Snowflake; token::String, before=nothing, limit=50) -> ChannelPins\n\nGet one page of a channel's pinned messages, newest first.\n\nUse this when a bot needs to display or manage pinned messages, such as in a pin archive command or pin management utility.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbefore — ISO8601 timestamp: only pins made before it. Use the last pinned_at of the previous page to page backwards.\nlimit::Int — Pins per page, 1–50 (default 50).\n\nReturns\n\nA ChannelPins: items (each a MessagePin with message and pinned_at) and has_more.\n\nPermissions\n\nRequires VIEW_CHANNEL and READ_MESSAGE_HISTORY.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_pinned_messages"},{"category":"function","location":"api/#Accord.get_channel","page":"API Reference","text":"get_channel(rl::RateLimiter, channel_id::Snowflake; token::String) -> DiscordChannel\n\nRetrieve a channel by its ID.\n\nThis is used when a bot needs to fetch channel information, such as when processing a command that references a channel or caching channel data.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the channel to retrieve.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 403 if the bot lacks permission to view the channel.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\nget_channel(client::Client, channel_id::Snowflake) -> DiscordChannel\n\nUse this to retrieve channel information, with automatic caching for performance.\n\nGet a channel by ID. Checks the local state cache first.\n\nExample\n\nchannel = get_channel(client, channel_id)\nprintln(\"Channel name: \", channel.name)\n\n\n\n\n\n","title":"Accord.get_channel"},{"category":"function","location":"api/#Accord.modify_channel","page":"API Reference","text":"modify_channel(rl::RateLimiter, channel_id::Snowflake; token::String, body::Dict, reason=nothing) -> DiscordChannel\n\nUpdate a channel's settings.\n\nUse this when a bot needs to change channel properties like name, topic, position, or permission overwrites. Requires appropriate permissions based on the changes being made.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the channel to modify.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Channel fields to update (name, type, position, topic, etc.).\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_CHANNELS for most modifications. Thread modifications may require different permissions.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_channel"},{"category":"function","location":"api/#Accord.delete_channel","page":"API Reference","text":"delete_channel(rl::RateLimiter, channel_id::Snowflake; token::String, reason=nothing) -> DiscordChannel\n\nDelete a channel or close a private message.\n\nUse this when a bot needs to remove a channel from a guild or close a DM. Deleting a guild channel cannot be undone. Deleting a category channel will also delete all child channels.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the channel to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the deletion (optional).\n\nPermissions\n\nRequires MANAGE_CHANNELS for guild channels.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_channel"},{"category":"function","location":"api/#Accord.edit_channel_permissions","page":"API Reference","text":"edit_channel_permissions(rl::RateLimiter, channel_id::Snowflake, overwrite_id::Snowflake; token::String, body::Dict, reason=nothing)\n\nEdit the permission overwrites for a channel.\n\nUse this when a bot needs to grant or restrict permissions for a user or role in a specific channel. This creates or updates permission overwrites.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the channel.\noverwrite_id::Snowflake — The user or role ID to set permissions for.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Permission overwrite data (type, allow, deny bits).\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_ROLES with the bot's top role higher than the target role (for role overwrites) or MANAGE_CHANNELS.\n\nErrors\n\nHTTP 403 if missing required permissions or if the bot's role is too low.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.edit_channel_permissions"},{"category":"function","location":"api/#Accord.delete_channel_permission","page":"API Reference","text":"delete_channel_permission(rl::RateLimiter, channel_id::Snowflake, overwrite_id::Snowflake; token::String, reason=nothing)\n\nDelete a permission overwrite from a channel.\n\nUse this when a bot needs to remove custom permissions for a user or role, reverting them to the channel's default permission settings.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the channel.\noverwrite_id::Snowflake — The user or role ID to remove permissions for.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the deletion (optional).\n\nPermissions\n\nRequires MANAGE_ROLES with the bot's top role higher than the target role (for role overwrites) or MANAGE_CHANNELS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel or overwrite does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_channel_permission"},{"category":"function","location":"api/#Accord.get_channel_invites","page":"API Reference","text":"get_channel_invites(rl::RateLimiter, channel_id::Snowflake; token::String) -> Vector{Invite}\n\nGet all invites for a channel.\n\nUse this when a bot needs to list active invites in a channel, such as for moderation purposes or invite management commands.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_CHANNELS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_channel_invites"},{"category":"function","location":"api/#Accord.create_channel_invite","page":"API Reference","text":"create_channel_invite(rl::RateLimiter, channel_id::Snowflake; token::String, body::Dict=Dict(), reason=nothing) -> Invite\n\nCreate a new invite for a channel.\n\nUse this when a bot needs to generate an invite link programmatically, with specific settings like expiration time or maximum uses.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Invite settings (maxage, maxuses, temporary, unique).\nreason::String — Audit log reason for creating the invite (optional).\n\nPermissions\n\nRequires CREATE_INSTANT_INVITE.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_channel_invite"},{"category":"function","location":"api/#Accord.follow_announcement_channel","page":"API Reference","text":"follow_announcement_channel(rl::RateLimiter, channel_id::Snowflake; token::String, body::Dict) -> Dict{String, Any}\n\nFollow an Announcement Channel to send messages to a target channel.\n\nUse this when a bot needs to set up crossposting from an announcement channel (news channel) to another channel in a different server.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the announcement channel to follow.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Contains webhook_channel_id for the target channel.\n\nPermissions\n\nRequires MANAGE_WEBHOOKS in the target channel's guild.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.follow_announcement_channel"},{"category":"function","location":"api/#Accord.trigger_typing_indicator","page":"API Reference","text":"trigger_typing_indicator(rl::RateLimiter, channel_id::Snowflake; token::String)\n\nTrigger the typing indicator in a channel.\n\nUse this when a bot is processing a command and wants to indicate to users that it is working on a response. The typing indicator lasts for 10 seconds or until a message is sent.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires SEND_MESSAGES in the channel.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.trigger_typing_indicator"},{"category":"function","location":"api/#Accord.get_guild","page":"API Reference","text":"get_guild(rl::RateLimiter, guild_id::Snowflake; token::String, with_counts::Bool=false) -> Guild\n\nRetrieve a guild by its ID.\n\nUse this when a bot needs to fetch guild information, such as guild settings, features, or member counts.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild to retrieve.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nwith_counts::Bool — Include approximate member and presence counts.\n\nErrors\n\nHTTP 403 if the bot is not in the guild.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\nget_guild(client::Client, guild_id::Snowflake) -> Guild\n\nUse this to retrieve server information, with automatic caching for performance.\n\nGet a guild by ID. Checks the local state cache first.\n\nExample\n\nguild = get_guild(client, guild_id)\nprintln(\"Server name: \", guild.name)\n\n\n\n\n\n","title":"Accord.get_guild"},{"category":"function","location":"api/#Accord.modify_guild","page":"API Reference","text":"modify_guild(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict, reason=nothing) -> Guild\n\nModify a guild's settings.\n\nUse this when a bot needs to update guild configuration such as name, icon, verification level, default notifications, or explicit content filter.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild to modify.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Guild fields to update.\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_guild"},{"category":"function","location":"api/#Accord.delete_guild","page":"API Reference","text":"delete_guild(rl::RateLimiter, guild_id::Snowflake; token::String)\n\nDelete a guild permanently.\n\nUse this when a bot needs to delete a guild it owns. This action is irreversible.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nThe bot must be the owner of the guild.\n\nErrors\n\nHTTP 403 if the bot is not the guild owner.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_guild"},{"category":"function","location":"api/#Accord.get_guild_channels","page":"API Reference","text":"get_guild_channels(rl::RateLimiter, guild_id::Snowflake; token::String) -> Vector{DiscordChannel}\n\nGet all channels in a guild.\n\nUse this when a bot needs to list all channels in a guild, such as for channel management commands or initialization.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires VIEW_CHANNEL for channels the bot can see.\n\nErrors\n\nHTTP 403 if the bot is not in the guild.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_channels"},{"category":"function","location":"api/#Accord.create_guild_channel","page":"API Reference","text":"create_guild_channel(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict, reason=nothing) -> DiscordChannel\n\nCreate a new channel in a guild.\n\nUse this when a bot needs to create channels programmatically, such as for temporary channels, ticket systems, or dynamic channel creation.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Channel settings (name, type, parent, permission overwrites, etc.).\nreason::String — Audit log reason for the creation (optional).\n\nPermissions\n\nRequires MANAGE_CHANNELS.\n\nErrors\n\nHTTP 403 if missing required permissions or channel limit reached.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_guild_channel"},{"category":"function","location":"api/#Accord.modify_guild_channel_positions","page":"API Reference","text":"modify_guild_channel_positions(rl::RateLimiter, guild_id::Snowflake; token::String, body::Vector)\n\nModify the positions of channels in a guild.\n\nUse this when a bot needs to reorder channels, such as for automatic category organization or dynamic channel sorting.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Vector — Array of channel position updates (id, position, lock_permissions).\n\nPermissions\n\nRequires MANAGE_CHANNELS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_guild_channel_positions"},{"category":"function","location":"api/#Accord.get_guild_preview","page":"API Reference","text":"get_guild_preview(rl::RateLimiter, guild_id::Snowflake; token::String) -> Guild\n\nGet a guild preview object for a public guild.\n\nUse this when a bot needs to display information about a public guild before the user joins, such as for guild discovery features.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the public guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the guild is not public or does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_preview"},{"category":"function","location":"api/#Accord.list_guild_members","page":"API Reference","text":"list_guild_members(rl::RateLimiter, guild_id::Snowflake; token::String, limit::Int=1, after::Optional{Snowflake}=missing) -> Vector{Member}\n\nList members in a guild.\n\nUse this when a bot needs to retrieve guild members for member listing, searching, or batch processing operations.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nlimit::Int — Maximum members to return (1-1000, default 1).\nafter::Snowflake — Get members after this user ID (for pagination).\n\nErrors\n\nHTTP 403 if the bot is not in the guild.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_guild_members"},{"category":"function","location":"api/#Accord.search_guild_members","page":"API Reference","text":"search_guild_members(rl::RateLimiter, guild_id::Snowflake; token::String, query_str::String, limit::Int=1) -> Vector{Member}\n\nSearch for guild members by username or nickname.\n\nUse this when a bot needs to find specific members by name, such as for user lookup commands or autocomplete functionality.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nquery_str::String — Query string to match against username/nickname.\nlimit::Int — Maximum members to return (1-1000, default 1).\n\nErrors\n\nHTTP 403 if the bot is not in the guild.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.search_guild_members"},{"category":"function","location":"api/#Accord.get_guild_member","page":"API Reference","text":"get_guild_member(rl::RateLimiter, guild_id::Snowflake, user_id::Snowflake; token::String) -> Member\n\nGet a guild member by user ID.\n\nUse this when a bot needs to fetch specific member information such as roles, nickname, join date, or permissions.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nuser_id::Snowflake — The ID of the user.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 403 if the bot is not in the guild.\nHTTP 404 if the member or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_member"},{"category":"function","location":"api/#Accord.add_guild_member","page":"API Reference","text":"add_guild_member(rl::RateLimiter, guild_id::Snowflake, user_id::Snowflake; token::String, body::Dict) -> Member\n\nAdd a user to a guild using an OAuth2 access token.\n\nUse this when a bot needs to add users to guilds through OAuth2 authorization, such as for guild join systems or membership management.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nuser_id::Snowflake — The ID of the user to add.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Must contain access_token and optionally nick and roles.\n\nPermissions\n\nRequires CREATE_INSTANT_INVITE.\n\nErrors\n\nHTTP 403 if missing required permissions or the user is already in the guild.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.add_guild_member"},{"category":"function","location":"api/#Accord.modify_guild_member","page":"API Reference","text":"modify_guild_member(rl::RateLimiter, guild_id::Snowflake, user_id::Snowflake; token::String, body::Dict, reason=nothing) -> Member\n\nModify attributes of a guild member.\n\nUse this when a bot needs to change a member's roles, nickname, timeout, or voice channel status.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nuser_id::Snowflake — The ID of the member to modify.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Member fields to update (nick, roles, mute, deaf, etc.).\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nMANAGE_NICKNAMES for changing nicknames.\nMANAGE_ROLES for managing roles.\nMODERATE_MEMBERS for timeouts.\nMOVE_MEMBERS for moving between voice channels.\n\nErrors\n\nHTTP 403 if missing required permissions or role hierarchy violation.\nHTTP 404 if the member or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_guild_member"},{"category":"function","location":"api/#Accord.modify_current_member","page":"API Reference","text":"modify_current_member(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict, reason=nothing) -> Member\n\nModify the current bot member's attributes.\n\nUse this when a bot needs to change its own nickname in a guild.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Member fields to update (currently only nick is supported).\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires CHANGE_NICKNAME or MANAGE_NICKNAMES.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_current_member"},{"category":"function","location":"api/#Accord.remove_guild_member","page":"API Reference","text":"remove_guild_member(rl::RateLimiter, guild_id::Snowflake, user_id::Snowflake; token::String, reason=nothing)\n\nRemove a member from a guild (kick).\n\nUse this when a bot needs to kick users from the guild, such as for moderation commands or automated removal systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nuser_id::Snowflake — The ID of the member to remove.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the removal (optional).\n\nPermissions\n\nRequires KICK_MEMBERS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the member or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.remove_guild_member"},{"category":"function","location":"api/#Accord.add_guild_member_role","page":"API Reference","text":"add_guild_member_role(rl::RateLimiter, guild_id::Snowflake, user_id::Snowflake, role_id::Snowflake; token::String, reason=nothing)\n\nAdd a role to a guild member.\n\nUse this when a bot needs to assign roles to users, such as for reaction roles, leveling systems, or automated moderation.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nuser_id::Snowflake — The ID of the member.\nrole_id::Snowflake — The ID of the role to add.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_ROLES with the bot's top role higher than the target role.\n\nErrors\n\nHTTP 403 if missing required permissions or role hierarchy violation.\nHTTP 404 if the member, role, or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.add_guild_member_role"},{"category":"function","location":"api/#Accord.remove_guild_member_role","page":"API Reference","text":"remove_guild_member_role(rl::RateLimiter, guild_id::Snowflake, user_id::Snowflake, role_id::Snowflake; token::String, reason=nothing)\n\nRemove a role from a guild member.\n\nUse this when a bot needs to remove roles from users, such as for temporary role assignments, reaction roles, or demotion systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nuser_id::Snowflake — The ID of the member.\nrole_id::Snowflake — The ID of the role to remove.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_ROLES with the bot's top role higher than the target role.\n\nErrors\n\nHTTP 403 if missing required permissions or role hierarchy violation.\nHTTP 404 if the member, role, or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.remove_guild_member_role"},{"category":"function","location":"api/#Accord.leave_guild","page":"API Reference","text":"leave_guild(rl::RateLimiter, guild_id::Snowflake; token::String)\n\nLeave a guild (server).\n\nUse this when a bot needs to programmatically leave a server, such as for bot removal commands or guild blacklisting systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild to leave.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the bot is not a member of the guild.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.leave_guild"},{"category":"function","location":"api/#Accord.get_guild_bans","page":"API Reference","text":"get_guild_bans(rl::RateLimiter, guild_id::Snowflake; token::String, limit::Int=1000) -> Vector{Ban}\n\nGet all bans in a guild.\n\nUse this when a bot needs to list banned users, such as for ban management commands or displaying ban lists to moderators.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nlimit::Int — Maximum bans to return (default 1000).\n\nPermissions\n\nRequires BAN_MEMBERS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_bans"},{"category":"function","location":"api/#Accord.get_guild_ban","page":"API Reference","text":"get_guild_ban(rl::RateLimiter, guild_id::Snowflake, user_id::Snowflake; token::String) -> Ban\n\nGet a specific ban for a user.\n\nUse this when a bot needs to check if a user is banned and see their ban reason, such as before attempting to unban or for ban information commands.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nuser_id::Snowflake — The ID of the user to check.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires BAN_MEMBERS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the user is not banned or the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_ban"},{"category":"function","location":"api/#Accord.create_guild_ban","page":"API Reference","text":"create_guild_ban(rl::RateLimiter, guild_id::Snowflake, user_id::Snowflake; token::String, body::Dict=Dict(), reason=nothing)\n\nBan a user from a guild.\n\nUse this when a bot needs to ban users, such as for moderation commands or automated ban systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nuser_id::Snowflake — The ID of the user to ban.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Ban options (deletemessagedays, deletemessageseconds).\nreason::String — Audit log reason for the ban (optional).\n\nPermissions\n\nRequires BAN_MEMBERS.\n\nErrors\n\nHTTP 403 if missing required permissions or if the bot cannot ban the target.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_guild_ban"},{"category":"function","location":"api/#Accord.remove_guild_ban","page":"API Reference","text":"remove_guild_ban(rl::RateLimiter, guild_id::Snowflake, user_id::Snowflake; token::String, reason=nothing)\n\nUnban a user from a guild.\n\nUse this when a bot needs to remove bans, such as for unban commands, temporary bans, or ban appeal systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nuser_id::Snowflake — The ID of the user to unban.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the unban (optional).\n\nPermissions\n\nRequires BAN_MEMBERS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the user is not banned or the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.remove_guild_ban"},{"category":"function","location":"api/#Accord.bulk_guild_ban","page":"API Reference","text":"bulk_guild_ban(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict, reason=nothing) -> Dict{String, Any}\n\nBan up to 200 users from a guild.\n\nUse this when a bot needs to ban multiple users at once, such as for raid protection or mass moderation actions.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Contains user_ids array and optional delete_message_seconds.\nreason::String — Audit log reason for the bans (optional).\n\nPermissions\n\nRequires BAN_MEMBERS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.bulk_guild_ban"},{"category":"function","location":"api/#Accord.get_guild_roles","page":"API Reference","text":"get_guild_roles(rl::RateLimiter, guild_id::Snowflake; token::String) -> Vector{Role}\n\nGet all roles in a guild.\n\nUse this when a bot needs to list guild roles, such as for role management commands or permission checking.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 403 if the bot is not in the guild.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_roles"},{"category":"function","location":"api/#Accord.get_guild_role_member_counts","page":"API Reference","text":"get_guild_role_member_counts(rl::RateLimiter, guild_id::Snowflake; token::String) -> Dict{Snowflake, Int}\n\nHow many members have each role (the @everyone role is not included).\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_role_member_counts"},{"category":"function","location":"api/#Accord.get_guild_role","page":"API Reference","text":"get_guild_role(rl::RateLimiter, guild_id::Snowflake, role_id::Snowflake; token::String) -> Role\n\nGet a specific role by ID.\n\nUse this when a bot needs to retrieve detailed information about a single role, such as for role management or permission checking.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nrole_id::Snowflake — The ID of the role.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the role or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_role"},{"category":"function","location":"api/#Accord.create_guild_role","page":"API Reference","text":"create_guild_role(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict=Dict(), reason=nothing) -> Role\n\nCreate a new role in a guild.\n\nUse this when a bot needs to create roles programmatically, such as for reaction roles, self-assignable roles, or temporary role systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Role settings (name, permissions, color, hoist, mentionable, etc.).\nreason::String — Audit log reason for the creation (optional).\n\nPermissions\n\nRequires MANAGE_ROLES.\n\nErrors\n\nHTTP 403 if missing required permissions or role limit reached.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_guild_role"},{"category":"function","location":"api/#Accord.modify_guild_role_positions","page":"API Reference","text":"modify_guild_role_positions(rl::RateLimiter, guild_id::Snowflake; token::String, body::Vector, reason=nothing) -> Vector{Role}\n\nModify the positions of roles in a guild.\n\nUse this when a bot needs to reorder roles, such as for role hierarchy management or sorting by activity/level.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Vector — Array of role position updates (id, position).\nreason::String — Audit log reason for the changes (optional).\n\nPermissions\n\nRequires MANAGE_ROLES.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_guild_role_positions"},{"category":"function","location":"api/#Accord.modify_guild_role","page":"API Reference","text":"modify_guild_role(rl::RateLimiter, guild_id::Snowflake, role_id::Snowflake; token::String, body::Dict, reason=nothing) -> Role\n\nModify a guild role.\n\nUse this when a bot needs to update role properties such as name, color, permissions, or mentionability.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nrole_id::Snowflake — The ID of the role to modify.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Role fields to update.\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_ROLES and the bot's top role must be higher than the target role.\n\nErrors\n\nHTTP 403 if missing required permissions or role hierarchy violation.\nHTTP 404 if the role or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_guild_role"},{"category":"function","location":"api/#Accord.delete_guild_role","page":"API Reference","text":"delete_guild_role(rl::RateLimiter, guild_id::Snowflake, role_id::Snowflake; token::String, reason=nothing)\n\nDelete a guild role.\n\nUse this when a bot needs to remove roles, such as for cleanup of temporary roles or automated role removal.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nrole_id::Snowflake — The ID of the role to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the deletion (optional).\n\nPermissions\n\nRequires MANAGE_ROLES and the bot's top role must be higher than the target role.\n\nErrors\n\nHTTP 403 if missing required permissions or role hierarchy violation.\nHTTP 404 if the role or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_guild_role"},{"category":"function","location":"api/#Accord.get_guild_prune_count","page":"API Reference","text":"get_guild_prune_count(rl::RateLimiter, guild_id::Snowflake; token::String, days::Int=7, include_roles::String=\"\") -> Dict{String, Any}\n\nGet the number of members that would be pruned.\n\nUse this when a bot needs to preview the results of a prune operation without actually removing members.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\ndays::Int — Number of days of inactivity to count (1-30, default 7).\ninclude_roles — Comma-separated list of role IDs to include.\n\nPermissions\n\nRequires KICK_MEMBERS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_prune_count"},{"category":"function","location":"api/#Accord.begin_guild_prune","page":"API Reference","text":"begin_guild_prune(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict, reason=nothing) -> Dict{String, Any}\n\nPrune inactive members from a guild.\n\nUse this when a bot needs to remove members who haven't been active for a specified number of days.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Prune options (days, computeprunecount, include_roles, etc.).\nreason::String — Audit log reason for the prune (optional).\n\nPermissions\n\nRequires KICK_MEMBERS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.begin_guild_prune"},{"category":"function","location":"api/#Accord.get_guild_voice_regions","page":"API Reference","text":"get_guild_voice_regions(rl::RateLimiter, guild_id::Snowflake; token::String) -> Vector{VoiceRegion}\n\nGet available voice regions for a guild.\n\nUse this when a bot needs to list voice regions available to the guild, which may differ from the global list due to VIP server status.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 403 if the bot is not in the guild.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_voice_regions"},{"category":"function","location":"api/#Accord.get_guild_invites","page":"API Reference","text":"get_guild_invites(rl::RateLimiter, guild_id::Snowflake; token::String) -> Vector{Invite}\n\nGet all invites in a guild.\n\nUse this when a bot needs to list active invites for moderation, analytics, or invite management purposes.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_invites"},{"category":"function","location":"api/#Accord.get_guild_integrations","page":"API Reference","text":"get_guild_integrations(rl::RateLimiter, guild_id::Snowflake; token::String) -> Vector{Integration}\n\nGet all integrations for a guild.\n\nUse this when a bot needs to list connected integrations such as Twitch, YouTube, or other third-party services.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_integrations"},{"category":"function","location":"api/#Accord.delete_guild_integration","page":"API Reference","text":"delete_guild_integration(rl::RateLimiter, guild_id::Snowflake, integration_id::Snowflake; token::String, reason=nothing)\n\nDelete an integration from a guild.\n\nUse this when a bot needs to remove third-party integrations from the guild.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nintegration_id::Snowflake — The ID of the integration to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the deletion (optional).\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the integration or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_guild_integration"},{"category":"function","location":"api/#Accord.get_guild_widget_settings","page":"API Reference","text":"get_guild_widget_settings(rl::RateLimiter, guild_id::Snowflake; token::String) -> Dict{String, Any}\n\nGet the guild widget settings.\n\nUse this when a bot needs to check the widget configuration, such as whether the widget is enabled and which channel it displays.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_widget_settings"},{"category":"function","location":"api/#Accord.modify_guild_widget","page":"API Reference","text":"modify_guild_widget(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict, reason=nothing) -> Dict{String, Any}\n\nModify the guild widget settings.\n\nUse this when a bot needs to enable/disable the widget or change the widget channel.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Widget settings (enabled, channel_id).\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_guild_widget"},{"category":"function","location":"api/#Accord.get_guild_widget","page":"API Reference","text":"get_guild_widget(rl::RateLimiter, guild_id::Snowflake; token::String) -> Dict{String, Any}\n\nGet the guild widget JSON data.\n\nUse this when a bot needs to retrieve public widget data for the guild, which can be used to display online members and invite links.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the guild widget is disabled or the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_widget"},{"category":"function","location":"api/#Accord.get_guild_vanity_url","page":"API Reference","text":"get_guild_vanity_url(rl::RateLimiter, guild_id::Snowflake; token::String) -> Invite\n\nGet the vanity URL for a guild.\n\nUse this when a bot needs to retrieve or display a guild's custom invite URL.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild has no vanity URL.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_vanity_url"},{"category":"function","location":"api/#Accord.get_guild_welcome_screen","page":"API Reference","text":"get_guild_welcome_screen(rl::RateLimiter, guild_id::Snowflake; token::String) -> WelcomeScreen\n\nGet the welcome screen for a guild.\n\nUse this when a bot needs to display or cache the guild's welcome screen, which shows description and recommended channels for new members.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the guild has no welcome screen enabled.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_welcome_screen"},{"category":"function","location":"api/#Accord.modify_guild_welcome_screen","page":"API Reference","text":"modify_guild_welcome_screen(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict, reason=nothing) -> WelcomeScreen\n\nModify the welcome screen for a guild.\n\nUse this when a bot needs to update the guild's welcome screen, such as changing the description or recommended channels.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Welcome screen settings (enabled, description, welcome_channels).\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_guild_welcome_screen"},{"category":"function","location":"api/#Accord.get_guild_onboarding","page":"API Reference","text":"get_guild_onboarding(rl::RateLimiter, guild_id::Snowflake; token::String) -> Onboarding\n\nGet the onboarding configuration for a guild.\n\nUse this when a bot needs to retrieve the guild's onboarding prompts and settings for new member guidance.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_onboarding"},{"category":"function","location":"api/#Accord.modify_guild_onboarding","page":"API Reference","text":"modify_guild_onboarding(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict, reason=nothing) -> Onboarding\n\nModify the onboarding configuration for a guild.\n\nUse this when a bot needs to update the guild's onboarding prompts, default channels, or other new member guidance settings.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Onboarding configuration (prompts, defaultchannelids, etc.).\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_guild_onboarding"},{"category":"function","location":"api/#Accord.start_thread_from_message","page":"API Reference","text":"start_thread_from_message(rl::RateLimiter, channel_id::Snowflake, message_id::Snowflake; token::String, body::Dict, reason=nothing) -> DiscordChannel\n\nCreate a new thread from an existing message.\n\nUse this when a bot needs to create a discussion thread around a specific message, such as for off-topic conversations or detailed discussions.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the parent channel (must support threads).\nmessage_id::Snowflake — The ID of the message to start the thread from.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Thread settings (name, autoarchiveduration, ratelimitper_user).\nreason::String — Audit log reason for creating the thread (optional).\n\nPermissions\n\nRequires CREATE_PUBLIC_THREADS for public threads.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel or message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.start_thread_from_message"},{"category":"function","location":"api/#Accord.start_thread_without_message","page":"API Reference","text":"start_thread_without_message(rl::RateLimiter, channel_id::Snowflake; token::String, body::Dict, reason=nothing) -> DiscordChannel\n\nCreate a new thread without an existing message.\n\nUse this when a bot needs to create a standalone thread, such as for announcements, support tickets, or scheduled discussions.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the parent channel (must support threads).\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Thread settings (name, type, autoarchiveduration, etc.).\nreason::String — Audit log reason for creating the thread (optional).\n\nPermissions\n\nRequires CREATE_PUBLIC_THREADS for public threads or CREATE_PRIVATE_THREADS for private threads.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.start_thread_without_message"},{"category":"function","location":"api/#Accord.start_thread_in_forum","page":"API Reference","text":"start_thread_in_forum(rl::RateLimiter, channel_id::Snowflake; token::String, body::Dict, files=nothing, reason=nothing) -> DiscordChannel\n\nCreate a new post in a forum channel.\n\nUse this when a bot needs to create a forum post with optional attachments, such as for automated announcements, support tickets, or content sharing.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the forum channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Post settings (name, message, applied_tags).\nfiles — File attachments for the post (optional).\nreason::String — Audit log reason for creating the post (optional).\n\nPermissions\n\nRequires SEND_MESSAGES in the forum channel.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.start_thread_in_forum"},{"category":"function","location":"api/#Accord.join_thread","page":"API Reference","text":"join_thread(rl::RateLimiter, channel_id::Snowflake; token::String)\n\nAdd the bot user to a thread.\n\nUse this when a bot needs to join a thread to send messages or receive events from it, such as when participating in a conversation.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the thread (threads are also channels).\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 403 if the thread is private and the bot wasn't added.\nHTTP 404 if the thread does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.join_thread"},{"category":"function","location":"api/#Accord.add_thread_member","page":"API Reference","text":"add_thread_member(rl::RateLimiter, channel_id::Snowflake, user_id::Snowflake; token::String)\n\nAdd another user to a thread.\n\nUse this when a bot needs to add a specific user to a thread, such as for moderation purposes or bringing someone into a conversation.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the thread.\nuser_id::Snowflake — The ID of the user to add.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_THREADS to add members to private threads.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the thread or user does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.add_thread_member"},{"category":"function","location":"api/#Accord.leave_thread","page":"API Reference","text":"leave_thread(rl::RateLimiter, channel_id::Snowflake; token::String)\n\nRemove the bot user from a thread.\n\nUse this when a bot no longer needs to participate in a thread or when cleaning up thread memberships.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the thread.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the thread does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.leave_thread"},{"category":"function","location":"api/#Accord.remove_thread_member","page":"API Reference","text":"remove_thread_member(rl::RateLimiter, channel_id::Snowflake, user_id::Snowflake; token::String)\n\nRemove a user from a thread.\n\nUse this when a bot needs to remove someone from a thread, such as for moderation purposes or managing private thread access.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the thread.\nuser_id::Snowflake — The ID of the user to remove.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_THREADS to remove members from private threads.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the thread or user does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.remove_thread_member"},{"category":"function","location":"api/#Accord.get_thread_member","page":"API Reference","text":"get_thread_member(rl::RateLimiter, channel_id::Snowflake, user_id::Snowflake; token::String, with_member::Bool=false) -> ThreadMember\n\nGet a thread member object for a user.\n\nUse this when a bot needs to check a user's thread membership status or retrieve their thread-specific member information.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the thread.\nuser_id::Snowflake — The ID of the user.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nwith_member::Bool — Include guild member data in the response.\n\nPermissions\n\nRequires MANAGE_THREADS for private threads.\n\nErrors\n\nHTTP 403 if missing required permissions (for private threads).\nHTTP 404 if the thread or user does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_thread_member"},{"category":"function","location":"api/#Accord.list_thread_members","page":"API Reference","text":"list_thread_members(rl::RateLimiter, channel_id::Snowflake; token::String, with_member::Bool=false, limit::Int=100) -> Vector{ThreadMember}\n\nGet all members of a thread.\n\nUse this when a bot needs to list participants in a thread, such as for thread management or notification purposes.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the thread.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nwith_member::Bool — Include guild member data for each member.\nlimit::Int — Maximum number of members to return (1-100, default 100).\n\nPermissions\n\nRequires MANAGE_THREADS for private threads.\n\nErrors\n\nHTTP 403 if missing required permissions (for private threads).\nHTTP 404 if the thread does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_thread_members"},{"category":"function","location":"api/#Accord.list_public_archived_threads","page":"API Reference","text":"list_public_archived_threads(rl::RateLimiter, channel_id::Snowflake; token::String, limit::Int=50) -> Dict{String, Any}\n\nGet archived public threads in a channel.\n\nUse this when a bot needs to browse or search through archived public threads, such as for thread discovery or archival features.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the parent channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nlimit::Int — Maximum threads to return (default 50).\n\nErrors\n\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_public_archived_threads"},{"category":"function","location":"api/#Accord.list_private_archived_threads","page":"API Reference","text":"list_private_archived_threads(rl::RateLimiter, channel_id::Snowflake; token::String, limit::Int=50) -> Dict{String, Any}\n\nGet archived private threads in a channel.\n\nUse this when a bot needs to browse private archived threads that the bot has access to, such as for moderation or content management.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the parent channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nlimit::Int — Maximum threads to return (default 50).\n\nPermissions\n\nRequires MANAGE_THREADS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_private_archived_threads"},{"category":"function","location":"api/#Accord.list_joined_private_archived_threads","page":"API Reference","text":"list_joined_private_archived_threads(rl::RateLimiter, channel_id::Snowflake; token::String, limit::Int=50) -> Dict{String, Any}\n\nGet archived private threads that the bot has joined in a channel.\n\nUse this when a bot needs to list private threads it has access to through membership, such as for thread management or notification purposes.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the parent channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nlimit::Int — Maximum threads to return (default 50).\n\nErrors\n\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_joined_private_archived_threads"},{"category":"function","location":"api/#Accord.list_active_guild_threads","page":"API Reference","text":"list_active_guild_threads(rl::RateLimiter, guild_id::Snowflake; token::String) -> Dict{String, Any}\n\nGet all active threads in a guild.\n\nUse this when a bot needs to list active threads for thread management, moderation, or archival purposes.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 403 if the bot is not in the guild.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_active_guild_threads"},{"category":"function","location":"api/#Accord.get_global_application_commands","page":"API Reference","text":"get_global_application_commands(rl::RateLimiter, application_id::Snowflake; token::String, with_localizations::Bool=false) -> Vector{ApplicationCommand}\n\nGet all global application commands for the bot.\n\nUse this when a bot needs to list or sync its global slash commands. Global commands are available in all guilds and take up to an hour to propagate.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nwith_localizations::Bool — Include name and description localizations.\n\nErrors\n\nHTTP 401 if the token is invalid.\nHTTP 404 if the application does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_global_application_commands"},{"category":"function","location":"api/#Accord.create_global_application_command","page":"API Reference","text":"create_global_application_command(rl::RateLimiter, application_id::Snowflake; token::String, body::Dict) -> ApplicationCommand\n\nCreate a new global application command.\n\nUse this when a bot needs to register a new global slash command, context menu command, or autocomplete command.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Command definition (name, description, type, options, etc.).\n\nErrors\n\nHTTP 400 if the command data is invalid or name/description requirements not met.\nHTTP 401 if the token is invalid.\nHTTP 429 if too many commands created (limit is 100 global commands).\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_global_application_command"},{"category":"function","location":"api/#Accord.get_global_application_command","page":"API Reference","text":"get_global_application_command(rl::RateLimiter, application_id::Snowflake, command_id::Snowflake; token::String) -> ApplicationCommand\n\nGet a specific global application command.\n\nUse this when a bot needs to retrieve details of a specific global command, such as for editing or inspection.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\ncommand_id::Snowflake — The ID of the command.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the command does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_global_application_command"},{"category":"function","location":"api/#Accord.edit_global_application_command","page":"API Reference","text":"edit_global_application_command(rl::RateLimiter, application_id::Snowflake, command_id::Snowflake; token::String, body::Dict) -> ApplicationCommand\n\nEdit a global application command.\n\nUse this when a bot needs to update an existing global command's name, description, options, or other properties.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\ncommand_id::Snowflake — The ID of the command to edit.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated command fields.\n\nErrors\n\nHTTP 400 if the updated data is invalid.\nHTTP 404 if the command does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.edit_global_application_command"},{"category":"function","location":"api/#Accord.delete_global_application_command","page":"API Reference","text":"delete_global_application_command(rl::RateLimiter, application_id::Snowflake, command_id::Snowflake; token::String)\n\nDelete a global application command.\n\nUse this when a bot needs to remove a global command. Deletion is irreversible and will immediately remove the command from all guilds.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\ncommand_id::Snowflake — The ID of the command to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the command does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_global_application_command"},{"category":"function","location":"api/#Accord.bulk_overwrite_global_application_commands","page":"API Reference","text":"bulk_overwrite_global_application_commands(rl::RateLimiter, application_id::Snowflake; token::String, body::Vector) -> Vector{ApplicationCommand}\n\nReplace all global application commands with a new set.\n\nUse this when a bot needs to perform a complete command sync, such as during startup or when updating all commands at once. This is more efficient than creating commands individually.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Vector — Array of command definitions to set.\n\nErrors\n\nHTTP 400 if any command data is invalid.\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.bulk_overwrite_global_application_commands"},{"category":"function","location":"api/#Accord.get_guild_application_commands","page":"API Reference","text":"get_guild_application_commands(rl::RateLimiter, application_id::Snowflake, guild_id::Snowflake; token::String, with_localizations::Bool=false) -> Vector{ApplicationCommand}\n\nGet all application commands for a specific guild.\n\nUse this when a bot needs to list guild-specific commands, which take precedence over global commands in that guild.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nwith_localizations::Bool — Include name and description localizations.\n\nPermissions\n\nRequires VIEW_CHANNEL in the guild.\n\nErrors\n\nHTTP 403 if the bot is not in the guild.\nHTTP 404 if the guild or application does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_application_commands"},{"category":"function","location":"api/#Accord.create_guild_application_command","page":"API Reference","text":"create_guild_application_command(rl::RateLimiter, application_id::Snowflake, guild_id::Snowflake; token::String, body::Dict) -> ApplicationCommand\n\nCreate a guild-specific application command.\n\nUse this when a bot needs to register a command that is only available in a specific guild. Guild commands are available immediately (no propagation delay).\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Command definition.\n\nPermissions\n\nRequires VIEW_CHANNEL in the guild.\n\nErrors\n\nHTTP 400 if the command data is invalid.\nHTTP 403 if the bot is not in the guild.\nHTTP 429 if too many commands created (limit is 100 guild commands).\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_guild_application_command"},{"category":"function","location":"api/#Accord.get_guild_application_command","page":"API Reference","text":"get_guild_application_command(rl::RateLimiter, application_id::Snowflake, guild_id::Snowflake, command_id::Snowflake; token::String) -> ApplicationCommand\n\nGet a specific guild application command.\n\nUse this when a bot needs to retrieve details of a guild-specific command.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nguild_id::Snowflake — The ID of the guild.\ncommand_id::Snowflake — The ID of the command.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the command does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_application_command"},{"category":"function","location":"api/#Accord.edit_guild_application_command","page":"API Reference","text":"edit_guild_application_command(rl::RateLimiter, application_id::Snowflake, guild_id::Snowflake, command_id::Snowflake; token::String, body::Dict) -> ApplicationCommand\n\nEdit a guild-specific application command.\n\nUse this when a bot needs to update a guild command's properties.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nguild_id::Snowflake — The ID of the guild.\ncommand_id::Snowflake — The ID of the command to edit.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated command fields.\n\nErrors\n\nHTTP 400 if the updated data is invalid.\nHTTP 404 if the command does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.edit_guild_application_command"},{"category":"function","location":"api/#Accord.delete_guild_application_command","page":"API Reference","text":"delete_guild_application_command(rl::RateLimiter, application_id::Snowflake, guild_id::Snowflake, command_id::Snowflake; token::String)\n\nDelete a guild-specific application command.\n\nUse this when a bot needs to remove a guild command. Changes are immediate.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nguild_id::Snowflake — The ID of the guild.\ncommand_id::Snowflake — The ID of the command to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the command does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_guild_application_command"},{"category":"function","location":"api/#Accord.bulk_overwrite_guild_application_commands","page":"API Reference","text":"bulk_overwrite_guild_application_commands(rl::RateLimiter, application_id::Snowflake, guild_id::Snowflake; token::String, body::Vector) -> Vector{ApplicationCommand}\n\nReplace all guild application commands with a new set.\n\nUse this when a bot needs to perform a complete guild command sync. This is more efficient than updating commands individually and takes effect immediately.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Vector — Array of command definitions to set.\n\nErrors\n\nHTTP 400 if any command data is invalid.\nHTTP 403 if the bot is not in the guild.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.bulk_overwrite_guild_application_commands"},{"category":"function","location":"api/#Accord.get_guild_application_command_permissions","page":"API Reference","text":"get_guild_application_command_permissions(rl::RateLimiter, application_id::Snowflake, guild_id::Snowflake; token::String) -> Vector{Dict{String, Any}}\n\nGet permissions for all commands in a guild.\n\nUse this when a bot needs to list command permission overwrites for a guild, showing which roles and users can use specific commands.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires ADMINISTRATOR or application ownership.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild or application does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_application_command_permissions"},{"category":"function","location":"api/#Accord.get_application_command_permissions","page":"API Reference","text":"get_application_command_permissions(rl::RateLimiter, application_id::Snowflake, guild_id::Snowflake, command_id::Snowflake; token::String) -> Dict{String, Any}\n\nGet permissions for a specific command in a guild.\n\nUse this when a bot needs to check the permission overwrites for a specific guild command.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nguild_id::Snowflake — The ID of the guild.\ncommand_id::Snowflake — The ID of the command.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires ADMINISTRATOR or application ownership.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the command or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_application_command_permissions"},{"category":"function","location":"api/#Accord.edit_application_command_permissions","page":"API Reference","text":"edit_application_command_permissions(rl::RateLimiter, application_id::Snowflake, guild_id::Snowflake, command_id::Snowflake; token::String, body::Dict) -> Dict{String, Any}\n\nEdit permissions for a specific command in a guild.\n\nUse this when a bot needs to restrict or grant command access to specific roles or users in a guild.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nguild_id::Snowflake — The ID of the guild.\ncommand_id::Snowflake — The ID of the command.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Permission overwrites array.\n\nPermissions\n\nRequires ADMINISTRATOR.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the command or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.edit_application_command_permissions"},{"category":"function","location":"api/#Accord.create_interaction_response","page":"API Reference","text":"create_interaction_response(rl::RateLimiter, interaction_id::Snowflake, interaction_token::String; token::String, body::Dict, files=nothing)\n\nSend a response to an interaction.\n\nUse this when a bot needs to respond to a slash command, button press, select menu choice, or modal submission. Must be sent within 3 seconds of receiving the interaction.\n\nwarning: Warning\nThis endpoint bypasses the rate limiter to meet the 3-second Discord timeout.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance (not used for throttling).\ninteraction_id::Snowflake — The ID of the interaction.\ninteraction_token::String — The interaction token from the gateway event.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Response data (type, content, embeds, components, etc.).\nfiles — File attachments (optional).\n\nResponse Types\n\n1 — Pong (for ping)\n4 — Channel message with source\n5 — Deferred channel message with source\n6 — Deferred update message (for components)\n7 — Update message (for components)\n9 — Application command autocomplete result\n10 — Modal\n\nErrors\n\nHTTP 400 if the response data is invalid.\nHTTP 401 if the interaction token is invalid.\nHTTP 429 if responding too frequently to the same interaction.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_interaction_response"},{"category":"function","location":"api/#Accord.get_original_interaction_response","page":"API Reference","text":"get_original_interaction_response(rl::RateLimiter, application_id::Snowflake, interaction_token::String; token::String) -> Message\n\nGet the original response message for an interaction.\n\nUse this when a bot needs to fetch the message that was sent as the initial interaction response, such as for editing or reference.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\ninteraction_token::String — The interaction token.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if no response message exists.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_original_interaction_response"},{"category":"function","location":"api/#Accord.edit_original_interaction_response","page":"API Reference","text":"edit_original_interaction_response(rl::RateLimiter, application_id::Snowflake, interaction_token::String; token::String, body::Dict, files=nothing) -> Message\n\nEdit the original response message for an interaction.\n\nUse this when a bot needs to update the message that was sent as the initial response, such as to show updated information or results.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\ninteraction_token::String — The interaction token.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated message content.\nfiles — New file attachments (optional).\n\nErrors\n\nHTTP 400 if the message data is invalid.\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.edit_original_interaction_response"},{"category":"function","location":"api/#Accord.delete_original_interaction_response","page":"API Reference","text":"delete_original_interaction_response(rl::RateLimiter, application_id::Snowflake, interaction_token::String; token::String)\n\nDelete the original response message for an interaction.\n\nUse this when a bot needs to remove the message that was sent as the initial response.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\ninteraction_token::String — The interaction token.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_original_interaction_response"},{"category":"function","location":"api/#Accord.create_followup_message","page":"API Reference","text":"create_followup_message(rl::RateLimiter, application_id::Snowflake, interaction_token::String; token::String, body::Dict, files=nothing) -> Message\n\nCreate a followup message for an interaction.\n\nUse this when a bot needs to send additional messages after the initial response, such as for multi-step interactions or additional notifications.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\ninteraction_token::String — The interaction token.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Message content.\nfiles — File attachments (optional).\n\nErrors\n\nHTTP 400 if the message data is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_followup_message"},{"category":"function","location":"api/#Accord.get_followup_message","page":"API Reference","text":"get_followup_message(rl::RateLimiter, application_id::Snowflake, interaction_token::String, message_id::Snowflake; token::String) -> Message\n\nGet a specific followup message for an interaction.\n\nUse this when a bot needs to retrieve a previously sent followup message.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\ninteraction_token::String — The interaction token.\nmessage_id::Snowflake — The ID of the followup message.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_followup_message"},{"category":"function","location":"api/#Accord.edit_followup_message","page":"API Reference","text":"edit_followup_message(rl::RateLimiter, application_id::Snowflake, interaction_token::String, message_id::Snowflake; token::String, body::Dict, files=nothing) -> Message\n\nEdit a followup message for an interaction.\n\nUse this when a bot needs to update a previously sent followup message, such as to correct information or show updated status.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\ninteraction_token::String — The interaction token.\nmessage_id::Snowflake — The ID of the followup message to edit.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated message content.\nfiles — New file attachments (optional).\n\nErrors\n\nHTTP 400 if the message data is invalid.\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.edit_followup_message"},{"category":"function","location":"api/#Accord.delete_followup_message","page":"API Reference","text":"delete_followup_message(rl::RateLimiter, application_id::Snowflake, interaction_token::String, message_id::Snowflake; token::String)\n\nDelete a followup message for an interaction.\n\nUse this when a bot needs to remove a previously sent followup message.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\ninteraction_token::String — The interaction token.\nmessage_id::Snowflake — The ID of the followup message to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the message does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_followup_message"},{"category":"function","location":"api/#Accord.get_current_user","page":"API Reference","text":"get_current_user(rl::RateLimiter; token::String) -> User\n\nGet the bot's own user object.\n\nUse this when a bot needs to retrieve its own user information, such as username, ID, avatar, and discriminator. This is commonly used during initialization to confirm authentication.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the token is invalid or expired.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_current_user"},{"category":"function","location":"api/#Accord.get_user","page":"API Reference","text":"get_user(rl::RateLimiter, user_id::Snowflake; token::String) -> User\n\nGet a user by ID.\n\nUse this when a bot needs to retrieve information about a specific user, such as username, avatar, or public flags. Only returns public information.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nuser_id::Snowflake — The ID of the user to retrieve.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the user does not exist.\n\nDiscord docs\n\n\n\n\n\nget_user(client::Client, user_id::Snowflake) -> User\n\nUse this to retrieve user information, with automatic caching for performance.\n\nGet a user by ID. Checks the local state cache first.\n\nExample\n\nuser = get_user(client, user_id)\nprintln(\"User tag: \", user.username, \"#\", user.discriminator)\n\n\n\n\n\n","title":"Accord.get_user"},{"category":"function","location":"api/#Accord.modify_current_user","page":"API Reference","text":"modify_current_user(rl::RateLimiter; token::String, body::Dict) -> User\n\nModify the bot's own user account settings.\n\nUse this when a bot needs to update its own profile, such as changing its username or avatar. Use with caution as username changes are rate limited.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — User fields to update (username, avatar base64).\n\nRate Limits\n\nUsername changes are heavily rate limited (typically twice per hour).\n\nErrors\n\nHTTP 400 if the username or avatar is invalid.\nHTTP 401 if the token is invalid.\nHTTP 429 if too many username changes attempted.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_current_user"},{"category":"function","location":"api/#Accord.get_current_user_guilds","page":"API Reference","text":"get_current_user_guilds(rl::RateLimiter; token::String, limit::Int=200, before::Optional{Snowflake}=missing, after::Optional{Snowflake}=missing) -> Vector{Guild}\n\nGet the guilds the bot is a member of.\n\nUse this when a bot needs to list the servers it has joined, such as for guild management features or admin dashboards.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nlimit::Int — Maximum guilds to return (1-200, default 200).\nbefore::Snowflake — Get guilds before this guild ID.\nafter::Snowflake — Get guilds after this guild ID.\n\nErrors\n\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_current_user_guilds"},{"category":"function","location":"api/#Accord.get_current_user_guild_member","page":"API Reference","text":"get_current_user_guild_member(rl::RateLimiter, guild_id::Snowflake; token::String) -> Member\n\nGet the bot's guild member object for a specific guild.\n\nUse this when a bot needs to check its own permissions, roles, or nickname in a particular server, such as for permission validation before actions.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the bot is not a member of the guild.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_current_user_guild_member"},{"category":"function","location":"api/#Accord.create_dm","page":"API Reference","text":"create_dm(rl::RateLimiter; token::String, recipient_id::Snowflake) -> DiscordChannel\n\nCreate a direct message channel with a user.\n\nUse this when a bot needs to initiate a private conversation with a user, such as for sending DMs, confirmation messages, or support interactions.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nrecipient_id::Snowflake — The ID of the user to create a DM with.\n\nNotes\n\nYou should not use this endpoint to spam users or send unsolicited messages.\nThe bot cannot DM users who have not enabled DMs from server members.\n\nErrors\n\nHTTP 400 if the user cannot be messaged.\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_dm"},{"category":"function","location":"api/#Accord.get_current_user_connections","page":"API Reference","text":"get_current_user_connections(rl::RateLimiter; token::String) -> Vector{Connection}\n\nGet the third-party connections linked to the bot's account.\n\nUse this when a bot needs to retrieve connected services such as Twitch, YouTube, Spotify, or other OAuth-linked platforms. Note that bots typically do not have connections, this is more useful for OAuth2 applications.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\n\nKeyword Arguments\n\ntoken::String — Authentication token (can be OAuth2 user token).\n\nErrors\n\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_current_user_connections"},{"category":"function","location":"api/#Accord.get_current_user_application_role_connection","page":"API Reference","text":"get_current_user_application_role_connection(rl::RateLimiter, application_id::Snowflake; token::String) -> Dict{String, Any}\n\nGet the role connection metadata for the bot's account.\n\nUse this when a bot needs to retrieve Linked Role verification data for the current user (typically used with OAuth2 applications for role verification).\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\n\nKeyword Arguments\n\ntoken::String — Authentication token (typically OAuth2 user token).\n\nErrors\n\nHTTP 401 if the token is invalid.\nHTTP 404 if no role connection exists.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_current_user_application_role_connection"},{"category":"function","location":"api/#Accord.update_current_user_application_role_connection","page":"API Reference","text":"update_current_user_application_role_connection(rl::RateLimiter, application_id::Snowflake; token::String, body::Dict) -> Dict{String, Any}\n\nUpdate the role connection metadata for the bot's account.\n\nUse this when a bot needs to update Linked Role verification data, such as for applications that provide role verification based on external platform data.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\n\nKeyword Arguments\n\ntoken::String — Authentication token (typically OAuth2 user token).\nbody::Dict — Role connection metadata (platformname, platformusername, metadata).\n\nErrors\n\nHTTP 400 if the metadata is invalid.\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.update_current_user_application_role_connection"},{"category":"function","location":"api/#Accord.get_gateway_bot","page":"API Reference","text":"get_gateway_bot(token::String) -> (url, shards, session_start_limit)\n\nUse this to retrieve gateway connection info and determine how many shards your bot needs.\n\nFetch /gateway/bot to get recommended shard count and session limits.\n\nExample\n\ninfo = get_gateway_bot(\"Bot my_token\")\nprintln(\"Recommended shards: \", info.shards)\nprintln(\"Remaining sessions: \", info.session_start_limit[\"remaining\"])\n\n\n\n\n\n","title":"Accord.get_gateway_bot"},{"category":"function","location":"api/#Accord.create_webhook","page":"API Reference","text":"create_webhook(rl::RateLimiter, channel_id::Snowflake; token::String, body::Dict, reason=nothing) -> Webhook\n\nCreate a new webhook in a channel.\n\nUse this when a bot needs to create webhooks for external message posting, such as for GitHub notifications, RSS feeds, or third-party integrations.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the channel where the webhook will be created.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Webhook settings (name, avatar).\nreason::String — Audit log reason for the creation (optional).\n\nPermissions\n\nRequires MANAGE_WEBHOOKS.\n\nErrors\n\nHTTP 400 if the webhook name is invalid or too long (max 80 characters).\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_webhook"},{"category":"function","location":"api/#Accord.get_channel_webhooks","page":"API Reference","text":"get_channel_webhooks(rl::RateLimiter, channel_id::Snowflake; token::String) -> Vector{Webhook}\n\nGet all webhooks in a channel.\n\nUse this when a bot needs to list webhooks for management, such as for webhook configuration commands or cleanup utilities.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_WEBHOOKS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_channel_webhooks"},{"category":"function","location":"api/#Accord.get_guild_webhooks","page":"API Reference","text":"get_guild_webhooks(rl::RateLimiter, guild_id::Snowflake; token::String) -> Vector{Webhook}\n\nGet all webhooks in a guild.\n\nUse this when a bot needs to list all webhooks across a guild, such as for audit or bulk webhook management.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_WEBHOOKS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_webhooks"},{"category":"function","location":"api/#Accord.get_webhook","page":"API Reference","text":"get_webhook(rl::RateLimiter, webhook_id::Snowflake; token::String) -> Webhook\n\nGet a webhook by ID.\n\nUse this when a bot needs to retrieve webhook details, such as for configuration checking or validation.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nwebhook_id::Snowflake — The ID of the webhook.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_WEBHOOKS in the webhook's channel.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the webhook does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_webhook"},{"category":"function","location":"api/#Accord.get_webhook_with_token","page":"API Reference","text":"get_webhook_with_token(rl::RateLimiter, webhook_id::Snowflake, webhook_token::String; token::String) -> Webhook\n\nGet a webhook using its token.\n\nUse this when external services need to fetch webhook information using only the webhook URL components (ID and token), without needing bot authentication.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nwebhook_id::Snowflake — The ID of the webhook.\nwebhook_token::String — The webhook token.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token (for additional validation).\n\nErrors\n\nHTTP 401 if the webhook token is invalid.\nHTTP 404 if the webhook does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_webhook_with_token"},{"category":"function","location":"api/#Accord.modify_webhook","page":"API Reference","text":"modify_webhook(rl::RateLimiter, webhook_id::Snowflake; token::String, body::Dict, reason=nothing) -> Webhook\n\nModify a webhook.\n\nUse this when a bot needs to update webhook settings such as name, avatar, or channel location.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nwebhook_id::Snowflake — The ID of the webhook.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated webhook fields (name, avatar, channel_id).\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_WEBHOOKS in the webhook's channel.\n\nErrors\n\nHTTP 400 if the webhook name is invalid.\nHTTP 403 if missing required permissions.\nHTTP 404 if the webhook does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_webhook"},{"category":"function","location":"api/#Accord.modify_webhook_with_token","page":"API Reference","text":"modify_webhook_with_token(rl::RateLimiter, webhook_id::Snowflake, webhook_token::String; body::Dict, reason=nothing) -> Webhook\n\nModify a webhook using its token.\n\nUse this when external services need to update webhook settings without requiring bot authentication, using only the webhook credentials.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nwebhook_id::Snowflake — The ID of the webhook.\nwebhook_token::String — The webhook token.\n\nKeyword Arguments\n\nbody::Dict — Updated webhook fields.\nreason::String — Audit log reason (optional, requires bot auth).\n\nErrors\n\nHTTP 400 if the webhook name is invalid.\nHTTP 401 if the webhook token is invalid.\nHTTP 404 if the webhook does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_webhook_with_token"},{"category":"function","location":"api/#Accord.delete_webhook","page":"API Reference","text":"delete_webhook(rl::RateLimiter, webhook_id::Snowflake; token::String, reason=nothing)\n\nDelete a webhook permanently.\n\nUse this when a bot needs to remove webhooks, such as for cleanup of unused webhooks or webhook management commands.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nwebhook_id::Snowflake — The ID of the webhook.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the deletion (optional).\n\nPermissions\n\nRequires MANAGE_WEBHOOKS in the webhook's channel.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the webhook does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_webhook"},{"category":"function","location":"api/#Accord.delete_webhook_with_token","page":"API Reference","text":"delete_webhook_with_token(rl::RateLimiter, webhook_id::Snowflake, webhook_token::String; reason=nothing)\n\nDelete a webhook using its token.\n\nUse this when external services need to delete webhooks without requiring bot authentication, using only the webhook credentials.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nwebhook_id::Snowflake — The ID of the webhook.\nwebhook_token::String — The webhook token.\n\nKeyword Arguments\n\nreason::String — Audit log reason (optional, requires bot auth).\n\nErrors\n\nHTTP 401 if the webhook token is invalid.\nHTTP 404 if the webhook does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_webhook_with_token"},{"category":"function","location":"api/#Accord.execute_webhook","page":"API Reference","text":"execute_webhook(rl::RateLimiter, webhook_id::Snowflake, webhook_token::String; token::String, body::Dict, files=nothing, wait::Bool=false, thread_id=nothing) -> Union{Message, Response}\n\nExecute a webhook to send a message.\n\nUse this when a bot or external service needs to post messages via webhook, such as for cross-platform notifications or automated announcements.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nwebhook_id::Snowflake — The ID of the webhook.\nwebhook_token::String — The webhook token.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Message content (content, embeds, components, etc.).\nfiles — File attachments (optional).\nwait::Bool — Wait for server confirmation and return the created message.\nthread_id — Send to a specific forum thread or channel thread.\n\nErrors\n\nHTTP 400 if the message data is invalid.\nHTTP 401 if the webhook token is invalid.\nHTTP 404 if the webhook does not exist.\nHTTP 429 if rate limited (webhooks have their own rate limits).\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.execute_webhook"},{"category":"function","location":"api/#Accord.get_webhook_message","page":"API Reference","text":"get_webhook_message(rl::RateLimiter, webhook_id::Snowflake, webhook_token::String, message_id::Snowflake; token::String) -> Message\n\nGet a message sent by a webhook.\n\nUse this when a bot needs to retrieve a message that was previously sent via webhook, such as for editing or reference.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nwebhook_id::Snowflake — The ID of the webhook.\nwebhook_token::String — The webhook token.\nmessage_id::Snowflake — The ID of the message.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the webhook token is invalid.\nHTTP 404 if the message or webhook does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_webhook_message"},{"category":"function","location":"api/#Accord.edit_webhook_message","page":"API Reference","text":"edit_webhook_message(rl::RateLimiter, webhook_id::Snowflake, webhook_token::String, message_id::Snowflake; token::String, body::Dict, files=nothing) -> Message\n\nEdit a message sent by a webhook.\n\nUse this when a bot or external service needs to update a previously sent webhook message, such as to correct information or show progress.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nwebhook_id::Snowflake — The ID of the webhook.\nwebhook_token::String — The webhook token.\nmessage_id::Snowflake — The ID of the message to edit.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated message content.\nfiles — New file attachments (optional).\n\nErrors\n\nHTTP 400 if the message data is invalid.\nHTTP 401 if the webhook token is invalid.\nHTTP 404 if the message or webhook does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.edit_webhook_message"},{"category":"function","location":"api/#Accord.delete_webhook_message","page":"API Reference","text":"delete_webhook_message(rl::RateLimiter, webhook_id::Snowflake, webhook_token::String, message_id::Snowflake; token::String)\n\nDelete a message sent by a webhook.\n\nUse this when a bot needs to remove a previously sent webhook message.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nwebhook_id::Snowflake — The ID of the webhook.\nwebhook_token::String — The webhook token.\nmessage_id::Snowflake — The ID of the message to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the webhook token is invalid.\nHTTP 404 if the message or webhook does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_webhook_message"},{"category":"function","location":"api/#Accord.list_guild_emojis","page":"API Reference","text":"list_guild_emojis(rl::RateLimiter, guild_id::Snowflake; token::String) -> Vector{Emoji}\n\nGet all custom emojis in a guild.\n\nUse this when a bot needs to list available custom emojis, such as for emoji management commands or reaction role systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 403 if the bot is not in the guild.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_guild_emojis"},{"category":"function","location":"api/#Accord.get_guild_emoji","page":"API Reference","text":"get_guild_emoji(rl::RateLimiter, guild_id::Snowflake, emoji_id::Snowflake; token::String) -> Emoji\n\nGet a specific custom emoji from a guild.\n\nUse this when a bot needs to retrieve information about a single emoji, such as its name, roles, or creator.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nemoji_id::Snowflake — The ID of the emoji.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 403 if the bot is not in the guild.\nHTTP 404 if the emoji or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_emoji"},{"category":"function","location":"api/#Accord.create_guild_emoji","page":"API Reference","text":"create_guild_emoji(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict, reason=nothing) -> Emoji\n\nCreate a new custom emoji in a guild.\n\nUse this when a bot needs to upload custom emojis programmatically, such as for emoji management tools or automated emoji creation systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Emoji data (name, image base64, roles).\nreason::String — Audit log reason for the creation (optional).\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nEmoji Requirements\n\nImage must be at most 256KB in size.\nDimensions must be at least 128x128 pixels.\nSupports PNG, JPEG, or GIF formats (animated GIFs allowed with appropriate plan).\n\nErrors\n\nHTTP 400 if the image is too large or invalid format.\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_guild_emoji"},{"category":"function","location":"api/#Accord.modify_guild_emoji","page":"API Reference","text":"modify_guild_emoji(rl::RateLimiter, guild_id::Snowflake, emoji_id::Snowflake; token::String, body::Dict, reason=nothing) -> Emoji\n\nModify a custom emoji in a guild.\n\nUse this when a bot needs to update emoji properties such as name or role restrictions.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nemoji_id::Snowflake — The ID of the emoji to modify.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated emoji fields (name, roles).\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nErrors\n\nHTTP 400 if the name is invalid.\nHTTP 403 if missing required permissions.\nHTTP 404 if the emoji or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_guild_emoji"},{"category":"function","location":"api/#Accord.delete_guild_emoji","page":"API Reference","text":"delete_guild_emoji(rl::RateLimiter, guild_id::Snowflake, emoji_id::Snowflake; token::String, reason=nothing)\n\nDelete a custom emoji from a guild.\n\nUse this when a bot needs to remove custom emojis, such as for emoji cleanup or management systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nemoji_id::Snowflake — The ID of the emoji to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the deletion (optional).\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the emoji or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_guild_emoji"},{"category":"function","location":"api/#Accord.list_application_emojis","page":"API Reference","text":"list_application_emojis(rl::RateLimiter, application_id::Snowflake; token::String) -> Dict{String, Any}\n\nGet all custom emojis for an application.\n\nUse this when a bot needs to list application-owned emojis that can be used across all guilds the bot is in, such as for premium feature emojis.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the token is invalid.\nHTTP 404 if the application does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_application_emojis"},{"category":"function","location":"api/#Accord.get_application_emoji","page":"API Reference","text":"get_application_emoji(rl::RateLimiter, application_id::Snowflake, emoji_id::Snowflake; token::String) -> Emoji\n\nGet a specific application-owned emoji.\n\nUse this when a bot needs to retrieve details about an application emoji, such as for management or configuration purposes.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nemoji_id::Snowflake — The ID of the emoji.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the token is invalid.\nHTTP 404 if the emoji or application does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_application_emoji"},{"category":"function","location":"api/#Accord.create_application_emoji","page":"API Reference","text":"create_application_emoji(rl::RateLimiter, application_id::Snowflake; token::String, body::Dict) -> Emoji\n\nCreate a new application-owned emoji.\n\nUse this when a bot needs to upload emojis that can be used across all guilds the bot is in, useful for premium features or consistent branding.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Emoji data (name, image base64).\n\nEmoji Requirements\n\nImage must be at most 256KB in size.\nDimensions must be at least 128x128 pixels.\nSupports PNG, JPEG, or GIF formats.\n\nErrors\n\nHTTP 400 if the image is too large or invalid format.\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_application_emoji"},{"category":"function","location":"api/#Accord.modify_application_emoji","page":"API Reference","text":"modify_application_emoji(rl::RateLimiter, application_id::Snowflake, emoji_id::Snowflake; token::String, body::Dict) -> Emoji\n\nModify an application-owned emoji.\n\nUse this when a bot needs to update application emoji properties such as name.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nemoji_id::Snowflake — The ID of the emoji to modify.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated emoji fields (name).\n\nErrors\n\nHTTP 400 if the name is invalid.\nHTTP 401 if the token is invalid.\nHTTP 404 if the emoji does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_application_emoji"},{"category":"function","location":"api/#Accord.delete_application_emoji","page":"API Reference","text":"delete_application_emoji(rl::RateLimiter, application_id::Snowflake, emoji_id::Snowflake; token::String)\n\nDelete an application-owned emoji.\n\nUse this when a bot needs to remove application emojis, such as for cleanup or emoji management.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nemoji_id::Snowflake — The ID of the emoji to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the token is invalid.\nHTTP 404 if the emoji does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_application_emoji"},{"category":"function","location":"api/#Accord.get_sticker","page":"API Reference","text":"get_sticker(rl::RateLimiter, sticker_id::Snowflake; token::String) -> Sticker\n\nGet a sticker by ID.\n\nUse this when a bot needs to retrieve sticker information, such as for sticker preview commands or content management systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nsticker_id::Snowflake — The ID of the sticker.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if the sticker does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_sticker"},{"category":"function","location":"api/#Accord.list_sticker_packs","page":"API Reference","text":"list_sticker_packs(rl::RateLimiter; token::String) -> Dict{String, Any}\n\nGet the list of default sticker packs available to all users.\n\nUse this when a bot needs to list standard Discord sticker packs, such as for sticker browsing features or recommendations.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_sticker_packs"},{"category":"function","location":"api/#Accord.list_guild_stickers","page":"API Reference","text":"list_guild_stickers(rl::RateLimiter, guild_id::Snowflake; token::String) -> Vector{Sticker}\n\nGet all custom stickers in a guild.\n\nUse this when a bot needs to list guild-specific stickers, such as for sticker management commands or content discovery.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_guild_stickers"},{"category":"function","location":"api/#Accord.get_guild_sticker","page":"API Reference","text":"get_guild_sticker(rl::RateLimiter, guild_id::Snowflake, sticker_id::Snowflake; token::String) -> Sticker\n\nGet a specific custom sticker from a guild.\n\nUse this when a bot needs to retrieve information about a single guild sticker.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nsticker_id::Snowflake — The ID of the sticker.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the sticker or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_sticker"},{"category":"function","location":"api/#Accord.create_guild_sticker","page":"API Reference","text":"create_guild_sticker(rl::RateLimiter, guild_id::Snowflake; token::String, name::String, description::String, tags::String, file, reason=nothing) -> Sticker\n\nCreate a new custom sticker in a guild.\n\nUse this when a bot needs to upload custom stickers programmatically, such as for sticker management tools or automated sticker creation.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nname::String — Name of the sticker (2-30 characters).\ndescription::String — Description of the sticker (empty or 2-100 characters).\ntags::String — Autocomplete/suggestion tags for the sticker (max 200 characters).\nfile — Sticker image file (PNG, APNG, or Lottie JSON, max 512KB).\nreason::String — Audit log reason for the creation (optional).\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nSticker Requirements\n\nStatic stickers must be PNG or APNG format, max 320x320 pixels.\nAnimated stickers must be APNG format, max 320x320 pixels.\nFile size must not exceed 512KB.\n\nErrors\n\nHTTP 400 if the sticker data is invalid or file too large.\nHTTP 403 if missing required permissions or sticker limit reached.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_guild_sticker"},{"category":"function","location":"api/#Accord.modify_guild_sticker","page":"API Reference","text":"modify_guild_sticker(rl::RateLimiter, guild_id::Snowflake, sticker_id::Snowflake; token::String, body::Dict, reason=nothing) -> Sticker\n\nModify a custom sticker in a guild.\n\nUse this when a bot needs to update sticker properties such as name, description, or tags.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nsticker_id::Snowflake — The ID of the sticker to modify.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated sticker fields (name, description, tags).\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nErrors\n\nHTTP 400 if the sticker data is invalid.\nHTTP 403 if missing required permissions.\nHTTP 404 if the sticker or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_guild_sticker"},{"category":"function","location":"api/#Accord.delete_guild_sticker","page":"API Reference","text":"delete_guild_sticker(rl::RateLimiter, guild_id::Snowflake, sticker_id::Snowflake; token::String, reason=nothing)\n\nDelete a custom sticker from a guild.\n\nUse this when a bot needs to remove custom stickers, such as for sticker cleanup or management systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nsticker_id::Snowflake — The ID of the sticker to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the deletion (optional).\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the sticker or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_guild_sticker"},{"category":"function","location":"api/#Accord.get_invite","page":"API Reference","text":"get_invite(rl::RateLimiter, invite_code::String; token::String, with_counts::Bool=false, with_expiration::Bool=false, guild_scheduled_event_id=nothing) -> Invite\n\nGet an invite by its code.\n\nUse this when a bot needs to retrieve invite information, such as for validating invite links, checking expiration, or getting guild/channel info.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\ninvite_code::String — The invite code (e.g., \"abc123\").\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nwith_counts::Bool — Include approximate member and presence counts.\nwith_expiration::Bool — Include expiration timestamp.\nguild_scheduled_event_id — Include guild scheduled event information.\n\nErrors\n\nHTTP 404 if the invite does not exist or has expired.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_invite"},{"category":"function","location":"api/#Accord.delete_invite","page":"API Reference","text":"delete_invite(rl::RateLimiter, invite_code::String; token::String, reason=nothing) -> Invite\n\nDelete/revoke an invite.\n\nUse this when a bot needs to revoke invite links, such as for moderation purposes, invite rotation systems, or security measures.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\ninvite_code::String — The invite code to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the deletion (optional).\n\nPermissions\n\nRequires MANAGE_CHANNELS in the invite's channel or MANAGE_GUILD for any invite in the guild.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the invite does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_invite"},{"category":"function","location":"api/#Accord.get_guild_audit_log","page":"API Reference","text":"get_guild_audit_log(rl::RateLimiter, guild_id::Snowflake; token::String,\n    user_id=nothing, action_type=nothing, before=nothing, after=nothing, limit::Int=50) -> AuditLog\n\nGet the audit log for a guild.\n\nUse this when a bot needs to retrieve guild moderation history, such as for audit dashboards, logging systems, or tracking administrative actions.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nuser_id::Snowflake — Filter by user who made the changes.\naction_type::Int — Filter by action type (see AuditLogEventTypes).\nbefore::Snowflake — Filter entries before this entry ID.\nafter::Snowflake — Filter entries after this entry ID.\nlimit::Int — Maximum entries to return (1-100, default 50).\n\nPermissions\n\nRequires VIEW_AUDIT_LOG.\n\nRate Limits\n\nThis endpoint has stricter rate limits than most endpoints due to the sensitivity of audit log data.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_audit_log"},{"category":"function","location":"api/#Accord.list_auto_moderation_rules","page":"API Reference","text":"list_auto_moderation_rules(rl::RateLimiter, guild_id::Snowflake; token::String) -> Vector{AutoModRule}\n\nGet all AutoMod rules for a guild.\n\nUse this when a bot needs to list configured AutoMod rules, such as for moderation dashboards or rule management commands.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_auto_moderation_rules"},{"category":"function","location":"api/#Accord.get_auto_moderation_rule","page":"API Reference","text":"get_auto_moderation_rule(rl::RateLimiter, guild_id::Snowflake, rule_id::Snowflake; token::String) -> AutoModRule\n\nGet a specific AutoMod rule.\n\nUse this when a bot needs to retrieve details of a single AutoMod rule, such as for editing or displaying rule information.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nrule_id::Snowflake — The ID of the rule.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the rule or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_auto_moderation_rule"},{"category":"function","location":"api/#Accord.create_auto_moderation_rule","page":"API Reference","text":"create_auto_moderation_rule(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict, reason=nothing) -> AutoModRule\n\nCreate a new AutoMod rule.\n\nUse this when a bot needs to set up automatic moderation rules, such as for content filtering, keyword detection, or spam prevention.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Rule configuration (name, eventtype, triggertype, actions, etc.).\nreason::String — Audit log reason for the creation (optional).\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nRule Limits\n\nMaximum 5 rules per guild for most trigger types.\nMaximum 6 MENTION_SPAM rules per guild.\n\nErrors\n\nHTTP 400 if the rule configuration is invalid.\nHTTP 403 if missing required permissions.\nHTTP 429 if too many rules created.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_auto_moderation_rule"},{"category":"function","location":"api/#Accord.modify_auto_moderation_rule","page":"API Reference","text":"modify_auto_moderation_rule(rl::RateLimiter, guild_id::Snowflake, rule_id::Snowflake; token::String, body::Dict, reason=nothing) -> AutoModRule\n\nModify an existing AutoMod rule.\n\nUse this when a bot needs to update rule configuration, such as changing trigger conditions, actions, or exempt roles/channels.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nrule_id::Snowflake — The ID of the rule to modify.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated rule fields.\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 400 if the rule configuration is invalid.\nHTTP 403 if missing required permissions.\nHTTP 404 if the rule does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_auto_moderation_rule"},{"category":"function","location":"api/#Accord.delete_auto_moderation_rule","page":"API Reference","text":"delete_auto_moderation_rule(rl::RateLimiter, guild_id::Snowflake, rule_id::Snowflake; token::String, reason=nothing)\n\nDelete an AutoMod rule.\n\nUse this when a bot needs to remove moderation rules, such as for rule management systems or temporary rule disabling.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nrule_id::Snowflake — The ID of the rule to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the deletion (optional).\n\nPermissions\n\nRequires MANAGE_GUILD.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the rule or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_auto_moderation_rule"},{"category":"function","location":"api/#Accord.list_scheduled_events","page":"API Reference","text":"list_scheduled_events(rl::RateLimiter, guild_id::Snowflake; token::String, with_user_count::Bool=false) -> Vector{ScheduledEvent}\n\nGet all scheduled events for a guild.\n\nUse this when a bot needs to list guild events, such as for event calendars, upcoming event notifications, or event management commands.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nwith_user_count::Bool — Include subscriber count for each event.\n\nPermissions\n\nRequires VIEW_CHANNEL to see entity-associated events.\nSome event types may require additional permissions.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_scheduled_events"},{"category":"function","location":"api/#Accord.create_guild_scheduled_event","page":"API Reference","text":"create_guild_scheduled_event(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict, reason=nothing) -> ScheduledEvent\n\nCreate a new scheduled event in a guild.\n\nUse this when a bot needs to create events programmatically, such as for event management systems, integration with external calendars, or automated scheduled activities.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Event data (name, description, scheduledstarttime, entity_type, etc.).\nreason::String — Audit log reason for the creation (optional).\n\nPermissions\n\nRequires MANAGE_EVENTS or ADMINISTRATOR.\n\nEvent Types\n\n1 (STAGE_INSTANCE) — Stage channel event\n2 (VOICE) — Voice channel event\n3 (EXTERNAL) — External event (URL-based)\n\nErrors\n\nHTTP 400 if the event data is invalid.\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_guild_scheduled_event"},{"category":"function","location":"api/#Accord.get_guild_scheduled_event","page":"API Reference","text":"get_guild_scheduled_event(rl::RateLimiter, guild_id::Snowflake, event_id::Snowflake; token::String, with_user_count::Bool=false) -> ScheduledEvent\n\nGet a specific scheduled event.\n\nUse this when a bot needs to retrieve event details, such as for displaying event information or checking event status.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nevent_id::Snowflake — The ID of the event.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nwith_user_count::Bool — Include subscriber count.\n\nPermissions\n\nRequires VIEW_CHANNEL to see entity-associated events.\n\nErrors\n\nHTTP 404 if the event or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_scheduled_event"},{"category":"function","location":"api/#Accord.modify_guild_scheduled_event","page":"API Reference","text":"modify_guild_scheduled_event(rl::RateLimiter, guild_id::Snowflake, event_id::Snowflake; token::String, body::Dict, reason=nothing) -> ScheduledEvent\n\nModify a scheduled event.\n\nUse this when a bot needs to update event details, such as changing the time, location, description, or status of an event.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nevent_id::Snowflake — The ID of the event to modify.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated event fields.\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_EVENTS or ADMINISTRATOR.\n\nErrors\n\nHTTP 400 if the event data is invalid.\nHTTP 403 if missing required permissions or not the event creator.\nHTTP 404 if the event or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_guild_scheduled_event"},{"category":"function","location":"api/#Accord.delete_guild_scheduled_event","page":"API Reference","text":"delete_guild_scheduled_event(rl::RateLimiter, guild_id::Snowflake, event_id::Snowflake; token::String)\n\nDelete a scheduled event.\n\nUse this when a bot needs to cancel or remove events, such as for event management or cleanup systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nevent_id::Snowflake — The ID of the event to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_EVENTS or ADMINISTRATOR.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the event or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_guild_scheduled_event"},{"category":"function","location":"api/#Accord.get_guild_scheduled_event_users","page":"API Reference","text":"get_guild_scheduled_event_users(rl::RateLimiter, guild_id::Snowflake, event_id::Snowflake; token::String, limit::Int=100, with_member::Bool=false) -> Dict{String, Any}\n\nGet users subscribed to a scheduled event.\n\nUse this when a bot needs to list event attendees, such as for attendance tracking, reminder systems, or capacity management.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nevent_id::Snowflake — The ID of the event.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nlimit::Int — Maximum users to return (1-100, default 100).\nwith_member::Bool — Include guild member data for each user.\n\nPermissions\n\nRequires MANAGE_EVENTS or ADMINISTRATOR.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the event or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_scheduled_event_users"},{"category":"function","location":"api/#Accord.create_stage_instance","page":"API Reference","text":"create_stage_instance(rl::RateLimiter; token::String, body::Dict, reason=nothing) -> StageInstance\n\nCreate a new Stage instance.\n\nUse this when a bot needs to start a Stage event programmatically, such as for scheduled stage events or automated broadcast systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Stage instance data (channelid, topic, privacylevel, sendstartnotification).\nreason::String — Audit log reason for the creation (optional).\n\nPermissions\n\nRequires MANAGE_CHANNELS and MOVE_MEMBERS in the Stage channel.\n\nPrivacy Levels\n\n1 (PUBLIC) — Stage visible to everyone\n2 (GUILD_ONLY) — Stage visible only to guild members\n\nErrors\n\nHTTP 400 if the stage data is invalid or channel is not a Stage channel.\nHTTP 403 if missing required permissions.\nHTTP 409 if a stage instance already exists for this channel.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_stage_instance"},{"category":"function","location":"api/#Accord.get_stage_instance","page":"API Reference","text":"get_stage_instance(rl::RateLimiter, channel_id::Snowflake; token::String) -> StageInstance\n\nGet the Stage instance for a Stage channel.\n\nUse this when a bot needs to retrieve information about an active Stage, such as the topic, privacy level, or associated guild scheduled event.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the Stage channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 404 if no stage instance exists for this channel.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_stage_instance"},{"category":"function","location":"api/#Accord.modify_stage_instance","page":"API Reference","text":"modify_stage_instance(rl::RateLimiter, channel_id::Snowflake; token::String, body::Dict, reason=nothing) -> StageInstance\n\nModify a Stage instance.\n\nUse this when a bot needs to update the topic, privacy level, or other properties of an active Stage.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the Stage channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated stage fields (topic, privacy_level).\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_CHANNELS and MOVE_MEMBERS in the Stage channel.\n\nErrors\n\nHTTP 400 if the stage data is invalid.\nHTTP 403 if missing required permissions.\nHTTP 404 if no stage instance exists for this channel.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_stage_instance"},{"category":"function","location":"api/#Accord.delete_stage_instance","page":"API Reference","text":"delete_stage_instance(rl::RateLimiter, channel_id::Snowflake; token::String, reason=nothing)\n\nDelete a Stage instance (close the Stage).\n\nUse this when a bot needs to end a Stage event, such as after a scheduled event concludes or for moderation purposes.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the Stage channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the deletion (optional).\n\nPermissions\n\nRequires MANAGE_CHANNELS and MOVE_MEMBERS in the Stage channel.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if no stage instance exists for this channel.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_stage_instance"},{"category":"function","location":"api/#Accord.list_default_soundboard_sounds","page":"API Reference","text":"list_default_soundboard_sounds(rl::RateLimiter; token::String) -> Vector{SoundboardSound}\n\nGet the list of default soundboard sounds available to all users.\n\nUse this when a bot needs to list Discord's built-in soundboard sounds, such as for sound previews or integration features.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_default_soundboard_sounds"},{"category":"function","location":"api/#Accord.list_guild_soundboard_sounds","page":"API Reference","text":"list_guild_soundboard_sounds(rl::RateLimiter, guild_id::Snowflake; token::String) -> Dict{String, Any}\n\nGet all custom soundboard sounds for a guild.\n\nUse this when a bot needs to list guild-specific soundboard sounds, such as for sound management or discovery features.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_guild_soundboard_sounds"},{"category":"function","location":"api/#Accord.get_guild_soundboard_sound","page":"API Reference","text":"get_guild_soundboard_sound(rl::RateLimiter, guild_id::Snowflake, sound_id::Snowflake; token::String) -> SoundboardSound\n\nGet a specific guild soundboard sound.\n\nUse this when a bot needs to retrieve information about a single soundboard sound, such as for editing or management.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nsound_id::Snowflake — The ID of the sound.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the sound or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_guild_soundboard_sound"},{"category":"function","location":"api/#Accord.create_guild_soundboard_sound","page":"API Reference","text":"create_guild_soundboard_sound(rl::RateLimiter, guild_id::Snowflake; token::String, body::Dict, reason=nothing) -> SoundboardSound\n\nCreate a new soundboard sound in a guild.\n\nUse this when a bot needs to upload custom soundboard sounds programmatically, such as for sound management tools or automated sound creation.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Sound data (name, sound base64, volume, emoji_id/name).\nreason::String — Audit log reason for the creation (optional).\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nSound Requirements\n\nMust be MP3 or OGG format.\nMax duration: 5 seconds.\nMax file size: 512KB.\n\nErrors\n\nHTTP 400 if the sound data is invalid or file too large.\nHTTP 403 if missing required permissions.\nHTTP 429 if sound limit reached for the guild.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_guild_soundboard_sound"},{"category":"function","location":"api/#Accord.modify_guild_soundboard_sound","page":"API Reference","text":"modify_guild_soundboard_sound(rl::RateLimiter, guild_id::Snowflake, sound_id::Snowflake; token::String, body::Dict, reason=nothing) -> SoundboardSound\n\nModify a guild soundboard sound.\n\nUse this when a bot needs to update sound properties such as name, volume, or associated emoji.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nsound_id::Snowflake — The ID of the sound to modify.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Updated sound fields (name, volume, emojiid, emojiname).\nreason::String — Audit log reason for the change (optional).\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nErrors\n\nHTTP 400 if the sound data is invalid.\nHTTP 403 if missing required permissions.\nHTTP 404 if the sound or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_guild_soundboard_sound"},{"category":"function","location":"api/#Accord.delete_guild_soundboard_sound","page":"API Reference","text":"delete_guild_soundboard_sound(rl::RateLimiter, guild_id::Snowflake, sound_id::Snowflake; token::String, reason=nothing)\n\nDelete a guild soundboard sound.\n\nUse this when a bot needs to remove soundboard sounds, such as for sound management or cleanup systems.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nguild_id::Snowflake — The ID of the guild.\nsound_id::Snowflake — The ID of the sound to delete.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nreason::String — Audit log reason for the deletion (optional).\n\nPermissions\n\nRequires MANAGE_GUILD_EXPRESSIONS.\n\nErrors\n\nHTTP 403 if missing required permissions.\nHTTP 404 if the sound or guild does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_guild_soundboard_sound"},{"category":"function","location":"api/#Accord.send_soundboard_sound","page":"API Reference","text":"send_soundboard_sound(rl::RateLimiter, channel_id::Snowflake; token::String, body::Dict)\n\nSend a soundboard sound to a voice channel.\n\nUse this when a bot needs to trigger a soundboard sound in a voice channel, such as for automated announcements or interactive voice features.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nchannel_id::Snowflake — The ID of the voice channel.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Contains sound_id of the sound to play.\n\nPermissions\n\nRequires SEND_MESSAGES and the bot must be connected to the voice channel.\n\nErrors\n\nHTTP 400 if the sound ID is invalid.\nHTTP 403 if missing required permissions or not in the voice channel.\nHTTP 404 if the channel or sound does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.send_soundboard_sound"},{"category":"function","location":"api/#Accord.list_voice_regions","page":"API Reference","text":"list_voice_regions(rl::RateLimiter; token::String) -> Vector{VoiceRegion}\n\nGet all available voice regions.\n\nUse this when a bot needs to list voice regions for server configuration, voice channel setup, or region selection features.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nNote\n\nThis returns the global list of voice regions. Some regions may be VIP-only or deprecated. Use get_guild_voice_regions for guild-specific regions.\n\nErrors\n\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_voice_regions"},{"category":"function","location":"api/#Accord.list_skus","page":"API Reference","text":"list_skus(rl::RateLimiter, application_id::Snowflake; token::String) -> Vector{SKU}\n\nGet all SKUs (Stock Keeping Units) for an application.\n\nUse this when a bot needs to list available premium products or subscription plans offered by the application, such as for store displays or upgrade flows.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nSKU Types\n\n2 (DURABLE) — One-time purchase\n3 (CONSUMABLE) — Consumable purchase\n5 (SUBSCRIPTION) — Subscription\n6 (SUBSCRIPTION_GROUP) — Subscription group\n\nErrors\n\nHTTP 401 if the token is invalid.\nHTTP 404 if the application does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_skus"},{"category":"function","location":"api/#Accord.list_entitlements","page":"API Reference","text":"list_entitlements(rl::RateLimiter, application_id::Snowflake; token::String,\n    user_id=nothing, sku_ids=nothing, before=nothing, after=nothing, limit::Int=100,\n    guild_id=nothing, exclude_ended::Bool=false, exclude_deleted::Bool=true) -> Vector{Entitlement}\n\nGet all entitlements for an application.\n\nUse this when a bot needs to list user purchases and subscriptions, such as for checking premium status, managing subscriptions, or customer support.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nuser_id::Snowflake — Filter by user ID.\nsku_ids::Vector{Snowflake} — Filter by specific SKU IDs.\nbefore::Snowflake — Get entitlements before this ID.\nafter::Snowflake — Get entitlements after this ID.\nlimit::Int — Maximum entitlements to return (1-100, default 100).\nguild_id::Snowflake — Filter by guild ID.\nexclude_ended::Bool — Exclude ended entitlements.\nexclude_deleted::Bool — Exclude deleted entitlements.\n\nEntitlement Types\n\n1 — Application subscription\n2 — Application entitlement\n3 — Application gift\n\nErrors\n\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_entitlements"},{"category":"function","location":"api/#Accord.create_test_entitlement","page":"API Reference","text":"create_test_entitlement(rl::RateLimiter, application_id::Snowflake; token::String, body::Dict) -> Entitlement\n\nCreate a test entitlement for development purposes.\n\nUse this when developing premium features and testing entitlement checking without making actual purchases. Only works in development mode.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Test entitlement data (skuid, userid, guild_id, etc.).\n\nNote\n\nTest entitlements are only available in development mode and do not appear in production or billing systems.\n\nErrors\n\nHTTP 400 if the request data is invalid.\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_test_entitlement"},{"category":"function","location":"api/#Accord.delete_test_entitlement","page":"API Reference","text":"delete_test_entitlement(rl::RateLimiter, application_id::Snowflake, entitlement_id::Snowflake; token::String)\n\nDelete a test entitlement.\n\nUse this when cleaning up test data or resetting test scenarios during development.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nentitlement_id::Snowflake — The ID of the test entitlement.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the token is invalid.\nHTTP 404 if the entitlement does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_test_entitlement"},{"category":"function","location":"api/#Accord.consume_entitlement","page":"API Reference","text":"consume_entitlement(rl::RateLimiter, application_id::Snowflake, entitlement_id::Snowflake; token::String)\n\nConsume an entitlement.\n\nUse this when a bot needs to mark an entitlement as consumed, such as for consumable purchases or one-time use premium features.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nentitlement_id::Snowflake — The ID of the entitlement to consume.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the token is invalid.\nHTTP 404 if the entitlement does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.consume_entitlement"},{"category":"function","location":"api/#Accord.get_entitlement","page":"API Reference","text":"get_entitlement(rl::RateLimiter, application_id::Snowflake, entitlement_id::Snowflake; token::String) -> Entitlement\n\nGet a specific entitlement.\n\nUse this when a bot needs to retrieve details about a single entitlement, such as for verification or customer support purposes.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\nentitlement_id::Snowflake — The ID of the entitlement.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the token is invalid.\nHTTP 404 if the entitlement does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_entitlement"},{"category":"function","location":"api/#Accord.list_sku_subscriptions","page":"API Reference","text":"list_sku_subscriptions(rl::RateLimiter, sku_id::Snowflake; token::String, before=nothing, after=nothing, limit::Int=100, user_id=nothing) -> Vector{Subscription}\n\nGet all subscriptions for a specific SKU.\n\nUse this when a bot needs to list active subscriptions for a product, such as for billing management, subscriber analytics, or customer support.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nsku_id::Snowflake — The ID of the SKU.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbefore::Snowflake — Get subscriptions before this ID.\nafter::Snowflake — Get subscriptions after this ID.\nlimit::Int — Maximum subscriptions to return (1-100, default 100).\nuser_id::Snowflake — Filter by user ID.\n\nErrors\n\nHTTP 401 if the token is invalid.\nHTTP 404 if the SKU does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.list_sku_subscriptions"},{"category":"function","location":"api/#Accord.get_sku_subscription","page":"API Reference","text":"get_sku_subscription(rl::RateLimiter, sku_id::Snowflake, subscription_id::Snowflake; token::String) -> Subscription\n\nGet a specific subscription.\n\nUse this when a bot needs to retrieve details about a single subscription, such as for billing verification or subscription status checks.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\nsku_id::Snowflake — The ID of the SKU.\nsubscription_id::Snowflake — The ID of the subscription.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the token is invalid.\nHTTP 404 if the subscription or SKU does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_sku_subscription"},{"category":"function","location":"api/#Accord.get_guild_templates","page":"API Reference","text":"Use this to retrieve all guild templates available for a specific server.\n\nGet all templates for a guild.\n\n\n\n\n\n","title":"Accord.get_guild_templates"},{"category":"function","location":"api/#Accord.create_guild_template","page":"API Reference","text":"Use this to create a new template from the current state of a guild.\n\nCreate a guild template.\n\n\n\n\n\n","title":"Accord.create_guild_template"},{"category":"function","location":"api/#Accord.sync_guild_template","page":"API Reference","text":"Use this to update a template to match the current state of the guild.\n\nSync the template to the guild's current state.\n\n\n\n\n\n","title":"Accord.sync_guild_template"},{"category":"function","location":"api/#Accord.modify_guild_template","page":"API Reference","text":"Use this to change the name or description of an existing guild template.\n\nModify a guild template's metadata.\n\n\n\n\n\n","title":"Accord.modify_guild_template"},{"category":"function","location":"api/#Accord.delete_guild_template","page":"API Reference","text":"Use this to remove a guild template permanently.\n\nDelete a guild template.\n\n\n\n\n\n","title":"Accord.delete_guild_template"},{"category":"function","location":"api/#Accord.get_current_application","page":"API Reference","text":"get_current_application(rl::RateLimiter; token::String) -> Dict{String, Any}\n\nGet the bot's own application information.\n\nUse this when a bot needs to retrieve its application details, such as name, description, icon, public flags, and interaction endpoint URL. This is useful for verifying configuration or displaying application information.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nErrors\n\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_current_application"},{"category":"function","location":"api/#Accord.modify_current_application","page":"API Reference","text":"modify_current_application(rl::RateLimiter; token::String, body::Dict) -> Dict{String, Any}\n\nModify the bot's own application settings.\n\nUse this when a bot needs to update its application configuration, such as description, interaction endpoint URL, flags, or tags. Changes affect how the application appears to users.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Dict — Application fields to update (description, icon, flags, etc.).\n\nUpdatable Fields\n\ncustom_install_url — Custom authorization URL\ndescription — Application description\nicon — Base64-encoded icon\ncover_image — Base64-encoded cover image\ninteractions_endpoint_url — URL for receiving interactions\nflags — Public flags (GATEWAYPRESENCELIMITED, etc.)\ntags — Array of tags describing the app\n\nErrors\n\nHTTP 400 if any field is invalid.\nHTTP 401 if the token is invalid.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_current_application"},{"category":"function","location":"api/#Accord.get_application_role_connection_metadata_records","page":"API Reference","text":"get_application_role_connection_metadata_records(rl::RateLimiter, application_id::Snowflake; token::String) -> Vector{Dict{String, Any}}\n\nGet the role connection metadata records for an application.\n\nUse this when a bot needs to retrieve the configuration for Linked Roles, which allow users to obtain roles based on external platform data.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\n\nMetadata Types\n\nINTEGER_LESS_THAN_OR_EQUAL — Integer ≤ comparison\nINTEGER_GREATER_THAN_OR_EQUAL — Integer ≥ comparison\nINTEGER_EQUAL — Integer = comparison\nINTEGER_NOT_EQUAL — Integer ≠ comparison\nDATETIME_LESS_THAN_OR_EQUAL — Unix timestamp ≤ comparison\nDATETIME_GREATER_THAN_OR_EQUAL — Unix timestamp ≥ comparison\nBOOLEAN_EQUAL — Boolean = comparison\nBOOLEAN_NOT_EQUAL — Boolean ≠ comparison\n\nErrors\n\nHTTP 401 if the token is invalid.\nHTTP 404 if the application does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.get_application_role_connection_metadata_records"},{"category":"function","location":"api/#Accord.update_application_role_connection_metadata_records","page":"API Reference","text":"update_application_role_connection_metadata_records(rl::RateLimiter, application_id::Snowflake; token::String, body::Vector) -> Vector{Dict{String, Any}}\n\nUpdate the role connection metadata records for an application.\n\nUse this when a bot needs to configure Linked Role requirements, defining what external data can be used to grant roles to users.\n\nArguments\n\nrl::RateLimiter — The rate limiter instance for request throttling.\napplication_id::Snowflake — The ID of the application.\n\nKeyword Arguments\n\ntoken::String — Bot authentication token.\nbody::Vector — Array of metadata record definitions.\n\nRecord Fields\n\ntype — The type of metadata value (INTEGER, BOOLEAN, DATETIME)\nkey — Unique key for this metadata field\nname — Display name for the metadata field\nname_localizations — Localized names (optional)\ndescription — Description of the field\ndescription_localizations — Localized descriptions (optional)\n\nErrors\n\nHTTP 400 if the metadata configuration is invalid.\nHTTP 401 if the token is invalid.\nHTTP 404 if the application does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.update_application_role_connection_metadata_records"},{"category":"type","location":"api/#Accord.InteractionContext","page":"API Reference","text":"InteractionContext\n\nUse this in your slash command handlers to access interaction data and send responses.\n\nWraps an Interaction with convenience methods for responding. Holds a reference to the Client.\n\ncompat: Accord 0.1.0\nInteractionContext and all interaction helpers are available since Accord 0.1.0.\n\n\n\n\n\n","title":"Accord.InteractionContext"},{"category":"method","location":"api/#Base.getproperty-Tuple{InteractionContext, Symbol}","page":"API Reference","text":"Use this property to access the Discord user who invoked the command or interaction.\n\nGet the user who triggered the interaction.\n\n\n\n\n\n","title":"Base.getproperty"},{"category":"type","location":"api/#Accord.CommandTree","page":"API Reference","text":"CommandTree\n\nOrganizes and routes slash commands, components, and modal handlers. The client.command_tree field holds the instance used by the bot.\n\ncompat: Accord 0.1.0\nCommandTree and the declarative command registration API are available since Accord 0.1.0.\n\nFields\n\ncommands::Dict{String, CommandDefinition}: Map of command names to definitions.\ncomponent_handlers::Dict{String, Function}: Map of custom_ids to component handlers.\ncomponent_prefix_handlers::Dict{String, Function}: Map of custom_id prefixes to handlers.\nmodal_handlers::Dict{String, Function}: Map of custom_ids to modal handlers.\nautocomplete_handlers::Dict{String, Function}: Map of command names to autocomplete handlers.\n\nSee register_command!, sync_commands!.\n\n\n\n\n\n","title":"Accord.CommandTree"},{"category":"function","location":"api/#Accord.sync_commands!","page":"API Reference","text":"sync_commands!(client, tree::CommandTree; guild_id=nothing)\n\nUpload registered commands to Discord.\n\nUse this to update the command list visible to users. Global commands can take up to 1 hour to propagate, while guild commands are instant.\n\nwarning: Warning\nThis endpoint is rate-limited. During development, use guild_id to sync to a single test server for instant updates. Only sync globally for production.\n\nArguments\n\nclient: The Client instance.\ntree::CommandTree: The command tree containing commands to sync.\n\nKeyword Arguments\n\nguild_id::Optional{Snowflake}: If provided, only sync commands for this specific guild. If omitted, syncs global commands AND all guild-specific commands registered in the tree.\n\nExample\n\non(client, ReadyEvent) do c, event\n    sync_commands!(c, c.command_tree)\nend\n\n\n\n\n\n","title":"Accord.sync_commands!"},{"category":"function","location":"api/#Accord.register_command!","page":"API Reference","text":"register_command!(tree::CommandTree, name::String, description::String, handler::Function; type=1, options=[], guild_id=missing, checks=[])\n\nRegister a new application command (slash command).\n\nUse this to define a command that users can invoke via /name. The handler function should accept a single argument: the InteractionContext.\n\nArguments\n\ntree::CommandTree: The command tree to register into (usually client.command_tree).\nname::String: The command name (lowercase, no spaces).\ndescription::String: Help text shown to the user.\nhandler::Function: Function called when command is invoked.\n\nKeyword Arguments\n\ntype::Int: Command type (default: 1 for Chat Input). See ApplicationCommandTypes.\noptions::Vector: List of arguments/parameters for the command.\nguild_id::Optional{Snowflake}: If provided, registers as a guild-specific command (faster updates) instead of global.\nchecks::Vector{Function}: List of functions ctx -> Bool that must return true for the command to run.\n\nExample\n\nregister_command!(client.command_tree, \"ping\", \"Checks latency\", ctx -> begin\n    reply(ctx, \"Pong!\")\nend)\n\n\n\n\n\n","title":"Accord.register_command!"},{"category":"function","location":"api/#Accord.register_component!","page":"API Reference","text":"register_component!(tree::CommandTree, custom_id::String, handler::Function)\n\nRegister a handler for a Message Component (button or select menu).\n\nUse this to handle interactions from buttons or dropdowns. The custom_id can be an exact match or a prefix (if no exact match is found).\n\nArguments\n\ntree::CommandTree: The command tree.\ncustom_id::String: The identifier string assigned to the component. Use \"prefix*\" for prefix matching.\nhandler::Function: Function ctx -> Any called when the component is used.\n\nExample\n\n# Register a button handler\nregister_component!(client.command_tree, \"click_one\", ctx -> begin\n    reply(ctx, \"Button clicked!\")\nend)\n\n# Register a prefix handler\nregister_component!(client.command_tree, \"user_select:*\", ctx -> begin\n    id = split(ctx.interaction.data.custom_id, \":\")[2]\n    reply(ctx, \"Selected user $id\")\nend)\n\n\n\n\n\n","title":"Accord.register_component!"},{"category":"function","location":"api/#Accord.register_modal!","page":"API Reference","text":"register_modal!(tree::CommandTree, custom_id::String, handler::Function)\n\nRegister a handler for a Modal submission.\n\nUse this to process form data submitted by users via Modals.\n\nArguments\n\ntree::CommandTree: The command tree.\ncustom_id::String: The identifier string assigned to the modal.\nhandler::Function: Function ctx -> Any called when the modal is submitted.\n\nExample\n\nregister_modal!(client.command_tree, \"feedback_form\", ctx -> begin\n    input = modal_values(ctx)[\"message\"]\n    reply(ctx, \"Received: $input\")\nend)\n\n\n\n\n\n","title":"Accord.register_modal!"},{"category":"function","location":"api/#Accord.register_autocomplete!","page":"API Reference","text":"register_autocomplete!(tree::CommandTree, command_name::String, handler::Function)\n\nRegister an autocomplete handler for a slash command option.\n\nUse this to provide dynamic choices as the user types an argument.\n\nArguments\n\ntree::CommandTree: The command tree.\ncommand_name::String: The name of the command to attach autocomplete to.\nhandler::Function: Function ctx -> Any called on autocomplete interaction.\n\nExample\n\nregister_autocomplete!(client.command_tree, \"search\", ctx -> begin\n    # ... logic to return choices ...\nend)\n\n\n\n\n\n","title":"Accord.register_autocomplete!"},{"category":"function","location":"api/#Accord.register_subcommand!","page":"API Reference","text":"register_subcommand!(parent_options::Vector, name::String, description::String, handler::Function; options=[], checks=[])\n\nRegister a subcommand into a list of options for a parent command or group. Internal helper used by the @group and @subcommand macros.\n\n\n\n\n\n","title":"Accord.register_subcommand!"},{"category":"function","location":"api/#Accord.dispatch_interaction!","page":"API Reference","text":"dispatch_interaction!(tree::CommandTree, client, interaction::Interaction)\n\nRoute an incoming interaction to the appropriate handler.\n\nInternal function called by the InteractionCreate event handler. It matches the interaction type and ID to a registered handler in the tree.\n\nArguments\n\ntree::CommandTree: The command tree.\nclient: The Client instance.\ninteraction::Interaction: The interaction object received from the gateway.\n\nReturns\n\nThe result of the handler function, or nothing if no handler was found.\n\nExample\n\n# This is wired automatically by Client, but can be called manually:\non(client, InteractionCreate) do c, event\n    dispatch_interaction!(c.command_tree, c, event.interaction)\nend\n\n\n\n\n\n","title":"Accord.dispatch_interaction!"},{"category":"macro","location":"api/#Accord.@slash_command","page":"API Reference","text":"@slash_command client [guild_id] name description [options] handler\n\nUse this macro to define slash commands that users can invoke with \"/command\".\n\nRegister a slash command with the client's command tree.\n\nExample\n\njulia> client = Client(\"token\");\n\njulia> # Simple command\n       @slash_command client \"greet\" \"Say hello\" (ctx) -> \"Hello!\";\n\njulia> # Command with options\n       @slash_command client \"double\" \"Double a number\" [\n           @option Integer \"number\" \"Number to double\" required=true\n       ] (ctx) -> get_option(ctx, \"number\", 0) * 2;\n\njulia> # Guild-specific command (Guild ID 123)\n       @slash_command client 123 \"info\" \"Server info\" (ctx) -> \"Guild command!\";\n\n\n\n\n\n","title":"Accord.@slash_command"},{"category":"macro","location":"api/#Accord.@user_command","page":"API Reference","text":"@user_command client [guild_id] name handler\n\nUse this macro to add right-click context menu commands on users.\n\nRegister a User Context Menu command (right-click on a user). Context menu commands have no description or options.\n\nExample\n\njulia> client = Client(\"token\");\n\njulia> @user_command client \"User Info\" (ctx) -> \"User Info\";\n\njulia> @user_command client 123 \"Warn User\" (ctx) -> \"Warned\";\n\n\n\n\n\n","title":"Accord.@user_command"},{"category":"macro","location":"api/#Accord.@message_command","page":"API Reference","text":"@message_command client [guild_id] name handler\n\nUse this macro to add right-click context menu commands on messages.\n\nRegister a Message Context Menu command (right-click on a message). Context menu commands have no description or options.\n\nExample\n\njulia> client = Client(\"token\");\n\njulia> @message_command client \"Bookmark\" (ctx) -> \"Bookmarked\";\n\njulia> @message_command client 123 \"Report\" (ctx) -> \"Reported\";\n\n\n\n\n\n","title":"Accord.@message_command"},{"category":"macro","location":"api/#Accord.@group","page":"API Reference","text":"@group client [guild_id] name description begin ... end\n\nOrganize related slash commands into a single top-level command with subcommands.\n\nExample\n\n@group client \"admin\" \"Moderation tools\" begin\n    @subcommand \"ban\" \"Ban a user\" [\n        @option User \"user\" \"The user to ban\" required=true\n    ] (ctx) -> respond(ctx, content=\"Banned!\")\n\n    @subcommand \"kick\" \"Kick a user\" (ctx) -> respond(ctx, content=\"Kicked!\")\nend\n\n\n\n\n\n","title":"Accord.@group"},{"category":"macro","location":"api/#Accord.@subcommand","page":"API Reference","text":"@subcommand name description [options] handler\n\nDefine a subcommand inside a @group block. Note: This is automatically transformed by @group.\n\n\n\n\n\n","title":"Accord.@subcommand"},{"category":"macro","location":"api/#Accord.@button_handler","page":"API Reference","text":"@button_handler client custom_id handler\n\nUse this macro to handle clicks on buttons with a specific custom_id.\n\nRegister a button click handler.\n\nExample\n\n@button_handler client \"my_button\" function(ctx)\n    respond(ctx; content=\"Button clicked!\", ephemeral=true)\nend\n\n\n\n\n\n","title":"Accord.@button_handler"},{"category":"macro","location":"api/#Accord.@select_handler","page":"API Reference","text":"@select_handler client custom_id handler\n\nUse this macro to handle selections from dropdown menus.\n\nRegister a select menu handler.\n\nExample\n\n@select_handler client \"color_select\" function(ctx)\n    values = selected_values(ctx)\n    respond(ctx; content=\"You selected: $(join(values, \", \"))\")\nend\n\n\n\n\n\n","title":"Accord.@select_handler"},{"category":"macro","location":"api/#Accord.@modal_handler","page":"API Reference","text":"@modal_handler client custom_id handler\n\nUse this macro to handle form submissions from modal dialogs.\n\nRegister a modal submission handler.\n\nExample\n\n@modal_handler client \"feedback_form\" function(ctx)\n    values = modal_values(ctx)\n    respond(ctx; content=\"Thanks for your feedback: $(values[\"feedback\"])\")\nend\n\n\n\n\n\n","title":"Accord.@modal_handler"},{"category":"macro","location":"api/#Accord.@autocomplete","page":"API Reference","text":"@autocomplete client command_name handler\n\nUse this macro to provide dynamic autocomplete suggestions as users type command options.\n\nRegister an autocomplete handler for a slash command.\n\nExample\n\n@autocomplete client \"search\" function(ctx)\n    query = get_option(ctx, \"query\", \"\")\n    choices = [Dict(\"name\" => r, \"value\" => r) for r in search_results(query)]\n    body = Dict(\"type\" => InteractionCallbackTypes.APPLICATION_COMMAND_AUTOCOMPLETE_RESULT,\n                \"data\" => Dict(\"choices\" => choices))\n    create_interaction_response(ctx.client, ctx.interaction.id, ctx.interaction.token; body)\nend\n\n\n\n\n\n","title":"Accord.@autocomplete"},{"category":"macro","location":"api/#Accord.@check","page":"API Reference","text":"@check check_function\n\nUse this macro to add permission checks or guards before a command executes.\n\nAdd a pre-execution check (guard) to the next @slash_command, @user_command, or @message_command. Checks are stacked — multiple @check macros accumulate and are all drained when a command macro is invoked.\n\nCheck functions receive an InteractionContext and return true (pass) or false (deny). If a check fails, the command handler is never called and a default \"permission denied\" ephemeral message is sent.\n\nBuilt-in checks\n\nhas_permissions(perms...) — require specific permissions\nis_owner() — require guild owner\nis_in_guild() — require guild context (not DMs)\ncooldown(seconds; per=:user) — rate-limit per user/guild/channel/global\n\nExample\n\njulia> @check has_permissions(:MANAGE_GUILD);\n\njulia> @check is_owner();\n\njulia> length(Accord.pending_checks()) # Verifies checks were queued\n2\n\n\n\n\n\n","title":"Accord.@check"},{"category":"macro","location":"api/#Accord.@option","page":"API Reference","text":"@option Type name description [kwargs...]\n\nUse this macro to define command options with types and validation rules.\n\nCreate a command option dict using a concise syntax. Type is one of: String, Integer, Boolean, User, Channel, Role, Mentionable, Number, or Attachment.\n\nExamples\n\njulia> opt = @option String \"query\" \"Search query\" required=true;\n\njulia> opt[\"name\"]\n\"query\"\n\njulia> opt[\"type\"] == 3 # STRING type\ntrue\n\njulia> opt = @option Integer \"count\" \"How many\" min_value=1 max_value=25;\n\njulia> opt[\"min_value\"]\n1\n\n\n\n\n\n","title":"Accord.@option"},{"category":"macro","location":"api/#Accord.@on_message","page":"API Reference","text":"@on_message client handler\n\nUse this macro to easily register a handler for incoming text messages.\n\nRegister a MessageCreate handler that automatically skips bot messages and messages with missing author or content.\n\nThe handler receives (client, message) — the Message object directly.\n\nExample\n\njulia> client = Client(\"token\");\n\njulia> @on_message client (c, msg) -> \"handled\";\n\njulia> length(client.event_handler.handlers[Accord.MessageCreate])\n1\n\n\n\n\n\n","title":"Accord.@on_message"},{"category":"macro","location":"api/#Accord.@on","page":"API Reference","text":"@on client EventType handler\n\nRegister an event handler using a clean decorator syntax.\n\nExample\n\n@on client MessageCreate (c, event) -> println(event.message.content)\n\n@on client ReadyEvent function(c, event)\n    @info \"Logged in as $(event.user.username)\"\nend\n\n\n\n\n\n","title":"Accord.@on"},{"category":"macro","location":"api/#Accord.@embed","page":"API Reference","text":"@embed begin ... end\n\nDSL for building Discord embeds quickly.\n\nSupported Keywords\n\ntitle(\"text\")\ndescription(\"text\")\nurl(\"url\")\ncolor(:symbol) or color(0xHEX)\nimage(\"url\")\nthumbnail(\"url\")\nauthor(\"name\", icon=\"url\", url=\"url\")\nfooter(\"text\", icon=\"url\")\nfield(\"name\", \"value\", inline=true/false)\ntimestamp() (uses current time)\n\nExample\n\ne = @embed begin\n    title(\"Success\")\n    description(\"Operation completed\")\n    color(:green)\n    field(\"ID\", \"123\", inline=true)\n    timestamp()\nend\n\n\n\n\n\n","title":"Accord.@embed"},{"category":"function","location":"api/#Accord.respond","page":"API Reference","text":"respond(ctx; content=\"\", embeds=[], components=[], ephemeral=false, tts=false, files=nothing)\n\nUse this to send an immediate response to a slash command or component interaction.\n\nSend an interaction response. Automatically chooses between creating a new response or editing a deferred one.\n\nwarning: Warning\nYou must call respond within 3 seconds of receiving the interaction, unless you first call defer. After deferring, you have up to 15 minutes.\n\nExample\n\n@slash_command client \"hello\" \"Say hello\" function(ctx)\n    respond(ctx; content=\"Hello, world!\", ephemeral=true)\nend\n\n\n\n\n\n","title":"Accord.respond"},{"category":"function","location":"api/#Accord.defer","page":"API Reference","text":"defer(ctx; ephemeral=false)\n\nUse this when you need more than 3 seconds to process a command before responding.\n\nAcknowledge the interaction and defer the response (shows a \"thinking...\" indicator). This gives you 15 minutes to call respond or edit_response.\n\nwarning: Warning\ndefer must itself be called within 3 seconds of receiving the interaction. Always defer at the top of your handler if the response may take time.\n\nExample\n\n@slash_command client \"slow\" \"Slow command\" function(ctx)\n    defer(ctx)\n    sleep(5)\n    respond(ctx; content=\"Done!\")\nend\n\n\n\n\n\n","title":"Accord.defer"},{"category":"function","location":"api/#Accord.followup","page":"API Reference","text":"followup(ctx; content=\"\", embeds=[], components=[], ephemeral=false, files=nothing)\n\nUse this to send additional messages after the initial response to an interaction.\n\nSend a followup message to an interaction after the initial response.\n\nExample\n\n@slash_command client \"multi\" \"Send multiple messages\" function(ctx)\n    respond(ctx; content=\"Message 1\")\n    followup(ctx; content=\"Message 2\")\n    followup(ctx; content=\"Secret message\", ephemeral=true)\nend\n\n\n\n\n\n","title":"Accord.followup"},{"category":"function","location":"api/#Accord.edit_response","page":"API Reference","text":"edit_response(ctx; content=nothing, embeds=nothing, components=nothing, files=nothing)\n\nUse this to modify your bot's response after it has already been sent.\n\nEdit the original interaction response.\n\nExample\n\n@slash_command client \"countdown\" \"Start a countdown\" function(ctx)\n    respond(ctx; content=\"3...\")\n    sleep(1); edit_response(ctx; content=\"2...\")\n    sleep(1); edit_response(ctx; content=\"1...\")\n    sleep(1); edit_response(ctx; content=\"🚀 Go!\")\nend\n\n\n\n\n\n","title":"Accord.edit_response"},{"category":"function","location":"api/#Accord.show_modal","page":"API Reference","text":"show_modal(ctx; title::String, custom_id::String, components::Vector)\n\nUse this to display a popup form for users to input data.\n\nShow a modal dialog to the user.\n\nwarning: Warning\nYou cannot call defer before show_modal. Modals must be the first and only response to the interaction.\n\nExample\n\n@slash_command client \"feedback\" \"Give feedback\" function(ctx)\n    show_modal(ctx;\n        title=\"Feedback Form\",\n        custom_id=\"feedback_form\",\n        components=[label(\"Your feedback\", text_input(custom_id=\"message\", style=TextInputStyles.PARAGRAPH))]\n    )\nend\n\n\n\n\n\n","title":"Accord.show_modal"},{"category":"function","location":"api/#Accord.get_options","page":"API Reference","text":"get_options(ctx::InteractionContext) -> Dict{String, Any}\n\nUse this to retrieve all command options that the user provided when invoking a slash command.\n\nGet all interaction data options as a dictionary mapping option names to values.\n\n\n\n\n\n","title":"Accord.get_options"},{"category":"function","location":"api/#Accord.get_option","page":"API Reference","text":"get_option(ctx, name, default=nothing)\n\nUse this to retrieve a specific command option value by its name.\n\nGet a specific option value by name from the interaction data.\n\nExample\n\n@slash_command client \"greet\" \"Greet someone\" options=[command_option(type=6, name=\"user\", description=\"Who to greet\", required=true)] function(ctx)\n    user_id = get_option(ctx, \"user\")\n    respond(ctx; content=\"Hello, <@$user_id>!\")\nend\n\n\n\n\n\n","title":"Accord.get_option"},{"category":"function","location":"api/#Accord.custom_id","page":"API Reference","text":"custom_id(ctx) -> String\n\nUse this to identify which button, select menu, or modal was interacted with.\n\nGet the custom_id for component interactions (buttons, selects) or modal submissions.\n\nExample\n\nregister_component!(client.command_tree, \"action_\", ctx -> begin\n    id = custom_id(ctx)  # e.g. \"action_delete\" or \"action_ban\"\n    respond(ctx; content=\"You triggered: $id\")\nend)\n\n\n\n\n\n","title":"Accord.custom_id"},{"category":"function","location":"api/#Accord.selected_values","page":"API Reference","text":"selected_values(ctx) -> Vector{String}\n\nUse this to retrieve the values selected by the user in a select menu component.\n\nGet the selected values for a select menu interaction.\n\nExample\n\nregister_component!(client.command_tree, \"color_select\", ctx -> begin\n    colors = selected_values(ctx)  # [\"red\", \"blue\"]\n    respond(ctx; content=\"You picked: $(join(colors, \", \"))\")\nend)\n\n\n\n\n\n","title":"Accord.selected_values"},{"category":"function","location":"api/#Accord.modal_values","page":"API Reference","text":"modal_values(ctx) -> Dict{String, Any}\n\nUse this to retrieve what the user entered in a modal form submission.\n\nMaps each input's custom_id to its value:\n\nComponent Value\ntext_input String\nradio_group chosen String, or nothing\ncheckbox Bool\ncheckbox_group, select menus Vector{String}\nfile_upload Vector{String} of attachment ids (see modal_files)\n\nInputs may be wrapped in a label or, in the older layout, an action row.\n\nExample\n\nregister_modal!(client.command_tree, \"feedback_form\", ctx -> begin\n    vals = modal_values(ctx)\n    respond(ctx; content=\"Thanks! You said: $(vals[\"message\"])\")\nend)\n\n\n\n\n\n","title":"Accord.modal_values"},{"category":"function","location":"api/#Accord.modal_files","page":"API Reference","text":"modal_files(ctx, custom_id) -> Vector{Attachment}\n\nThe files a user submitted through the file_upload with custom_id. Empty when the field is absent or nothing was uploaded.\n\n\n\n\n\n","title":"Accord.modal_files"},{"category":"function","location":"api/#Accord.target","page":"API Reference","text":"target(ctx::InteractionContext)\n\nUse this to get the user or message that was right-clicked in a context menu command.\n\nGet the target of a context menu interaction (User or Message command). Returns the resolved User or Message object, or nothing if unavailable.\n\nFor User commands (ApplicationCommandTypes.USER), returns a User. For Message commands (ApplicationCommandTypes.MESSAGE), returns a Message.\n\nExample\n\nregister_command!(client.command_tree, \"User Info\", \"\", ctx -> begin\n    user = target(ctx)\n    respond(ctx; content=\"User: $(user.username)#$(user.discriminator)\")\nend; type=ApplicationCommandTypes.USER)\n\n\n\n\n\n","title":"Accord.target"},{"category":"function","location":"api/#Accord.run_checks","page":"API Reference","text":"run_checks(checks::Vector{Function}, ctx::InteractionContext) -> Bool\n\nUse this internal function to execute all permission checks before running a command handler.\n\nRun all check functions against a context. Returns true if all pass. If a check fails and the interaction hasn't been responded to, sends a default ephemeral error message.\n\n\n\n\n\n","title":"Accord.run_checks"},{"category":"function","location":"api/#Accord.drain_pending_checks!","page":"API Reference","text":"drain_pending_checks!() -> Vector{Function}\n\nUse this internal function to retrieve and clear accumulated permission checks.\n\nDrain all pending checks accumulated by @check macros. Called internally by @slash_command.\n\n\n\n\n\n","title":"Accord.drain_pending_checks!"},{"category":"function","location":"api/#Accord.cooldown","page":"API Reference","text":"cooldown(seconds::Real; per::Symbol=:user) -> Function\n\nUse this check to rate-limit command usage and prevent spam.\n\nCreate a cooldown check. If the cooldown has not expired, sends an ephemeral message with the remaining time and blocks execution.\n\nper can be :user, :guild, :channel, or :global.\n\nExample\n\n@check cooldown(5)                    # 5s per user\n@check cooldown(30; per=:guild)       # 30s per guild\n@slash_command client \"roll\" \"Roll dice\" handler\n\n\n\n\n\n","title":"Accord.cooldown"},{"category":"function","location":"api/#Accord.is_owner","page":"API Reference","text":"is_owner() -> Function\n\nUse this check to restrict commands to only the server owner.\n\nCreate a check that verifies the invoking user is the guild owner.\n\nExample\n\n@check is_owner()\n@slash_command client \"nuke\" \"Owner-only command\" function(ctx)\n    respond(ctx; content=\"Only the owner can do this!\")\nend\n\n\n\n\n\n","title":"Accord.is_owner"},{"category":"function","location":"api/#Accord.is_in_guild","page":"API Reference","text":"is_in_guild() -> Function\n\nUse this check to ensure commands can only be used in servers, not in direct messages.\n\nCreate a check that verifies the interaction was triggered inside a guild (not DMs).\n\nExample\n\n@check is_in_guild()\n@slash_command client \"server-info\" \"Show server info\" function(ctx)\n    respond(ctx; content=\"Guild ID: $(ctx.guild_id)\")\nend\n\n\n\n\n\n","title":"Accord.is_in_guild"},{"category":"function","location":"api/#Accord.has_permissions","page":"API Reference","text":"has_permissions(perms...) -> Function\n\nUse this check to restrict commands to users with specific Discord permissions.\n\nCreate a check that verifies the invoking user has all specified permissions. Accepts Permissions values or symbols (:MANAGE_GUILD, :BAN_MEMBERS, etc.).\n\nExamples\n\n@check has_permissions(PermManageGuild)\n@check has_permissions(:MANAGE_GUILD, :BAN_MEMBERS)\n@check has_permissions(PermManageGuild | PermBanMembers)\n\n\n\n\n\n","title":"Accord.has_permissions"},{"category":"type","location":"api/#Accord.CheckFailedError","page":"API Reference","text":"CheckFailedError\n\nUse this error type to identify when a permission check has prevented command execution.\n\nError thrown internally when a pre-execution check fails. Contains the name of the failed check for diagnostics.\n\n\n\n\n\n","title":"Accord.CheckFailedError"},{"category":"function","location":"api/#Accord.button","page":"API Reference","text":"Use this to create interactive buttons that users can click.\n\nCreate a Button component.\n\nExample\n\nbtn = button(label=\"Click me\", custom_id=\"click_me\", style=ButtonStyles.PRIMARY)\n\n\n\n\n\n","title":"Accord.button"},{"category":"function","location":"api/#Accord.string_select","page":"API Reference","text":"Use this to create dropdown menus for users to select from text options.\n\nCreate a String Select Menu component.\n\nExample\n\noptions = [\n    select_option(label=\"Option 1\", value=\"opt1\"),\n    select_option(label=\"Option 2\", value=\"opt2\")\n]\nsel = string_select(custom_id=\"my_select\", options=options, placeholder=\"Choose one...\")\n\n\n\n\n\n","title":"Accord.string_select"},{"category":"function","location":"api/#Accord.user_select","page":"API Reference","text":"Use this to create a dropdown for selecting Discord users.\n\nCreate a User Select Menu.\n\nExample\n\nsel = user_select(custom_id=\"pick_user\", placeholder=\"Select a member\")\n\n\n\n\n\n","title":"Accord.user_select"},{"category":"function","location":"api/#Accord.role_select","page":"API Reference","text":"Use this to create a dropdown for selecting server roles.\n\nCreate a Role Select Menu.\n\nExample\n\nsel = role_select(custom_id=\"assign_role\", placeholder=\"Pick a role\", max_values=3)\n\n\n\n\n\n","title":"Accord.role_select"},{"category":"function","location":"api/#Accord.mentionable_select","page":"API Reference","text":"Use this to create a dropdown for selecting users or roles.\n\nCreate a Mentionable Select Menu.\n\nExample\n\nsel = mentionable_select(custom_id=\"mention_target\", placeholder=\"Pick a user or role\")\n\n\n\n\n\n","title":"Accord.mentionable_select"},{"category":"function","location":"api/#Accord.channel_select","page":"API Reference","text":"Use this to create a dropdown for selecting channels.\n\nCreate a Channel Select Menu.\n\nExample\n\nsel = channel_select(custom_id=\"log_channel\", placeholder=\"Pick a text channel\", channel_types=[0])\n\n\n\n\n\n","title":"Accord.channel_select"},{"category":"function","location":"api/#Accord.select_option","page":"API Reference","text":"Use this to define individual options within a string select menu.\n\nCreate a select option for string select menus.\n\nExample\n\nopt = select_option(label=\"Pizza\", value=\"pizza\"; description=\"Classic choice\", default=true)\n\n\n\n\n\n","title":"Accord.select_option"},{"category":"function","location":"api/#Accord.text_input","page":"API Reference","text":"Use this to create text input fields inside modal dialogs.\n\nCreate a Text Input component (for modals). Wrap it in a label, which carries the question shown to the user; the label keyword here is Discord's older form, still accepted inside an action_row but deprecated.\n\nExample\n\nlabel(\"Reason for report\",\n      text_input(custom_id=\"reason\", style=TextInputStyles.PARAGRAPH,\n                 placeholder=\"Describe what happened...\"))\n\n\n\n\n\n","title":"Accord.text_input"},{"category":"function","location":"api/#Accord.label","page":"API Reference","text":"label(text, component; description=\"\") -> Dict\n\nWrap one modal input with the question shown above it. Every interactive component of a modal goes in a Label: text_input, the select menus, file_upload, radio_group, checkbox_group and checkbox.\n\nExample\n\nshow_modal(ctx; title=\"Report\", custom_id=\"report\", components=[\n    label(\"What happened?\", text_input(custom_id=\"what\", style=TextInputStyles.PARAGRAPH)),\n    label(\"Severity\", radio_group(custom_id=\"sev\", options=[\n        select_option(label=\"Low\", value=\"low\"),\n        select_option(label=\"High\", value=\"high\"),\n    ]); description=\"Pick one\"),\n])\n\n\n\n\n\n","title":"Accord.label"},{"category":"function","location":"api/#Accord.file_upload","page":"API Reference","text":"file_upload(; custom_id, min_values=1, max_values=1, required=true, file_types=String[])\n\nA file picker for modals (wrap it in a label). file_types restricts what can be chosen: \"image\", \"video\", \"audio\" or extensions like \".pdf\". The submission carries attachment ids; read the files with modal_files.\n\n\n\n\n\n","title":"Accord.file_upload"},{"category":"function","location":"api/#Accord.radio_group","page":"API Reference","text":"radio_group(; custom_id, options, required=true)\n\nExactly-one choice for modals (wrap it in a label). options are select_options, between 2 and 10; mark one with default=true to preselect it.\n\n\n\n\n\n","title":"Accord.radio_group"},{"category":"function","location":"api/#Accord.checkbox_group","page":"API Reference","text":"checkbox_group(; custom_id, options, min_values=1, max_values=length(options), required=true)\n\nMultiple-choice checkboxes for modals (wrap it in a label). options are select_options, up to 10.\n\n\n\n\n\n","title":"Accord.checkbox_group"},{"category":"function","location":"api/#Accord.checkbox","page":"API Reference","text":"checkbox(; custom_id, default=false)\n\nA single yes/no box for modals (wrap it in a label). Discord does not let a lone checkbox be required; use a one-option checkbox_group for that.\n\n\n\n\n\n","title":"Accord.checkbox"},{"category":"function","location":"api/#Accord.action_row","page":"API Reference","text":"Use this to group buttons and select menus into a horizontal row.\n\nCreate an Action Row containing components.\n\nExample\n\nrow = action_row([\n    button(label=\"Yes\", custom_id=\"yes\", style=ButtonStyles.SUCCESS),\n    button(label=\"No\", custom_id=\"no\", style=ButtonStyles.DANGER)\n])\n\n\n\n\n\n","title":"Accord.action_row"},{"category":"function","location":"api/#Accord.embed","page":"API Reference","text":"Use this to create rich embedded messages with formatted content.\n\nCreate an Embed dict.\n\nExample\n\ne = embed(\n    title=\"Hello\",\n    description=\"This is an embed\",\n    color=0x5865F2,\n    fields=[embed_field(\"Name\", \"Accord.jl\")]\n)\n\n\n\n\n\n","title":"Accord.embed"},{"category":"function","location":"api/#Accord.embed_footer","page":"API Reference","text":"embed_footer(text; icon_url=\"\")\n\nUse this to add a footer with optional icon to your embed messages.\n\nCreate an embed footer dict. Use with the embed() builder's footer parameter.\n\nExample\n\nembed(title=\"Report\", footer=embed_footer(\"Generated by Accord.jl\"; icon_url=\"https://example.com/icon.png\"))\n\n\n\n\n\n","title":"Accord.embed_footer"},{"category":"function","location":"api/#Accord.embed_author","page":"API Reference","text":"embed_author(name; url=\"\", icon_url=\"\")\n\nUse this to add an author section with optional link and icon to your embed messages.\n\nCreate an embed author dict. Use with the embed() builder's author parameter.\n\nExample\n\nembed(title=\"Post\", author=embed_author(\"Alice\"; url=\"https://alice.com\", icon_url=\"https://alice.com/avatar.png\"))\n\n\n\n\n\n","title":"Accord.embed_author"},{"category":"function","location":"api/#Accord.embed_field","page":"API Reference","text":"embed_field(name, value; inline=false)\n\nUse this to add labeled fields to your embed messages.\n\nCreate an embed field dict. Use with the embed() builder's fields parameter.\n\nExample\n\nembed(title=\"Info\", fields=[\n    embed_field(\"Name\", \"Accord.jl\"; inline=true),\n    embed_field(\"Version\", \"0.1.0\"; inline=true),\n])\n\n\n\n\n\n","title":"Accord.embed_field"},{"category":"function","location":"api/#Accord.thumbnail","page":"API Reference","text":"Use this to display small preview images in v2 messages.\n\nCreate a Thumbnail component.\n\nExample\n\nthumb = thumbnail(media=unfurled_media(\"https://example.com/preview.png\"); description=\"Map Preview\")\n\n\n\n\n\n","title":"Accord.thumbnail"},{"category":"function","location":"api/#Accord.command_option","page":"API Reference","text":"Use this internal function to build command option dictionaries.\n\nCreate a command option dict.\n\nExample\n\nopt = command_option(type=ApplicationCommandOptionTypes.STRING,\n    name=\"query\", description=\"Search term\", required=true)\n\n\n\n\n\n","title":"Accord.command_option"},{"category":"function","location":"api/#Accord.container","page":"API Reference","text":"Use this to create a container for organizing components in v2 messages.\n\nCreate a Container component (top-level v2 wrapper).\n\ncompat: Accord 0.1.0\nComponents V2 builders (container, section, text_display, separator, media_gallery, file_component, unfurled_media) are available since Accord 0.1.0.\n\nExample\n\nmsg = container([\n    text_display(\"Welcome to the server!\"),\n    separator(),\n    section([text_display(\"Click to learn more\")]; accessory=button(label=\"Info\", custom_id=\"info\"))\n]; color=0x5865F2)\n\n\n\n\n\n","title":"Accord.container"},{"category":"function","location":"api/#Accord.section","page":"API Reference","text":"Use this to group text and accessory components in v2 messages.\n\nCreate a Section component with text and optional accessory.\n\nExample\n\nsec = section([text_display(\"Server stats\")]; accessory=thumbnail(media=unfurled_media(\"https://example.com/icon.png\")))\n\n\n\n\n\n","title":"Accord.section"},{"category":"function","location":"api/#Accord.text_display","page":"API Reference","text":"Use this to display plain text in v2 messages.\n\nCreate a Text Display component.\n\nExample\n\ntd = text_display(\"**Bold** and *italic* markdown supported\")\n\n\n\n\n\n","title":"Accord.text_display"},{"category":"function","location":"api/#Accord.separator","page":"API Reference","text":"Use this to add visual separation between components in v2 messages.\n\nCreate a Separator component.\n\nExample\n\nsep = separator(divider=true, spacing=2)\n\n\n\n\n\n","title":"Accord.separator"},{"category":"function","location":"api/#Accord.media_gallery","page":"API Reference","text":"Use this to display collections of images or videos in v2 messages.\n\nCreate a Media Gallery component.\n\nExample\n\ngallery = media_gallery([\n    media_gallery_item(media=unfurled_media(\"https://example.com/img1.png\")),\n    media_gallery_item(media=unfurled_media(\"https://example.com/img2.png\"); description=\"Photo 2\")\n])\n\n\n\n\n\n","title":"Accord.media_gallery"},{"category":"function","location":"api/#Accord.media_gallery_item","page":"API Reference","text":"Use this to add individual items to a media gallery.\n\nCreate a media gallery item.\n\nExample\n\nitem = media_gallery_item(media=unfurled_media(\"https://example.com/photo.png\"); description=\"A nice photo\", spoiler=true)\n\n\n\n\n\n","title":"Accord.media_gallery_item"},{"category":"function","location":"api/#Accord.file_component","page":"API Reference","text":"Use this to attach downloadable files to v2 messages.\n\nCreate a File component.\n\nExample\n\nf = file_component(media=unfurled_media(\"attachment://report.pdf\"))\n\n\n\n\n\n","title":"Accord.file_component"},{"category":"function","location":"api/#Accord.unfurled_media","page":"API Reference","text":"Use this to create media references for thumbnails, galleries, and file attachments.\n\nCreate an unfurled media object (used by thumbnail, media_gallery, file).\n\nExample\n\nmedia = unfurled_media(\"https://example.com/image.png\")\nthumb = thumbnail(media=media)\n\n\n\n\n\n","title":"Accord.unfurled_media"},{"category":"type","location":"api/#Accord.VoiceClient","page":"API Reference","text":"VoiceClient\n\nUse this to connect your bot to voice channels and play audio.\n\nManages a voice connection to a Discord voice channel. Handles the full connection flow: gateway → voice WS → UDP → audio.\n\ncompat: Accord 0.1.0\nVoice support was added in Accord 0.1.0.\n\n\n\n\n\n","title":"Accord.VoiceClient"},{"category":"function","location":"api/#Accord.connect!","page":"API Reference","text":"connect!(vc::VoiceClient) -> VoiceClient\n\nUse this to establish a connection to a voice channel before playing audio.\n\nConnect to the voice channel. This performs the full handshake:\n\nSend VOICESTATEUPDATE to gateway\nWait for VOICESTATEUPDATE and VOICESERVERUPDATE events\nConnect to voice WebSocket\nPerform IP discovery\nSelect protocol and establish session\n\nnote: Note\nYour bot must have the IntentGuildVoiceStates intent enabled, otherwise the connection will hang waiting for voice events.\n\nExample\n\nvc = VoiceClient(client, guild_id, channel_id)\nconnect!(vc)\n\n\n\n\n\n","title":"Accord.connect!"},{"category":"function","location":"api/#Accord.disconnect!","page":"API Reference","text":"disconnect!(vc::VoiceClient)\n\nUse this to leave a voice channel and clean up resources.\n\nDisconnect from the voice channel.\n\nExample\n\n# Leave the voice channel and clean up\ndisconnect!(vc)\n\n\n\n\n\n","title":"Accord.disconnect!"},{"category":"function","location":"api/#Accord.update_voice_state","page":"API Reference","text":"update_voice_state(client, guild_id; channel_id=nothing, self_mute=false, self_deaf=false)\n\nUse this to make your bot join, leave, or move between voice channels.\n\nSend a gateway command to update voice state (join/leave/move voice channels).\n\nExample\n\n# Join a voice channel (unmuted)\nupdate_voice_state(client, guild_id; channel_id=voice_channel_id)\n\n# Self-mute\nupdate_voice_state(client, guild_id; channel_id=voice_channel_id, self_mute=true)\n\n# Leave voice channel\nupdate_voice_state(client, guild_id; channel_id=nothing)\n\n\n\n\n\n","title":"Accord.update_voice_state"},{"category":"type","location":"api/#Accord.AudioPlayer","page":"API Reference","text":"AudioPlayer\n\nUse this to manage audio playback in voice channels including play, pause, and stop operations.\n\nControls playback of audio to a voice connection.\n\n\n\n\n\n","title":"Accord.AudioPlayer"},{"category":"function","location":"api/#Accord.play!","page":"API Reference","text":"play!(player, source, send_fn)\n\nUse this to begin playing audio from a source through a voice connection.\n\nStart playing an audio source. send_fn(opus_data) is called for each encoded frame.\n\n\n\n\n\nplay!(vc::VoiceClient, source::AbstractAudioSource)\n\nUse this to start playing audio in a connected voice channel.\n\nPlay audio from the given source.\n\nwarning: Warning\nOnly one source can play at a time. Calling play! while audio is already playing will stop the current source and start the new one.\n\nExample\n\nsource = FFmpegSource(\"music.mp3\")\nplay!(vc, source)\n\n\n\n\n\n","title":"Accord.play!"},{"category":"function","location":"api/#Accord.stop!","page":"API Reference","text":"Use this to immediately stop audio playback and clean up the source.\n\nStop playback.\n\n\n\n\n\nstop!(vc::VoiceClient)\n\nUse this to stop playing audio in a voice channel.\n\nStop audio playback.\n\nExample\n\n# Stop the current track without disconnecting\nstop!(vc)\n# Play something else\nplay!(vc, FFmpegSource(\"next_song.mp3\"))\n\n\n\n\n\n","title":"Accord.stop!"},{"category":"function","location":"api/#Accord.pause!","page":"API Reference","text":"Use this to temporarily pause audio playback without releasing resources.\n\nPause playback.\n\n\n\n\n\n","title":"Accord.pause!"},{"category":"function","location":"api/#Accord.resume!","page":"API Reference","text":"Use this to continue playing audio after a pause.\n\nResume playback.\n\n\n\n\n\n","title":"Accord.resume!"},{"category":"function","location":"api/#Accord.is_playing","page":"API Reference","text":"Use this to determine whether audio is currently being played.\n\nCheck if the player is currently playing.\n\n\n\n\n\n","title":"Accord.is_playing"},{"category":"type","location":"api/#Accord.AbstractAudioSource","page":"API Reference","text":"AbstractAudioSource\n\nUse this abstract type when implementing custom audio sources for voice playback.\n\nBase type for audio sources. Subtypes must implement:\n\nread_frame(source) -> Union{Vector{Int16}, Nothing} — read one frame of PCM audio (960 samples * channels)\nclose_source(source) — cleanup\n\n\n\n\n\n","title":"Accord.AbstractAudioSource"},{"category":"type","location":"api/#Accord.PCMSource","page":"API Reference","text":"PCMSource\n\nUse this to play raw PCM audio data through the voice connection.\n\nAudio source from raw PCM Int16 data (48kHz, stereo).\n\nExample\n\npcm_data = zeros(Int16, 48000 * 2 * 5)  # 5 seconds of silence\nsource = PCMSource(pcm_data)\n\n\n\n\n\n","title":"Accord.PCMSource"},{"category":"type","location":"api/#Accord.FileSource","page":"API Reference","text":"FileSource\n\nUse this to play audio from raw PCM files on disk.\n\nAudio source from a raw PCM file (48kHz, 16-bit signed LE, stereo).\n\nExample\n\nsource = FileSource(\"audio.raw\")\n\n\n\n\n\n","title":"Accord.FileSource"},{"category":"type","location":"api/#Accord.FFmpegSource","page":"API Reference","text":"FFmpegSource\n\nUse this to play audio files in any format supported by FFmpeg.\n\nAudio source that uses FFmpeg to decode any audio format to PCM. Requires ffmpeg to be available in PATH.\n\ncompat: Accord 0.1.0\nAudio sources (FFmpegSource, PCMSource, FileSource, SilenceSource) are available since Accord 0.1.0.\n\nExample\n\nsource = FFmpegSource(\"song.mp3\")\nsource_low_vol = FFmpegSource(\"song.mp3\"; volume=0.5)\n\n\n\n\n\n","title":"Accord.FFmpegSource"},{"category":"type","location":"api/#Accord.SilenceSource","page":"API Reference","text":"SilenceSource\n\nUse this to send silent frames and maintain the voice connection without playing audio.\n\nGenerates silence frames. Useful for keeping the voice connection alive.\n\nExample\n\n# Send 5 seconds of silence to keep the connection alive\nplay!(vc, SilenceSource(5000))\n\n\n\n\n\n","title":"Accord.SilenceSource"},{"category":"function","location":"api/#Accord.close_source","page":"API Reference","text":"Use this to release resources when done playing audio from a source.\n\nClose/cleanup the audio source.\n\n\n\n\n\n","title":"Accord.close_source"},{"category":"function","location":"api/#Accord.read_frame","page":"API Reference","text":"Use this to retrieve audio data from a source during playback.\n\nRead one PCM frame from the source. Returns nothing when done.\n\n\n\n\n\n","title":"Accord.read_frame"},{"category":"type","location":"api/#Accord.OpusEncoder","page":"API Reference","text":"Use this to encode PCM audio to Opus format for voice transmission.\n\nOpus encoder handle.\n\n\n\n\n\n","title":"Accord.OpusEncoder"},{"category":"type","location":"api/#Accord.OpusDecoder","page":"API Reference","text":"Use this to decode Opus audio back to PCM format.\n\nOpus decoder handle.\n\n\n\n\n\n","title":"Accord.OpusDecoder"},{"category":"function","location":"api/#Accord.opus_encode","page":"API Reference","text":"opus_encode(encoder, pcm) -> Vector{UInt8}\n\nUse this to compress PCM audio into Opus format for efficient voice transmission.\n\nEncode PCM audio (Int16 samples) to Opus. pcm should contain frame_size * channels samples.\n\n\n\n\n\n","title":"Accord.opus_encode"},{"category":"function","location":"api/#Accord.opus_decode","page":"API Reference","text":"opus_decode(decoder, data, frame_size) -> Vector{Int16}\n\nUse this to decompress Opus audio back into PCM format for playback or processing.\n\nDecode Opus data to PCM audio (Int16 samples).\n\n\n\n\n\n","title":"Accord.opus_decode"},{"category":"function","location":"api/#Accord.set_bitrate!","page":"API Reference","text":"Use this to adjust the audio quality and bandwidth usage of the Opus encoder.\n\nSet the bitrate for an Opus encoder.\n\n\n\n\n\n","title":"Accord.set_bitrate!"},{"category":"function","location":"api/#Accord.set_signal!","page":"API Reference","text":"Use this to optimize the encoder for either music or voice content.\n\nSet the signal type for an Opus encoder (OPUSSIGNALMUSIC or OPUSSIGNALVOICE).\n\n\n\n\n\n","title":"Accord.set_signal!"},{"category":"function","location":"api/#Accord.init_sodium","page":"API Reference","text":"Initialize libsodium (must be called once).\n\n\n\n\n\n","title":"Accord.init_sodium"},{"category":"function","location":"api/#Accord.random_nonce","page":"API Reference","text":"Generate a random nonce of the specified length.\n\n\n\n\n\n","title":"Accord.random_nonce"},{"category":"module","location":"api/#Accord.LibDave","page":"API Reference","text":"Accord.LibDave\n\nLow-level bindings to libdave's C API. You normally don't call these directly: VoiceClient drives the DAVE session. Load the library with ENV[\"ACCORD_LIBDAVE\"] = \"/path/to/libdave.so\" (read on first use) or LibDave.load!.\n\n\n\n\n\n","title":"Accord.LibDave"},{"category":"function","location":"api/#Accord.LibDave.load!","page":"API Reference","text":"load!(path=get(ENV, \"ACCORD_LIBDAVE\", \"\")) -> Bool\n\nLoad libdave from path. Returns true when the library is loaded (now or before), false when no path is configured. Throws if the path is set but the library cannot be opened.\n\n\n\n\n\n","title":"Accord.LibDave.load!"},{"category":"function","location":"api/#Accord.LibDave.available","page":"API Reference","text":"available() -> Bool\n\nWhether libdave is loaded or can be loaded from ACCORD_LIBDAVE.\n\n\n\n\n\n","title":"Accord.LibDave.available"},{"category":"function","location":"api/#Accord.LibDave.max_protocol_version","page":"API Reference","text":"Highest DAVE protocol version the loaded libdave supports.\n\n\n\n\n\n","title":"Accord.LibDave.max_protocol_version"},{"category":"type","location":"api/#Accord.LibDave.Session","page":"API Reference","text":"MLS group state for one voice connection (DAVESessionHandle).\n\n\n\n\n\n","title":"Accord.LibDave.Session"},{"category":"function","location":"api/#Accord.LibDave.key_package","page":"API Reference","text":"Serialized MLS key package to send to the voice gateway (opcode 26).\n\n\n\n\n\n","title":"Accord.LibDave.key_package"},{"category":"function","location":"api/#Accord.LibDave.process_proposals","page":"API Reference","text":"process_proposals(s, payload, recognized_user_ids) -> Vector{UInt8}\n\nProcess an opcode 27 payload (operation type byte + proposals). Returns the commit/welcome bytes to send back (opcode 28), or an empty vector when there is nothing to commit.\n\n\n\n\n\n","title":"Accord.LibDave.process_proposals"},{"category":"function","location":"api/#Accord.LibDave.process_commit","page":"API Reference","text":"process_commit(s, commit) -> (; failed, ignored, roster)\n\nApply an announced commit (opcode 29).\n\n\n\n\n\n","title":"Accord.LibDave.process_commit"},{"category":"function","location":"api/#Accord.LibDave.process_welcome","page":"API Reference","text":"process_welcome(s, welcome, recognized_user_ids) -> Union{Vector{UInt64}, Nothing}\n\nJoin the group from a Welcome (opcode 30). Returns the roster, or nothing when the welcome could not be processed.\n\n\n\n\n\n","title":"Accord.LibDave.process_welcome"},{"category":"type","location":"api/#Accord.LibDave.KeyRatchet","page":"API Reference","text":"Per-sender key ratchet (DAVEKeyRatchetHandle).\n\n\n\n\n\n","title":"Accord.LibDave.KeyRatchet"},{"category":"function","location":"api/#Accord.LibDave.key_ratchet","page":"API Reference","text":"Key ratchet for user_id in the current epoch, or nothing.\n\n\n\n\n\n","title":"Accord.LibDave.key_ratchet"},{"category":"type","location":"api/#Accord.LibDave.Encryptor","page":"API Reference","text":"Frame encryptor (DAVEEncryptorHandle). Holds a reference to its key ratchet, because libdave does not take ownership of it.\n\n\n\n\n\n","title":"Accord.LibDave.Encryptor"},{"category":"function","location":"api/#Accord.LibDave.encrypt","page":"API Reference","text":"encrypt(e, ssrc, frame) -> (code, bytes)\n\nEncrypt one Opus frame. code is libdave's result code (0 on success).\n\n\n\n\n\n","title":"Accord.LibDave.encrypt"},{"category":"type","location":"api/#Accord.LibDave.Decryptor","page":"API Reference","text":"Frame decryptor for one remote sender (DAVEDecryptorHandle).\n\n\n\n\n\n","title":"Accord.LibDave.Decryptor"},{"category":"function","location":"api/#Accord.LibDave.decrypt","page":"API Reference","text":"decrypt(d, frame) -> (code, bytes)\n\nDecrypt one DAVE audio frame. code is libdave's result code (0 on success).\n\n\n\n\n\n","title":"Accord.LibDave.decrypt"},{"category":"type","location":"api/#Accord.DaveSession","page":"API Reference","text":"DaveSession\n\nPer-connection DAVE state. Created by the voice gateway when the server announces a DAVE protocol version; frames go through dave_encrypt before transport encryption.\n\n\n\n\n\n","title":"Accord.DaveSession"},{"category":"function","location":"api/#Accord.dave_session_description!","page":"API Reference","text":"dave_session_description!(ds, protocol_version)\n\nHandle the DAVE part of opcode 4: start (or skip) E2EE at the given version.\n\n\n\n\n\n","title":"Accord.dave_session_description!"},{"category":"function","location":"api/#Accord.dave_handle_json!","page":"API Reference","text":"dave_handle_json!(ds, op, d)\n\nHandle a JSON DAVE opcode (11, 13, 21, 22, 24). Returns true if op was a DAVE opcode.\n\n\n\n\n\n","title":"Accord.dave_handle_json!"},{"category":"function","location":"api/#Accord.dave_handle_binary!","page":"API Reference","text":"dave_handle_binary!(ds, op, payload)\n\nHandle a binary DAVE opcode (25, 27, 29, 30). payload excludes the sequence number and opcode bytes.\n\n\n\n\n\n","title":"Accord.dave_handle_binary!"},{"category":"function","location":"api/#Accord.dave_encrypt","page":"API Reference","text":"dave_encrypt(ds, ssrc, opus) -> Union{Vector{UInt8}, Nothing}\n\nE2EE-encrypt one outgoing Opus frame. Returns the frame unchanged when E2EE is off (protocol version 0), and nothing when the frame must be dropped because the key for the current epoch isn't ready yet.\n\n\n\n\n\n","title":"Accord.dave_encrypt"},{"category":"function","location":"api/#Accord.parse_dave_binary","page":"API Reference","text":"parse_dave_binary(frame) -> (seq, op, payload)\n\nSplit a server→client binary voice gateway frame: big-endian uint16 sequence number, uint8 opcode, then the payload.\n\n\n\n\n\n","title":"Accord.parse_dave_binary"},{"category":"function","location":"api/#Accord.dave_binary_frame","page":"API Reference","text":"Client→server binary frame: opcode byte followed by the payload (no sequence number).\n\n\n\n\n\n","title":"Accord.dave_binary_frame"},{"category":"type","location":"api/#Accord.Snowflake","page":"API Reference","text":"Snowflake\n\nUse this type to work with Discord's unique identifier format for all Discord objects.\n\nDiscord Snowflake ID type — a UInt64 wrapper with timestamp extraction. Discord sends snowflakes as JSON strings; we parse them to UInt64.\n\nExample\n\njulia> id = Snowflake(\"1234567890123456789\")\nSnowflake(1234567890123456789)\n\njulia> id = Snowflake(1234567890123456789)\nSnowflake(1234567890123456789)\n\n\n\n\n\n","title":"Accord.Snowflake"},{"category":"function","location":"api/#Accord.timestamp","page":"API Reference","text":"Use this to find out when a Discord object was created based on its ID.\n\nExtract the creation timestamp from a Snowflake.\n\nExample\n\njulia> id = Snowflake(\"175928847299117063\");\n\njulia> timestamp(id)\n2016-04-30T11:18:25.796\n\n\n\n\n\n","title":"Accord.timestamp"},{"category":"function","location":"api/#Accord.worker_id","page":"API Reference","text":"Use this for debugging or analyzing how Discord distributes ID generation across workers.\n\nExtract the internal worker ID.\n\nExample\n\njulia> Int(Accord.worker_id(Snowflake(\"175928847299117063\")))\n1\n\n\n\n\n\n","title":"Accord.worker_id"},{"category":"function","location":"api/#Accord.process_id","page":"API Reference","text":"Use this for debugging or analyzing how Discord distributes ID generation across processes.\n\nExtract the internal process ID.\n\nExample\n\njulia> Int(Accord.process_id(Snowflake(\"175928847299117063\")))\n0\n\n\n\n\n\n","title":"Accord.process_id"},{"category":"function","location":"api/#Accord.increment","page":"API Reference","text":"Use this for debugging or understanding the sequence of IDs generated within the same millisecond.\n\nExtract the increment.\n\nExample\n\njulia> Int(Accord.increment(Snowflake(\"175928847299117063\")))\n7\n\n\n\n\n\n","title":"Accord.increment"},{"category":"type","location":"api/#Accord.User","page":"API Reference","text":"User\n\nRepresents a Discord user. Users are global and not tied to any specific guild, although they can have guild-specific metadata (see Member).\n\nFields\n\nid::Snowflake: The unique ID of the user.\nusername::String: The user's Discord username.\ndiscriminator::Maybe{String}: The user's 4-digit tag (legacy, e.g., \"1234\").\nglobal_name::Maybe{String}: The user's display name as seen by everyone.\navatar::Maybe{String}: The hash of the user's avatar.\nbot::Maybe{Bool}: Whether the user is an official bot.\nsystem::Maybe{Bool}: Whether the user is an official Discord system user.\nmfa_enabled::Maybe{Bool}: Whether the user has two-factor authentication enabled.\nbanner::Maybe{String}: The hash of the user's banner image.\naccent_color::Maybe{Int}: The user's banner color encoded as an integer.\nlocale::Maybe{String}: The user's chosen language (e.g., \"en-US\").\nverified::Maybe{Bool}: Whether the email on this account has been verified.\nemail::Maybe{String}: The user's email address (requires scopes).\nflags::Maybe{Int}: The public flags on a user's account.\npremium_type::Maybe{Int}: The type of Nitro subscription on a user's account.\npublic_flags::Maybe{Int}: The public flags on a user's account.\navatar_decoration_data::Maybe{Any}: Metadata about the user's avatar decoration.\ncollectibles::Maybe{Any}: Collectibles the user has (nameplates, …).\nprimary_guild::Maybe{PrimaryGuild}: The server tag the user displays.\n\nExample\n\nuser = msg.author\nprintln(\"Hello, $(user.username)!\")\n\nSee Also\n\nDiscord API: User Object\n\n\n\n\n\n","title":"Accord.User"},{"category":"type","location":"api/#Accord.PrimaryGuild","page":"API Reference","text":"PrimaryGuild\n\nThe server tag a user displays next to their name (User.primary_guild).\n\nFields\n\nidentity_guild_id::Maybe{Snowflake}: The guild whose tag is shown.\nidentity_enabled::Maybe{Bool}: Whether the tag is shown; empty when Discord cleared it.\ntag::Maybe{String}: The tag text (up to 4 characters).\nbadge::Maybe{String}: The badge image hash.\n\n\n\n\n\n","title":"Accord.PrimaryGuild"},{"category":"type","location":"api/#Accord.Member","page":"API Reference","text":"Member\n\nRepresents a Discord guild member. A Member differs from a User in that it contains metadata specific to a particular guild (like nicknames and roles).\n\nFields\n\nuser::Maybe{User}: The underlying user object.\nnick::Maybe{String}: The guild-specific nickname.\navatar::Maybe{String}: The guild-specific avatar hash.\nroles::Vector{Snowflake}: Array of role IDs assigned to this member.\njoined_at::String: ISO8601 timestamp of when the member joined the guild.\npremium_since::Maybe{String}: ISO8601 timestamp of when the member started boosting the guild.\ndeaf::Maybe{Bool}: Whether the member is deafened in voice channels.\nmute::Maybe{Bool}: Whether the member is muted in voice channels.\nflags::Int: Guild member flags (see GuildMemberFlags).\npending::Maybe{Bool}: Whether the member has not yet passed the guild's Membership Screening.\npermissions::Maybe{String}: Total permissions of the member in a channel (sent in interactions).\ncommunication_disabled_until::Maybe{String}: ISO8601 timestamp of when the member's timeout expires.\navatar_decoration_data::Maybe{Any}: Metadata about the member's guild avatar decoration.\n\nExample\n\nmember = msg.member\nif !ismissing(member.nick)\n    println(\"Member nickname: $(member.nick)\")\nend\n\nSee Also\n\nDiscord API: Guild Member Object\n\n\n\n\n\n","title":"Accord.Member"},{"category":"type","location":"api/#Accord.Role","page":"API Reference","text":"Role\n\nRepresents a Discord guild role. Roles are used to grant permissions to users and group them in the member list.\n\nFields\n\nid::Snowflake: The unique ID of the role.\nname::String: The name of the role (e.g., \"@everyone\", \"Moderator\").\ncolor::Int: The role colour as an integer (deprecated by Discord in favour of colors).\ncolors::Optional{RoleColors}: Primary, secondary and tertiary colours.\nhoist::Bool: Whether the role is pinned (hoisted) in the user listing.\nicon::Optional{String}: The role's icon hash.\nunicode_emoji::Optional{String}: The role's unicode emoji.\nposition::Int: Position of this role in the hierarchy (higher is higher).\npermissions::String: Permission bitfield as a string.\nmanaged::Bool: Whether the role is managed by an integration (bot, etc.).\nmentionable::Bool: Whether the role can be mentioned by anyone.\ntags::Optional{RoleTags}: Special tags for this role.\nflags::Int: Role flags (see RoleFlags).\n\nExample\n\nroles = guild.roles\nmod_role = findfirst(r -> r.name == \"Moderator\", roles)\nprintln(\"Moderator role ID: $(mod_role.id)\")\n\nSee Also\n\nDiscord API: Role Object\n\n\n\n\n\n","title":"Accord.Role"},{"category":"type","location":"api/#Accord.DiscordChannel","page":"API Reference","text":"DiscordChannel\n\nRepresents a Discord channel. This can be a text channel, voice channel, category,  thread, or DM.\n\nChannels are the primary containers for messages and other Discord resources.\n\nFields\n\nid::Snowflake: The unique ID of the channel.\ntype::Int: The type of channel (see ChannelTypes).\nguild_id::Optional{Snowflake}: The ID of the guild (missing for DMs).\nposition::Optional{Int}: Sorting position in the guild.\npermission_overwrites::Optional{Vector{Overwrite}}: Explicit permission overwrites.\nname::Optional{String}: The name of the channel.\ntopic::Optional{String}: The channel topic.\nnsfw::Optional{Bool}: Whether the channel is marked as age-restricted.\nlast_message_id::Optional{Snowflake}: ID of the most recent message.\nbitrate::Optional{Int}: Bitrate (in bits) for voice channels.\nuser_limit::Optional{Int}: Maximum users allowed in a voice channel.\nrate_limit_per_user::Optional{Int}: Slowmode duration in seconds.\nrecipients::Optional{Vector{User}}: The recipients of a DM.\nicon::Optional{String}: Icon hash for group DMs.\nowner_id::Optional{Snowflake}: ID of the creator of a thread or group DM.\napplication_id::Optional{Snowflake}: Application ID of a bot-created group DM.\nmanaged::Optional{Bool}: Whether a group DM is managed by an app.\nparent_id::Optional{Snowflake}: ID of the category or parent channel.\nlast_pin_timestamp::Optional{String}: ISO8601 timestamp of the last pinned message.\nrtc_region::Optional{String}: Voice region ID (automatic if null).\nvideo_quality_mode::Optional{Int}: Video quality (1=auto, 2=full).\nmessage_count::Optional{Int}: Approximate message count in threads.\nmember_count::Optional{Int}: Approximate member count in threads.\nthread_metadata::Optional{ThreadMetadata}: Thread-specific metadata.\nmember::Optional{ThreadMember}: Thread member object for the current user.\ndefault_auto_archive_duration::Optional{Int}: Default duration for new threads.\npermissions::Optional{String}: Computed permissions for the user (in interactions).\nflags::Optional{Int}: Channel flags (see ChannelFlags).\ntotal_message_sent::Optional{Int}: Total messages ever sent in a thread.\navailable_tags::Optional{Vector{ForumTag}}: Tags available in forum channels.\napplied_tags::Optional{Vector{Snowflake}}: Tags applied to a thread.\ndefault_reaction_emoji::Optional{DefaultReaction}: Default forum reaction emoji.\ndefault_thread_rate_limit_per_user::Optional{Int}: Initial slowmode for new threads.\ndefault_sort_order::Optional{Int}: Default sort order for forum posts.\ndefault_forum_layout::Optional{Int}: Default view layout for forum posts.\n\nExample\n\nchannel = fetch_channel(client, id)\nprintln(\"Channel name: $(channel.name)\")\n\nSee Also\n\nDiscord API: Channel Object\n\n\n\n\n\n","title":"Accord.DiscordChannel"},{"category":"type","location":"api/#Accord.Message","page":"API Reference","text":"Message\n\nRepresents a message sent in a Discord channel.\n\nA Message is the primary way users communicate on Discord. It contains text, attachments, embeds, and more.\n\nFields\n\nid::Snowflake: The unique ID of the message.\nchannel_id::Snowflake: The ID of the channel the message was sent in.\nauthor::Optional{User}: The user who sent the message (may be missing for some webhooks).\ncontent::Optional{String}: The text content of the message.\ntimestamp::Optional{String}: ISO8601 timestamp of when the message was sent.\nedited_timestamp::Optional{String}: ISO8601 timestamp of when the message was last edited.\ntts::Optional{Bool}: Whether the message was a text-to-speech message.\nmention_everyone::Optional{Bool}: Whether the message mentions @everyone.\nmentions::Optional{Vector{User}}: Users specifically mentioned in the message.\nmention_roles::Optional{Vector{Snowflake}}: Roles specifically mentioned in the message.\nmention_channels::Optional{Vector{ChannelMention}}: Channels mentioned in the message.\nattachments::Optional{Vector{Attachment}}: Files attached to the message.\nembeds::Optional{Vector{Embed}}: Rich embeds contained in the message.\nreactions::Optional{Vector{Reaction}}: Reactions added to the message.\nnonce::Optional{Any}: A value used for optimistic message sending.\npinned::Optional{Bool}: Whether the message is pinned.\nwebhook_id::Optional{Snowflake}: If sent by a webhook, the webhook's ID.\ntype::Optional{Int}: The message type (see MessageType).\nactivity::Optional{MessageActivity}: Associated activity (e.g., Spotify).\napplication_id::Optional{Snowflake}: The ID of the application if sent by an app.\nmessage_reference::Optional{MessageReference}: Metadata about a replied-to message.\nflags::Optional{Int}: Message flags (see MessageFlags).\nreferenced_message::Optional{Message}: The message being replied to.\ninteraction_metadata::Optional{MessageInteractionMetadata}: Metadata about the interaction this message responded to.\nthread::Optional{DiscordChannel}: The thread that was started from this message.\ncomponents::Optional{Vector{Component}}: Buttons, select menus, and other UI components.\nsticker_items::Optional{Vector{StickerItem}}: Stickers sent with the message.\nposition::Optional{Int}: A generally increasing integer for message ordering in threads.\npoll::Optional{Poll}: An associated poll.\nguild_id::Optional{Snowflake}: The ID of the guild the message was sent in.\nmember::Optional{Member}: Member properties for the author (only in some contexts).\nmessage_snapshots::Optional{Vector{MessageSnapshot}}: The forwarded message, for forwards.\n\nExample\n\non_message(ctx) do msg\n    println(\"Received message from $(msg.author.username): $(msg.content)\")\nend\n\nSee Also\n\nDiscord API: Message Object\n\n\n\n\n\n","title":"Accord.Message"},{"category":"type","location":"api/#Accord.MessageSnapshot","page":"API Reference","text":"MessageSnapshot\n\nA copy of a forwarded message at the time it was forwarded (Message.message_snapshots). The copied fields are in message, a SnapshotMessage.\n\n\n\n\n\n","title":"Accord.MessageSnapshot"},{"category":"type","location":"api/#Accord.SnapshotMessage","page":"API Reference","text":"SnapshotMessage\n\nThe part of a forwarded message that Discord copies into the forward: content, embeds, attachments, components and mentions, but no author.\n\n\n\n\n\n","title":"Accord.SnapshotMessage"},{"category":"type","location":"api/#Accord.MessagePin","page":"API Reference","text":"MessagePin\n\nA pinned message and when it was pinned, as returned by get_pinned_messages.\n\n\n\n\n\n","title":"Accord.MessagePin"},{"category":"type","location":"api/#Accord.ChannelPins","page":"API Reference","text":"ChannelPins\n\nOne page of a channel's pins: items (newest first) and has_more. Pass the last item's pinned_at as before to get_pinned_messages for the next page.\n\n\n\n\n\n","title":"Accord.ChannelPins"},{"category":"type","location":"api/#Accord.Embed","page":"API Reference","text":"Embed\n\nRepresents a rich embed object that can be sent with messages. \n\nEmbeds allow bots to present structured content with colors, images, and  multiple fields.\n\nFields\n\ntitle::Optional{String}: Title of the embed (max 256 characters).\ntype::Optional{String}: Type of embed (default \"rich\").\ndescription::Optional{String}: Main content of the embed (max 4096 characters).\nurl::Optional{String}: URL of the embed (links the title).\ntimestamp::Optional{String}: ISO8601 timestamp displayed in the embed.\ncolor::Optional{Int}: Color code of the embed (integer).\nfooter::Optional{EmbedFooter}: Footer information.\nimage::Optional{EmbedImage}: Main image information.\nthumbnail::Optional{EmbedThumbnail}: Thumbnail information.\nvideo::Optional{EmbedVideo}: Video information (read-only).\nprovider::Optional{EmbedProvider}: Provider information (read-only).\nauthor::Optional{EmbedAuthor}: Author information.\nfields::Optional{Vector{EmbedField}}: Up to 25 fields.\n\nExample\n\nembed = Embed(\n    title = \"System Status\",\n    description = \"All systems operational.\",\n    color = 0x00ff00\n)\npush!(embed.fields, EmbedField(name=\"CPU\", value=\"15%\", inline=true))\n\nSee Also\n\nDiscord API: Embed Object\n\n\n\n\n\n","title":"Accord.Embed"},{"category":"type","location":"api/#Accord.Interaction","page":"API Reference","text":"Interaction\n\nRepresents a Discord interaction (Slash Command, Component, Modal, etc.).\n\nAn Interaction is sent by Discord whenever a user interacts with your bot's  commands or components.\n\nFields\n\nid::Snowflake: The unique ID of the interaction.\napplication_id::Snowflake: ID of the application.\ntype::Int: Type of interaction (see InteractionTypes).\ndata::Optional{InteractionData}: The command/component data payload.\nguild_id::Optional{Snowflake}: ID of the guild it originated from.\nchannel::Optional{DiscordChannel}: The channel it originated from.\nmember::Optional{Member}: Member data for the invoking user (in guilds).\nuser::Optional{User}: User data for the invoking user (in DMs).\ntoken::String: Continuation token for responding.\nmessage::Optional{Message}: The message the component was attached to.\n\nExample\n\non_interaction(ctx) do int\n    if int.type == InteractionTypes.APPLICATION_COMMAND\n        println(\"Command invoked: $(int.data.name)\")\n    end\nend\n\nSee Also\n\nDiscord API: Interaction Object\n\n\n\n\n\n","title":"Accord.Interaction"},{"category":"type","location":"api/#Accord.Emoji","page":"API Reference","text":"Emoji\n\nRepresents a Discord emoji. This can be a standard Unicode emoji or a  custom guild emoji.\n\nFields\n\nid::Nullable{Snowflake}: Unique ID for custom emojis (null for Unicode).\nname::Nullable{String}: Name of the emoji (e.g., \"thinking\" or \"Julia\").\nroles::Optional{Vector{Snowflake}}: Roles allowed to use this emoji.\nuser::Optional{User}: User that created this emoji.\nrequire_colons::Optional{Bool}: Whether the emoji requires colons (custom emojis).\nmanaged::Optional{Bool}: Whether the emoji is managed by an integration.\nanimated::Optional{Bool}: Whether the emoji is animated.\navailable::Optional{Bool}: Whether the emoji can be used.\n\nSee Also\n\nDiscord API: Emoji Object\n\n\n\n\n\n","title":"Accord.Emoji"},{"category":"type","location":"api/#Accord.Reaction","page":"API Reference","text":"Reaction\n\nRepresents an emoji reaction to a Discord message.\n\nFields\n\ncount::Int: Total number of times this emoji was used.\ncount_details::Optional{ReactionCountDetails}: Specific breakdown of reaction types.\nme::Bool: Whether the current bot/user reacted with this emoji.\nme_burst::Bool: Whether the current user super-reacted.\nemoji::Optional{Emoji}: The emoji used for the reaction.\nburst_colors::Vector{String}: HEX colors for the super-reaction animation.\n\nSee Also\n\nDiscord API: Reaction Object\n\n\n\n\n\n","title":"Accord.Reaction"},{"category":"type","location":"api/#Accord.AutoModRule","page":"API Reference","text":"AutoModRule\n\nRepresents a rule for the Discord Auto Moderation system.\n\nRules define what content is filtered and what actions are taken automatically.\n\nFields\n\nid::Snowflake: Unique ID of the rule.\nguild_id::Snowflake: ID of the guild the rule belongs to.\nname::String: Name of the rule.\ncreator_id::Snowflake: ID of the user who created the rule.\nevent_type::Int: Event context (see AutoModEventTypes).\ntrigger_type::Int: What triggers the rule (see AutoModTriggerTypes).\ntrigger_metadata::Optional{AutoModTriggerMetadata}: Details about the trigger.\nactions::Vector{AutoModAction}: Actions to perform on trigger.\nenabled::Bool: Whether the rule is active.\nexempt_roles::Vector{Snowflake}: Roles exempt from this rule.\nexempt_channels::Vector{Snowflake}: Channels exempt from this rule.\n\nSee Also\n\nDiscord API: Auto Moderation Rule Object\n\n\n\n\n\n","title":"Accord.AutoModRule"},{"category":"type","location":"api/#Accord.Guild","page":"API Reference","text":"Guild\n\nRepresents a Discord guild (server).\n\nA Guild contains all the data about a server, including its name, roles,  emojis, and (in GUILD_CREATE events) its channels and members.\n\nFields\n\nid::Snowflake: The unique ID of the guild.\nname::String: The guild's name.\nicon::Nullable{String}: The guild's icon hash.\nsplash::Nullable{String}: The guild's splash image hash.\ndiscovery_splash::Nullable{String}: Discovery splash hash (for partnered/verified).\nowner_id::Optional{Snowflake}: ID of the guild owner.\npermissions::Optional{String}: Total permissions for the user in the guild.\nafk_channel_id::Nullable{Snowflake}: ID of the AFK voice channel.\nafk_timeout::Optional{Int}: AFK timeout in seconds.\nwidget_enabled::Optional{Bool}: Whether the server widget is enabled.\nverification_level::Optional{Int}: Verification level required for the guild.\nroles::Optional{Vector{Role}}: Roles assigned to this guild.\nemojis::Optional{Vector{Emoji}}: Custom emojis in this guild.\nfeatures::Optional{Vector{String}}: List of enabled guild features (e.g., \"COMMUNITY\").\nmfa_level::Optional{Int}: MFA level required for moderators.\nsystem_channel_id::Nullable{Snowflake}: ID of the channel where system messages are sent.\nvanity_url_code::Nullable{String}: The vanity URL code (for boosted guilds).\ndescription::Nullable{String}: The guild's description.\nbanner::Nullable{String}: The guild's banner image hash.\npremium_tier::Optional{Int}: The Nitro boost tier of the guild.\npremium_subscription_count::Optional{Int}: The number of Nitro boosts.\napproximate_member_count::Optional{Int}: Approximate total member count.\napproximate_presence_count::Optional{Int}: Approximate online member count.\nnsfw_level::Optional{Int}: Guild's NSFW level.\nstickers::Optional{Vector{Sticker}}: Custom stickers in this guild.\n\nExample\n\nguild = fetch_guild(client, guild_id)\nprintln(\"Server name: $(guild.name) ($(guild.id))\")\n\nSee Also\n\nDiscord API: Guild Object\n\n\n\n\n\n","title":"Accord.Guild"},{"category":"type","location":"api/#Accord.Presence","page":"API Reference","text":"Presence\n\nRepresents a user's current status and activities.\n\nFields\n\nuser::Any: The user being updated (partial).\nguild_id::Optional{Snowflake}: Guild ID.\nstatus::String: The user's status (online, dnd, idle, invisible, offline).\nactivities::Vector{Activity}: Current activities.\nclient_status::Optional{ClientStatus}: Status per platform.\n\nSee Also\n\nDiscord API: Presence Update Event\n\n\n\n\n\n","title":"Accord.Presence"},{"category":"type","location":"api/#Accord.Attachment","page":"API Reference","text":"Attachment\n\nRepresents a file attached to a Discord message. This can be an image, video, audio file, or any other type of file.\n\nFields\n\nid::Snowflake: The unique ID of the attachment.\nfilename::String: The name of the file (e.g., \"cat.png\").\ntitle::Optional{String}: The title of the file (usually for audio files).\ndescription::Optional{String}: A description for the file (alt text, max 1024 characters).\ncontent_type::Optional{String}: The MIME type of the file (e.g., \"image/png\").\nsize::Int: The size of the file in bytes.\nurl::String: The source URL of the file.\nproxy_url::String: A proxied URL of the file.\nheight::Optional{Int}: The height of the file (if it is an image).\nwidth::Optional{Int}: The width of the file (if it is an image).\nephemeral::Optional{Bool}: Whether this attachment is ephemeral (removed after a period).\nduration_secs::Optional{Float64}: The duration of the audio file (for voice messages).\nwaveform::Optional{String}: Base64 encoded waveform data (for voice messages).\nflags::Optional{Int}: Attachment flags (see AttachmentFlags).\n\nSee Also\n\nDiscord API: Attachment Object\n\n\n\n\n\n","title":"Accord.Attachment"},{"category":"type","location":"api/#Accord.ThreadMetadata","page":"API Reference","text":"ThreadMetadata\n\nContains metadata about a Discord thread, such as its archive status and lock state.\n\nFields\n\narchived::Bool: Whether the thread is archived.\nauto_archive_duration::Int: Duration in minutes to automatically archive the thread after recent activity (60, 1440, 4320, 10080).\narchive_timestamp::String: ISO8601 timestamp when the thread's archive status was last changed.\nlocked::Bool: Whether the thread is locked.\ninvitable::Optional{Bool}: Whether non-moderators can add other non-moderators to a private thread.\ncreate_timestamp::Optional{String}: ISO8601 timestamp when the thread was created.\n\nSee Also\n\nDiscord API: Thread Metadata Object\n\n\n\n\n\n","title":"Accord.ThreadMetadata"},{"category":"type","location":"api/#Accord.ThreadMember","page":"API Reference","text":"ThreadMember\n\nRepresents a member of a thread.\n\nFields\n\nid::Optional{Snowflake}: ID of the thread.\nuser_id::Optional{Snowflake}: ID of the user.\njoin_timestamp::String: ISO8601 timestamp when the user joined the thread.\nflags::Int: User-thread settings (notifications, etc.).\nmember::Optional{Member}: Additional member information (if requested).\n\nSee Also\n\nDiscord API: Thread Member Object\n\n\n\n\n\n","title":"Accord.ThreadMember"},{"category":"type","location":"api/#Accord.ForumTag","page":"API Reference","text":"ForumTag\n\nRepresents a tag that can be applied to threads in a forum or media channel.\n\nFields\n\nid::Snowflake: Unique ID of the tag.\nname::String: The name of the tag (0-20 characters).\nmoderated::Bool: Whether this tag can only be added/removed by moderators.\nemoji_id::Nullable{Snowflake}: ID of a custom guild emoji.\nemoji_name::Nullable{String}: Unicode character of the emoji.\n\nSee Also\n\nDiscord API: Forum Tag Object\n\n\n\n\n\n","title":"Accord.ForumTag"},{"category":"type","location":"api/#Accord.DefaultReaction","page":"API Reference","text":"DefaultReaction\n\nThe default emoji shown in the reaction button for a forum post.\n\nFields\n\nemoji_id::Nullable{Snowflake}: ID of a custom guild emoji.\nemoji_name::Nullable{String}: Unicode character of the emoji.\n\n\n\n\n\n","title":"Accord.DefaultReaction"},{"category":"type","location":"api/#Accord.Overwrite","page":"API Reference","text":"Overwrite\n\nRepresents a permission overwrite for a role or member in a specific channel.\n\nOverwrites allow you to customize permissions on a per-channel basis,  overriding the default guild permissions for specific entities.\n\nFields\n\nid::Snowflake: The ID of the role or member.\ntype::Int: The type of entity (0 for role, 1 for member).\nallow::String: Bitset of allowed permissions (string).\ndeny::String: Bitset of denied permissions (string).\n\nSee Also\n\nDiscord API: Overwrite Object\n\n\n\n\n\n","title":"Accord.Overwrite"},{"category":"type","location":"api/#Accord.EmbedFooter","page":"API Reference","text":"EmbedFooter\n\nThe footer section of an Embed.\n\nFields\n\ntext::String: The footer text (max 2048 characters).\nicon_url::Optional{String}: URL of the footer icon (http/https/attachments only).\nproxy_icon_url::Optional{String}: A proxied URL of the footer icon.\n\nSee Also\n\nDiscord API: Embed Footer\n\n\n\n\n\n","title":"Accord.EmbedFooter"},{"category":"type","location":"api/#Accord.EmbedImage","page":"API Reference","text":"EmbedImage\n\nImage information within an Embed.\n\nFields\n\nurl::String: Source URL of the image.\nproxy_url::Optional{String}: A proxied URL of the image.\nheight::Optional{Int}: Height of the image.\nwidth::Optional{Int}: Width of the image.\n\nSee Also\n\nDiscord API: Embed Image\n\n\n\n\n\n","title":"Accord.EmbedImage"},{"category":"type","location":"api/#Accord.EmbedThumbnail","page":"API Reference","text":"EmbedThumbnail\n\nThumbnail information for an Embed, displayed at the top right.\n\nFields\n\nurl::String: Source URL of the thumbnail.\nproxy_url::Optional{String}: A proxied URL of the thumbnail.\nheight::Optional{Int}: Height of the thumbnail.\nwidth::Optional{Int}: Width of the thumbnail.\n\nSee Also\n\nDiscord API: Embed Thumbnail\n\n\n\n\n\n","title":"Accord.EmbedThumbnail"},{"category":"type","location":"api/#Accord.EmbedVideo","page":"API Reference","text":"EmbedVideo\n\nVideo information within an Embed.\n\nSee Also\n\nDiscord API: Embed Video\n\n\n\n\n\n","title":"Accord.EmbedVideo"},{"category":"type","location":"api/#Accord.EmbedField","page":"API Reference","text":"EmbedField\n\nA key-value field within an Embed. Up to 25 fields can be added.\n\nFields\n\nname::String: Name of the field (max 256 characters).\nvalue::String: Value of the field (max 1024 characters).\ninline::Optional{Bool}: Whether the field should display inline with others.\n\nSee Also\n\nDiscord API: Embed Field\n\n\n\n\n\n","title":"Accord.EmbedField"},{"category":"type","location":"api/#Accord.EmbedAuthor","page":"API Reference","text":"EmbedAuthor\n\nAuthor information for an Embed, displayed at the top.\n\nFields\n\nname::String: Name of the author (max 256 characters).\nurl::Optional{String}: URL of the author (links the name).\nicon_url::Optional{String}: URL of the author's icon.\nproxy_icon_url::Optional{String}: A proxied URL of the author's icon.\n\nSee Also\n\nDiscord API: Embed Author\n\n\n\n\n\n","title":"Accord.EmbedAuthor"},{"category":"type","location":"api/#Accord.EmbedProvider","page":"API Reference","text":"EmbedProvider\n\nProvider information for an Embed (e.g., YouTube, Twitter).\n\nSee Also\n\nDiscord API: Embed Provider\n\n\n\n\n\n","title":"Accord.EmbedProvider"},{"category":"type","location":"api/#Accord.InteractionData","page":"API Reference","text":"InteractionData\n\nThe actual payload of an interaction. Fields vary depending on the interaction type.\n\nSee Also\n\nDiscord API: Interaction Data\n\n\n\n\n\n","title":"Accord.InteractionData"},{"category":"type","location":"api/#Accord.InteractionDataOption","page":"API Reference","text":"InteractionDataOption\n\nAn option/value received from a user in an interaction.\n\nSee Also\n\nDiscord API: Interaction Data Option\n\n\n\n\n\n","title":"Accord.InteractionDataOption"},{"category":"type","location":"api/#Accord.ResolvedData","page":"API Reference","text":"ResolvedData\n\nContains the full objects for users, roles, channels, etc., mentioned in an interaction.\n\nSee Also\n\nDiscord API: Resolved Data\n\n\n\n\n\n","title":"Accord.ResolvedData"},{"category":"type","location":"api/#Accord.ApplicationCommand","page":"API Reference","text":"ApplicationCommand\n\nRepresents a registered application command (Slash Command, User Command, or Message Command).\n\nFields\n\nid::Snowflake: The unique ID of the command.\ntype::Optional{Int}: The command type (default 1: CHAT_INPUT).\napplication_id::Snowflake: The ID of the parent application.\nguild_id::Optional{Snowflake}: The guild ID (missing for global commands).\nname::String: The command name.\ndescription::String: The command description.\noptions::Optional{Vector{ApplicationCommandOption}}: The command parameters.\ndefault_member_permissions::Nullable{String}: Default permissions required.\nnsfw::Optional{Bool}: Whether the command is age-restricted.\n\nSee Also\n\nDiscord API: Application Command\n\n\n\n\n\n","title":"Accord.ApplicationCommand"},{"category":"type","location":"api/#Accord.ApplicationCommandOption","page":"API Reference","text":"ApplicationCommandOption\n\nAn option (parameter) for an application command.\n\nFields\n\ntype::Int: The type of option (see ApplicationCommandOptionTypes).\nname::String: The parameter name (1-32 characters).\ndescription::String: The parameter description (1-100 characters).\nrequired::Optional{Bool}: Whether the parameter is required.\nchoices::Optional{Vector{ApplicationCommandOptionChoice}}: Fixed choices for the user.\noptions::Optional{Vector{ApplicationCommandOption}}: Nested sub-options (for groups/subcommands).\nautocomplete::Optional{Bool}: Whether this option supports autocomplete.\n\nSee Also\n\nDiscord API: Application Command Option\n\n\n\n\n\n","title":"Accord.ApplicationCommandOption"},{"category":"type","location":"api/#Accord.ApplicationCommandOptionChoice","page":"API Reference","text":"ApplicationCommandOptionChoice\n\nA choice for a string, integer, or number application command option.\n\nFields\n\nname::String: The choice name (1-100 characters).\nname_localizations::Optional{Any}: Localized names.\nvalue::Any: The value of the choice (String, Int, or Float64).\n\nSee Also\n\nDiscord API: Application Command Option Choice\n\n\n\n\n\n","title":"Accord.ApplicationCommandOptionChoice"},{"category":"type","location":"api/#Accord.CommandDefinition","page":"API Reference","text":"CommandDefinition\n\nInternal struct to store registered slash commands and their associated handlers. This is used by CommandTree to track available commands.\n\nFields\n\nname::String: Name of the command (1-32 characters).\ndescription::String: Description of the command (1-100 characters).\ntype::Int: The ApplicationCommandTypes (e.g., CHAT_INPUT, USER, MESSAGE).\noptions::Vector{Dict{String, Any}}: List of parameters/options for the command.\nhandler::Function: The function to execute when the command is triggered.\nguild_id::Optional{Snowflake}: If set, the command is specific to this guild.\nchecks::Vector{Function}: List of check functions that must pass for the command to run.\n\n\n\n\n\n","title":"Accord.CommandDefinition"},{"category":"type","location":"api/#Accord.Component","page":"API Reference","text":"Component\n\nRepresents an interactive message component (Buttons, Select Menus, Text Inputs).\n\nComponents are organized into \"Action Rows\" (type 1) and allow users to trigger interactions.\n\nFields\n\ntype::Int: Component type (see ComponentTypes).\ncustom_id::Optional{String}: Developer-defined ID for the component.\nstyle::Optional{Int}: Visual style (see ButtonStyles).\nlabel::Optional{String}: Text displayed on the component.\nemoji::Optional{Emoji}: Emoji displayed on the component.\nurl::Optional{String}: URL for link buttons.\ndisabled::Optional{Bool}: Whether the component is inactive.\ncomponents::Optional{Vector{Component}}: Children (Action Rows, Sections, Containers).\ncomponent::Optional{Component}: The wrapped child of a Label (modals).\noptions::Optional{Vector{SelectOption}}: Choices for select menus.\nplaceholder::Optional{String}: Placeholder text.\nmin_values::Optional{Int}: Minimum number of items to select.\nmax_values::Optional{Int}: Maximum number of items to select.\nmin_length::Optional{Int}: Minimum input length (Text Input).\nmax_length::Optional{Int}: Maximum input length (Text Input).\nrequired::Optional{Bool}: Whether input is mandatory.\nvalue::Optional{Any}: A Text Input's text, a Radio Group's chosen value (nothing when none) or a Checkbox's Bool. Modal submissions only, except the pre-filled value of a Text Input.\nvalues::Optional{Vector{String}}: Submitted values of a select, Checkbox Group or File Upload (attachment ids) inside a modal.\ndefault::Optional{Bool}: Initial state of a Checkbox.\nfile_types::Optional{Vector{String}}: Accepted types of a File Upload.\naccent_color::Maybe{Int}: Accent colour of a Container.\n\nExample\n\nbutton = Component(\n    type = ComponentTypes.BUTTON,\n    style = ButtonStyles.PRIMARY,\n    label = \"Click Me\",\n    custom_id = \"my_button\"\n)\nrow = Component(type=ComponentTypes.ACTION_ROW, components=[button])\n\nSee Also\n\nDiscord API: Component Object\n\n\n\n\n\n","title":"Accord.Component"},{"category":"type","location":"api/#Accord.SelectOption","page":"API Reference","text":"SelectOption\n\nAn option within a select menu component.\n\nFields\n\nlabel::String: The user-facing name of the option.\nvalue::String: The internal value sent to the bot when selected.\ndescription::Optional{String}: Additional text describing the option.\nemoji::Optional{Emoji}: Emoji to display with the option.\ndefault::Optional{Bool}: Whether this option is selected by default.\n\nSee Also\n\nDiscord API: Select Option\n\n\n\n\n\n","title":"Accord.SelectOption"},{"category":"module","location":"api/#Accord.GuildFeatures","page":"API Reference","text":"GuildFeatures\n\nString constants for the various features a guild can have enabled.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.GuildFeatures"},{"category":"type","location":"api/#Accord.RoleTags","page":"API Reference","text":"RoleTags\n\nExtra attributes describing a special role (e.g., bot role, booster role).\n\nFields\n\nbot_id::Optional{Snowflake}: The ID of the bot this role belongs to.\nintegration_id::Optional{Snowflake}: The ID of the integration this role belongs to.\npremium_subscriber::Optional{Nothing}: Present if this is the guild's booster role.\nsubscription_listing_id::Optional{Snowflake}: ID of the role's subscription SKU.\navailable_for_purchase::Optional{Nothing}: Present if the role is available for purchase.\nguild_connections::Optional{Nothing}: Present if the role is a guild's linked role.\n\nSee Also\n\nDiscord API: Role Tags Object\n\n\n\n\n\n","title":"Accord.RoleTags"},{"category":"type","location":"api/#Accord.RoleColors","page":"API Reference","text":"RoleColors\n\nA role's colours (Role.colors). Gradient and holographic roles use the secondary and tertiary colours, which need the guild feature ENHANCED_ROLE_COLORS.\n\nFields\n\nprimary_color::Int: The main colour (same value as the deprecated Role.color).\nsecondary_color::Maybe{Int}: Second gradient stop.\ntertiary_color::Maybe{Int}: Third stop (holographic roles).\n\n\n\n\n\n","title":"Accord.RoleColors"},{"category":"type","location":"api/#Accord.Ban","page":"API Reference","text":"Ban\n\nRepresents a ban record in a guild.\n\nFields\n\nreason::Nullable{String}: The reason for the ban, if provided.\nuser::Optional{User}: The user who was banned.\n\nSee Also\n\nDiscord API: Ban Object\n\n\n\n\n\n","title":"Accord.Ban"},{"category":"type","location":"api/#Accord.GuildTemplate","page":"API Reference","text":"GuildTemplate\n\nRepresents a snapshot of a guild that can be used to create new guilds.\n\nFields\n\ncode::String: The unique template code.\nname::String: Name of the template.\ndescription::Optional{String}: Description of the template.\nusage_count::Int: Number of times it has been used.\ncreator_id::Snowflake: ID of the user who created it.\nsource_guild_id::Snowflake: ID of the guild it was based on.\n\nSee Also\n\nDiscord API: Guild Template Object\n\n\n\n\n\n","title":"Accord.GuildTemplate"},{"category":"type","location":"api/#Accord.Activity","page":"API Reference","text":"Activity\n\nRepresents what a user is currently doing (playing a game, streaming, etc.).\n\nFields\n\nname::String: The activity's name.\ntype::Int: Activity type (see ActivityTypes).\nurl::Optional{String}: Stream URL (if streaming).\ndetails::Optional{String}: What the player is doing.\nstate::Optional{String}: The user's current party status.\nemoji::Optional{ActivityEmoji}: Status emoji.\nparty::Optional{ActivityParty}: Party information.\nassets::Optional{ActivityAssets}: Images and hover text.\nbuttons::Optional{Vector{ActivityButton}}: Custom Rich Presence buttons.\n\nSee Also\n\nDiscord API: Activity Object\n\n\n\n\n\n","title":"Accord.Activity"},{"category":"type","location":"api/#Accord.ActivityTimestamps","page":"API Reference","text":"ActivityTimestamps\n\nStart and end times for a user's Activity.\n\nSee Also\n\nDiscord API: Activity Timestamps\n\n\n\n\n\n","title":"Accord.ActivityTimestamps"},{"category":"type","location":"api/#Accord.ActivityEmoji","page":"API Reference","text":"ActivityEmoji\n\nThe emoji displayed in a user's status.\n\nSee Also\n\nDiscord API: Activity Emoji\n\n\n\n\n\n","title":"Accord.ActivityEmoji"},{"category":"type","location":"api/#Accord.ActivityParty","page":"API Reference","text":"ActivityParty\n\nInformation about the party/group a user is currently in.\n\nSee Also\n\nDiscord API: Activity Party\n\n\n\n\n\n","title":"Accord.ActivityParty"},{"category":"type","location":"api/#Accord.ActivityAssets","page":"API Reference","text":"ActivityAssets\n\nImages and hover text for a user's Rich Presence.\n\nSee Also\n\nDiscord API: Activity Assets\n\n\n\n\n\n","title":"Accord.ActivityAssets"},{"category":"type","location":"api/#Accord.ActivitySecrets","page":"API Reference","text":"ActivitySecrets\n\nSecrets for joining or spectating a user's game.\n\nSee Also\n\nDiscord API: Activity Secrets\n\n\n\n\n\n","title":"Accord.ActivitySecrets"},{"category":"type","location":"api/#Accord.ActivityButton","page":"API Reference","text":"ActivityButton\n\nA custom button displayed in a user's Rich Presence.\n\nSee Also\n\nDiscord API: Activity Buttons\n\n\n\n\n\n","title":"Accord.ActivityButton"},{"category":"type","location":"api/#Accord.ClientStatus","page":"API Reference","text":"ClientStatus\n\nActive session statuses for each platform (desktop, mobile, web).\n\nSee Also\n\nDiscord API: Client Status Object\n\n\n\n\n\n","title":"Accord.ClientStatus"},{"category":"type","location":"api/#Accord.Poll","page":"API Reference","text":"Poll\n\nRepresents a native Discord poll within a message.\n\nPolls allow users to vote on predefined answers and see real-time results.\n\nFields\n\nquestion::Optional{PollMedia}: The poll's question.\nanswers::Vector{PollAnswer}: Up to 10 answer options.\nexpiry::Optional{String}: ISO8601 timestamp of when the poll ends.\nallow_multiselect::Bool: Whether users can pick multiple answers.\nlayout_type::Int: The visual layout (default 1).\nresults::Optional{PollResults}: The current vote counts.\n\nSee Also\n\nDiscord API: Poll Object\n\n\n\n\n\n","title":"Accord.Poll"},{"category":"type","location":"api/#Accord.PollMedia","page":"API Reference","text":"PollMedia\n\nMedia content (text and/or emoji) for a poll question or answer.\n\nSee Also\n\nDiscord API: Poll Media Object\n\n\n\n\n\n","title":"Accord.PollMedia"},{"category":"type","location":"api/#Accord.PollAnswer","page":"API Reference","text":"PollAnswer\n\nRepresents an individual answer option in a Poll.\n\nSee Also\n\nDiscord API: Poll Answer Object\n\n\n\n\n\n","title":"Accord.PollAnswer"},{"category":"type","location":"api/#Accord.PollAnswerCount","page":"API Reference","text":"PollAnswerCount\n\nThe vote count for a specific poll answer.\n\nSee Also\n\nDiscord API: Poll Answer Count Object\n\n\n\n\n\n","title":"Accord.PollAnswerCount"},{"category":"type","location":"api/#Accord.PollResults","page":"API Reference","text":"PollResults\n\nThe results of a poll, containing vote counts for each answer.\n\nSee Also\n\nDiscord API: Poll Results Object\n\n\n\n\n\n","title":"Accord.PollResults"},{"category":"type","location":"api/#Accord.RecurrenceRule","page":"API Reference","text":"RecurrenceRule\n\nDefines how a ScheduledEvent repeats over time.\n\nSee Also\n\nDiscord API: Recurrence Rule Object\n\n\n\n\n\n","title":"Accord.RecurrenceRule"},{"category":"type","location":"api/#Accord.RecurrenceRuleNWeekday","page":"API Reference","text":"RecurrenceRuleNWeekday\n\nThe nth weekday of a month for a recurring event.\n\nSee Also\n\nDiscord API: Recurrence Rule N-Weekday\n\n\n\n\n\n","title":"Accord.RecurrenceRuleNWeekday"},{"category":"type","location":"api/#Accord.AuditLog","page":"API Reference","text":"AuditLog\n\nRepresents the audit log for a guild. Contains a list of entries and  referenced objects (users, webhooks, etc.).\n\nFields\n\naudit_log_entries::Vector{AuditLogEntry}: The actual log entries.\nusers::Vector{User}: Users referenced in the log.\nwebhooks::Vector{Webhook}: Webhooks referenced in the log.\napplication_commands::Vector{ApplicationCommand}: Commands referenced.\n\nSee Also\n\nDiscord API: Audit Log Object\n\n\n\n\n\n","title":"Accord.AuditLog"},{"category":"type","location":"api/#Accord.AuditLogEntry","page":"API Reference","text":"AuditLogEntry\n\nAn individual entry in the guild audit log.\n\nFields\n\ntarget_id::Nullable{String}: ID of the affected entity (User, Role, etc.).\nchanges::Optional{Vector{AuditLogChange}}: List of changes made.\nuser_id::Nullable{Snowflake}: ID of the user who performed the action.\nid::Snowflake: Unique ID of the entry.\naction_type::Int: Type of action (see AuditLogEvent).\noptions::Optional{AuditLogEntryInfo}: Additional context for the action.\nreason::Optional{String}: Reason provided by the user (max 512 characters).\n\nSee Also\n\nDiscord API: Audit Log Entry Object\n\n\n\n\n\n","title":"Accord.AuditLogEntry"},{"category":"type","location":"api/#Accord.AuditLogEntryInfo","page":"API Reference","text":"AuditLogEntryInfo\n\nExtra information for specific audit log events (e.g., prune details,  overwrite types).\n\nSee Also\n\nDiscord API: Audit Log Entry Info\n\n\n\n\n\n","title":"Accord.AuditLogEntryInfo"},{"category":"type","location":"api/#Accord.AuditLogChange","page":"API Reference","text":"AuditLogChange\n\nRepresents a change to a guild resource recorded in the audit log.\n\nFields\n\nnew_value::Optional{Any}: The value after the change.\nold_value::Optional{Any}: The value before the change.\nkey::String: The name of the property that was changed (e.g., \"name\", \"permissions\").\n\nSee Also\n\nDiscord API: Audit Log Change Object\n\n\n\n\n\n","title":"Accord.AuditLogChange"},{"category":"type","location":"api/#Accord.AutoModAction","page":"API Reference","text":"AutoModAction\n\nAn action to take when an AutoModRule is triggered.\n\nFields\n\ntype::Int: Action type (see AutoModActionTypes).\nmetadata::Optional{AutoModActionMetadata}: Additional data for the action.\n\nSee Also\n\nDiscord API: Auto Moderation Action Object\n\n\n\n\n\n","title":"Accord.AutoModAction"},{"category":"type","location":"api/#Accord.AutoModActionMetadata","page":"API Reference","text":"AutoModActionMetadata\n\nMetadata associated with an AutoModAction.\n\nFields\n\nchannel_id::Optional{Snowflake}: Channel to log alerts to (for SEND_ALERT_MESSAGE).\nduration_seconds::Optional{Int}: Timeout duration (for TIMEOUT).\ncustom_message::Optional{String}: Message shown to the user (for BLOCK_MESSAGE).\n\nSee Also\n\nDiscord API: Auto Moderation Action Metadata\n\n\n\n\n\n","title":"Accord.AutoModActionMetadata"},{"category":"type","location":"api/#Accord.AutoModTriggerMetadata","page":"API Reference","text":"AutoModTriggerMetadata\n\nConfiguration for what triggers an AutoModRule.\n\nFields\n\nkeyword_filter::Optional{Vector{String}}: Substrings to search for.\nregex_patterns::Optional{Vector{String}}: Regex patterns to match.\npresets::Optional{Vector{Int}}: Predefined wordsets (see AutoModKeywordPresetTypes).\nallow_list::Optional{Vector{String}}: Substrings that are exempt from the rule.\nmention_total_limit::Optional{Int}: Max unique mentions allowed.\n\nSee Also\n\nDiscord API: Auto Moderation Trigger Metadata\n\n\n\n\n\n","title":"Accord.AutoModTriggerMetadata"},{"category":"type","location":"api/#Accord.Sticker","page":"API Reference","text":"Sticker\n\nRepresents a sticker that can be sent in messages.\n\nFields\n\nid::Snowflake: Unique ID of the sticker.\npack_id::Optional{Snowflake}: ID of the pack (for standard stickers).\nname::String: Name of the sticker.\ndescription::Nullable{String}: Description of the sticker.\ntags::String: Autocomplete tags or associated emoji.\ntype::Int: Sticker type (see StickerTypes).\nformat_type::Int: Format type (see StickerFormatTypes).\navailable::Optional{Bool}: Whether the sticker can be used.\nguild_id::Optional{Snowflake}: ID of the guild that owns the sticker.\nuser::Optional{User}: The user who uploaded the sticker.\nsort_value::Optional{Int}: Sort order within a pack.\n\nSee Also\n\nDiscord API: Sticker Object\n\n\n\n\n\n","title":"Accord.Sticker"},{"category":"type","location":"api/#Accord.StickerItem","page":"API Reference","text":"StickerItem\n\nA partial representation of a Sticker, used for rendering.\n\nSee Also\n\nDiscord API: Sticker Item Object\n\n\n\n\n\n","title":"Accord.StickerItem"},{"category":"type","location":"api/#Accord.StickerPack","page":"API Reference","text":"StickerPack\n\nRepresents a collection of standard Discord stickers.\n\nSee Also\n\nDiscord API: Sticker Pack Object\n\n\n\n\n\n","title":"Accord.StickerPack"},{"category":"type","location":"api/#Accord.Invite","page":"API Reference","text":"Invite\n\nRepresents a Discord invite code.\n\nInvites are used to add users to guilds or group DMs.\n\nFields\n\ncode::String: The unique invite code (e.g., \"discord-jl\").\nguild::Optional{Guild}: The guild this invite is for.\nchannel::Nullable{DiscordChannel}: The channel this invite is for.\ninviter::Optional{User}: The user who created the invite.\ntarget_type::Optional{Int}: The target type (see InviteTargetTypes).\napproximate_presence_count::Optional{Int}: Online members count.\napproximate_member_count::Optional{Int}: Total members count.\nexpires_at::Optional{String}: ISO8601 expiration timestamp.\n\nSee Also\n\nDiscord API: Invite Object\n\n\n\n\n\n","title":"Accord.Invite"},{"category":"type","location":"api/#Accord.InviteMetadata","page":"API Reference","text":"InviteMetadata\n\nExtra usage statistics and metadata for a Discord Invite.\n\nSee Also\n\nDiscord API: Invite Metadata\n\n\n\n\n\n","title":"Accord.InviteMetadata"},{"category":"type","location":"api/#Accord.Webhook","page":"API Reference","text":"Webhook\n\nRepresents a Discord webhook. Webhooks allow bots and external services to  post messages to a channel without requiring a full bot user or authentication.\n\nFields\n\nid::Snowflake: The unique ID of the webhook.\ntype::Int: The type of webhook (see WebhookTypes).\nguild_id::Optional{Snowflake}: The ID of the guild the webhook is in.\nchannel_id::Nullable{Snowflake}: The ID of the channel the webhook posts to.\nuser::Optional{User}: The user who created the webhook.\nname::Nullable{String}: The default name of the webhook.\navatar::Nullable{String}: The default avatar hash.\ntoken::Optional{String}: The secure token (for executing the webhook).\nurl::Optional{String}: The full execution URL.\n\nSee Also\n\nDiscord API: Webhook Object\n\n\n\n\n\n","title":"Accord.Webhook"},{"category":"type","location":"api/#Accord.VoiceState","page":"API Reference","text":"VoiceState\n\nRepresents a user's voice connection status in a guild.\n\nFields\n\nguild_id::Optional{Snowflake}: Guild ID.\nchannel_id::Nullable{Snowflake}: Connected channel ID (null if disconnected).\nuser_id::Snowflake: User ID.\nsession_id::String: Unique session ID.\ndeaf::Bool: Whether the user is server-deafened.\nmute::Bool: Whether the user is server-muted.\nself_deaf::Bool: Whether the user is self-deafened.\nself_mute::Bool: Whether the user is self-muted.\nself_stream::Optional{Bool}: Whether the user is streaming.\nself_video::Bool: Whether the user's camera is on.\nsuppress::Bool: Whether the user is suppressed (for stages).\n\nSee Also\n\nDiscord API: Voice State Object\n\n\n\n\n\n","title":"Accord.VoiceState"},{"category":"type","location":"api/#Accord.VoiceRegion","page":"API Reference","text":"VoiceRegion\n\nRepresents a Discord voice server region.\n\nSee Also\n\nDiscord API: Voice Region Object\n\n\n\n\n\n","title":"Accord.VoiceRegion"},{"category":"type","location":"api/#Accord.StageInstance","page":"API Reference","text":"StageInstance\n\nRepresents a live event in a Discord Stage channel.\n\nFields\n\nid::Snowflake: Unique ID of the instance.\nguild_id::Snowflake: Guild ID of the associated Stage channel.\nchannel_id::Snowflake: ID of the Stage channel.\ntopic::String: Topic of the stage (1-120 characters).\nprivacy_level::Int: Privacy level (see StageInstancePrivacyLevels).\nguild_scheduled_event_id::Nullable{Snowflake}: ID of the associated scheduled event.\n\nSee Also\n\nDiscord API: Stage Instance Object\n\n\n\n\n\n","title":"Accord.StageInstance"},{"category":"type","location":"api/#Accord.SoundboardSound","page":"API Reference","text":"SoundboardSound\n\nRepresents a sound that can be played in a Discord voice channel's soundboard.\n\nFields\n\nname::String: Name of the sound.\nsound_id::Snowflake: Unique ID of the sound.\nvolume::Float64: Default playback volume (0.0 to 1.0).\nemoji_id::Nullable{Snowflake}: ID of the associated custom emoji.\nemoji_name::Nullable{String}: Unicode name of the associated emoji.\nguild_id::Optional{Snowflake}: Guild where the sound is hosted.\navailable::Bool: Whether the sound can be played.\nuser::Optional{User}: User who uploaded the sound.\n\nSee Also\n\nDiscord API: Soundboard Sound Object\n\n\n\n\n\n","title":"Accord.SoundboardSound"},{"category":"type","location":"api/#Accord.Connection","page":"API Reference","text":"Connection\n\nRepresents a third-party account (Steam, Twitch, etc.) connected to a Discord user.\n\nFields\n\nid::String: ID of the connected account.\nname::String: Username of the connected account.\ntype::String: Service name (e.g., \"twitch\").\nrevoked::Optional{Bool}: Whether the connection is revoked.\nverified::Bool: Whether the connection is verified.\nfriend_sync::Bool: Whether friends are synced.\nshow_activity::Bool: Whether to show in presence updates.\nvisibility::Int: Visibility (0=hidden, 1=everyone).\n\nSee Also\n\nDiscord API: Connection Object\n\n\n\n\n\n","title":"Accord.Connection"},{"category":"type","location":"api/#Accord.ReactionCountDetails","page":"API Reference","text":"ReactionCountDetails\n\nBreakdown of normal and super (burst) reaction counts.\n\nSee Also\n\nDiscord API: Reaction Count Details\n\n\n\n\n\n","title":"Accord.ReactionCountDetails"},{"category":"type","location":"api/#Accord.SKU","page":"API Reference","text":"SKU\n\nRepresents a Stock Keeping Unit (SKU) for application monetization.\n\nSee Also\n\nDiscord API: SKU Object\n\n\n\n\n\n","title":"Accord.SKU"},{"category":"type","location":"api/#Accord.Entitlement","page":"API Reference","text":"Entitlement\n\nRepresents access to a premium offering (SKU) by a user or guild.\n\nSee Also\n\nDiscord API: Entitlement Object\n\n\n\n\n\n","title":"Accord.Entitlement"},{"category":"type","location":"api/#Accord.Subscription","page":"API Reference","text":"Subscription\n\nRepresents a user's subscription to a premium SKU.\n\nSee Also\n\nDiscord API: Subscription Object\n\n\n\n\n\n","title":"Accord.Subscription"},{"category":"type","location":"api/#Accord.ScheduledEvent","page":"API Reference","text":"ScheduledEvent\n\nRepresents a Discord guild scheduled event (Voice, Stage, or External).\n\nScheduled events allow servers to plan and publicize future gatherings.\n\nFields\n\nid::Snowflake: Unique ID of the event.\nguild_id::Snowflake: Guild where the event is hosted.\nchannel_id::Nullable{Snowflake}: Hosting channel (null for external).\nname::String: The event name.\ndescription::Optional{String}: The event description.\nscheduled_start_time::String: ISO8601 start time.\nscheduled_end_time::Nullable{String}: ISO8601 end time.\nprivacy_level::Int: Privacy level (see ScheduledEventPrivacyLevels).\nstatus::Int: Event status (see ScheduledEventStatuses).\nentity_type::Int: Type of event (see ScheduledEventEntityTypes).\nentity_id::Nullable{Snowflake}: ID of the associated entity (e.g., Stage ID).\nentity_metadata::Nullable{EntityMetadata}: Metadata for external events.\ncreator::Optional{User}: The user who created the event.\nuser_count::Optional{Int}: Number of users who signed up.\nimage::Nullable{String}: Cover image hash.\nrecurrence_rule::Nullable{RecurrenceRule}: How the event repeats.\n\nSee Also\n\nDiscord API: Scheduled Event Object\n\n\n\n\n\n","title":"Accord.ScheduledEvent"},{"category":"type","location":"api/#Accord.EntityMetadata","page":"API Reference","text":"EntityMetadata\n\nAdditional metadata for a ScheduledEvent (e.g., location for external events).\n\nSee Also\n\nDiscord API: Entity Metadata\n\n\n\n\n\n","title":"Accord.EntityMetadata"},{"category":"type","location":"api/#Accord.Integration","page":"API Reference","text":"Integration\n\nRepresents a guild integration (Twitch, YouTube, Discord App, etc.).\n\nFields\n\nid::Snowflake: Integration ID.\nname::String: Integration name.\ntype::String: Integration type (\"twitch\", \"youtube\", \"discord\").\nenabled::Optional{Bool}: Whether it is enabled.\nuser::Optional{User}: User for this integration.\naccount::Optional{IntegrationAccount}: Connected account info.\napplication::Optional{IntegrationApplication}: For Discord App integrations.\n\nSee Also\n\nDiscord API: Integration Object\n\n\n\n\n\n","title":"Accord.Integration"},{"category":"type","location":"api/#Accord.IntegrationAccount","page":"API Reference","text":"IntegrationAccount\n\nThird-party account info for an Integration.\n\nSee Also\n\nDiscord API: Integration Account\n\n\n\n\n\n","title":"Accord.IntegrationAccount"},{"category":"type","location":"api/#Accord.IntegrationApplication","page":"API Reference","text":"IntegrationApplication\n\nApplication info for a Discord Integration.\n\nSee Also\n\nDiscord API: Integration Application\n\n\n\n\n\n","title":"Accord.IntegrationApplication"},{"category":"type","location":"api/#Accord.Onboarding","page":"API Reference","text":"Onboarding\n\nThe complete onboarding configuration for a guild.\n\nFields\n\nguild_id::Snowflake: Guild ID.\nprompts::Vector{OnboardingPrompt}: Questions shown during flow.\ndefault_channel_ids::Vector{Snowflake}: Channels everyone gets.\nenabled::Bool: Whether onboarding is active.\nmode::Int: Onboarding mode (see OnboardingModes).\n\nSee Also\n\nDiscord API: Onboarding Object\n\n\n\n\n\n","title":"Accord.Onboarding"},{"category":"type","location":"api/#Accord.OnboardingPrompt","page":"API Reference","text":"OnboardingPrompt\n\nA question or choice shown to new members during guild onboarding.\n\nSee Also\n\nDiscord API: Onboarding Prompt Object\n\n\n\n\n\n","title":"Accord.OnboardingPrompt"},{"category":"type","location":"api/#Accord.OnboardingPromptOption","page":"API Reference","text":"OnboardingPromptOption\n\nAn individual choice within an onboarding prompt.\n\nFields\n\nid::Snowflake: Unique ID of the option.\nchannel_ids::Vector{Snowflake}: Channels assigned if selected.\nrole_ids::Vector{Snowflake}: Roles assigned if selected.\ntitle::String: Label for the option.\ndescription::Nullable{String}: Help text for the option.\n\nSee Also\n\nDiscord API: Onboarding Prompt Option\n\n\n\n\n\n","title":"Accord.OnboardingPromptOption"},{"category":"module","location":"api/#Accord.ChannelTypes","page":"API Reference","text":"ChannelTypes\n\nConstants for the various types of channels in Discord.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ChannelTypes"},{"category":"module","location":"api/#Accord.InteractionTypes","page":"API Reference","text":"InteractionTypes\n\nConstants for the various types of interactions in Discord.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.InteractionTypes"},{"category":"module","location":"api/#Accord.InteractionCallbackTypes","page":"API Reference","text":"InteractionCallbackTypes\n\nConstants for the various ways to respond to an interaction.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.InteractionCallbackTypes"},{"category":"module","location":"api/#Accord.ApplicationCommandTypes","page":"API Reference","text":"ApplicationCommandTypes\n\nConstants for the various types of application commands.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ApplicationCommandTypes"},{"category":"module","location":"api/#Accord.ApplicationCommandOptionTypes","page":"API Reference","text":"ApplicationCommandOptionTypes\n\nConstants for the various types of options for application commands.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ApplicationCommandOptionTypes"},{"category":"module","location":"api/#Accord.ComponentTypes","page":"API Reference","text":"ComponentTypes\n\nConstants for the various types of message components.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ComponentTypes"},{"category":"module","location":"api/#Accord.ButtonStyles","page":"API Reference","text":"ButtonStyles\n\nConstants for the various visual styles of buttons.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ButtonStyles"},{"category":"module","location":"api/#Accord.TextInputStyles","page":"API Reference","text":"TextInputStyles\n\nConstants for the various visual styles of text inputs in modals.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.TextInputStyles"},{"category":"module","location":"api/#Accord.ActivityTypes","page":"API Reference","text":"ActivityTypes\n\nConstants for the various types of presence activities.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ActivityTypes"},{"category":"module","location":"api/#Accord.MessageTypes","page":"API Reference","text":"MessageTypes\n\nConstants for the various types of messages in Discord.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.MessageTypes"},{"category":"module","location":"api/#Accord.MessageReferenceTypes","page":"API Reference","text":"MessageReferenceTypes\n\nKinds of message reference (MessageReference.type): a reply (DEFAULT) or a forward (FORWARD), whose copy arrives in Message.message_snapshots.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.MessageReferenceTypes"},{"category":"module","location":"api/#Accord.VerificationLevels","page":"API Reference","text":"VerificationLevels\n\nConstants for the various guild verification levels.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.VerificationLevels"},{"category":"module","location":"api/#Accord.DefaultMessageNotificationLevels","page":"API Reference","text":"DefaultMessageNotificationLevels\n\nConstants for the various guild default message notification levels.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.DefaultMessageNotificationLevels"},{"category":"module","location":"api/#Accord.ExplicitContentFilterLevels","page":"API Reference","text":"ExplicitContentFilterLevels\n\nConstants for the various guild explicit content filter levels.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ExplicitContentFilterLevels"},{"category":"module","location":"api/#Accord.MFALevels","page":"API Reference","text":"MFALevels\n\nConstants for the various guild multi-factor authentication levels.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.MFALevels"},{"category":"module","location":"api/#Accord.NSFWLevels","page":"API Reference","text":"NSFWLevels\n\nConstants for the various guild NSFW levels.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.NSFWLevels"},{"category":"module","location":"api/#Accord.PremiumTiers","page":"API Reference","text":"PremiumTiers\n\nConstants for the various guild premium (Boost) tiers.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.PremiumTiers"},{"category":"module","location":"api/#Accord.PremiumTypes","page":"API Reference","text":"PremiumTypes\n\nConstants for the various user premium (Nitro) types.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.PremiumTypes"},{"category":"module","location":"api/#Accord.StatusTypes","page":"API Reference","text":"StatusTypes\n\nConstants for the various presence status strings.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.StatusTypes"},{"category":"module","location":"api/#Accord.WebhookTypes","page":"API Reference","text":"WebhookTypes\n\nConstants for the various types of webhooks.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.WebhookTypes"},{"category":"module","location":"api/#Accord.AuditLogEventTypes","page":"API Reference","text":"AuditLogEventTypes\n\nConstants for the various types of events recorded in the audit log.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.AuditLogEventTypes"},{"category":"module","location":"api/#Accord.AutoModTriggerTypes","page":"API Reference","text":"AutoModTriggerTypes\n\nConstants for the various types of triggers for auto moderation rules.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.AutoModTriggerTypes"},{"category":"module","location":"api/#Accord.AutoModEventTypes","page":"API Reference","text":"AutoModEventTypes\n\nConstants for the various event contexts where auto moderation rules are checked.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.AutoModEventTypes"},{"category":"module","location":"api/#Accord.AutoModActionTypes","page":"API Reference","text":"AutoModActionTypes\n\nConstants for the various actions that auto moderation rules can take.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.AutoModActionTypes"},{"category":"module","location":"api/#Accord.AutoModKeywordPresetTypes","page":"API Reference","text":"AutoModKeywordPresetTypes\n\nConstants for the various built-in word lists for auto moderation.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.AutoModKeywordPresetTypes"},{"category":"module","location":"api/#Accord.SortOrderTypes","page":"API Reference","text":"SortOrderTypes\n\nConstants for the various sort orders for forum and media channels.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.SortOrderTypes"},{"category":"module","location":"api/#Accord.ForumLayoutTypes","page":"API Reference","text":"ForumLayoutTypes\n\nConstants for the various forum layout views.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ForumLayoutTypes"},{"category":"module","location":"api/#Accord.StickerTypes","page":"API Reference","text":"StickerTypes\n\nConstants for the various types of stickers.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.StickerTypes"},{"category":"module","location":"api/#Accord.StickerFormatTypes","page":"API Reference","text":"StickerFormatTypes\n\nConstants for the various formats of stickers.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.StickerFormatTypes"},{"category":"module","location":"api/#Accord.InviteTargetTypes","page":"API Reference","text":"InviteTargetTypes\n\nConstants for the various types of targets for voice channel invites.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.InviteTargetTypes"},{"category":"module","location":"api/#Accord.ScheduledEventPrivacyLevels","page":"API Reference","text":"ScheduledEventPrivacyLevels\n\nConstants for the various privacy levels of guild scheduled events.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ScheduledEventPrivacyLevels"},{"category":"module","location":"api/#Accord.ScheduledEventStatuses","page":"API Reference","text":"ScheduledEventStatuses\n\nConstants for the various statuses of guild scheduled events.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ScheduledEventStatuses"},{"category":"module","location":"api/#Accord.ScheduledEventEntityTypes","page":"API Reference","text":"ScheduledEventEntityTypes\n\nConstants for the various types of entities associated with guild scheduled events.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ScheduledEventEntityTypes"},{"category":"module","location":"api/#Accord.StageInstancePrivacyLevels","page":"API Reference","text":"StageInstancePrivacyLevels\n\nConstants for the various privacy levels of Stage instances.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.StageInstancePrivacyLevels"},{"category":"module","location":"api/#Accord.OnboardingModes","page":"API Reference","text":"OnboardingModes\n\nConstants for the various guild onboarding modes.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.OnboardingModes"},{"category":"module","location":"api/#Accord.SKUTypes","page":"API Reference","text":"SKUTypes\n\nConstants for the various types of SKUs.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.SKUTypes"},{"category":"module","location":"api/#Accord.EntitlementTypes","page":"API Reference","text":"EntitlementTypes\n\nConstants for the various types of entitlements.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.EntitlementTypes"},{"category":"module","location":"api/#Accord.AllowedMentionTypes","page":"API Reference","text":"AllowedMentionTypes\n\nConstants for the various types of allowed mentions.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.AllowedMentionTypes"},{"category":"module","location":"api/#Accord.Locales","page":"API Reference","text":"Locales\n\nConstants for the various supported locales in Discord.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.Locales"},{"category":"type","location":"api/#Accord.Intents","page":"API Reference","text":"Intents\n\nGateway intents allow you to subscribe to specific buckets of events sent by Discord. Privileged intents (Members, Presences, MessageContent) must be enabled in the Developer Portal.\n\nDiscord docs\n\nExample\n\n# Combine intents using the | operator\nintents = IntentGuilds | IntentGuildMessages | IntentMessageContent\n\n\n\n\n\n","title":"Accord.Intents"},{"category":"constant","location":"api/#Accord.IntentGuilds","page":"API Reference","text":"Enables GUILDCREATE, GUILDUPDATE, GUILDDELETE, GUILDROLE*, CHANNEL, THREAD_, STAGEINSTANCE* events.\n\n\n\n\n\n","title":"Accord.IntentGuilds"},{"category":"constant","location":"api/#Accord.IntentGuildMembers","page":"API Reference","text":"Enables GUILDMEMBERADD, GUILDMEMBERUPDATE, GUILDMEMBERREMOVE, THREADMEMBERSUPDATE events. Privileged Intent.\n\n\n\n\n\n","title":"Accord.IntentGuildMembers"},{"category":"constant","location":"api/#Accord.IntentGuildModeration","page":"API Reference","text":"Enables GUILDAUDITLOGENTRYCREATE, GUILDBANADD, GUILDBANREMOVE events.\n\n\n\n\n\n","title":"Accord.IntentGuildModeration"},{"category":"constant","location":"api/#Accord.IntentGuildExpressions","page":"API Reference","text":"Enables GUILDEMOJISUPDATE, GUILDSTICKERSUPDATE, GUILDSOUNDBOARDSOUND_* events.\n\n\n\n\n\n","title":"Accord.IntentGuildExpressions"},{"category":"constant","location":"api/#Accord.IntentGuildIntegrations","page":"API Reference","text":"Enables GUILDINTEGRATIONSUPDATE, INTEGRATIONCREATE, INTEGRATIONUPDATE, INTEGRATION_DELETE events.\n\n\n\n\n\n","title":"Accord.IntentGuildIntegrations"},{"category":"constant","location":"api/#Accord.IntentGuildWebhooks","page":"API Reference","text":"Enables WEBHOOKS_UPDATE events.\n\n\n\n\n\n","title":"Accord.IntentGuildWebhooks"},{"category":"constant","location":"api/#Accord.IntentGuildInvites","page":"API Reference","text":"Enables INVITECREATE, INVITEDELETE events.\n\n\n\n\n\n","title":"Accord.IntentGuildInvites"},{"category":"constant","location":"api/#Accord.IntentGuildVoiceStates","page":"API Reference","text":"Enables VOICESTATEUPDATE events.\n\n\n\n\n\n","title":"Accord.IntentGuildVoiceStates"},{"category":"constant","location":"api/#Accord.IntentGuildPresences","page":"API Reference","text":"Enables PRESENCE_UPDATE events. Privileged Intent.\n\n\n\n\n\n","title":"Accord.IntentGuildPresences"},{"category":"constant","location":"api/#Accord.IntentGuildMessages","page":"API Reference","text":"Enables MESSAGECREATE, MESSAGEUPDATE, MESSAGEDELETE, MESSAGEDELETE_BULK events in guilds.\n\n\n\n\n\n","title":"Accord.IntentGuildMessages"},{"category":"constant","location":"api/#Accord.IntentGuildMessageReactions","page":"API Reference","text":"Enables MESSAGEREACTIONADD, MESSAGEREACTIONREMOVE, MESSAGEREACTIONREMOVEALL, MESSAGEREACTIONREMOVEEMOJI events in guilds.\n\n\n\n\n\n","title":"Accord.IntentGuildMessageReactions"},{"category":"constant","location":"api/#Accord.IntentGuildMessageTyping","page":"API Reference","text":"Enables TYPING_START events in guilds.\n\n\n\n\n\n","title":"Accord.IntentGuildMessageTyping"},{"category":"constant","location":"api/#Accord.IntentDirectMessages","page":"API Reference","text":"Enables MESSAGECREATE, MESSAGEUPDATE, MESSAGEDELETE, CHANNELPINS_UPDATE events in DMs.\n\n\n\n\n\n","title":"Accord.IntentDirectMessages"},{"category":"constant","location":"api/#Accord.IntentDirectMessageReactions","page":"API Reference","text":"Enables MESSAGEREACTIONADD, MESSAGEREACTIONREMOVE, MESSAGEREACTIONREMOVEALL, MESSAGEREACTIONREMOVEEMOJI events in DMs.\n\n\n\n\n\n","title":"Accord.IntentDirectMessageReactions"},{"category":"constant","location":"api/#Accord.IntentDirectMessageTyping","page":"API Reference","text":"Enables TYPING_START events in DMs.\n\n\n\n\n\n","title":"Accord.IntentDirectMessageTyping"},{"category":"constant","location":"api/#Accord.IntentMessageContent","page":"API Reference","text":"Enables access to message content (content, embeds, attachments, components) in events. Privileged Intent.\n\n\n\n\n\n","title":"Accord.IntentMessageContent"},{"category":"constant","location":"api/#Accord.IntentGuildScheduledEvents","page":"API Reference","text":"Enables GUILDSCHEDULEDEVENT_* events.\n\n\n\n\n\n","title":"Accord.IntentGuildScheduledEvents"},{"category":"constant","location":"api/#Accord.IntentAutoModerationConfiguration","page":"API Reference","text":"Enables AUTOMODERATIONRULE_* events.\n\n\n\n\n\n","title":"Accord.IntentAutoModerationConfiguration"},{"category":"constant","location":"api/#Accord.IntentAutoModerationExecution","page":"API Reference","text":"Enables AUTOMODERATIONACTION_EXECUTION events.\n\n\n\n\n\n","title":"Accord.IntentAutoModerationExecution"},{"category":"constant","location":"api/#Accord.IntentGuildMessagePolls","page":"API Reference","text":"Enables MESSAGEPOLLVOTE_* events in guilds.\n\n\n\n\n\n","title":"Accord.IntentGuildMessagePolls"},{"category":"constant","location":"api/#Accord.IntentDirectMessagePolls","page":"API Reference","text":"Enables MESSAGEPOLLVOTE_* events in DMs.\n\n\n\n\n\n","title":"Accord.IntentDirectMessagePolls"},{"category":"constant","location":"api/#Accord.IntentAllNonPrivileged","page":"API Reference","text":"All non-privileged intents combined.\n\n\n\n\n\n","title":"Accord.IntentAllNonPrivileged"},{"category":"constant","location":"api/#Accord.IntentAll","page":"API Reference","text":"All intents combined, including privileged ones.\n\n\n\n\n\n","title":"Accord.IntentAll"},{"category":"type","location":"api/#Accord.Permissions","page":"API Reference","text":"Permissions\n\nDiscord permissions are stored as a bitmask. Accord.jl provides constant values for each permission. Use has_flag to check if a set of permissions contains a specific one.\n\nDiscord docs\n\nExample\n\n# Check for a specific permission\nif has_flag(member_perms, PermAdministrator)\n    println(\"User is an admin\")\nend\n\n# Combine permissions\nrequired = PermSendMessages | PermEmbedLinks\n\n\n\n\n\n","title":"Accord.Permissions"},{"category":"function","location":"api/#Accord.has_flag","page":"API Reference","text":"Use this to verify if a user has specific permissions or if certain flags are enabled.\n\nCheck if a has all flags in b set.\n\nExample\n\njulia> perms = PermSendMessages | PermEmbedLinks;\n\njulia> has_flag(perms, PermSendMessages)\ntrue\n\njulia> has_flag(perms, PermAdministrator)\nfalse\n\n\n\n\n\n","title":"Accord.has_flag"},{"category":"function","location":"api/#Accord.compute_base_permissions","page":"API Reference","text":"compute_base_permissions(member_roles::Vector{Snowflake}, guild_roles::Vector{Role}, owner_id::Snowflake, user_id::Snowflake) -> Permissions\n\nUse this to determine what permissions a user has at the guild level before considering channel-specific restrictions.\n\nCompute the base Permissions for a member in a guild (before channel overwrites). Takes a list of Role IDs, all guild roles, the owner's Snowflake, and the member's ID.\n\nExample\n\njulia> r = Role(; id=Snowflake(1), name=\"foo\", color=0, hoist=false, position=0, permissions=\"8\", managed=false, mentionable=false);\n\njulia> base = Accord.compute_base_permissions([Snowflake(1)], [r], Snowflake(2), Snowflake(3));\n\njulia> has_flag(base, PermAdministrator)\ntrue\n\n\n\n\n\n","title":"Accord.compute_base_permissions"},{"category":"function","location":"api/#Accord.compute_channel_permissions","page":"API Reference","text":"compute_channel_permissions(base::Permissions, member_roles::Vector{Snowflake}, overwrites::Vector{Overwrite}, guild_id::Snowflake, user_id::Snowflake) -> Permissions\n\nUse this to calculate final permissions by applying channel-specific overwrites to base guild permissions.\n\nApply channel Overwrites to base Permissions.\n\nExample\n\njulia> r = Role(; id=Snowflake(1), name=\"foo\", color=0, hoist=false, position=0, permissions=\"0\", managed=false, mentionable=false);\n\njulia> ow = Overwrite(; id=Snowflake(1), type=0, allow=\"2048\", deny=\"0\");\n\njulia> base = Permissions(0);\n\njulia> channel_perms = Accord.compute_channel_permissions(base, [Snowflake(1)], [ow], Snowflake(2), Snowflake(3));\n\njulia> has_flag(channel_perms, PermSendMessages)\ntrue\n\n\n\n\n\n","title":"Accord.compute_channel_permissions"},{"category":"type","location":"api/#Accord.MessageFlags","page":"API Reference","text":"MessageFlags\n\nBitfield representing extra attributes of a message, such as whether it is ephemeral or crossposted.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.MessageFlags"},{"category":"constant","location":"api/#Accord.MsgFlagCrossposted","page":"API Reference","text":"This message has been published to subscribed channels (via Channel Following).\n\n\n\n\n\n","title":"Accord.MsgFlagCrossposted"},{"category":"constant","location":"api/#Accord.MsgFlagIsCrosspost","page":"API Reference","text":"This message originated from a message in another channel (via Channel Following).\n\n\n\n\n\n","title":"Accord.MsgFlagIsCrosspost"},{"category":"constant","location":"api/#Accord.MsgFlagSuppressEmbeds","page":"API Reference","text":"Do not include any embeds when serializing this message.\n\n\n\n\n\n","title":"Accord.MsgFlagSuppressEmbeds"},{"category":"constant","location":"api/#Accord.MsgFlagSourceMessageDeleted","page":"API Reference","text":"The source message for this crosspost has been deleted (via Channel Following).\n\n\n\n\n\n","title":"Accord.MsgFlagSourceMessageDeleted"},{"category":"constant","location":"api/#Accord.MsgFlagUrgent","page":"API Reference","text":"This message came from the urgent message system.\n\n\n\n\n\n","title":"Accord.MsgFlagUrgent"},{"category":"constant","location":"api/#Accord.MsgFlagHasThread","page":"API Reference","text":"This message has an associated thread, with the same id as the message.\n\n\n\n\n\n","title":"Accord.MsgFlagHasThread"},{"category":"constant","location":"api/#Accord.MsgFlagEphemeral","page":"API Reference","text":"This message is only visible to the user who invoked the Interaction.\n\n\n\n\n\n","title":"Accord.MsgFlagEphemeral"},{"category":"constant","location":"api/#Accord.MsgFlagLoading","page":"API Reference","text":"This message is an Interaction Response and the bot is \"thinking\".\n\n\n\n\n\n","title":"Accord.MsgFlagLoading"},{"category":"constant","location":"api/#Accord.MsgFlagFailedToMentionSomeRolesInThread","page":"API Reference","text":"This message failed to mention some roles and add their members to the thread.\n\n\n\n\n\n","title":"Accord.MsgFlagFailedToMentionSomeRolesInThread"},{"category":"constant","location":"api/#Accord.MsgFlagSuppressNotifications","page":"API Reference","text":"This message will not trigger push and desktop notifications.\n\n\n\n\n\n","title":"Accord.MsgFlagSuppressNotifications"},{"category":"constant","location":"api/#Accord.MsgFlagIsVoiceMessage","page":"API Reference","text":"This message is a voice message.\n\n\n\n\n\n","title":"Accord.MsgFlagIsVoiceMessage"},{"category":"constant","location":"api/#Accord.MsgFlagHasSnapshot","page":"API Reference","text":"This message carries a snapshot of a forwarded message (message_snapshots).\n\n\n\n\n\n","title":"Accord.MsgFlagHasSnapshot"},{"category":"constant","location":"api/#Accord.MsgFlagIsComponentsV2","page":"API Reference","text":"The message uses Components V2: layout components, no content or embeds. Required when sending container, section, text_display and friends.\n\n\n\n\n\n","title":"Accord.MsgFlagIsComponentsV2"},{"category":"type","location":"api/#Accord.UserFlags","page":"API Reference","text":"UserFlags\n\nBitfield representing public flags on a user's account, such as whether they are a Discord employee or a partner.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.UserFlags"},{"category":"constant","location":"api/#Accord.UserFlagStaff","page":"API Reference","text":"Discord Employee\n\n\n\n\n\n","title":"Accord.UserFlagStaff"},{"category":"constant","location":"api/#Accord.UserFlagPartner","page":"API Reference","text":"Partnered Server Owner\n\n\n\n\n\n","title":"Accord.UserFlagPartner"},{"category":"constant","location":"api/#Accord.UserFlagHypeSquad","page":"API Reference","text":"HypeSquad Events Member\n\n\n\n\n\n","title":"Accord.UserFlagHypeSquad"},{"category":"constant","location":"api/#Accord.UserFlagBugHunterLevel1","page":"API Reference","text":"Bug Hunter Level 1\n\n\n\n\n\n","title":"Accord.UserFlagBugHunterLevel1"},{"category":"constant","location":"api/#Accord.UserFlagHypeSquadBravery","page":"API Reference","text":"House Bravery Member\n\n\n\n\n\n","title":"Accord.UserFlagHypeSquadBravery"},{"category":"constant","location":"api/#Accord.UserFlagHypeSquadBrilliance","page":"API Reference","text":"House Brilliance Member\n\n\n\n\n\n","title":"Accord.UserFlagHypeSquadBrilliance"},{"category":"constant","location":"api/#Accord.UserFlagHypeSquadBalance","page":"API Reference","text":"House Balance Member\n\n\n\n\n\n","title":"Accord.UserFlagHypeSquadBalance"},{"category":"constant","location":"api/#Accord.UserFlagEarlyNitroSupporter","page":"API Reference","text":"Early Nitro Supporter\n\n\n\n\n\n","title":"Accord.UserFlagEarlyNitroSupporter"},{"category":"constant","location":"api/#Accord.UserFlagTeamPseudoUser","page":"API Reference","text":"User is a team\n\n\n\n\n\n","title":"Accord.UserFlagTeamPseudoUser"},{"category":"constant","location":"api/#Accord.UserFlagBugHunterLevel2","page":"API Reference","text":"Bug Hunter Level 2\n\n\n\n\n\n","title":"Accord.UserFlagBugHunterLevel2"},{"category":"constant","location":"api/#Accord.UserFlagVerifiedBot","page":"API Reference","text":"Verified Bot\n\n\n\n\n\n","title":"Accord.UserFlagVerifiedBot"},{"category":"constant","location":"api/#Accord.UserFlagVerifiedDeveloper","page":"API Reference","text":"Early Verified Bot Developer\n\n\n\n\n\n","title":"Accord.UserFlagVerifiedDeveloper"},{"category":"constant","location":"api/#Accord.UserFlagCertifiedModerator","page":"API Reference","text":"Moderator Programs Alumni\n\n\n\n\n\n","title":"Accord.UserFlagCertifiedModerator"},{"category":"constant","location":"api/#Accord.UserFlagBotHTTPInteractions","page":"API Reference","text":"Bot uses only HTTP interactions and is shown in the online member list\n\n\n\n\n\n","title":"Accord.UserFlagBotHTTPInteractions"},{"category":"constant","location":"api/#Accord.UserFlagActiveDeveloper","page":"API Reference","text":"Active Developer\n\n\n\n\n\n","title":"Accord.UserFlagActiveDeveloper"},{"category":"type","location":"api/#Accord.ChannelFlags","page":"API Reference","text":"ChannelFlags\n\nBitfield representing extra attributes of a channel, such as whether it is pinned in a forum.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ChannelFlags"},{"category":"constant","location":"api/#Accord.ChanFlagPinned","page":"API Reference","text":"The channel is pinned in a forum.\n\n\n\n\n\n","title":"Accord.ChanFlagPinned"},{"category":"constant","location":"api/#Accord.ChanFlagRequireTag","page":"API Reference","text":"The channel requires tags (forums).\n\n\n\n\n\n","title":"Accord.ChanFlagRequireTag"},{"category":"constant","location":"api/#Accord.ChanFlagHideMediaDownloadOptions","page":"API Reference","text":"When set hides the embedded media download options.\n\n\n\n\n\n","title":"Accord.ChanFlagHideMediaDownloadOptions"},{"category":"type","location":"api/#Accord.GuildMemberFlags","page":"API Reference","text":"GuildMemberFlags\n\nBitfield representing attributes of a guild member, such as whether they have completed onboarding.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.GuildMemberFlags"},{"category":"constant","location":"api/#Accord.MemberFlagDidRejoin","page":"API Reference","text":"Member has left and rejoined the guild.\n\n\n\n\n\n","title":"Accord.MemberFlagDidRejoin"},{"category":"constant","location":"api/#Accord.MemberFlagCompletedOnboarding","page":"API Reference","text":"Member has completed onboarding.\n\n\n\n\n\n","title":"Accord.MemberFlagCompletedOnboarding"},{"category":"constant","location":"api/#Accord.MemberFlagBypassesVerification","page":"API Reference","text":"Member is exempt from verification requirements.\n\n\n\n\n\n","title":"Accord.MemberFlagBypassesVerification"},{"category":"constant","location":"api/#Accord.MemberFlagStartedOnboarding","page":"API Reference","text":"Member has started onboarding.\n\n\n\n\n\n","title":"Accord.MemberFlagStartedOnboarding"},{"category":"constant","location":"api/#Accord.MemberFlagIsGuest","page":"API Reference","text":"Member is a guest and can only access the guild through the channel they were invited to.\n\n\n\n\n\n","title":"Accord.MemberFlagIsGuest"},{"category":"constant","location":"api/#Accord.MemberFlagStartedHomeActions","page":"API Reference","text":"Member has started home actions.\n\n\n\n\n\n","title":"Accord.MemberFlagStartedHomeActions"},{"category":"constant","location":"api/#Accord.MemberFlagCompletedHomeActions","page":"API Reference","text":"Member has completed home actions.\n\n\n\n\n\n","title":"Accord.MemberFlagCompletedHomeActions"},{"category":"constant","location":"api/#Accord.MemberFlagAutomodQuarantinedUsername","page":"API Reference","text":"Member's username is quarantined by automod.\n\n\n\n\n\n","title":"Accord.MemberFlagAutomodQuarantinedUsername"},{"category":"constant","location":"api/#Accord.MemberFlagDMSettingsUpsellAcknowledged","page":"API Reference","text":"Member has acknowledged the DM settings upsell.\n\n\n\n\n\n","title":"Accord.MemberFlagDMSettingsUpsellAcknowledged"},{"category":"type","location":"api/#Accord.SystemChannelFlags","page":"API Reference","text":"SystemChannelFlags\n\nBitfield representing which standard system notifications are disabled in a guild's system channel.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.SystemChannelFlags"},{"category":"constant","location":"api/#Accord.SysChanSuppressJoinNotifications","page":"API Reference","text":"Suppress member join notifications.\n\n\n\n\n\n","title":"Accord.SysChanSuppressJoinNotifications"},{"category":"constant","location":"api/#Accord.SysChanSuppressJoinNotificationReplies","page":"API Reference","text":"Suppress member join notification replies.\n\n\n\n\n\n","title":"Accord.SysChanSuppressJoinNotificationReplies"},{"category":"constant","location":"api/#Accord.SysChanSuppressPremiumSubscriptions","page":"API Reference","text":"Suppress server boost notifications.\n\n\n\n\n\n","title":"Accord.SysChanSuppressPremiumSubscriptions"},{"category":"constant","location":"api/#Accord.SysChanSuppressGuildReminderNotifications","page":"API Reference","text":"Suppress server setup tips.\n\n\n\n\n\n","title":"Accord.SysChanSuppressGuildReminderNotifications"},{"category":"constant","location":"api/#Accord.SysChanSuppressRoleSubscriptionPurchaseNotifications","page":"API Reference","text":"Suppress role subscription purchase and renewal notifications.\n\n\n\n\n\n","title":"Accord.SysChanSuppressRoleSubscriptionPurchaseNotifications"},{"category":"constant","location":"api/#Accord.SysChanSuppressRoleSubscriptionPurchaseNotificationReplies","page":"API Reference","text":"Suppress role subscription purchase and renewal notification replies.\n\n\n\n\n\n","title":"Accord.SysChanSuppressRoleSubscriptionPurchaseNotificationReplies"},{"category":"type","location":"api/#Accord.RoleFlags","page":"API Reference","text":"RoleFlags\n\nBitfield representing attributes of a role, such as whether it is displayed in an onboarding prompt.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.RoleFlags"},{"category":"constant","location":"api/#Accord.RoleFlagInPrompt","page":"API Reference","text":"Role can be selected by members in an onboarding prompt.\n\n\n\n\n\n","title":"Accord.RoleFlagInPrompt"},{"category":"type","location":"api/#Accord.AttachmentFlags","page":"API Reference","text":"AttachmentFlags\n\nBitfield representing attributes of an attachment, such as whether it is a remix.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.AttachmentFlags"},{"category":"constant","location":"api/#Accord.AttachFlagIsClip","page":"API Reference","text":"The attachment is a clip from a stream.\n\n\n\n\n\n","title":"Accord.AttachFlagIsClip"},{"category":"constant","location":"api/#Accord.AttachFlagIsThumbnail","page":"API Reference","text":"The attachment is the thumbnail of a thread in a media channel.\n\n\n\n\n\n","title":"Accord.AttachFlagIsThumbnail"},{"category":"constant","location":"api/#Accord.AttachFlagIsRemix","page":"API Reference","text":"The attachment is a remix.\n\n\n\n\n\n","title":"Accord.AttachFlagIsRemix"},{"category":"constant","location":"api/#Accord.AttachFlagIsSpoiler","page":"API Reference","text":"The attachment is marked as a spoiler.\n\n\n\n\n\n","title":"Accord.AttachFlagIsSpoiler"},{"category":"constant","location":"api/#Accord.AttachFlagContainsExplicitContent","page":"API Reference","text":"Discord's scan flagged the attachment as explicit content.\n\n\n\n\n\n","title":"Accord.AttachFlagContainsExplicitContent"},{"category":"constant","location":"api/#Accord.AttachFlagIsAnimated","page":"API Reference","text":"The attachment is an animated image.\n\n\n\n\n\n","title":"Accord.AttachFlagIsAnimated"},{"category":"constant","location":"api/#Accord.AttachFlagContainsGoreContent","page":"API Reference","text":"Discord's scan flagged the attachment as gore.\n\n\n\n\n\n","title":"Accord.AttachFlagContainsGoreContent"},{"category":"constant","location":"api/#Accord.AttachFlagContainsSelfHarmContent","page":"API Reference","text":"Discord's scan flagged the attachment as self-harm content.\n\n\n\n\n\n","title":"Accord.AttachFlagContainsSelfHarmContent"},{"category":"type","location":"api/#Accord.SKUFlags","page":"API Reference","text":"SKUFlags\n\nBitfield representing attributes of a SKU, such as whether it is a user or guild subscription.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.SKUFlags"},{"category":"constant","location":"api/#Accord.SKUFlagAvailable","page":"API Reference","text":"SKU is available for purchase.\n\n\n\n\n\n","title":"Accord.SKUFlagAvailable"},{"category":"constant","location":"api/#Accord.SKUFlagGuildSubscription","page":"API Reference","text":"SKU is a guild subscription.\n\n\n\n\n\n","title":"Accord.SKUFlagGuildSubscription"},{"category":"constant","location":"api/#Accord.SKUFlagUserSubscription","page":"API Reference","text":"SKU is a user subscription.\n\n\n\n\n\n","title":"Accord.SKUFlagUserSubscription"},{"category":"macro","location":"api/#Accord.@discord_struct","page":"API Reference","text":"@discord_struct Name begin\n    field::Type\n    field::Optional{Type}  # = missing\n    ...\nend\n\nUse this macro when defining new Discord API data structures to automatically handle optional fields and JSON serialization.\n\nGenerate a Discord API struct with:\n\nMutable struct with keyword constructor\nAll Optional{T} fields default to missing\nAll Nullable{T} fields default to nothing\nAll other fields get sensible defaults for zero-arg construction\nJSON3/StructTypes Mutable() integration\n\nExample\n\njulia> Accord.@discord_struct MyResource begin\n           id::Snowflake\n           name::String\n           description::Optional{String}\n           count::Int\n       end;\n\njulia> r = MyResource(id=Snowflake(123), name=\"test\");\n\njulia> r.description === missing\ntrue\n\n\n\n\n\n","title":"Accord.@discord_struct"},{"category":"macro","location":"api/#Accord.@discord_flags","page":"API Reference","text":"@discord_flags Name begin\n    FLAG_NAME = value\n    ...\nend\n\nUse this macro when creating new bitfield flag types for Discord API features.\n\nDefine a flags type backed by UInt64 with bitwise operations.\n\n\n\n\n\n","title":"Accord.@discord_flags"},{"category":"macro","location":"api/#Accord.@_flags_structtypes_int","page":"API Reference","text":"Use this macro internally to enable JSON serialization for flag types.\n\nRegister integer-based StructTypes for a flags type.\n\nExample\n\njulia> struct MyFlagsType; value::UInt64; end;\n\njulia> Accord.@_flags_structtypes_int MyFlagsType\n\n\n\n\n\n","title":"Accord.@_flags_structtypes_int"},{"category":"type","location":"api/#Accord.EventHandler","page":"API Reference","text":"EventHandler\n\nUse this internal struct to manage event handlers and middleware for the client.\n\nStores registered event handlers for the client.\n\nExample\n\neh = EventHandler()  # fresh handler with no handlers registered\n\n\n\n\n\n","title":"Accord.EventHandler"},{"category":"type","location":"api/#Accord.EventWaiter","page":"API Reference","text":"EventWaiter\n\nUse this internal struct to wait for specific gateway events matching a predicate.\n\nInternal struct for wait_for. Holds the event type filter, predicate, and a Channel that receives the matching event.\n\n\n\n\n\n","title":"Accord.EventWaiter"},{"category":"function","location":"api/#Accord.register_handler!","page":"API Reference","text":"register_handler!(eh::EventHandler, event_type, handler)\n\nUse this internal function to add an event handler for a specific gateway event type.\n\nRegister a handler function for a specific event type. The handler should accept (client, event).\n\nExample\n\nregister_handler!(eh, MessageCreate, (client, event) -> println(event.message.content))\n\n\n\n\n\n","title":"Accord.register_handler!"},{"category":"function","location":"api/#Accord.register_middleware!","page":"API Reference","text":"register_middleware!(eh::EventHandler, middleware)\n\nUse this internal function to add middleware that processes events before handlers.\n\nRegister middleware that runs before event handlers. Middleware should accept (client, event) and return the event (or nothing to cancel).\n\nExample\n\nregister_middleware!(eh, (client, event) -> begin\n    @info \"Event received\" type=typeof(event)\n    event  # return event to continue, or nothing to cancel\nend)\n\n\n\n\n\n","title":"Accord.register_middleware!"},{"category":"function","location":"api/#Accord.dispatch_event!","page":"API Reference","text":"dispatch_event!(eh::EventHandler, client, event)\n\nUse this internal function to route an incoming event to all applicable handlers.\n\nDispatch an event to all registered handlers.\n\nExample\n\nevent = MessageCreate(message)\ndispatch_event!(client.event_handler, client, event)\n\n\n\n\n\n","title":"Accord.dispatch_event!"},{"category":"function","location":"api/#Accord.parse_event","page":"API Reference","text":"parse_event(event_name::String, data::Union{Dict{String, Any}, String}) -> AbstractEvent\n\nParse a raw gateway dispatch payload (either as a Dict or a JSON string) into a typed AbstractEvent struct. If data is a String, it is deserialized directly into the event struct, avoiding intermediate Dict conversion.\n\n\n\n\n\n","title":"Accord.parse_event"},{"category":"type","location":"api/#Accord.GatewaySession","page":"API Reference","text":"GatewaySession\n\nUse this internal struct to track the state of an active gateway WebSocket connection.\n\nHolds state for a single GatewaySession.\n\nExample\n\nsession = GatewaySession()  # creates a fresh, unconnected session\nsession.connected            # => false\n\n\n\n\n\n","title":"Accord.GatewaySession"},{"category":"type","location":"api/#Accord.ShardInfo","page":"API Reference","text":"ShardInfo\n\nUse this internal struct to manage the lifecycle and events of a single gateway shard.\n\nTracks state for a single gateway shard. Uses GatewaySession for the connection. Events are dispatched to a shared AbstractEvent channel. Commands are received via a GatewayCommand channel.\n\nExample\n\nevents = Channel{AbstractEvent}(1024)\nshard = ShardInfo(0, 1, events)  # shard 0 of 1\n\n\n\n\n\n","title":"Accord.ShardInfo"},{"category":"type","location":"api/#Accord.GatewayCommand","page":"API Reference","text":"Use this internal struct to send control commands to the gateway connection actor.\n\nGatewayCommand sent to the connection actor.\n\nExample\n\ncmd = GatewayCommand(GatewayOpcodes.PRESENCE_UPDATE, Dict(\"status\" => \"online\"))\n\n\n\n\n\n","title":"Accord.GatewayCommand"},{"category":"function","location":"api/#Accord.GatewayCloseCodes.can_reconnect","page":"API Reference","text":"Check if a close code allows reconnection.\n\nExample\n\nGatewayCloseCodes.can_reconnect(4000)  # => true (unknown error)\nGatewayCloseCodes.can_reconnect(4004)  # => false (auth failed)\n\n\n\n\n\n","title":"Accord.GatewayCloseCodes.can_reconnect"},{"category":"function","location":"api/#Accord.start_shard","page":"API Reference","text":"start_shard(shard::ShardInfo, token::String, intents::UInt32)\n\nUse this internal function to launch a new shard connection as a background task.\n\nStart a gateway connection for this ShardInfo in a new Task.\n\nExample\n\ntask = start_shard(shard, \"Bot my_token\", UInt32(513))\n\n\n\n\n\n","title":"Accord.start_shard"},{"category":"function","location":"api/#Accord.stop_shard","page":"API Reference","text":"stop_shard(shard::ShardInfo)\n\nUse this internal function to gracefully terminate a shard connection.\n\nSignal the ShardInfo to disconnect.\n\nExample\n\nstop_shard(shard)  # triggers graceful shutdown\n\n\n\n\n\n","title":"Accord.stop_shard"},{"category":"function","location":"api/#Accord.send_to_shard","page":"API Reference","text":"send_to_shard(shard::ShardInfo, cmd::GatewayCommand)\n\nUse this internal function to send control commands to a running shard.\n\nSend a GatewayCommand to a specific ShardInfo.\n\nExample\n\ncmd = GatewayCommand(GatewayOpcodes.PRESENCE_UPDATE, payload)\nsend_to_shard(shard, cmd)\n\n\n\n\n\n","title":"Accord.send_to_shard"},{"category":"function","location":"api/#Accord.gateway_connect","page":"API Reference","text":"gateway_connect(token, intents, shard, events_channel, commands_channel; resume=false)\n\nUse this internal function to establish and maintain a WebSocket connection to Discord's gateway.\n\nMain gateway connection loop. Runs as a Task.\n\nConnects to Discord gateway via WebSocket\nHandles IDENTIFY/RESUME\nDispatches events to events_channel (which receives AbstractEvents)\nReceives commands from commands_channel (which receives GatewayCommands)\nAuto-reconnects on disconnection\n\nnote: Note\nThis function automatically reconnects on network errors and resumable close codes. Fatal close codes (e.g. invalid token, disallowed intents) will stop the loop.\n\n\n\n\n\n","title":"Accord.gateway_connect"},{"category":"function","location":"api/#Accord.shard_for_guild","page":"API Reference","text":"shard_for_guild(guild_id::Snowflake, num_shards::Int) -> Int\n\nUse this internal function to determine which shard should handle events for a specific guild.\n\nCalculate which shard handles a given guild Snowflake. Formula: (guildid >> 22) % numshards\n\nExample\n\nshard_id = shard_for_guild(Snowflake(123456789), 4)  # => 0, 1, 2, or 3\n\n\n\n\n\n","title":"Accord.shard_for_guild"},{"category":"type","location":"api/#Accord.RateLimiter","page":"API Reference","text":"RateLimiter\n\nUse this to manage Discord API requests and automatically respect rate limits.\n\nProcesses REST requests respecting Discord's per-bucket and global rate limits. Different buckets are served concurrently; requests within a bucket are sent one at a time.\n\nnote: Note\nThe rate limiter automatically retries on HTTP 429 responses (up to 5 times) using the Retry-After header. You do not need to handle rate limiting yourself. Network errors are retried only for idempotent methods (GET, HEAD, PUT, DELETE, OPTIONS), so a POST is never sent twice because of a dropped connection.\n\n\n\n\n\n","title":"Accord.RateLimiter"},{"category":"type","location":"api/#Accord.BucketState","page":"API Reference","text":"Use this internal struct to track rate limit state for each Discord API bucket.\n\nState for a single rate limit bucket.\n\nExample\n\nbucket = BucketState()  # remaining=1, reset_at=0.0\n\n\n\n\n\n","title":"Accord.BucketState"},{"category":"type","location":"api/#Accord.RestJob","page":"API Reference","text":"Use this internal struct to queue REST API requests for rate-limited execution.\n\nA REST job submitted to the RateLimiter.\n\nbody is either the request body itself (nothing, a String, bytes) or a zero-argument function that builds it. Use a function for bodies that are consumed when sent, such as multipart forms, so every retry gets a fresh body.\n\nExample\n\nresult_ch = Channel{Any}(1)\njob = RestJob(route, \"GET\", url, headers, nothing, result_ch)\n\n\n\n\n\n","title":"Accord.RestJob"},{"category":"type","location":"api/#Accord.Route","page":"API Reference","text":"Route\n\nUse this struct when making REST API calls to properly handle Discord's rate limiting per endpoint.\n\nRepresents a Discord REST API route with method, path, and bucket key. The bucket key groups routes that share a rate limit.\n\nExample\n\nroute = Route(\"GET\", \"/channels/{channel_id}/messages\", \"channel_id\" => \"123456\")\nurl(route)  # => \"https://discord.com/api/v10/channels/123456/messages\"\n\n\n\n\n\n","title":"Accord.Route"},{"category":"function","location":"api/#Accord.url","page":"API Reference","text":"Use this to get the complete URL for making HTTP requests to this route.\n\nFull URL for this route.\n\nExample\n\nroute = Route(\"POST\", \"/channels/123/messages\")\nurl(route)  # => \"https://discord.com/api/v10/channels/123/messages\"\n\n\n\n\n\n","title":"Accord.url"},{"category":"function","location":"api/#Accord.start_ratelimiter!","page":"API Reference","text":"Use this to begin processing REST jobs through the rate limiter.\n\nStart the RateLimiter dispatcher loop.\n\nExample\n\nrl = RateLimiter()\nstart_ratelimiter!(rl)  # begins processing in background\n\n\n\n\n\n","title":"Accord.start_ratelimiter!"},{"category":"function","location":"api/#Accord.stop_ratelimiter!","page":"API Reference","text":"Use this to gracefully shut down the rate limiter and stop processing jobs.\n\nStop the RateLimiter. Requests already in flight are allowed to finish.\n\nExample\n\nstop_ratelimiter!(rl)  # closes job channel, stops dispatcher\n\n\n\n\n\n","title":"Accord.stop_ratelimiter!"},{"category":"function","location":"api/#Accord.submit_rest","page":"API Reference","text":"Use this to queue a REST API request and receive the response through rate limiting.\n\nSubmit a RestJob and wait for the result.\n\nExample\n\nresp = submit_rest(rl, job)  # blocks until response or error\nresp.status  # => 200\n\n\n\n\n\n","title":"Accord.submit_rest"},{"category":"function","location":"api/#Accord.discord_get","page":"API Reference","text":"discord_get(rl, path; token, query=nothing, kwargs...) -> HTTP.Response\n\nUse this convenience function when you need to fetch data from the Discord API.\n\nConvenience for GET requests.\n\nExample\n\nresp = discord_get(client.ratelimiter, \"/channels/$(channel_id)/messages\";\n    token=client.token, query=Dict(\"limit\" => 10))\nmessages = parse_response_array(Message, resp)\n\n\n\n\n\n","title":"Accord.discord_get"},{"category":"function","location":"api/#Accord.discord_post","page":"API Reference","text":"discord_post(rl, path; token, body=nothing, kwargs...) -> HTTP.Response\n\nUse this convenience function when you need to create new resources in the Discord API.\n\nConvenience for POST requests.\n\nExample\n\nresp = discord_post(client.ratelimiter, \"/channels/$(channel_id)/messages\";\n    token=client.token, body=Dict(\"content\" => \"Hello!\"))\n\n\n\n\n\n","title":"Accord.discord_post"},{"category":"function","location":"api/#Accord.discord_put","page":"API Reference","text":"discord_put(rl, path; token, body=nothing, kwargs...) -> HTTP.Response\n\nUse this convenience function when you need to update or replace resources in the Discord API.\n\nConvenience for PUT requests.\n\nExample\n\nresp = discord_put(client.ratelimiter, \"/channels/$(channel_id)/pins/$(msg_id)\";\n    token=client.token)\n\n\n\n\n\n","title":"Accord.discord_put"},{"category":"function","location":"api/#Accord.discord_patch","page":"API Reference","text":"discord_patch(rl, path; token, body=nothing, kwargs...) -> HTTP.Response\n\nUse this convenience function when you need to partially update resources in the Discord API.\n\nConvenience for PATCH requests.\n\nExample\n\nresp = discord_patch(client.ratelimiter, \"/channels/$(channel_id)\";\n    token=client.token, body=Dict(\"name\" => \"new-name\"))\n\n\n\n\n\n","title":"Accord.discord_patch"},{"category":"function","location":"api/#Accord.discord_delete","page":"API Reference","text":"discord_delete(rl, path; token, kwargs...) -> HTTP.Response\n\nUse this convenience function when you need to delete resources from the Discord API.\n\nConvenience for DELETE requests.\n\nExample\n\nresp = discord_delete(client.ratelimiter, \"/channels/$(channel_id)/messages/$(msg_id)\";\n    token=client.token, reason=\"Cleanup\")\n\n\n\n\n\n","title":"Accord.discord_delete"},{"category":"function","location":"api/#Accord.discord_request","page":"API Reference","text":"discord_request(rl::RateLimiter, route::Route; kwargs...) -> HTTP.Response\n\nUse this function when you need full control over Discord API requests with custom headers and body.\n\nExecute a Discord REST API request through the RateLimiter. Uses a Route to track rate limits.\n\nKeyword arguments\n\ntoken::String — Bot token for Authorization header\nbody=nothing — Request body (Dict for JSON, or raw)\nfiles=nothing — Vector of (filename, data) for multipart upload\nreason=nothing — Audit log reason (X-Audit-Log-Reason header)\nquery=nothing — Query string parameters\n\n\n\n\n\n","title":"Accord.discord_request"},{"category":"function","location":"api/#Accord.parse_response","page":"API Reference","text":"Use this helper function to deserialize Discord API responses into Julia structs.\n\nParse a JSON response body into type T.\n\nExample\n\nresp = discord_get(rl, \"/users/@me\"; token=token)\nuser = parse_response(User, resp)\nprintln(user.username)\n\n\n\n\n\n","title":"Accord.parse_response"},{"category":"function","location":"api/#Accord.parse_response_array","page":"API Reference","text":"Use this helper function to deserialize Discord API array responses into Julia vectors.\n\nParse a JSON response body into a Vector of type T.\n\nExample\n\nresp = discord_get(rl, \"/guilds/$(guild_id)/roles\"; token=token)\nroles = parse_response_array(Role, resp)\n\n\n\n\n\n","title":"Accord.parse_response_array"},{"category":"type","location":"api/#Accord.VoiceGatewaySession","page":"API Reference","text":"VoiceGatewaySession\n\nUse this internal struct to manage the voice gateway WebSocket connection state.\n\nState for a voice gateway WebSocket connection.\n\n\n\n\n\n","title":"Accord.VoiceGatewaySession"},{"category":"function","location":"api/#Accord.voice_gateway_connect","page":"API Reference","text":"voice_gateway_connect(session::VoiceGatewaySession) -> Task\n\nUse this internal function to establish the voice gateway connection.\n\nConnect to the voice gateway WebSocket and complete the handshake.\n\n\n\n\n\n","title":"Accord.voice_gateway_connect"},{"category":"function","location":"api/#Accord.send_select_protocol","page":"API Reference","text":"Use this internal function to complete the voice connection handshake after IP discovery.\n\nSend Select Protocol to the voice gateway after IP discovery.\n\n\n\n\n\n","title":"Accord.send_select_protocol"},{"category":"function","location":"api/#Accord.send_speaking","page":"API Reference","text":"Use this internal function to signal when your bot starts or stops speaking.\n\nSend Speaking opcode to the voice gateway.\n\n\n\n\n\n","title":"Accord.send_speaking"},{"category":"function","location":"api/#Accord.create_voice_udp","page":"API Reference","text":"create_voice_udp(address::String, port::Int) -> UDPSocket\n\nCreate and connect a UDP socket for voice communication.\n\n\n\n\n\n","title":"Accord.create_voice_udp"},{"category":"function","location":"api/#Accord.ip_discovery","page":"API Reference","text":"ip_discovery(sock::UDPSocket, address::String, port::Int, ssrc::UInt32) -> (ip, port)\n\nPerform IP discovery to find our external IP and port. Sends a 74-byte request packet and reads the response.\n\n\n\n\n\n","title":"Accord.ip_discovery"},{"category":"function","location":"api/#Accord.select_encryption_mode","page":"API Reference","text":"select_encryption_mode(server_modes) -> String\n\nSelect the best encryption mode offered by the voice server. AES-256-GCM is skipped when the CPU lacks hardware AES support.\n\n\n\n\n\n","title":"Accord.select_encryption_mode"},{"category":"constant","location":"api/#Accord.ENCRYPTION_MODES","page":"API Reference","text":"Available encryption modes in order of preference (Discord prefers AES-GCM).\n\n\n\n\n\n","title":"Accord.ENCRYPTION_MODES"},{"category":"function","location":"api/#Accord.send_voice_packet","page":"API Reference","text":"send_voice_packet(sock, address, port, header, encrypted_audio)\n\nSend an encrypted voice packet via UDP.\n\n\n\n\n\n","title":"Accord.send_voice_packet"},{"category":"function","location":"api/#Accord.rtp_header","page":"API Reference","text":"Build the RTP header bytes.\n\n\n\n\n\n","title":"Accord.rtp_header"},{"category":"function","location":"api/#Accord.parse_rtp_header","page":"API Reference","text":"Parse an RTP header from raw bytes.\n\n\n\n\n\n","title":"Accord.parse_rtp_header"},{"category":"type","location":"api/#Accord.RTPPacket","page":"API Reference","text":"RTPPacket\n\nRepresents an RTP packet for voice data.\n\n\n\n\n\n","title":"Accord.RTPPacket"},{"category":"function","location":"api/#Accord.encrypt_rtpsize","page":"API Reference","text":"encrypt_rtpsize(mode, key, counter, header, payload) -> Vector{UInt8}\n\nEncrypt one voice payload for an rtpsize mode. The RTP header is the additional authenticated data, and the 4-byte nonce counter is appended to the ciphertext, as Discord expects: ciphertext ‖ tag ‖ nonce[1:4].\n\n\n\n\n\n","title":"Accord.encrypt_rtpsize"},{"category":"function","location":"api/#Accord.decrypt_rtpsize","page":"API Reference","text":"decrypt_rtpsize(mode, key, header, data) -> Vector{UInt8}\n\nInverse of encrypt_rtpsize: strips the trailing 4-byte nonce from data, rebuilds the full nonce and decrypts with header as AAD.\n\n\n\n\n\n","title":"Accord.decrypt_rtpsize"},{"category":"function","location":"api/#Accord.rtpsize_nonce","page":"API Reference","text":"rtpsize_nonce(counter, mode) -> Vector{UInt8}\n\nFull-length nonce for an rtpsize mode: the 32-bit big-endian counter followed by zeros (12 bytes for AES-GCM, 24 for XChaCha20).\n\n\n\n\n\n","title":"Accord.rtpsize_nonce"},{"category":"function","location":"api/#Accord.aes256gcm_available","page":"API Reference","text":"aes256gcm_available() -> Bool\n\nWhether libsodium can use AES-256-GCM on this CPU (it needs hardware AES).\n\n\n\n\n\n","title":"Accord.aes256gcm_available"},{"category":"function","location":"api/#Accord.aead_aes256gcm_encrypt","page":"API Reference","text":"aead_aes256gcm_encrypt(key, nonce, plaintext, aad) -> ciphertext\n\nEncrypt using AEAD AES-256-GCM. Requires aes256gcm_available.\n\n\n\n\n\n","title":"Accord.aead_aes256gcm_encrypt"},{"category":"function","location":"api/#Accord.aead_aes256gcm_decrypt","page":"API Reference","text":"aead_aes256gcm_decrypt(key, nonce, ciphertext, aad) -> plaintext\n\nDecrypt using AEAD AES-256-GCM. Requires aes256gcm_available.\n\n\n\n\n\n","title":"Accord.aead_aes256gcm_decrypt"},{"category":"function","location":"api/#Accord.aead_xchacha20_poly1305_encrypt","page":"API Reference","text":"aead_xchacha20_poly1305_encrypt(key, nonce, plaintext, aad) -> ciphertext\n\nEncrypt using AEAD XChaCha20-Poly1305.\n\n\n\n\n\n","title":"Accord.aead_xchacha20_poly1305_encrypt"},{"category":"function","location":"api/#Accord.aead_xchacha20_poly1305_decrypt","page":"API Reference","text":"aead_xchacha20_poly1305_decrypt(key, nonce, ciphertext, aad) -> plaintext\n\nDecrypt using AEAD XChaCha20-Poly1305.\n\n\n\n\n\n","title":"Accord.aead_xchacha20_poly1305_decrypt"},{"category":"function","location":"api/#Accord.start_heartbeat","page":"API Reference","text":"start_heartbeat(ws, interval_ms, seq_ref, stop_event; send_lock=ReentrantLock()) -> (Task, HeartbeatState)\n\nUse this internal function to maintain the gateway connection by sending periodic heartbeats.\n\nLaunch a heartbeat actor that sends OP 1 Heartbeat at the given interval. Returns the Task. Set stop_event to signal shutdown.\n\nseq_ref is a Ref{Union{Int,Nothing}} tracking the last sequence number. send_lock must be the lock shared by every writer of ws (and by the writer of seq_ref), so heartbeat frames never interleave with other gateway sends.\n\n\n\n\n\n","title":"Accord.start_heartbeat"},{"category":"function","location":"api/#Accord.stop_heartbeat!","page":"API Reference","text":"Use this to terminate the heartbeat task gracefully.\n\nStop the heartbeat loop.\n\n\n\n\n\n","title":"Accord.stop_heartbeat!"},{"category":"function","location":"api/#Accord.heartbeat_ack!","page":"API Reference","text":"Use this to acknowledge receipt of a heartbeat ACK from the gateway.\n\nMark that a heartbeat ACK was received.\n\n\n\n\n\n","title":"Accord.heartbeat_ack!"},{"category":"function","location":"api/#Accord.heartbeat_latency","page":"API Reference","text":"Use this to measure the round-trip time between your bot and Discord's gateway.\n\nCalculate the current latency in milliseconds.\n\n\n\n\n\n","title":"Accord.heartbeat_latency"},{"category":"function","location":"api/#Accord._notify_waiters!","page":"API Reference","text":"_notify_waiters!(client::Client, event::AbstractEvent)\n\nUse this internal function to match incoming events against registered waiters for wait_for.\n\nCheck registered waiters against an incoming event. If a waiter's predicate matches, deliver the event through its channel. Called from _event_loop.\n\n\n\n\n\n","title":"Accord._notify_waiters!"},{"category":"constant","location":"api/#Accord._CHECKS_TLS_KEY","page":"API Reference","text":"pending_checks() -> Vector{Function}\n\nUse this internal accumulator to collect checks before they're applied to the next command.\n\nReturn a copy of checks accumulated by @check for the current Task. Checks are task-local to avoid cross-task leakage when commands are declared in parallel contexts (e.g., test workers or async setup code).\n\n\n\n\n\n","title":"Accord._CHECKS_TLS_KEY"},{"category":"function","location":"api/#Accord._resolve_perm","page":"API Reference","text":"Resolve a permission symbol or Permissions value to Permissions.\n\n\n\n\n\n","title":"Accord._resolve_perm"},{"category":"type","location":"api/#Accord.UnavailableGuild","page":"API Reference","text":"UnavailableGuild\n\nRepresents a guild that is currently unavailable due to an outage.\n\nSee Also\n\nDiscord API: Unavailable Guild Object\n\n\n\n\n\n","title":"Accord.UnavailableGuild"},{"category":"type","location":"api/#Accord.WelcomeScreen","page":"API Reference","text":"WelcomeScreen\n\nThe welcome screen shown to new members in a guild.\n\nSee Also\n\nDiscord API: Welcome Screen Object\n\n\n\n\n\n","title":"Accord.WelcomeScreen"},{"category":"type","location":"api/#Accord.WelcomeScreenChannel","page":"API Reference","text":"WelcomeScreenChannel\n\nMetadata for a channel on a guild's welcome screen.\n\nSee Also\n\nDiscord API: Welcome Screen Channel Object\n\n\n\n\n\n","title":"Accord.WelcomeScreenChannel"},{"category":"type","location":"api/#Accord.VoiceChannelStatusUpdate","page":"API Reference","text":"VoiceChannelStatusUpdate\n\nSent when a voice channel's status is updated. Discord docs\n\n\n\n\n\n","title":"Accord.VoiceChannelStatusUpdate"},{"category":"type","location":"api/#Accord.VoiceChannelStartTimeUpdate","page":"API Reference","text":"VoiceChannelStartTimeUpdate\n\nSent when a voice channel's start time is updated.\n\n\n\n\n\n","title":"Accord.VoiceChannelStartTimeUpdate"},{"category":"type","location":"api/#Accord.RateLimited","page":"API Reference","text":"RateLimited\n\nSent when a gateway request was rate limited and dropped, so no reply will come. opcode is the request's opcode (8 for request_guild_members), retry_after is in seconds, and meta carries the request's guild_id and nonce. Accord also logs a warning when it arrives.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.RateLimited"},{"category":"type","location":"api/#Accord.ChannelInfo","page":"API Reference","text":"ChannelInfo\n\nReply to request_channel_info: the voice status and start time of a guild's channels.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.ChannelInfo"},{"category":"type","location":"api/#Accord.ChannelInfoEntry","page":"API Reference","text":"ChannelInfoEntry\n\nOne channel in a ChannelInfo event: its id and, when requested, status and voice_start_time (Unix seconds).\n\n\n\n\n\n","title":"Accord.ChannelInfoEntry"},{"category":"function","location":"api/#Accord.create_poll","page":"API Reference","text":"create_poll(rl::RateLimiter, channel_id::Snowflake; token::String, question::String, answers::Vector{String}, duration_hours::Int=24, allow_multiselect::Bool=false) -> Message\n\nCreate a poll in a channel.\n\nUse this to post a poll message that users can vote on. The poll is embedded in a regular message and managed by Discord's native poll system.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the channel.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\nquestion::String: The poll question text (max 300 characters).\nanswers::Vector{String}: Answer options (1–10 items, each max 55 characters).\nduration_hours::Int: How long the poll runs in hours (1–168, default 24).\nallow_multiselect::Bool: Whether users may vote for multiple answers (default false).\n\nErrors\n\nThrows ArgumentError if answers is empty or duration_hours is out of range.\nHTTP 403 if the bot lacks SEND_MESSAGES permission.\nHTTP 404 if the channel does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_poll"},{"category":"function","location":"api/#Accord.modify_thread","page":"API Reference","text":"modify_thread(rl::RateLimiter, channel_id::Snowflake; token::String, name=nothing, archived=nothing, locked=nothing, auto_archive_duration=nothing, reason=nothing) -> DiscordChannel\n\nModify a thread channel's metadata.\n\nUse this to rename a thread, archive it, lock it, or change its auto-archive duration after it has been created.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the thread channel.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\nname::String: New name for the thread (1–100 characters).\narchived::Bool: Whether to archive the thread.\nlocked::Bool: Whether to lock the thread (only moderators can unarchive).\nauto_archive_duration::Int: Minutes until archive after inactivity (60, 1440, 4320, 10080).\nreason::String: Audit log reason (optional).\n\nErrors\n\nThrows ArgumentError if no keyword is provided.\nHTTP 403 if missing MANAGE_THREADS permission.\nHTTP 404 if the thread does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_thread"},{"category":"function","location":"api/#Accord.create_forum_tag","page":"API Reference","text":"create_forum_tag(rl::RateLimiter, channel_id::Snowflake; token::String, name::String, emoji_id=nothing, emoji_name=nothing, moderated::Bool=false) -> ForumTag\n\nAdd a new tag to a forum channel.\n\nUse this to create filterable tags on a GUILD_FORUM channel. Tags can have a text name and optionally an emoji (standard unicode or custom guild emoji).\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the forum channel.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\nname::String: Tag name (0–20 characters).\nemoji_id::Snowflake: ID of a custom guild emoji (mutually exclusive with emoji_name).\nemoji_name::String: Unicode emoji character (mutually exclusive with emoji_id).\nmoderated::Bool: Whether this tag can only be applied by moderators (default false).\n\nErrors\n\nHTTP 403 if the bot lacks MANAGE_CHANNELS permission.\nHTTP 404 if the channel does not exist or is not a forum.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.create_forum_tag"},{"category":"function","location":"api/#Accord.modify_forum_tag","page":"API Reference","text":"modify_forum_tag(rl::RateLimiter, channel_id::Snowflake, tag_id::Snowflake; token::String, name=nothing, emoji_id=nothing, emoji_name=nothing, moderated=nothing) -> ForumTag\n\nUpdate an existing tag on a forum channel.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the forum channel.\ntag_id::Snowflake: The ID of the tag to modify.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\nname::String: New tag name.\nemoji_id::Snowflake: New custom emoji ID.\nemoji_name::String: New unicode emoji.\nmoderated::Bool: New moderated flag.\n\nErrors\n\nThrows ArgumentError if no keyword is provided.\nHTTP 403 if missing MANAGE_CHANNELS.\nHTTP 404 if the channel or tag does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.modify_forum_tag"},{"category":"function","location":"api/#Accord.delete_forum_tag","page":"API Reference","text":"delete_forum_tag(rl::RateLimiter, channel_id::Snowflake, tag_id::Snowflake; token::String, reason=nothing)\n\nRemove a tag from a forum channel.\n\nArguments\n\nrl::RateLimiter: The rate limiter instance.\nchannel_id::Snowflake: The ID of the forum channel.\ntag_id::Snowflake: The ID of the tag to delete.\n\nKeyword Arguments\n\ntoken::String: Bot authentication token.\nreason::String: Audit log reason (optional).\n\nErrors\n\nHTTP 403 if missing MANAGE_CHANNELS.\nHTTP 404 if the channel or tag does not exist.\n\nDiscord docs\n\n\n\n\n\n","title":"Accord.delete_forum_tag"},{"category":"function","location":"api/#Accord.parse_timestamp","page":"API Reference","text":"parse_timestamp(s) -> Union{DateTime, Missing}\n\nParse a Discord ISO8601 timestamp string into a Julia DateTime. Returns missing if s is missing, empty, or unparseable (with a @warn). Sub-millisecond precision is silently truncated to milliseconds.\n\n\n\n\n\n","title":"Accord.parse_timestamp"},{"category":"function","location":"api/#Accord.push_pending_check!","page":"API Reference","text":"push_pending_check!(check::Function)\n\nUse this internal function to append a check to the task-local pending stack. Called by @check.\n\n\n\n\n\n","title":"Accord.push_pending_check!"},{"category":"macro","location":"api/#Accord.@wrap_resource_event","page":"API Reference","text":"@wrap_resource_event EventType PayloadType\n\nGenerates the decoder for events that just wrap a single resource struct. EventType is the dispatched event to build (e.g. MessageCreate) and PayloadType is the inner resource (e.g. Message). Use this macro for the simple cases so parse_event stays DRY, but keep custom logic in place for events that need extra parsing.\n\n\n\n\n\n","title":"Accord.@wrap_resource_event"},{"category":"section","location":"cookbook/#cookbook-index","page":"Accord.jl Cookbook","text":"Practical, copy-paste-ready recipes for building Discord bots in Julia with Accord.jl.","title":"Accord.jl Cookbook"},{"category":"section","location":"cookbook/#Prerequisites","page":"Accord.jl Cookbook","text":"Julia 1.11+ (download)\nDiscord bot token — create one at the Discord Developer Portal\nAccord.jl installed: ] add Accord\n\n","title":"Prerequisites"},{"category":"section","location":"cookbook/#Getting-Started","page":"Accord.jl Cookbook","text":"# Recipe What you'll build\n01 Your First Bot Hello world, ping/pong, intents, REPL mode\n02 Rich Messages Embeds, reactions, attachments, bulk operations","title":"Getting Started"},{"category":"section","location":"cookbook/#Interactions","page":"Accord.jl Cookbook","text":"# Recipe What you'll build\n03 Slash Commands Commands with options, autocomplete, subcommands\n04 Buttons, Selects & Modals Interactive components, ticket system workflow\n10 Polls Creating polls, listening for votes, ending early","title":"Interactions"},{"category":"section","location":"cookbook/#Advanced-Features","page":"Accord.jl Cookbook","text":"# Recipe What you'll build\n05 Voice Playback, recording, transcription\n06 Permissions Computing permissions, @check guards, private channels\n07 Caching Cache strategies, per-resource config, memory tips\n08 Sharding Multi-shard bots for 2,500+ guilds\n09 Auto-Moderation Keyword filters, spam protection, alert channels","title":"Advanced Features"},{"category":"section","location":"cookbook/#Production","page":"Accord.jl Cookbook","text":"# Recipe What you'll build\n11 Architectural Patterns Project structure, middleware, @check guards, wait_for, state injection\n12 Performance Type stability, precompilation, async patterns\n13 Deployment Systemd, Docker, sysimages, health checks\n14 Troubleshooting Common errors, debug logging, gateway issues","title":"Production"},{"category":"section","location":"cookbook/#Advocacy-and-Capstone","page":"Accord.jl Cookbook","text":"# Recipe What you'll build\n15 Why Julia for Discord Bots? Performance, multiple dispatch, scientific computing\n16 AI Agent Bot LLM integration, streaming, tool use, memory","title":"Advocacy & Capstone"},{"category":"section","location":"cookbook/10-polls/#Recipe-10-—-Polls","page":"Polls","text":"Difficulty: Beginner What you will build: Discord-native polls with vote tracking, result checking, and early endings.\n\nPrerequisites: Recipe 01, Recipe 03\n\n","title":"Recipe 10 — Polls"},{"category":"section","location":"cookbook/10-polls/#1.-How-Discord-Polls-Work","page":"Polls","text":"Polls are sent as part of a Message via the poll field. Users vote using Discord's native UI — no buttons needed.\n\nRequired intent for vote events:\n\nclient = Client(token;\n    intents = IntentGuilds | IntentGuildMessages | IntentGuildMessagePolls\n)","title":"1. How Discord Polls Work"},{"category":"section","location":"cookbook/10-polls/#2.-Creating-a-Poll","page":"Polls","text":"note: Poll Duration and Answer Limits\nDiscord imposes limits on polls:Duration: 1 to 336 hours (14 days maximum)\nAnswers: Maximum 10 answer choices per poll\nQuestion: Maximum 300 characters\nAnswer text: Maximum 55 characters\n\nPolls use the poll body in create_message:\n\nbody = Dict{String, Any}(\n    \"poll\" => Dict(\n        \"question\" => Dict(\"text\" => \"What's your favorite language?\"),\n        \"answers\" => [\n            Dict(\"answer_id\" => 1, \"poll_media\" => Dict(\"text\" => \"Julia\")),\n            Dict(\"answer_id\" => 2, \"poll_media\" => Dict(\"text\" => \"Python\")),\n            Dict(\"answer_id\" => 3, \"poll_media\" => Dict(\"text\" => \"Rust\")),\n            Dict(\"answer_id\" => 4, \"poll_media\" => Dict(\"text\" => \"Other\")),\n        ],\n        \"duration\" => 24,            # hours (1-336, max 14 days)\n        \"allow_multiselect\" => false, # single choice\n        \"layout_type\" => 1,           # DEFAULT layout\n    )\n)\n\ncreate_message(client, channel_id; poll=body[\"poll\"])","title":"2. Creating a Poll"},{"category":"section","location":"cookbook/10-polls/#Poll-with-Emoji","page":"Polls","text":"Dict(\n    \"poll\" => Dict(\n        \"question\" => Dict(\"text\" => \"Pick a fruit\"),\n        \"answers\" => [\n            Dict(\"answer_id\" => 1, \"poll_media\" => Dict(\"text\" => \"Apple\", \"emoji\" => Dict(\"name\" => \"🍎\"))),\n            Dict(\"answer_id\" => 2, \"poll_media\" => Dict(\"text\" => \"Banana\", \"emoji\" => Dict(\"name\" => \"🍌\"))),\n            Dict(\"answer_id\" => 3, \"poll_media\" => Dict(\"text\" => \"Cherry\", \"emoji\" => Dict(\"name\" => \"🍒\"))),\n        ],\n        \"duration\" => 1,\n        \"allow_multiselect\" => true,\n    )\n)","title":"Poll with Emoji"},{"category":"section","location":"cookbook/10-polls/#3.-Listening-for-Votes","page":"Polls","text":"Accord.on(client, [`MessagePollVoteAdd`](@ref)) do c, event\n    @info \"Vote added\" user=event.user_id message=event.message_id answer=event.answer_id\nend\n\nAccord.on(client, [`MessagePollVoteRemove`](@ref)) do c, event\n    @info \"Vote removed\" user=event.user_id message=event.message_id answer=event.answer_id\nend","title":"3. Listening for Votes"},{"category":"section","location":"cookbook/10-polls/#Track-Votes-in-Real-Time","page":"Polls","text":"# Simple in-memory vote tracker\nconst vote_counts = Dict{[`Snowflake`](@ref), Dict{Int, Int}}()  # message_id → answer_id → count\n\nAccord.on(client, [`MessagePollVoteAdd`](@ref)) do c, event\n    msg_votes = get!(vote_counts, event.message_id, Dict{Int, Int}())\n    msg_votes[event.answer_id] = get(msg_votes, event.answer_id, 0) + 1\nend\n\nAccord.on(client, MessagePollVoteRemove) do c, event\n    msg_votes = get!(vote_counts, event.message_id, Dict{Int, Int}())\n    msg_votes[event.answer_id] = max(0, get(msg_votes, event.answer_id, 0) - 1)\nend","title":"Track Votes in Real Time"},{"category":"section","location":"cookbook/10-polls/#4.-Getting-Poll-Results","page":"Polls","text":"# Get voters for a specific answer\nvoters = Accord.get_answer_voters(client, channel_id, message_id, 1;\n    limit=100)\n\n# voters is a Dict with \"users\" key\nfor user_data in voters[\"users\"]\n    @info \"Voter\" id=user_data[\"id\"] username=user_data[\"username\"]\nend","title":"4. Getting Poll Results"},{"category":"section","location":"cookbook/10-polls/#5.-Ending-a-Poll-Early","page":"Polls","text":"# End the poll and finalize results\nresult_msg = Accord.end_poll(client, channel_id, message_id)\n@info \"Poll ended\" message_id=result_msg.id","title":"5. Ending a Poll Early"},{"category":"section","location":"cookbook/10-polls/#6.-Practical-Example:-Poll-Bot-with-Slash-Commands","page":"Polls","text":"using Accord\n\ntoken = ENV[\"DISCORD_TOKEN\"]\nclient = Client(token;\n    intents = IntentGuilds | IntentGuildMessages | IntentGuildMessagePolls\n)\n\n# /poll \"Question?\" \"Option A\" \"Option B\" [\"Option C\"] [\"Option D\"]\noptions_poll = [\n    Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"question\", description=\"Poll question\", required=true),\n    Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"option1\", description=\"First option\", required=true),\n    Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"option2\", description=\"Second option\", required=true),\n    Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"option3\", description=\"Third option\"),\n    Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"option4\", description=\"Fourth option\"),\n    Accord.command_option(type=ApplicationCommandOptionTypes.INTEGER, name=\"hours\", description=\"Duration in hours (default: 24)\", min_value=1, max_value=336),\n    Accord.command_option(type=ApplicationCommandOptionTypes.BOOLEAN, name=\"multiselect\", description=\"Allow multiple votes?\"),\n]\n\n@slash_command client \"poll\" \"Create a poll\" options_poll function(ctx)\n    question = Accord.get_option(ctx, \"question\", \"\")\n    opt1 = Accord.get_option(ctx, \"option1\", \"\")\n    opt2 = Accord.get_option(ctx, \"option2\", \"\")\n    opt3 = Accord.get_option(ctx, \"option3\", nothing)\n    opt4 = Accord.get_option(ctx, \"option4\", nothing)\n    hours = Accord.get_option(ctx, \"hours\", 24)\n    multi = Accord.get_option(ctx, \"multiselect\", false)\n\n    answers = [\n        Dict(\"answer_id\" => 1, \"poll_media\" => Dict(\"text\" => opt1)),\n        Dict(\"answer_id\" => 2, \"poll_media\" => Dict(\"text\" => opt2)),\n    ]\n    !isnothing(opt3) && push!(answers, Dict(\"answer_id\" => 3, \"poll_media\" => Dict(\"text\" => opt3)))\n    !isnothing(opt4) && push!(answers, Dict(\"answer_id\" => 4, \"poll_media\" => Dict(\"text\" => opt4)))\n\n    # Create the poll in the channel\n    channel_id = ctx.interaction.channel_id\n    body = Dict{String, Any}(\n        \"poll\" => Dict(\n            \"question\" => Dict(\"text\" => question),\n            \"answers\" => answers,\n            \"duration\" => hours,\n            \"allow_multiselect\" => multi,\n            \"layout_type\" => 1,\n        )\n    )\n\n    Accord.defer(ctx)\n    create_message(ctx.client, channel_id; poll=body[\"poll\"])\n    Accord.respond(ctx; content=\"Poll created!\", ephemeral=true)\nend\n\n# /endpoll <message_id>\noptions_end = [\n    Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"message_id\", description=\"Message ID of the poll\", required=true),\n]\n\n@slash_command client \"endpoll\" \"End a poll early\" options_end function(ctx)\n    msg_id = Snowflake(Accord.get_option(ctx, \"message_id\", \"\"))\n    channel_id = ctx.interaction.channel_id\n\n    Accord.end_poll(ctx.client, channel_id, msg_id)\n    Accord.respond(ctx; content=\"Poll ended!\", ephemeral=true)\nend\n\n# Vote tracking\nAccord.on(client, MessagePollVoteAdd) do c, event\n    @info \"Vote\" user=event.user_id answer=event.answer_id message=event.message_id\nend\n\nAccord.on(client, [`ReadyEvent`](@ref)) do c, event\n    sync_commands!(c, c.command_tree)\n    @info \"Poll bot ready!\"\nend\n\nAccord.start(client)\n\n\n\nNext steps: Recipe 11 — Architectural Patterns for structuring a production bot.","title":"6. Practical Example: Poll Bot with Slash Commands"},{"category":"section","location":"diagnostics/#Elm-like-Diagnostics","page":"Diagnostics","text":"Accord.jl takes inspiration from the Elm programming language's philosophy: Error messages should be helpful, friendly, and didactic.\n\nInstead of dumping a raw stacktrace or a cryptic JSON error code, Accord.jl attempts to intercept common failure modes and present them in a structured, readable format.","title":"Elm-like Diagnostics"},{"category":"section","location":"diagnostics/#The-\"Double-Pareto\"-Philosophy","page":"Diagnostics","text":"The Discord API defines hundreds of error codes. However, based on our analysis, 99% of developer support tickets stem from fewer than 30 specific errors.\n\nAccord.jl implements a \"Double-Pareto\" strategy:\n\nIdentify the Top 30 Errors (The 20% of errors causing 80% of pain).\nProvide Top-Tier Diagnostics for these specific cases.\nFallback to Standard Errors for the long tail of rare edge cases.\n\nThis ensures the library remains lightweight while maximizing developer experience (DX) where it matters most.","title":"The \"Double-Pareto\" Philosophy"},{"category":"section","location":"diagnostics/#Matcher-Categories","page":"Diagnostics","text":"","title":"Matcher Categories"},{"category":"section","location":"diagnostics/#1.-Setup-and-Configuration-(Startup)","page":"Diagnostics","text":"These errors occur before the bot even connects.\n\nError Code Explanation\nMissing Token N/A Token string is empty.\nInvalid Token N/A Token contains spaces or newlines.\nDisallowed Intents 4014 Gateway connection refused due to privileged intent mismatch.\nAuthentication Failed 4004 Token is invalid or expired.\nSharding Config N/A Mismatch between num_shards and Gateway recommendation.","title":"1. Setup & Configuration (Startup)"},{"category":"section","location":"diagnostics/#2.-Runtime-and-API-(Interaction)","page":"Diagnostics","text":"These errors occur while the bot is running, usually due to permissions or logic.\n\nError Code Explanation\nMissing Permissions 50013 Bot lacks permission to perform action (e.g., Ban).\nUnknown Channel 10003 Sending message to a deleted channel.\nUnknown Message 10008 Editing/Deleting a non-existent message.\nUnknown Interaction 10062 Interaction token expired (taken >3s to respond).\nRate Limit 429 Global or bucket rate limit exceeded.\nInvalid Form Body 50035 Validation error (e.g., Embed too big, Malformed payload).\nEmpty Message 50006 Sending a message with no content/embeds.","title":"2. Runtime & API (Interaction)"},{"category":"section","location":"diagnostics/#3.-Development-and-Logic","page":"Diagnostics","text":"These are detected via static analysis hooks or runtime checks.\n\nBlocking Event Loop: (Planned) Detects long-running blocking calls in async handlers.\nHandler Arity: (Planned) Detects incorrect arguments for @on_message.","title":"3. Development & Logic"},{"category":"section","location":"diagnostics/#Example-Output","page":"Diagnostics","text":"When a diagnostic is triggered, Accord.jl prints a box like this:\n\n┌── MISSING PRIVILEGED INTENT ───────────────────────────────┐\n│                                                            │\n│  I cannot access `message.content` because the             │\n│  Message Content Intent is missing.                        │\n│                                                            │\n│   > defined at bot.jl:14                                   │\n│                                                            │\n│   14 |   if message.content == \"!ping\"                     │\n│                     ^^^^^^^                                │\n│                                                            │\n│  Explanation:                                              │\n│  Discord does not send message content unless the          │\n│  privileged intent is enabled in both the Developer        │\n│  Portal and your Client config.                            │\n│                                                            │\n│  Fix:                                                      │\n│  1. Enable \"Message Content Intent\" in Dev Portal.         │\n│  2. Add `intents=IntentMessageContent` to Client().        │\n│                                                            │\n│  Docs: https://manelsen.github.io/Accord.jl/dev/intents    │\n│                                                            │\n└────────────────────────────────────────────────────────────┘","title":"Example Output"},{"category":"section","location":"diagnostics/#API-Reference","page":"Diagnostics","text":"","title":"API Reference"},{"category":"type","location":"diagnostics/#Accord.Diagnoser.Diagnostic","page":"Diagnostics","text":"Diagnostic\n\nA structured error report used to present friendly, Elm-like diagnostics to the user.\n\n\n\n\n\n","title":"Accord.Diagnoser.Diagnostic"},{"category":"function","location":"diagnostics/#Accord.Diagnoser.report","page":"Diagnostics","text":"report(exception, stacktone)\n\nThe main entry point for reporting errors. It attempts to diagnose the exception and print a friendly box. If no diagnosis is found, it falls back to standard Julia standard error.\n\n\n\n\n\n","title":"Accord.Diagnoser.report"},{"category":"section","location":"cookbook/01-basic-bot/#Recipe-01-—-Your-First-Bot","page":"Your First Bot","text":"Difficulty: Beginner What you will build: A Discord bot that responds to messages, measures latency, and runs interactively in the REPL.\n\n","title":"Recipe 01 — Your First Bot"},{"category":"section","location":"cookbook/01-basic-bot/#1.-Project-Setup","page":"Your First Bot","text":"# Create a new project\nmkdir MyBot && cd MyBot\njulia --project=. -e 'using Pkg; Pkg.add(\"Accord\")'\n\nYour Project.toml now tracks Accord.jl as a dependency.","title":"1. Project Setup"},{"category":"section","location":"cookbook/01-basic-bot/#2.-Token-Management","page":"Your First Bot","text":"tip: Token Security\nNever commit your Discord token to version control. Create a .env file and add it to .gitignore immediately.\n\n# .env\nDISCORD_TOKEN=Bot MTIzNDU2Nzg5MDEyMzQ1Njc4OQ.XXXXXX.XXXXXXXXXXXXXXXXXXXXXXXX\n\n# .gitignore\n.env\nManifest.toml\n\nLoad it in your bot:\n\n# Load token from environment\nfunction load_env(path=\".env\")\n    isfile(path) || return\n    for line in eachline(path)\n        stripped = strip(line)\n        (isempty(stripped) || startswith(stripped, '#')) && continue\n        key, value = split(stripped, '='; limit=2)\n        ENV[strip(key)] = strip(value)\n    end\nend\n\nload_env()\ntoken = ENV[\"DISCORD_TOKEN\"]","title":"2. Token Management"},{"category":"section","location":"cookbook/01-basic-bot/#3.-Hello-World-Bot","page":"Your First Bot","text":"using Accord\n\nload_env()  # from above\ntoken = ENV[\"DISCORD_TOKEN\"]\n\n# Create client with specific intents\nclient = Client(token;\n    intents = IntentGuilds | IntentGuildMessages | IntentMessageContent\n)\n\n!!! note \"Intents\"\n    Gateway intents control which events your bot receives. You must declare both [`IntentGuildMessages`](@ref) (for message events) and [`IntentMessageContent`](@ref) (to read actual message text). Without these, your bot won't see message content!\n\n# Log when connected\nAccord.on(client, [`ReadyEvent`](@ref)) do c, event\n    @info \"Bot online!\" user=event.user.username guilds=length(event.guilds)\nend\n\n# Respond to messages\nAccord.on(client, [`MessageCreate`](@ref)) do c, event\n    msg = event.message\n    ismissing(msg.author) && return\n    ismissing(msg.content) && return\n    !ismissing(msg.author.bot) && msg.author.bot == true && return\n\n    if msg.content == \"!hello\"\n        create_message(c, msg.channel_id; content=\"Hello from Accord.jl!\")\n    end\nend\n\nAccord.start(client)\n\nRun it:\n\njulia --project=. bot.jl","title":"3. Hello World Bot"},{"category":"section","location":"cookbook/01-basic-bot/#4.-Ping/Pong-with-Latency","page":"Your First Bot","text":"Accord.on(client, MessageCreate) do c, event\n    msg = event.message\n    ismissing(msg.author) && return\n    ismissing(msg.content) && return\n    !ismissing(msg.author.bot) && msg.author.bot == true && return\n\n    if msg.content == \"!ping\"\n        t_start = time()\n        sent = create_message(c, msg.channel_id; content=\"Pong!\")\n        latency_ms = round(Int, (time() - t_start) * 1000)\n\n        e = Accord.embed(\n            title=\"Pong!\",\n            description=\"Round-trip latency: **$(latency_ms) ms**\",\n            color=0x57F287  # green\n        )\n        edit_message(c, msg.channel_id, sent.id; embeds=[e])\n    end\nend","title":"4. Ping/Pong with Latency"},{"category":"section","location":"cookbook/01-basic-bot/#5.-Understanding-Intents","page":"Your First Bot","text":"Intents control which events your bot receives. Combine them with |:\n\nclient = Client(token;\n    intents = IntentGuilds | IntentGuildMessages | IntentMessageContent\n)","title":"5. Understanding Intents"},{"category":"section","location":"cookbook/01-basic-bot/#Intent-Reference","page":"Your First Bot","text":"Intent Bit Privileged Events\nIntentGuilds 0 No GuildCreate, GuildUpdate, GuildDelete, channels, roles\nIntentGuildMembers 1 Yes GuildMemberAdd/Remove/Update\nIntentGuildModeration 2 No GuildBanAdd/Remove, GuildAuditLogEntryCreate\nIntentGuildExpressions 3 No GuildEmojisUpdate, GuildStickersUpdate\nIntentGuildIntegrations 4 No IntegrationCreate/Update/Delete\nIntentGuildWebhooks 5 No WebhooksUpdate\nIntentGuildInvites 6 No InviteCreate/Delete\nIntentGuildVoiceStates 7 No VoiceStateUpdateEvent\nIntentGuildPresences 8 Yes PresenceUpdate\nIntentGuildMessages 9 No MessageCreate/Update/Delete in guilds\nIntentGuildMessageReactions 10 No MessageReactionAdd/Remove\nIntentGuildMessageTyping 11 No TypingStart\nIntentDirectMessages 12 No MessageCreate/Update/Delete in DMs\nIntentDirectMessageReactions 13 No MessageReactionAdd/Remove in DMs\nIntentDirectMessageTyping 14 No TypingStart in DMs\nIntentMessageContent 15 Yes Populates message.content, embeds, attachments\nIntentGuildScheduledEvents 16 No ScheduledEvent events\nIntentAutoModerationConfiguration 20 No AutoModerationRuleCreate/Update/Delete\nIntentAutoModerationExecution 21 No AutoModerationActionExecution\nIntentGuildMessagePolls 24 No MessagePollVoteAdd/Remove\nIntentDirectMessagePolls 25 No MessagePollVoteAdd/Remove in DMs\n\nPrivileged intents must be enabled in the Discord Developer Portal under Bot > Privileged Gateway Intents.\n\nwarning: MESSAGE_CONTENT Intent Required\nAs of 2022, Discord requires the privileged IntentMessageContent intent to receive message content. Without this intent, message.content will be empty or missing. You must enable this in the Developer Portal AND pass it in the Client constructor.\n\nShortcuts:\n\nIntentAllNonPrivileged and IntentAll:\n\nIntentAllNonPrivileged  # all non-privileged intents (default)\nIntentAll               # all intents including privileged","title":"Intent Reference"},{"category":"section","location":"cookbook/01-basic-bot/#6.-Non-Blocking-Mode-(REPL-Development)","page":"Your First Bot","text":"Start the bot without blocking your REPL:\n\nAccord.start(client; blocking=false)\n\n# Now you can interact with the client live:\nwait_until_ready(client)\n@info \"Bot user: $(client.state.me.username)\"\n\n# Send a message from the REPL\ncreate_message(client, [`Snowflake`](@ref)(123456789); content=\"Hello from the REPL!\")\n\n# Inspect cached state\n@info \"Guilds cached: $(length(client.state.guilds))\"\n\nThis is extremely useful during development — you get a live REPL connected to Discord.","title":"6. Non-Blocking Mode (REPL Development)"},{"category":"section","location":"cookbook/01-basic-bot/#7.-Graceful-Shutdown","page":"Your First Bot","text":"# Stop the client cleanly\nAccord.stop(client)\n\nIn blocking mode, pressing Ctrl+C triggers a graceful shutdown automatically.","title":"7. Graceful Shutdown"},{"category":"section","location":"cookbook/01-basic-bot/#8.-Handling-Multiple-Events","page":"Your First Bot","text":"You can register multiple handlers for the same event:\n\n# Analytics handler\nAccord.on(client, [`MessageCreate`](@ref)) do c, event\n    @debug \"Message received\" channel=event.message.channel_id\nend\n\n# Command handler (both run independently)\nAccord.on(client, [`MessageCreate`](@ref)) do c, event\n    msg = event.message\n    ismissing(msg.content) && return\n    msg.content == \"!ping\" && create_message(c, msg.channel_id; content=\"Pong!\")\nend\n\n# Catch-all: log every event type\nAccord.on(client, [`AbstractEvent`](@ref)) do c, event\n    @debug \"Event\" type=typeof(event)\nend","title":"8. Handling Multiple Events"},{"category":"section","location":"cookbook/01-basic-bot/#9.-Logging-Guild-Activity","page":"Your First Bot","text":"Accord.on(client, [`GuildCreate`](@ref)) do c, event\n    @info \"Guild available\" name=event.guild.name id=event.guild.id\nend\n\nAccord.on(client, [`GuildMemberAdd`](@ref)) do c, event\n    @info \"Member joined\" guild_id=event.guild_id\n    # Note: requires IntentGuildMembers (privileged)\nend\n\n","title":"9. Logging Guild Activity"},{"category":"section","location":"cookbook/01-basic-bot/#Complete-Example","page":"Your First Bot","text":"using Accord\n\n# Load token\ntoken = get(ENV, \"DISCORD_TOKEN\", \"\")\nisempty(token) && error(\"Set DISCORD_TOKEN environment variable\")\n\nclient = Client(token;\n    intents = IntentGuilds | IntentGuildMessages | IntentMessageContent\n)\n\nAccord.on(client, ReadyEvent) do c, event\n    @info \"Bot online!\" user=event.user.username guilds=length(event.guilds)\nend\n\nAccord.on(client, MessageCreate) do c, event\n    msg = event.message\n    ismissing(msg.author) && return\n    ismissing(msg.content) && return\n    !ismissing(msg.author.bot) && msg.author.bot == true && return\n\n    if msg.content == \"!ping\"\n        t = time()\n        sent = create_message(c, msg.channel_id; content=\"Pinging...\")\n        ms = round(Int, (time() - t) * 1000)\n        edit_message(c, msg.channel_id, sent.id;\n            content=\"Pong! Latency: **$(ms) ms**\")\n    elseif msg.content == \"!info\"\n        e = Accord.embed(\n            title=\"Bot Info\",\n            color=0x5865F2,\n            fields=[\n                Dict(\"name\" => \"Library\", \"value\" => \"Accord.jl\", \"inline\" => true),\n                Dict(\"name\" => \"Julia\", \"value\" => string(VERSION), \"inline\" => true),\n            ]\n        )\n        create_message(c, msg.channel_id; embeds=[e])\n    end\nend\n\nAccord.on(client, GuildCreate) do c, event\n    @info \"Guild available\" name=event.guild.name id=event.guild.id\nend\n\n@info \"Starting bot...\"\nAccord.start(client)\n\n\n\nNext steps: Recipe 02 — Rich Messages to learn about embeds, reactions, and file attachments.","title":"Complete Example"},{"category":"section","location":"cookbook/15-why-julia/#Recipe-15-—-Why-Julia-for-Discord-Bots?","page":"Why Julia?","text":"Difficulty: Conceptual What you will learn: Why Julia is a compelling alternative to Python for building Discord bots, with honest trade-offs.\n\n","title":"Recipe 15 — Why Julia for Discord Bots?"},{"category":"section","location":"cookbook/15-why-julia/#1.-The-Phoenix-Moment","page":"Why Julia?","text":"When the Elixir community built Phoenix, many PHP developers skeptically asked \"why would I switch?\" — then they experienced real concurrency, pattern matching, and fault tolerance. The answer became obvious.\n\nJulia offers a similar leap for Python bot developers: not just incremental improvement, but fundamentally different capabilities.","title":"1. The Phoenix Moment"},{"category":"section","location":"cookbook/15-why-julia/#2.-Performance:-No-GIL,-Real-Parallelism","page":"Why Julia?","text":"note: True Parallelism Without the GIL\nUnlike Python's Global Interpreter Lock (GIL) which prevents true parallelism, Julia has no GIL. CPU-bound tasks can run on multiple threads simultaneously, making Julia ideal for bots that perform computations, data processing, or ML inference.\n\nPython's Global Interpreter Lock (GIL) means your bot is single-threaded, no matter how many cores your server has. Julia has no GIL.\n\n# Julia: true parallel execution\nAccord.on(client, [`MessageCreate`](@ref)) do c, event\n    Threads.@spawn begin\n        # This runs on a separate thread — truly parallel\n        result = heavy_computation(event.message.content)\n        [`create_message`](@ref)(c, event.message.channel_id; content=result)\n    end\nend\n\n# Python: GIL prevents true parallelism\n@bot.event\nasync def on_message(message):\n    # asyncio is concurrent but NOT parallel\n    # CPU-bound work blocks the entire event loop\n    result = heavy_computation(message.content)  # blocks everything\n    await message.channel.send(result)\n\nStart Julia with --threads=auto and every CPU core works for your bot.","title":"2. Performance: No GIL, Real Parallelism"},{"category":"section","location":"cookbook/15-why-julia/#Benchmark:-Fibonacci(40)","page":"Why Julia?","text":"Language Time Notes\nPython (CPython) ~45s GIL prevents threading\nPython (asyncio) ~45s asyncio doesn't help CPU work\nJulia ~0.5s JIT-compiled, type-inferred\nJulia (4 threads) ~0.15s True parallelism","title":"Benchmark: Fibonacci(40)"},{"category":"section","location":"cookbook/15-why-julia/#3.-Multiple-Dispatch:-Type-Based-Event-Routing","page":"Why Julia?","text":"Accord.jl uses Julia's type system for event dispatch — no string matching or decorator chains:\n\n# Julia: the type system IS the routing\nAccord.on(client, [`MessageCreate`](@ref)) do c, event\n    # Only called for MessageCreate events\nend\n\nAccord.on(client, [`GuildMemberAdd`](@ref)) do c, event\n    # Only called for GuildMemberAdd events\nend\n\n# Even cache updates use dispatch:\n[`update_state!`](@ref)(state, event::[`GuildCreate`](@ref))    # handles guild creation\n[`update_state!`](@ref)(state, event::[`ChannelDelete`](@ref))  # handles channel deletion\n[`update_state!`](@ref)(state, event::[`AbstractEvent`](@ref))  # fallback\n\n# Python: string-based routing with decorators\n@bot.event\nasync def on_message(message):      # string \"on_message\" → function\n    pass\n\n@bot.event\nasync def on_member_join(member):   # string \"on_member_join\" → function\n    pass\n\nMultiple dispatch means you can extend behavior without modifying existing code — fundamental to Julia's design.","title":"3. Multiple Dispatch: Type-Based Event Routing"},{"category":"section","location":"cookbook/15-why-julia/#4.-Type-Safety","page":"Why Julia?","text":"Accord.jl catches bugs at compile time that Python misses at runtime:\n\n# Snowflake: can't accidentally pass a string where an ID is needed\nchannel_id = [`Snowflake`](@ref)(123456789012345678)\n[`create_message`](@ref)(client, channel_id; content=\"typed!\")\n\n# Permission flags: bitfield type prevents integer mistakes\nperms = [`PermSendMessages`](@ref) | [`PermEmbedLinks`](@ref)\n[`has_flag`](@ref)(perms, [`PermAdministrator`](@ref))  # false — type-safe check\n\n# Accord.Optional{T}: explicit handling of missing fields\nif !ismissing(msg.content)\n    # content is guaranteed to be String here\n    process(msg.content)\nend","title":"4. Type Safety"},{"category":"section","location":"cookbook/15-why-julia/#5.-Scientific-Computing-Integration-(The-Killer-Feature)","page":"Why Julia?","text":"This is where Julia truly separates from Python. No FFI, no subprocess calls — first-class scientific computing in the same language as your bot:","title":"5. Scientific Computing Integration (The Killer Feature)"},{"category":"section","location":"cookbook/15-why-julia/#Machine-Learning-Bot","page":"Why Julia?","text":"using Accord\nusing Flux  # Julia's ML framework\n\n# Load a trained model\nmodel = Chain(Dense(784, 128, relu), Dense(128, 10), softmax)\n# ... load weights ...\n\n@slash_command client \"classify\" \"Classify a digit\" function(ctx)\n    # Get attached image, preprocess, run inference\n    # All in pure Julia — no Python subprocess needed\n    img = load_image(attachment_url)\n    prediction = Flux.onecold(model(img))\n    [`respond`](@ref)(ctx; content=\"I think that's a **$prediction**!\")\nend","title":"Machine Learning Bot"},{"category":"section","location":"cookbook/15-why-julia/#Chart-Bot","page":"Why Julia?","text":"using Accord\nusing CairoMakie  # publication-quality plots\n\n@slash_command client \"chart\" \"Generate a chart\" function(ctx)\n    [`defer`](@ref)(ctx)\n\n    fig = Figure(size=(800, 400))\n    ax = Axis(fig[1,1], title=\"Server Activity\")\n    barplot!(ax, 1:7, rand(7), color=:steelblue)\n\n    # Save to buffer and send\n    io = IOBuffer()\n    save(io, fig; pt_per_unit=1)\n    [`respond`](@ref)(ctx; content=\"Here's your chart:\", files=[(\"chart.png\", take!(io))])\nend","title":"Chart Bot"},{"category":"section","location":"cookbook/15-why-julia/#Scientific-Computing-Bot","page":"Why Julia?","text":"using Accord\nusing DifferentialEquations  # world-class ODE solvers\n\noptions_simulate = [\n    [`command_option`](@ref)(type=ApplicationCommandOptionTypes.NUMBER, name=\"rate\", description=\"Growth rate\", required=true),\n]\n\n@slash_command client \"simulate\" \"Simulate a system\" options_simulate function(ctx)\n    [`defer`](@ref)(ctx)\n    rate = [`get_option`](@ref)(ctx, \"rate\", 1.0)::Number\n\n    # Solve an ODE — in the same process as the bot\n    f(u, p, t) = rate * u\n    prob = ODEProblem(f, 1.0, (0.0, 5.0))\n    sol = solve(prob)\n\n    [`respond`](@ref)(ctx; content=\"Final value at t=5: **$(round(sol.u[end], digits=3))**\")\nend\n\nIn Python, you'd need subprocess calls to Julia/R/MATLAB or complex FFI bindings. In Julia, it's all native.","title":"Scientific Computing Bot"},{"category":"section","location":"cookbook/15-why-julia/#6.-REPL-Driven-Development","page":"Why Julia?","text":"Non-blocking mode gives you a live REPL connected to Discord:\n\nAccord.start(client; blocking=false)\n[`wait_until_ready`](@ref)(client)\n\n# Test things live:\n[`create_message`](@ref)(client, [`Snowflake`](@ref)(ch_id); content=\"Testing!\")\n\n# Inspect state:\nclient.state.me.username\nlength(client.state.guilds)\n\n# Hot-reload handlers (just redefine):\nAccord.on(client, [`MessageCreate`](@ref)) do c, event\n    # This replaces the previous handler\n    @info \"New handler!\" content=event.message.content\nend\n\nNo restart cycle. No waiting for reconnection. Change code and see results instantly.","title":"6. REPL-Driven Development"},{"category":"section","location":"cookbook/15-why-julia/#7.-Package-Management","page":"Why Julia?","text":"Julia's built-in package manager is simple and reproducible:\n\n# Project.toml — declares dependencies\n[deps]\nAccord = \"xxx-xxx\"\nHTTP = \"...\"\n\n# Manifest.toml — exact resolved versions (auto-generated)\n# Committed for reproducible builds\n\nNo virtualenv, no pip freeze, no requirements.txt vs setup.py vs pyproject.toml confusion. One system, always works.","title":"7. Package Management"},{"category":"section","location":"cookbook/15-why-julia/#8.-Honest-Trade-Offs","page":"Why Julia?","text":"Julia isn't perfect for every use case. Here's what to expect:","title":"8. Honest Trade-Offs"},{"category":"section","location":"cookbook/15-why-julia/#JIT-Compilation-Latency-(Time-to-First-X)","page":"Why Julia?","text":"First bot startup takes 10-15 seconds as Julia compiles code. Mitigations:\n\nPackageCompiler.jl sysimage reduces this to ~1 second (see Recipe 13)\nSubsequent event handling is near-instant\nIn production, startup time is negligible (bot runs for weeks/months)","title":"JIT Compilation Latency (Time-to-First-X)"},{"category":"section","location":"cookbook/15-why-julia/#Smaller-Ecosystem","page":"Why Julia?","text":"Feature Python (discord.py) Julia (Accord.jl)\nLibrary maturity 8+ years New\nStackOverflow answers Thousands Few\nThird-party extensions Many (cogs, utils) Build your own\nDocumentation Extensive This cookbook!","title":"Smaller Ecosystem"},{"category":"section","location":"cookbook/15-why-julia/#Learning-Curve","page":"Why Julia?","text":"If your team only knows Python, there's a learning curve. Key differences:\n\n1-indexed arrays\nmissing vs nothing vs undef\nMultiple dispatch instead of classes\nMacros (powerful but unfamiliar)","title":"Learning Curve"},{"category":"section","location":"cookbook/15-why-julia/#9.-Migration-Guide:-discord.py-Accord.jl","page":"Why Julia?","text":"","title":"9. Migration Guide: discord.py → Accord.jl"},{"category":"section","location":"cookbook/15-why-julia/#Client-Setup","page":"Why Julia?","text":"# discord.py\nimport discord\nbot = discord.Bot(intents=discord.Intents.default())\n\n# Accord.jl\nusing Accord\nclient = [`Client`](@ref)(token; intents=[`IntentAllNonPrivileged`](@ref))","title":"Client Setup"},{"category":"section","location":"cookbook/15-why-julia/#Event-Handlers","page":"Why Julia?","text":"# discord.py\n@bot.event\nasync def on_message(message):\n    if message.content == \"!ping\":\n        await message.channel.send(\"Pong!\")\n\n# Accord.jl\nAccord.on(client, [`MessageCreate`](@ref)) do c, event\n    msg = event.message\n    ismissing(msg.content) && return\n    msg.content == \"!ping\" && [`create_message`](@ref)(c, msg.channel_id; content=\"Pong!\")\nend","title":"Event Handlers"},{"category":"section","location":"cookbook/15-why-julia/#Slash-Commands","page":"Why Julia?","text":"# discord.py\n@bot.slash_command()\nasync def greet(ctx, name: str):\n    await ctx.respond(f\"Hello, {name}!\")\n\n# Accord.jl\ntree = [`CommandTree`](@ref)()\n[`register_command!`](@ref)(tree, \"greet\", \"Say hello\", function(ctx)\n    name = [`get_option`](@ref)(ctx, \"name\", \"World\")\n    [`respond`](@ref)(ctx; content=\"Hello, $name!\")\nend; options=[\n    [`command_option`](@ref)(type=ApplicationCommandOptionTypes.STRING, name=\"name\", description=\"Name\", required=true),\n])","title":"Slash Commands"},{"category":"section","location":"cookbook/15-why-julia/#Embeds","page":"Why Julia?","text":"# discord.py\nembed = discord.Embed(title=\"Info\", color=0x5865F2)\nembed.add_field(name=\"Field\", value=\"Value\")\nawait ctx.send(embed=embed)\n\n# Accord.jl\ne = [`embed`](@ref)(title=\"Info\", color=0x5865F2, fields=[\n    Dict(\"name\" => \"Field\", \"value\" => \"Value\"),\n])\n[`create_message`](@ref)(client, channel_id; embeds=[e])","title":"Embeds"},{"category":"section","location":"cookbook/15-why-julia/#Permissions","page":"Why Julia?","text":"# discord.py\n@bot.command()\n@commands.has_permissions(ban_members=True)\nasync def ban(ctx, member):\n    await member.ban()\n\n# Accord.jl\n[`register_command!`](@ref)(tree, \"ban\", \"Ban a user\", function(ctx)\n    perms = get_member_permissions(ctx.client, ctx.interaction.guild_id, ctx.interaction.member.user.id)\n    [`has_flag`](@ref)(perms, [`PermBanMembers`](@ref)) || return [`respond`](@ref)(ctx; content=\"No permission\", ephemeral=true)\n    # ... ban logic\nend)","title":"Permissions"},{"category":"section","location":"cookbook/15-why-julia/#10.-When-to-Choose-Julia","page":"Why Julia?","text":"Choose Julia when:\n\nYou need real computational power (ML, scientific computing, data processing)\nYou want true parallelism without the GIL\nYou value type safety and multiple dispatch\nYour bot generates charts, runs simulations, or processes data\nYou're already in the Julia ecosystem\n\nStick with Python when:\n\nYou need maximum community support and tutorials\nYour bot is purely CRUD with no computation\nYour team only knows Python and learning Julia isn't feasible\nYou need specific discord.py extensions with no Julia equivalent\n\n\n\nNext steps: Recipe 16 — AI Agent Bot to build the ultimate showcase: an LLM-powered Discord bot in Julia.","title":"10. When to Choose Julia"},{"category":"section","location":"cookbook/09-automod/#Recipe-09-—-Auto-Moderation","page":"Auto-Moderation","text":"Difficulty: Intermediate What you will build: Keyword filters, spam protection, mention limits, and alert channels using Discord's Auto-Moderation system.\n\nPrerequisites: Recipe 01, Recipe 03\n\n","title":"Recipe 09 — Auto-Moderation"},{"category":"section","location":"cookbook/09-automod/#1.-How-Auto-Moderation-Works","page":"Auto-Moderation","text":"note: AutoMod Rule Limits\nDiscord limits guilds to:6 keyword rules per guild (keyword filter + keyword preset combined)\n1 spam rule per guild\n1 mention spam rule per guildPlan your moderation strategy accordingly. Combine similar keywords into single rules rather than creating many small rules.\n\nDiscord's AutoMod system lets you create rules that automatically act on messages:\n\nTrigger — what to look for (keywords, spam, mention spam, presets)\nAction — what to do (block message, send alert, timeout user)\nExemptions — roles/channels that bypass the rule\n\nYour bot needs these Intents:\n\nclient = Client(token;\n    intents = IntentGuilds | IntentAutoModerationConfiguration | IntentAutoModerationExecution\n)","title":"1. How Auto-Moderation Works"},{"category":"section","location":"cookbook/09-automod/#2.-Trigger-Types","page":"Auto-Moderation","text":"Type Constant Description\nKeyword AutoModTriggerTypes.KEYWORD (1) Match custom keywords/regex\nSpam AutoModTriggerTypes.SPAM (3) Generic spam detection\nKeyword Preset AutoModTriggerTypes.KEYWORD_PRESET (4) Discord's built-in word lists\nMention Spam AutoModTriggerTypes.MENTION_SPAM (5) Too many mentions\nMember Profile AutoModTriggerTypes.MEMBER_PROFILE (6) Profile content match","title":"2. Trigger Types"},{"category":"section","location":"cookbook/09-automod/#3.-Action-Types","page":"Auto-Moderation","text":"Type Constant Description\nBlock Message AutoModActionTypes.BLOCK_MESSAGE (1) Prevent the message from being sent\nSend Alert AutoModActionTypes.SEND_ALERT_MESSAGE (2) Send alert to a channel\nTimeout AutoModActionTypes.TIMEOUT (3) Timeout the user","title":"3. Action Types"},{"category":"section","location":"cookbook/09-automod/#4.-Creating-a-Keyword-Filter","page":"Auto-Moderation","text":"ALERT_CHANNEL = Snowflake(999999999999999999)\n\nbody = Dict(\n    \"name\" => \"Bad Words Filter\",\n    \"event_type\" => AutoModEventTypes.MESSAGE_SEND,\n    \"trigger_type\" => AutoModTriggerTypes.KEYWORD,\n    \"trigger_metadata\" => Dict(\n        \"keyword_filter\" => [\"badword1\", \"badword2\", \"*slur*\"],\n        \"regex_patterns\" => [\"b[a@]d\\\\s*w[o0]rd\"],  # regex support\n        \"allow_list\" => [\"badword1_but_ok\"],          # exceptions\n    ),\n    \"actions\" => [\n        Dict(\n            \"type\" => AutoModActionTypes.BLOCK_MESSAGE,\n            \"metadata\" => Dict(\n                \"custom_message\" => \"This message was blocked by AutoMod.\"\n            )\n        ),\n        Dict(\n            \"type\" => AutoModActionTypes.SEND_ALERT_MESSAGE,\n            \"metadata\" => Dict(\n                \"channel_id\" => string(ALERT_CHANNEL)\n            )\n        ),\n    ],\n    \"enabled\" => true,\n    \"exempt_roles\" => [],     # roles that bypass this rule\n    \"exempt_channels\" => [],  # channels that bypass this rule\n)\n\nrule = Accord.create_auto_moderation_rule(client, guild_id;\n    body=body)\n@info \"Created rule\" name=rule.name id=rule.id","title":"4. Creating a Keyword Filter"},{"category":"section","location":"cookbook/09-automod/#Keyword-Matching-Patterns","page":"Auto-Moderation","text":"Pattern Matches Doesn't Match\n\"test\" \"test\", \"testing\" \"atest\"\n\"*test\" \"atest\", \"test\" \"testa\"\n\"test*\" \"test\", \"testing\" \"atest\"\n\"*test*\" \"atest\", \"testing\", \"atesting\" —","title":"Keyword Matching Patterns"},{"category":"section","location":"cookbook/09-automod/#5.-Preset-Keyword-Lists","page":"Auto-Moderation","text":"Discord provides built-in word lists:\n\nbody = Dict(\n    \"name\" => \"Content Filter\",\n    \"event_type\" => AutoModEventTypes.MESSAGE_SEND,\n    \"trigger_type\" => AutoModTriggerTypes.KEYWORD_PRESET,\n    \"trigger_metadata\" => Dict(\n        \"presets\" => [\n            AutoModKeywordPresetTypes.PROFANITY,       # 1\n            AutoModKeywordPresetTypes.SEXUAL_CONTENT,   # 2\n            AutoModKeywordPresetTypes.SLURS,            # 3\n        ],\n        \"allow_list\" => [\"damn\", \"hell\"],  # words to allow despite presets\n    ),\n    \"actions\" => [\n        Dict(\"type\" => AutoModActionTypes.BLOCK_MESSAGE),\n    ],\n    \"enabled\" => true,\n)\n\nAccord.create_auto_moderation_rule(client, guild_id;\n    body=body)","title":"5. Preset Keyword Lists"},{"category":"section","location":"cookbook/09-automod/#6.-Mention-Spam-Protection","page":"Auto-Moderation","text":"Block messages with excessive mentions:\n\nbody = Dict(\n    \"name\" => \"Mention Spam Protection\",\n    \"event_type\" => AutoModEventTypes.MESSAGE_SEND,\n    \"trigger_type\" => AutoModTriggerTypes.MENTION_SPAM,\n    \"trigger_metadata\" => Dict(\n        \"mention_total_limit\" => 5,                    # max mentions per message\n        \"mention_raid_protection_enabled\" => true,     # enable raid protection\n    ),\n    \"actions\" => [\n        Dict(\"type\" => AutoModActionTypes.BLOCK_MESSAGE),\n        Dict(\n            \"type\" => AutoModActionTypes.TIMEOUT,\n            \"metadata\" => Dict(\n                \"duration_seconds\" => 300  # 5 minute timeout\n            )\n        ),\n    ],\n    \"enabled\" => true,\n)\n\nAccord.create_auto_moderation_rule(client, guild_id;\n    body=body)","title":"6. Mention Spam Protection"},{"category":"section","location":"cookbook/09-automod/#7.-Listening-for-AutoMod-Actions","page":"Auto-Moderation","text":"When an AutoModRule triggers, you get an AutoModerationActionExecution event:\n\nAccord.on(client, AutoModerationActionExecution) do c, event\n    @info \"AutoMod triggered\" rule_id=event.rule_id user_id=event.user_id\n\n    # event fields:\n    #   guild_id, action, rule_id, rule_trigger_type, user_id\n    #   channel_id, message_id, alert_system_message_id\n    #   content, matched_keyword, matched_content\n\n    if !ismissing(event.matched_keyword) && !ismissing(event.content)\n        @warn \"AutoMod match\" keyword=event.matched_keyword content=event.content user=event.user_id\n    end\nend","title":"7. Listening for AutoMod Actions"},{"category":"section","location":"cookbook/09-automod/#Custom-Alert-Embed","page":"Auto-Moderation","text":"Accord.on(client, AutoModerationActionExecution) do c, event\n    ALERT_CHANNEL = Snowflake(999999999999999999)\n\n    matched = ismissing(event.matched_keyword) ? \"N/A\" : event.matched_keyword\n    content = ismissing(event.content) ? \"N/A\" : event.content\n    channel = ismissing(event.channel_id) ? \"N/A\" : \"<#$(event.channel_id)>\"\n\n    e = Accord.embed(\n        title=\"AutoMod Action\",\n        color=0xED4245,\n        fields=[\n            Dict(\"name\" => \"User\", \"value\" => \"<@$(event.user_id)>\", \"inline\" => true),\n            Dict(\"name\" => \"Channel\", \"value\" => channel, \"inline\" => true),\n            Dict(\"name\" => \"Rule ID\", \"value\" => string(event.rule_id), \"inline\" => true),\n            Dict(\"name\" => \"Matched Keyword\", \"value\" => matched),\n            Dict(\"name\" => \"Content\", \"value\" => length(content) > 200 ? content[1:200] * \"...\" : content),\n        ]\n    )\n    create_message(c, ALERT_CHANNEL; embeds=[e])\nend","title":"Custom Alert Embed"},{"category":"section","location":"cookbook/09-automod/#8.-Managing-Rules","page":"Auto-Moderation","text":"","title":"8. Managing Rules"},{"category":"section","location":"cookbook/09-automod/#List-All-Rules","page":"Auto-Moderation","text":"rules = Accord.list_auto_moderation_rules(client, guild_id)\nfor rule in rules\n    @info \"Rule\" name=rule.name id=rule.id enabled=rule.enabled trigger_type=rule.trigger_type\nend","title":"List All Rules"},{"category":"section","location":"cookbook/09-automod/#Modify-a-Rule","page":"Auto-Moderation","text":"Accord.modify_auto_moderation_rule(client, guild_id, rule_id;\n    body=Dict(\n        \"name\" => \"Updated Filter\",\n        \"trigger_metadata\" => Dict(\n            \"keyword_filter\" => [\"newbadword1\", \"newbadword2\"],\n        ),\n    )\n)","title":"Modify a Rule"},{"category":"section","location":"cookbook/09-automod/#Delete-a-Rule","page":"Auto-Moderation","text":"Accord.delete_auto_moderation_rule(client, guild_id, rule_id)","title":"Delete a Rule"},{"category":"section","location":"cookbook/09-automod/#Add-Exempt-Roles/Channels","page":"Auto-Moderation","text":"Accord.modify_auto_moderation_rule(client, guild_id, rule_id;\n    body=Dict(\n        \"exempt_roles\" => [string(mod_role_id), string(admin_role_id)],\n        \"exempt_channels\" => [string(bot_testing_channel_id)],\n    )\n)","title":"Add Exempt Roles/Channels"},{"category":"section","location":"cookbook/09-automod/#9.-Slash-Command-for-Managing-AutoMod","page":"Auto-Moderation","text":"options_automod = [\n    Accord.command_option(\n        type=ApplicationCommandOptionTypes.SUB_COMMAND,\n        name=\"list\",\n        description=\"List all AutoMod rules\"\n    ),\n    Accord.command_option(\n        type=ApplicationCommandOptionTypes.SUB_COMMAND,\n        name=\"toggle\",\n        description=\"Enable/disable a rule\",\n        options=[\n            Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"rule_id\", description=\"Rule ID\", required=true),\n            Accord.command_option(type=ApplicationCommandOptionTypes.BOOLEAN, name=\"enabled\", description=\"Enable or disable\", required=true),\n        ]\n    ),\n]\n\n@slash_command client \"automod\" \"Manage auto-moderation\" options_automod function(ctx)\n    data = ctx.interaction.data\n    ismissing(data) && return\n    ismissing(data.options) && return\n\n    sub = data.options[1]\n    guild_id = ctx.interaction.guild_id\n\n    if sub.name == \"list\"\n        Accord.defer(ctx; ephemeral=true)\n        rules = Accord.list_auto_moderation_rules(ctx.client, guild_id)\n\n        if isempty(rules)\n            Accord.respond(ctx; content=\"No AutoMod rules configured.\")\n            return\n        end\n\n        fields = [\n            Dict(\n                \"name\" => \"$(rule.name) ($(rule.enabled ? \"ON\" : \"OFF\"))\",\n                \"value\" => \"ID: `$(rule.id)` | Trigger: $(rule.trigger_type)\",\n            )\n            for rule in rules\n        ]\n        e = Accord.embed(title=\"AutoMod Rules\", color=0x5865F2, fields=fields)\n        Accord.respond(ctx; embeds=[e])\n\n    elseif sub.name == \"toggle\"\n        sub_opts = Dict{String, Any}()\n        if !ismissing(sub.options)\n            for opt in sub.options\n                !ismissing(opt.value) && (sub_opts[opt.name] = opt.value)\n            end\n        end\n\n        rule_id = Snowflake(sub_opts[\"rule_id\"])\n        enabled = sub_opts[\"enabled\"]\n\n        Accord.modify_auto_moderation_rule(ctx.client, guild_id, rule_id;\n            body=Dict(\"enabled\" => enabled))\n\n        Accord.respond(ctx; content=\"Rule `$rule_id` $(enabled ? \"enabled\" : \"disabled\").\", ephemeral=true)\n    end\nend\n\n\n\nNext steps: Recipe 10 — Polls for Discord's native poll system, or Recipe 11 — Architectural Patterns for production structure.","title":"9. Slash Command for Managing AutoMod"},{"category":"section","location":"cookbook/13-deploy/#Recipe-13-—-Deployment","page":"Deployment","text":"Difficulty: Intermediate What you will build: Production deployment with systemd, Docker, sysimages, and health checks.\n\nPrerequisites: Recipe 11\n\n","title":"Recipe 13 — Deployment"},{"category":"section","location":"cookbook/13-deploy/#1.-Environment-Management","page":"Deployment","text":"","title":"1. Environment Management"},{"category":"section","location":"cookbook/13-deploy/#.env-File","page":"Deployment","text":"warning: Token Exposure Risk\nNever commit tokens to version control. Tokens are credentials that grant access to your bot. If exposed:Malicious users could control your bot\nYour bot could be used for spam/abuse\nDiscord may reset the token and ban the applicationUse environment variables or a .env file (in .gitignore), never hardcode tokens.\n\n# .env — NEVER commit this file\nDISCORD_TOKEN=Bot XXXXXXXXXXXXXXXXXXXXXXXXXX.XXXXXX.XXXXXXXXXXXXXXXXXXXXXXXX\nOPENAI_API_KEY=sk-...\nDATABASE_URL=sqlite:///data/bot.db","title":".env File"},{"category":"section","location":"cookbook/13-deploy/#.gitignore","page":"Deployment","text":".env\n*.db\nManifest.toml\nbot_sysimage.so\n/data/\n/logs/","title":".gitignore"},{"category":"section","location":"cookbook/13-deploy/#Loading-in-Julia","page":"Deployment","text":"function load_env(path=\".env\")\n    isfile(path) || return\n    for line in eachline(path)\n        stripped = strip(line)\n        (isempty(stripped) || startswith(stripped, '#')) && continue\n        eq_pos = findfirst('=', stripped)\n        isnothing(eq_pos) && continue\n        key = strip(stripped[1:eq_pos-1])\n        value = strip(stripped[eq_pos+1:end])\n        ENV[key] = value\n    end\nend","title":"Loading in Julia"},{"category":"section","location":"cookbook/13-deploy/#2.-Systemd-Service","page":"Deployment","text":"","title":"2. Systemd Service"},{"category":"section","location":"cookbook/13-deploy/#Service-Unit-File","page":"Deployment","text":"# /etc/systemd/system/discord-bot.service\n[Unit]\nDescription=Accord.jl Discord Bot\nAfter=network-online.target\nWants=network-online.target\n\n[Service]\nType=simple\nUser=botuser\nGroup=botuser\nWorkingDirectory=/opt/mybot\nEnvironmentFile=/opt/mybot/.env\nExecStart=/usr/local/bin/julia --project=/opt/mybot --threads=4 /opt/mybot/bin/run.jl\nRestart=always\nRestartSec=10\nStandardOutput=journal\nStandardError=journal\nSyslogIdentifier=discord-bot\n\n# Security hardening\nNoNewPrivileges=yes\nProtectSystem=strict\nProtectHome=yes\nReadWritePaths=/opt/mybot/data /opt/mybot/logs\nPrivateTmp=yes\n\n[Install]\nWantedBy=multi-user.target","title":"Service Unit File"},{"category":"section","location":"cookbook/13-deploy/#With-Sysimage-(Fast-Startup)","page":"Deployment","text":"ExecStart=/usr/local/bin/julia --sysimage=/opt/mybot/bot_sysimage.so --project=/opt/mybot --threads=4 /opt/mybot/bin/run.jl","title":"With Sysimage (Fast Startup)"},{"category":"section","location":"cookbook/13-deploy/#Managing-the-Service","page":"Deployment","text":"sudo systemctl daemon-reload\nsudo systemctl enable discord-bot\nsudo systemctl start discord-bot\nsudo systemctl status discord-bot\nsudo journalctl -u discord-bot -f      # follow logs\nsudo journalctl -u discord-bot --since \"1 hour ago\"","title":"Managing the Service"},{"category":"section","location":"cookbook/13-deploy/#3.-Docker","page":"Deployment","text":"","title":"3. Docker"},{"category":"section","location":"cookbook/13-deploy/#Dockerfile","page":"Deployment","text":"# Multi-stage build for smaller image\n\n# Stage 1: Build sysimage\nFROM julia:1.11 AS builder\n\nWORKDIR /app\nCOPY Project.toml Manifest.toml ./\nRUN julia --project=. -e 'using Pkg; Pkg.instantiate(); Pkg.precompile()'\n\nCOPY . .\n\n# Optional: create sysimage for fast startup\nRUN julia --project=. -e '\n    using PackageCompiler\n    create_sysimage(\n        [\"Accord\", \"HTTP\", \"JSON3\"],\n        sysimage_path=\"bot_sysimage.so\",\n        precompile_execution_file=\"precompile_script.jl\",\n    )\n'\n\n# Stage 2: Runtime\nFROM julia:1.11-slim\n\n# Install ffmpeg for voice support\nRUN apt-get update && apt-get install -y --no-install-recommends ffmpeg && rm -rf /var/lib/apt/lists/*\n\nWORKDIR /app\n\n# Copy project and sysimage\nCOPY --from=builder /app /app\n\n# Create data directory\nRUN mkdir -p /app/data /app/logs\n\n# Run as non-root\nRUN useradd -m botuser\nUSER botuser\n\nHEALTHCHECK --interval=30s --timeout=5s --retries=3 \\\n    CMD julia -e 'exit(isfile(\"/app/data/healthcheck\") && time() - mtime(\"/app/data/healthcheck\") < 60 ? 0 : 1)'\n\nENTRYPOINT [\"julia\", \"--sysimage=/app/bot_sysimage.so\", \"--project=/app\", \"--threads=4\", \"bin/run.jl\"]","title":"Dockerfile"},{"category":"section","location":"cookbook/13-deploy/#Dockerfile-(Simple,-No-Sysimage)","page":"Deployment","text":"FROM julia:1.11\n\nRUN apt-get update && apt-get install -y --no-install-recommends ffmpeg && rm -rf /var/lib/apt/lists/*\n\nWORKDIR /app\nCOPY Project.toml Manifest.toml ./\nRUN julia --project=. -e 'using Pkg; Pkg.instantiate(); Pkg.precompile()'\n\nCOPY . .\nRUN mkdir -p /app/data\n\nENTRYPOINT [\"julia\", \"--project=/app\", \"--threads=4\", \"bin/run.jl\"]","title":"Dockerfile (Simple, No Sysimage)"},{"category":"section","location":"cookbook/13-deploy/#docker-compose.yml","page":"Deployment","text":"version: \"3.8\"\n\nservices:\n  bot:\n    build: .\n    env_file: .env\n    restart: always\n    volumes:\n      - bot-data:/app/data\n      - bot-logs:/app/logs\n    logging:\n      driver: json-file\n      options:\n        max-size: \"10m\"\n        max-file: \"3\"\n\nvolumes:\n  bot-data:\n  bot-logs:","title":"docker-compose.yml"},{"category":"section","location":"cookbook/13-deploy/#Running","page":"Deployment","text":"# Build and start\ndocker compose up -d --build\n\n# View logs\ndocker compose logs -f bot\n\n# Restart\ndocker compose restart bot\n\n# Update\ngit pull\ndocker compose up -d --build","title":"Running"},{"category":"section","location":"cookbook/13-deploy/#4.-PackageCompiler-Sysimage","page":"Deployment","text":"tip: Sysimage Creation for Faster Startup\nPackageCompiler.jl can create a custom sysimage that pre-compiles Accord.jl and its dependencies. This reduces startup time from ~10 seconds to ~1 second — critical for production deployments where quick restarts matter.\n\nCreate a sysimage for near-instant startup (~1s vs ~10s):\n\n# build_sysimage.jl\nusing PackageCompiler\n\ncreate_sysimage(\n    [\"Accord\", \"HTTP\", \"JSON3\"],\n    sysimage_path=\"bot_sysimage.so\",\n    precompile_execution_file=\"precompile_script.jl\",\n)\n\n# precompile_script.jl\nusing Accord\n\n# Exercise the code paths that matter\nclient = [`Client`](@ref)(\"Bot fake\"; intents=[`IntentGuilds`](@ref))\ntree = [`CommandTree`](@ref)()\n\n# Components\n[`embed`](@ref)(title=\"T\", color=0x5865F2)\n[`button`](@ref)(label=\"B\", custom_id=\"b\")\n[`action_row`](@ref)([[`button`](@ref)(label=\"X\", custom_id=\"x\")])\n[`string_select`](@ref)(custom_id=\"s\", options=[[`select_option`](@ref)(label=\"L\", value=\"V\")])\n[`text_input`](@ref)(custom_id=\"ti\", label=\"L\")\n[`command_option`](@ref)(type=3, name=\"n\", description=\"d\")\n\nprintln(\"Precompilation complete\")\n\nBuild:\n\njulia --project=. build_sysimage.jl","title":"4. PackageCompiler Sysimage"},{"category":"section","location":"cookbook/13-deploy/#5.-Health-Checks","page":"Deployment","text":"","title":"5. Health Checks"},{"category":"section","location":"cookbook/13-deploy/#Simple-File-Based-Health-Check","page":"Deployment","text":"# In your bot, write a timestamp file periodically\n@async begin\n    while client.running\n        write(\"data/healthcheck\", string(time()))\n        sleep(30)\n    end\nend","title":"Simple File-Based Health Check"},{"category":"section","location":"cookbook/13-deploy/#HTTP-Health-Endpoint","page":"Deployment","text":"import HTTP\n\nfunction start_health_server(client; port=8080)\n    @async HTTP.serve(\"0.0.0.0\", port) do request\n        if request.target == \"/health\"\n            status = client.running ? 200 : 503\n            body = JSON3.write(Dict(\n                \"status\" => client.running ? \"ok\" : \"down\",\n                \"guilds\" => length(client.state.guilds),\n                \"uptime_s\" => round(Int, time() - start_time),\n            ))\n            return HTTP.Response(status, [\"Content-Type\" => \"application/json\"], body)\n        end\n        return HTTP.Response(404, \"Not found\")\n    end\nend\n\nconst start_time = time()\n\nAccord.on(client, [`ReadyEvent`](@ref)) do c, event\n    start_health_server(c)\n    @info \"Health endpoint running on :8080/health\"\nend","title":"HTTP Health Endpoint"},{"category":"section","location":"cookbook/13-deploy/#6.-Log-Rotation","page":"Deployment","text":"","title":"6. Log Rotation"},{"category":"section","location":"cookbook/13-deploy/#With-systemd-(automatic-via-journald)","page":"Deployment","text":"# journald handles rotation automatically\n# Configure limits in /etc/systemd/journald.conf:\n# SystemMaxUse=500M\n# MaxRetentionSec=30day","title":"With systemd (automatic via journald)"},{"category":"section","location":"cookbook/13-deploy/#Manual-File-Logging","page":"Deployment","text":"using Logging, Dates\n\nfunction setup_file_logging(path=\"logs/bot.log\")\n    mkpath(dirname(path))\n    io = open(path, \"a\")\n    logger = SimpleLogger(io, Logging.Info)\n    global_logger(logger)\n    return io\nend\n\n# Rotate daily\nfunction rotate_logs(base_path=\"logs/bot.log\")\n    date_str = Dates.format(today(), \"yyyy-mm-dd\")\n    archive = \"logs/bot-$(date_str).log\"\n    isfile(base_path) && mv(base_path, archive; force=true)\nend","title":"Manual File Logging"},{"category":"section","location":"cookbook/13-deploy/#7.-Update-Workflow","page":"Deployment","text":"","title":"7. Update Workflow"},{"category":"section","location":"cookbook/13-deploy/#Manual-Deployment","page":"Deployment","text":"# SSH into server\nssh botserver\n\n# Pull latest code\ncd /opt/mybot\ngit pull\n\n# Update dependencies\njulia --project=. -e 'using Pkg; Pkg.update(); Pkg.precompile()'\n\n# Rebuild sysimage (optional, takes a few minutes)\njulia --project=. build_sysimage.jl\n\n# Restart\nsudo systemctl restart discord-bot\nsudo journalctl -u discord-bot -f  # watch for errors","title":"Manual Deployment"},{"category":"section","location":"cookbook/13-deploy/#Docker-Deployment","page":"Deployment","text":"ssh botserver\ncd /opt/mybot\ngit pull\ndocker compose up -d --build\ndocker compose logs -f bot\n\n\n\nNext steps: Recipe 14 — Troubleshooting for debugging common issues.","title":"Docker Deployment"},{"category":"section","location":"cookbook/07-caching/#Recipe-07-—-Caching-Strategies","page":"Caching","text":"Difficulty: Intermediate What you will build: Per-resource cache configuration, memory-efficient state for bots at any scale.\n\nPrerequisites: Recipe 01\n\n","title":"Recipe 07 — Caching Strategies"},{"category":"section","location":"cookbook/07-caching/#1.-Why-Caching-Matters","page":"Caching","text":"Every time you call get_guild, get_channel, or get_user, Accord.jl checks its in-memory cache first. Cache hits avoid:\n\nREST API calls (each costs ~50-200ms)\nRate limit consumption (you only get ~50 requests/second)\n\nBut caching everything wastes memory. Accord.jl lets you choose per resource type.","title":"1. Why Caching Matters"},{"category":"section","location":"cookbook/07-caching/#2.-The-Four-Cache-Strategies","page":"Caching","text":"Strategy Constructor Behavior\nCacheForever CacheForever() Keep everything, never evict\nCacheNever CacheNever() Never cache, always fetch from API\nCacheLRU CacheLRU(n) Keep the n most recently used entries\nCacheTTL CacheTTL(seconds) Expire entries after seconds","title":"2. The Four Cache Strategies"},{"category":"section","location":"cookbook/07-caching/#3.-Per-Resource-Configuration","page":"Caching","text":"Configure caching in the Client constructor:\n\nclient = Client(token;\n    intents = IntentGuilds | IntentGuildMessages,\n\n    # Cache strategies (these are the defaults)\n    guild_strategy    = CacheForever(),     # guilds are small, keep all\n    channel_strategy  = CacheForever(),     # channels are small, keep all\n    user_strategy     = CacheLRU(10_000),   # keep 10k most active users\n    member_strategy   = CacheLRU(10_000),   # keep 10k most active members\n    presence_strategy = CacheNever(),       # presences are large, skip\n)","title":"3. Per-Resource Configuration"},{"category":"section","location":"cookbook/07-caching/#4.-Decision-Matrix","page":"Caching","text":"Choose based on your bot's scale:\n\nBot Size Guilds Users Recommended Config\nSmall (<100 guilds) CacheForever() CacheForever() Cache everything\nMedium (100-1000 guilds) CacheForever() CacheLRU(50_000) LRU for users/members\nLarge (1000+ guilds) CacheForever() CacheLRU(100_000) LRU or TTL for users/members\nVery Large (10k+ guilds) CacheTTL(3600) CacheLRU(100_000) TTL for guilds too","title":"4. Decision Matrix"},{"category":"section","location":"cookbook/07-caching/#Small-Bot-(Just-Cache-Everything)","page":"Caching","text":"client = Client(token;\n    guild_strategy    = CacheForever(),\n    channel_strategy  = CacheForever(),\n    user_strategy     = CacheForever(),\n    member_strategy   = CacheForever(),\n    presence_strategy = CacheNever(),  # still skip presences\n)\n\ntip: Memory-Constrained Environments\nFor bots running on limited memory (VPS with <2GB RAM), use CacheLRU or CacheTTL strategies. Avoid CacheForever for users and members, as these can grow unbounded in large guilds.","title":"Small Bot (Just Cache Everything)"},{"category":"section","location":"cookbook/07-caching/#Large-Bot-(Memory-Conscious)","page":"Caching","text":"client = Client(token;\n    guild_strategy    = CacheForever(),       # guilds are always needed\n    channel_strategy  = CacheLRU(50_000),     # only active channels\n    user_strategy     = CacheLRU(100_000),    # ~100k users\n    member_strategy   = CacheLRU(100_000),\n    presence_strategy = CacheNever(),\n)\n\nwarning: CacheNever Means REST Fallback on Every Access\nUsing CacheNever means every call to get_user, get_channel, etc. will hit the Discord REST API. This can quickly exhaust your rate limits. Only use CacheNever for data you truly don't need to cache, not as a default strategy.","title":"Large Bot (Memory Conscious)"},{"category":"section","location":"cookbook/07-caching/#5.-How-[Store](@ref){T}-Works-Internally","page":"Caching","text":"Each resource type has a Store{T}:\n\nmutable struct Store{T}\n    strategy::CacheStrategy\n    data::Dict{[`Snowflake`](@ref), T}        # the actual cache\n    access_order::Vector{[`Snowflake`](@ref)}  # LRU tracking\n    timestamps::Dict{[`Snowflake`](@ref), Float64}  # TTL tracking\n    maxsize::Int\nend\n\nCacheForever: items go in data, never removed\nCacheNever: setindex! is a no-op, get always returns nothing\nCacheLRU: on access, the key moves to end of access_order; when full, the oldest is evicted\nCacheTTL: on access, checks if time() - timestamps[key] > ttl; if so, deletes and returns nothing","title":"5. How Store{T} Works Internally"},{"category":"section","location":"cookbook/07-caching/#6.-Automatic-Cache-Updates","page":"Caching","text":"The cache updates automatically from gateway events:\n\nEvent Cache Action\nReadyEvent Sets state.me, caches unavailable guilds\nGuildCreate Caches guild, channels, roles, emojis, members\nGuildUpdate Updates guild\nGuildDelete Removes guild and all associated data\nChannelCreate/ChannelUpdate Caches channel\nChannelDelete Removes channel\nGuildMemberAdd Caches member and user\nGuildMemberRemove Removes member\nGuildMemberUpdate Updates member fields\nGuildRoleCreate/Update Caches role\nGuildRoleDelete Removes role\nMessageCreate Caches message author\nVoiceStateUpdateEvent Updates voice state tracking","title":"6. Automatic Cache Updates"},{"category":"section","location":"cookbook/07-caching/#7.-Memory-Estimation","page":"Caching","text":"Rough per-object memory estimates:\n\nObject Approximate Size\nGuild 2-5 KB\nDiscordChannel 0.5-1 KB\nUser 0.3-0.5 KB\nMember 0.2-0.5 KB\nRole 0.2-0.3 KB\nPresence 0.5-2 KB\n\nFor a bot in 1,000 guilds with an average 500 members per guild:\n\nGuilds: 1,000 × 3 KB ≈ 3 MB\nChannels: ~15,000 × 0.7 KB ≈ 10 MB\nUsers (LRU 100k): 100,000 × 0.4 KB ≈ 40 MB\n\nTotal: ~53 MB — very manageable.","title":"7. Memory Estimation"},{"category":"section","location":"cookbook/07-caching/#8.-Inspecting-the-Cache","page":"Caching","text":"Use non-blocking mode for REPL inspection:\n\nAccord.start(client; blocking=false)\nwait_until_ready(client)\n\n# Cache stats\n@info \"Guilds:   $(length(client.state.guilds))\"\n@info \"Channels: $(length(client.state.channels))\"\n@info \"Users:    $(length(client.state.users))\"\n\n# Look up a specific guild\nguild = get(client.state.guilds, [`Snowflake`](@ref)(123456789))\nguild.name\n\n# List cached roles for a guild\nroles = get(client.state.roles, [`Snowflake`](@ref)(123456789), nothing)\nif !isnothing(roles)\n    for role in values(roles)\n        println(\"  $(role.name): $(role.id)\")\n    end\nend","title":"8. Inspecting the Cache"},{"category":"section","location":"cookbook/07-caching/#9.-Custom-Application-Level-Caching","page":"Caching","text":"For external API data, build your own TTL cache:\n\nmutable struct TTLCache{K, V}\n    data::Dict{K, Tuple{V, Float64}}\n    ttl::Float64\nend\n\nTTLCache{K, V}(ttl::Float64) where {K, V} = TTLCache{K, V}(Dict{K, Tuple{V, Float64}}(), ttl)\n\nfunction Base.get(cache::TTLCache{K, V}, key::K, default=nothing) where {K, V}\n    if haskey(cache.data, key)\n        val, ts = cache.data[key]\n        if time() - ts <= cache.ttl\n            return val\n        end\n        delete!(cache.data, key)\n    end\n    return default\nend\n\nfunction Base.setindex!(cache::TTLCache{K, V}, value::V, key::K) where {K, V}\n    cache.data[key] = (value, time())\nend\n\n# Usage: cache weather API responses for 5 minutes\nconst weather_cache = TTLCache{String, Dict}(300.0)\n\n\n\nNext steps: Recipe 08 — Sharding if your bot is in 2,500+ guilds.","title":"9. Custom Application-Level Caching"},{"category":"section","location":"release-notes/#Release-Notes","page":"Release Notes","text":"","title":"Release Notes"},{"category":"section","location":"release-notes/#v0.3.0:-The-\"Reliability-and-Performance\"-Update","page":"Release Notes","text":"This release marks a major milestone for Accord.jl, focusing on extreme reliability, industry-standard documentation, and architectural improvements that make it one of the fastest Discord libraries in existence.","title":"v0.3.0: The \"Reliability & Performance\" Update"},{"category":"section","location":"release-notes/#Highlights","page":"Release Notes","text":"Production-Grade Reliability: Introduced a deterministic fault injection suite and automated smoke testing. The gateway now aggressively recovers from zombie connections, and the rate limiter is guarded by configurable safety buffers.\nIndustry-Standard Documentation: 100% of Discord Types (Tiers A, B, and C) and functional API methods are now documented with detailed docstrings, examples, and links to the official Discord API.\nExtreme Performance: Implemented \"Zero-Copy\" event parsing and O(1) interaction dispatch, achieving up to 9x faster event processing compared to v0.2.0.\nModel Resilience: Introduced the Maybe{T} type system to handle Discord's highly variable payloads without runtime crashes.","title":"Highlights"},{"category":"section","location":"release-notes/#Performance-(Measured)","page":"Release Notes","text":"Metric v0.2.0 v0.3.0 Gain\nParsing Throughput ~45k msg/s ~283k msg/s +530%\nParsing Latency 22.1 μs 3.5 μs -84%\nComponent Lookup O(N) O(1) 🚀","title":"Performance (Measured)"},{"category":"section","location":"release-notes/#Breaking-Changes","page":"Release Notes","text":"Component Registration: register_component! now requires an explicit * suffix for prefix matching (e.g., \"btn_*\"). Standard strings are now matched exactly for O(1) performance.\nCache Internals: The State cache now uses ShardedStore for global resources. Direct access to internal Dicts is discouraged.\n\n","title":"Breaking Changes"},{"category":"section","location":"release-notes/#v0.2.0:-The-\"Developer-Experience\"-Release","page":"Release Notes","text":"","title":"v0.2.0: The \"Developer Experience\" Release"},{"category":"section","location":"release-notes/#Breaking-Changes-2","page":"Release Notes","text":"This release bumps the version to 0.2.0, indicating changes to the public API that may affect backward compatibility.\n\nNew Diagnostic System (Diagnoser.jl): A new robust diagnostic and error handling system changes how exceptions are reported and handled. Scripts relying on previous error behavior or specific exceptions may need updates to align with the new validation flow (e.g., token, intents, and shard validation).\nStrict Typing and Optimizations: Internal refactoring in Client and Gateway modules introduced stricter types (e.g., explicitly typed dictionaries) to improve performance and safety. This may break code relying on flexible or undocumented internal data structures.\nDependencies: Updates and fixes in dependencies (like InteractiveUtils and LocalCoverage) may have altered the expected execution environment.","title":"Breaking Changes"},{"category":"section","location":"release-notes/#Highlights-2","page":"Release Notes","text":"Elm-like Diagnostics: New error reporting system in src/diagnostics/ catches common errors (Missing Token, Invalid Intents, Shard Disconnects) and displays them with rich visual formatting (box-drawing, ANSI colors) and actionable hints.\n100% Example Coverage: Documentation and examples now cover the entire public API (Client, Context, Components, Voice).\nNew Bot Templates: Added production-ready examples:\naccord_omni: Reference architecture using FunSQL.jl.\nmusic_bot: Async-ready voice player.\nai_chat: Non-blocking OpenAI integration.","title":"Highlights"},{"category":"section","location":"release-notes/#Fixes","page":"Release Notes","text":"Voice: Fixed invalid await calls in voice connection logic.\nConcurrency: Resolved blocking HTTP calls within event handlers.\nBuild: Resolved dependency issues with InteractiveUtils during documentation build.","title":"Fixes"},{"category":"section","location":"release-notes/#Performance","page":"Release Notes","text":"Optimized Diagnoser.jl to have zero runtime overhead when no errors occur.","title":"Performance"},{"category":"section","location":"cookbook/06-permissions/#Recipe-06-—-Permissions","page":"Permissions","text":"Difficulty: Intermediate What you will build: Permission computation, guards for commands, and private channels via overwrites.\n\nPrerequisites: Recipe 03\n\n","title":"Recipe 06 — Permissions"},{"category":"section","location":"cookbook/06-permissions/#1.-How-Discord-Permissions-Work","page":"Permissions","text":"Permissions are a layered system:\n\nBase permissions — union of all role permissions for the member\nChannel overwrites — @everyone overwrite → role overwrites → member-specific overwrite\nSpecial cases — guild owner gets all permissions; Administrator bypasses everything\n\nwarning: ADMINISTRATOR Permission Bypass\nThe PermAdministrator permission bypasses all permission checks, including channel overwrites. A user with this permission can perform any action regardless of explicit denials.\n\nnote: Guild Owner Always Has All Permissions\nThe guild owner implicitly has every permission, including Administrator, regardless of their roles. Permission checks should always account for this using is_owner().","title":"1. How Discord Permissions Work"},{"category":"section","location":"cookbook/06-permissions/#2.-Permission-Flags-Reference","page":"Permissions","text":"Accord.jl defines permissions as a Permissions bitfield type:\n\nFlag Bit Description\nPermCreateInstantInvite 0 Create channel invites\nPermKickMembers 1 Kick members\nPermBanMembers 2 Ban members\nPermAdministrator 3 Bypasses all permission checks\nPermManageChannels 4 Create/edit/delete channels\nPermManageGuild 5 Change server settings\nPermAddReactions 6 Add reactions to messages\nPermViewAuditLog 7 View audit log\nPermViewChannel 10 View channels\nPermSendMessages 11 Send messages in text channels\nPermManageMessages 13 Delete/pin other users' messages\nPermEmbedLinks 14 Send embeds\nPermAttachFiles 15 Upload files\nPermReadMessageHistory 16 Read message history\nPermMentionEveryone 17 @everyone / @here\nPermConnect 20 Connect to voice channels\nPermSpeak 21 Speak in voice channels\nPermMuteMembers 22 Mute members in voice\nPermDeafenMembers 23 Deafen members in voice\nPermMoveMembers 24 Move members between voice channels\nPermManageRoles 28 Create/edit roles below yours\nPermManageWebhooks 29 Manage webhooks\nPermModerateMembers 40 Timeout members\nPermSendVoiceMessages 46 Send voice messages\nPermSendPolls 49 Create polls","title":"2. Permission Flags Reference"},{"category":"section","location":"cookbook/06-permissions/#Checking-Flags","page":"Permissions","text":"perms = [`Permissions`](@ref)(0x00000800)  # PermSendMessages\nAccord.has_flag(perms, PermSendMessages)  # true\nAccord.has_flag(perms, PermBanMembers)    # false","title":"Checking Flags"},{"category":"section","location":"cookbook/06-permissions/#Combining-Flags","page":"Permissions","text":"required = PermSendMessages | PermEmbedLinks | PermAttachFiles\nAccord.has_flag(user_perms, required)  # true only if ALL are set","title":"Combining Flags"},{"category":"section","location":"cookbook/06-permissions/#3.-Computing-Base-Permissions","page":"Permissions","text":"function get_member_permissions(client, guild_id, user_id)\n    guild = get_guild(client, guild_id)\n\n    # Get member's roles\n    member_store = get(client.state.members, guild_id, nothing)\n    isnothing(member_store) && return [`Permissions`](@ref)(0)\n    member = get(member_store, user_id)\n    isnothing(member) && return [`Permissions`](@ref)(0)\n\n    # Get guild roles from cache\n    role_store = get(client.state.roles, guild_id, nothing)\n    isnothing(role_store) && return [`Permissions`](@ref)(0)\n    guild_roles = collect(values(role_store))\n\n    member_roles = ismissing(member.roles) ? [`Snowflake`](@ref)[] : member.roles\n    owner_id = guild.owner_id\n\n    return compute_base_permissions(member_roles, guild_roles, owner_id, user_id)\nend","title":"3. Computing Base Permissions"},{"category":"section","location":"cookbook/06-permissions/#4.-Computing-Channel-Permissions","page":"Permissions","text":"function get_channel_permissions(client, guild_id, channel_id, user_id)\n    base = get_member_permissions(client, guild_id, user_id)\n\n    channel = get_channel(client, channel_id)\n    overwrites = ismissing(channel.permission_overwrites) ? Overwrite[] : channel.permission_overwrites\n\n    member_store = get(client.state.members, guild_id, nothing)\n    isnothing(member_store) && return base\n    member = get(member_store, user_id)\n    isnothing(member) && return base\n\n    member_roles = ismissing(member.roles) ? Snowflake[] : member.roles\n\n    return compute_channel_permissions(base, member_roles, overwrites, guild_id, user_id)\nend","title":"4. Computing Channel Permissions"},{"category":"section","location":"cookbook/06-permissions/#5.-Permission-Guard-for-Commands","page":"Permissions","text":"","title":"5. Permission Guard for Commands"},{"category":"section","location":"cookbook/06-permissions/#Using-@check-Guards-(Recommended)","page":"Permissions","text":"The cleanest way to protect commands — stack @check macros before @slash_command:\n\n# Only users with BAN_MEMBERS permission can use this\n@check Accord.has_permissions(:BAN_MEMBERS)\n@slash_command client \"ban\" \"Ban a user\" options_ban function(ctx)\n    target_id = Snowflake(Accord.get_option(ctx, \"user\", \"\"))\n    reason = Accord.get_option(ctx, \"reason\", \"No reason provided\")\n\n    Accord.create_guild_ban(ctx.client, ctx.interaction.guild_id, target_id;\n        body=Dict(\"delete_message_seconds\" => 86400), reason=reason)\n\n    Accord.respond(ctx; content=\"Banned <@$(target_id)>. Reason: $reason\")\nend\n\nIf the user lacks the required permission, an ephemeral \"❌ You don't have permission\" message is sent automatically — no boilerplate needed.","title":"Using @check Guards (Recommended)"},{"category":"section","location":"cookbook/06-permissions/#Stacking-Multiple-Checks","page":"Permissions","text":"@check Accord.is_in_guild()\n@check Accord.has_permissions(:MANAGE_GUILD)\n@check Accord.is_owner()\n@slash_command client \"nuke\" \"Extreme action — owner only\" function(ctx)\n    Accord.respond(ctx; content=\"💥 Done!\")\nend\n\nAll checks must pass. If any fails, subsequent checks and the handler are skipped.","title":"Stacking Multiple Checks"},{"category":"section","location":"cookbook/06-permissions/#Built-in-Check-Factories","page":"Permissions","text":"Check Description\nhas_permissions(perms...) Require Discord permissions. Accepts Permissions constants or symbols (:ADMINISTRATOR, :BAN_MEMBERS).\nis_owner() Require the guild owner.\nis_in_guild() Require guild context (deny DMs).","title":"Built-in Check Factories"},{"category":"section","location":"cookbook/06-permissions/#Accepts-Both-Permissions-Constants-and-Symbols","page":"Permissions","text":"# These are equivalent:\n@check Accord.has_permissions(PermManageGuild | PermBanMembers)\n@check Accord.has_permissions(:MANAGE_GUILD, :BAN_MEMBERS)","title":"Accepts Both Permissions Constants and Symbols"},{"category":"section","location":"cookbook/06-permissions/#Manual-Approach-(Legacy)","page":"Permissions","text":"For full control, you can still check permissions manually:\n\nfunction require_permissions(ctx, required::Permissions)\n    guild_id = ctx.interaction.guild_id\n    user_id = ctx.interaction.member.user.id\n\n    perms = get_member_permissions(ctx.client, guild_id, user_id)\n    if !Accord.has_flag(perms, required)\n        Accord.respond(ctx; content=\"You don't have permission to use this command.\", ephemeral=true)\n        return false\n    end\n    return true\nend\n\n# Usage in a command\noptions_ban = [\n    Accord.command_option(type=ApplicationCommandOptionTypes.USER, name=\"user\", description=\"User to ban\", required=true),\n    Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"reason\", description=\"Ban reason\"),\n]\n\n@slash_command client \"ban\" \"Ban a user\" options_ban function(ctx)\n    require_permissions(ctx, PermBanMembers) || return\n\n    target_id = Snowflake(Accord.get_option(ctx, \"user\", \"\"))\n    reason = Accord.get_option(ctx, \"reason\", \"No reason provided\")\n\n    Accord.create_guild_ban(ctx.client, ctx.interaction.guild_id, target_id;\n        body=Dict(\"delete_message_seconds\" => 86400), reason=reason)\n\n    Accord.respond(ctx; content=\"Banned <@$(target_id)>. Reason: $reason\")\nend","title":"Manual Approach (Legacy)"},{"category":"section","location":"cookbook/06-permissions/#6.-Common-Permission-Patterns","page":"Permissions","text":"","title":"6. Common Permission Patterns"},{"category":"section","location":"cookbook/06-permissions/#Mod-Only-Command","page":"Permissions","text":"# Using @check — clean and declarative\n@check Accord.has_permissions(:KICK_MEMBERS)\n@slash_command client \"warn\" \"Warn a user\" options_warn function(ctx)\n    Accord.respond(ctx; content=\"User warned.\")\nend","title":"Mod-Only Command"},{"category":"section","location":"cookbook/06-permissions/#Admin-Only-Command","page":"Permissions","text":"@check Accord.has_permissions(:ADMINISTRATOR)\n@slash_command client \"config\" \"Configure the bot\" function(ctx)\n    Accord.respond(ctx; content=\"Config panel:\", ephemeral=true)\nend","title":"Admin-Only Command"},{"category":"section","location":"cookbook/06-permissions/#Owner-Only-Command","page":"Permissions","text":"@check Accord.is_owner()\n@slash_command client \"shutdown\" \"Shut down the bot\" function(ctx)\n    Accord.respond(ctx; content=\"Shutting down...\")\n    Accord.stop(ctx.client)\nend","title":"Owner-Only Command"},{"category":"section","location":"cookbook/06-permissions/#Guild-Only-(No-DMs)","page":"Permissions","text":"@check Accord.is_in_guild()\n@slash_command client \"server-info\" \"Show server info\" function(ctx)\n    Accord.respond(ctx; content=\"Guild: $(ctx.guild_id)\")\nend","title":"Guild-Only (No DMs)"},{"category":"section","location":"cookbook/06-permissions/#7.-Creating-Private-Channels-via-Overwrites","page":"Permissions","text":"function create_private_channel(client, guild_id, name, user_id)\n    # @everyone can't view, specific user can\n    overwrites = [\n        Dict(\n            \"id\" => string(guild_id),    # @everyone role ID = guild ID\n            \"type\" => 0,                  # role overwrite\n            \"deny\" => string(PermViewChannel.value),\n            \"allow\" => \"0\",\n        ),\n        Dict(\n            \"id\" => string(user_id),\n            \"type\" => 1,                  # member overwrite\n            \"deny\" => \"0\",\n            \"allow\" => string((PermViewChannel | PermSendMessages | PermReadMessageHistory).value),\n        ),\n    ]\n\n    body = Dict(\n        \"name\" => name,\n        \"type\" => ChannelTypes.GUILD_TEXT,\n        \"permission_overwrites\" => overwrites,\n    )\n\n    Accord.create_guild_channel(client, guild_id; body)\nend\n\n# Usage\nchannel = create_private_channel(client, guild_id, \"ticket-123\", user_id)\ncreate_message(client, channel.id; content=\"This channel is private to <@$(user_id)>.\")","title":"7. Creating Private Channels via Overwrites"},{"category":"section","location":"cookbook/06-permissions/#8.-Bot-Permission-Self-Check","page":"Permissions","text":"Ensure the bot has the permissions it needs:\n\nAccord.on(client, [`GuildCreate`](@ref)) do c, event\n    guild = event.guild\n    me_id = c.state.me.id\n\n    perms = get_member_permissions(c, guild.id, me_id)\n\n    required = PermSendMessages | PermEmbedLinks | PermManageMessages\n    if !Accord.has_flag(perms, required)\n        missing_perms = String[]\n        Accord.has_flag(perms, PermSendMessages) || push!(missing_perms, \"Send Messages\")\n        Accord.has_flag(perms, PermEmbedLinks) || push!(missing_perms, \"Embed Links\")\n        Accord.has_flag(perms, PermManageMessages) || push!(missing_perms, \"Manage Messages\")\n        @warn \"Missing permissions in guild\" guild=guild.name missing=missing_perms\n    end\nend\n\n\n\nNext steps: Recipe 07 — Caching to optimize state management for your bot's size.","title":"8. Bot Permission Self-Check"},{"category":"section","location":"cookbook/14-troubleshooting/#Recipe-14-—-Troubleshooting","page":"Troubleshooting","text":"Difficulty: All levels What you will build: A reference for diagnosing common errors, gateway issues, and interaction failures.\n\nPrerequisites: Recipe 01\n\n\n\nwarning: Common Pitfalls\nMost bot issues fall into these categories:Wrong intents: Missing IntentMessageContent for reading messages, missing privileged intents\nMissing permissions: Bot lacks required Discord permissions for actions\nToken issues: Wrong token format, expired tokens, or missing \"Bot \" prefix\nTiming: Interaction responses taking longer than 3 seconds","title":"Recipe 14 — Troubleshooting"},{"category":"section","location":"cookbook/14-troubleshooting/#1.-Common-Error-Table","page":"Troubleshooting","text":"Error Cause Fix\nGateway close 4004 Authentication failed Check your token; ensure Bot prefix\nGateway close 4014 Disallowed intent(s) Enable privileged intents in Developer Portal\nHTTP 401 Invalid token Regenerate token in Developer Portal\nHTTP 403 Missing permissions Check bot's role permissions in server\nHTTP 429 Rate limited Reduce request rate; Accord.jl handles this automatically\nHTTP 400 Bad request body Check payload format; log the body before sending\ncontent is empty Missing IntentMessageContent Enable Message Content intent\nNo message events Missing IntentGuildMessages Add IntentGuildMessages to intents\nNo member events Missing IntentGuildMembers Enable privileged intent + add to intents\nInteraction failed Response took >3 seconds Use defer(ctx) before slow operations\n\"Unknown interaction\" Double response or expired Don't respond twice; respond within 15 minutes\n\"Interaction already acknowledged\" Called respond after defer + respond Use edit_response after defer, not respond (note: Accord.jl handles this — respond auto-detects deferred state)\n\ntip: Enable Debug Logging\nWhen troubleshooting, enable debug logging to see detailed event and request information:ENV[\"JULIA_DEBUG\"] = \"Accord\"  # Accord.jl specific\nENV[\"JULIA_DEBUG\"] = \"all\"     # All packages (very verbose)","title":"1. Common Error Table"},{"category":"section","location":"cookbook/14-troubleshooting/#2.-Debug-Logging","page":"Troubleshooting","text":"Enable debug output from Accord.jl:\n\n# Before starting the client\nENV[\"JULIA_DEBUG\"] = \"Accord\"\n\n# Or for everything:\nENV[\"JULIA_DEBUG\"] = \"all\"","title":"2. Debug Logging"},{"category":"section","location":"cookbook/14-troubleshooting/#Custom-Logging","page":"Troubleshooting","text":"using Logging\n\n# Log to file with timestamps\nio = open(\"bot.log\", \"a\")\nlogger = SimpleLogger(io, Logging.Debug)\nglobal_logger(logger)\n\n# Log all events\nAccord.on(client, AbstractEvent) do c, event\n    @debug \"Event received\" type=typeof(event) time=time()\nend","title":"Custom Logging"},{"category":"section","location":"cookbook/14-troubleshooting/#3.-Gateway-Issues","page":"Troubleshooting","text":"","title":"3. Gateway Issues"},{"category":"section","location":"cookbook/14-troubleshooting/#Gateway-Opcodes","page":"Troubleshooting","text":"Opcode Name Direction\n0 Dispatch Receive\n1 Heartbeat Send/Receive\n2 Identify Send\n6 Resume Send\n7 Reconnect Receive\n9 Invalid Session Receive\n10 Hello Receive\n11 Heartbeat ACK Receive","title":"Gateway Opcodes"},{"category":"section","location":"cookbook/14-troubleshooting/#Gateway-Close-Codes","page":"Troubleshooting","text":"Code Meaning Can Resume?\n4000 Unknown error Yes\n4001 Unknown opcode Yes\n4002 Decode error Yes\n4003 Not authenticated No\n4004 Authentication failed No — check token\n4005 Already authenticated Yes\n4007 Invalid seq No — new session\n4008 Rate limited Yes\n4009 Session timed out No — new session\n4010 Invalid shard No — check shard config\n4011 Sharding required No — enable sharding\n4012 Invalid API version No — update library\n4013 Invalid intents No — check intent value\n4014 Disallowed intents No — enable in portal","title":"Gateway Close Codes"},{"category":"section","location":"cookbook/14-troubleshooting/#Resume-vs-New-Session","page":"Troubleshooting","text":"Accord.jl handles reconnection automatically. If you see frequent reconnects:\n\nAccord.on(client, ResumedEvent) do c, event\n    @info \"Gateway connection resumed\"\nend\n\nAccord.on(client, ReadyEvent) do c, event\n    @info \"New gateway session established\" guilds=length(event.guilds)\nend\n\nIf you see many ReadyEvents but few ResumedEvents, the bot may be losing its session (network issues, too slow to heartbeat).","title":"Resume vs New Session"},{"category":"section","location":"cookbook/14-troubleshooting/#4.-Interaction-Failures","page":"Troubleshooting","text":"","title":"4. Interaction Failures"},{"category":"section","location":"cookbook/14-troubleshooting/#The-3-Second-Rule","page":"Troubleshooting","text":"Discord requires an initial response within 3 seconds. If your handler is slow:\n\n# BAD: will fail if database is slow\n@slash_command client \"lookup\" \"Look up data\" function(ctx)\n    result = slow_database_query()  # might take 5 seconds\n    Accord.respond(ctx; content=result)     # TOO LATE — interaction expired\nend\n\n# GOOD: defer first\n@slash_command client \"lookup\" \"Look up data\" function(ctx)\n    Accord.defer(ctx)                       # immediate acknowledgment\n    result = slow_database_query()   # take as long as needed (up to 15 min)\n    Accord.respond(ctx; content=result)     # edits the deferred response\nend","title":"The 3-Second Rule"},{"category":"section","location":"cookbook/14-troubleshooting/#Double-Response-Errors","page":"Troubleshooting","text":"# BAD: responding twice\n@slash_command client \"test\" \"Test\" function(ctx)\n    Accord.respond(ctx; content=\"First\")\n    Accord.respond(ctx; content=\"Second\")   # ERROR: already responded\nend\n\n# GOOD: use followup for additional messages\n@slash_command client \"test\" \"Test\" function(ctx)\n    Accord.respond(ctx; content=\"First\")\n    Accord.followup(ctx; content=\"Second\")  # followup works after initial response\nend","title":"Double Response Errors"},{"category":"section","location":"cookbook/14-troubleshooting/#Component-Interaction-Response-Types","page":"Troubleshooting","text":"When handling button/select interactions, respond auto-selects UPDATE_MESSAGE (updates the original message). If you want a new message instead:\n\nregister_component!(tree, \"my_btn\", function(ctx)\n    # This updates the message the button is on:\n    Accord.respond(ctx; content=\"Updated!\")\n\n    # For a separate ephemeral reply, use followup:\n    # Accord.defer(ctx)  # acknowledge first\n    # Accord.followup(ctx; content=\"Separate reply!\", ephemeral=true)\nend)","title":"Component Interaction Response Types"},{"category":"section","location":"cookbook/14-troubleshooting/#5.-Rate-Limit-Debugging","page":"Troubleshooting","text":"Accord.jl handles rate limits automatically, but you can monitor them:\n\n# Check if you're hitting rate limits frequently\nregister_middleware!(client.event_handler) do client, event\n    if event isa InteractionCreate\n        @debug \"Interaction received\" id=event.interaction.id type=event.interaction.type\n    end\n    return event\nend","title":"5. Rate Limit Debugging"},{"category":"section","location":"cookbook/14-troubleshooting/#Common-Rate-Limit-Scenarios","page":"Troubleshooting","text":"Action Rate Limit Notes\nSend messages 5/5s per channel Spread across channels\nEdit messages 5/5s per channel Same bucket as send\nCreate reactions 1/0.25s Very tight\nBulk delete 1/1s Max 100 messages\nGlobal commands 200/day Use guild commands for dev\nGateway identify 1/5s Respect shard startup delay","title":"Common Rate Limit Scenarios"},{"category":"section","location":"cookbook/14-troubleshooting/#6.-Voice-Connection-Debugging","page":"Troubleshooting","text":"# Verbose voice connection logging\nENV[\"JULIA_DEBUG\"] = \"Accord\"\n\n# Check voice states\nfunction debug_voice(client, guild_id)\n    vs = get(client.state.voice_states, guild_id, nothing)\n    if isnothing(vs)\n        @info \"No voice states for guild\"\n        return\n    end\n    for (uid, state) in vs\n        @info \"Voice state\" user=uid channel=state.channel_id session=state.session_id\n    end\nend","title":"6. Voice Connection Debugging"},{"category":"section","location":"cookbook/14-troubleshooting/#Common-Voice-Issues","page":"Troubleshooting","text":"Issue Cause Fix\nconnect! hangs Missing IntentGuildVoiceStates Add intent\nNo audio output Missing ffmpeg Install ffmpeg\n\"No encryption key\" Session not fully established Wait longer after connect\nAudio cuts out Network jitter Check server connection\nOpus encode errors Wrong PCM format Ensure 48kHz, 16-bit, stereo","title":"Common Voice Issues"},{"category":"section","location":"cookbook/14-troubleshooting/#7.-REPL-Driven-Debugging","page":"Troubleshooting","text":"Use non-blocking mode to inspect live state:\n\nAccord.start(client; blocking=false)\nwait_until_ready(client)\n\n# Inspect client state\nclient.state.me                          # bot user\nclient.state.me.username                 # bot username\nlength(client.state.guilds)              # cached guild count\nlength(client.state.channels)            # cached channel count\n\n# Check a specific guild\nguild = get(client.state.guilds, Snowflake(123456789))\nguild.name\nguild.owner_id\n\n# Check shard status\nfor shard in client.shards\n    @info \"Shard\" id=shard.id connected=shard.session.connected\nend\n\n# Send a test message\ncreate_message(client, Snowflake(123456789); content=\"Test from REPL\")\n\n# Test an embed\ne = Accord.embed(title=\"Debug\", description=\"Testing\", color=0xFEE75C)\ncreate_message(client, Snowflake(123456789); embeds=[e])","title":"7. REPL-Driven Debugging"},{"category":"section","location":"cookbook/14-troubleshooting/#8.-Checklist-for-New-Bots","page":"Troubleshooting","text":"Token starts with Bot (Accord.jl adds this automatically)\nBot is invited with correct permissions (use OAuth2 URL generator)\nRequired intents are enabled in Developer Portal\nRequired intents are passed to Client()\nIntentMessageContent is enabled if reading message content\nInteractionCreate handler calls dispatch_interaction!\nReadyEvent handler calls sync_commands!\nCommand responses happen within 3 seconds (or use defer)\n.env file is in .gitignore\nError handler is registered with on_error\n\n\n\nNext steps: Recipe 15 — Why Julia? for the case for building Discord bots in Julia.","title":"8. Checklist for New Bots"},{"category":"section","location":"#Accord.jl","page":"Home","text":"Accord.jl is a high-performance, ergonomic Discord API library for Julia. Built for speed and developer happiness, it leverages Julia's multiple dispatch and concurrency model to make bot development intuitive and powerful.","title":"Accord.jl"},{"category":"section","location":"#Features","page":"Home","text":"Full v10 Support: Compatible with the latest Discord API features.\nErgonomic UI Macros: Decorators for Slash Commands, Buttons, Modals, and Select Menus.\n@check Guards: Declarative pre-execution checks for permissions, ownership, and custom conditions.\nwait_for Conversations: Lightweight state machines using Julia Channels — no manual state management.\nState Injection: Pass your database, config, or services via ctx.state — zero globals.\nHigh-Performance Voice: Built-in support for Opus encoding and encryption for music/voice bots.\nEfficient Caching: Automatic state management with customizable LRU/TTL strategies.\nType Safety: Leveraging Julia's type system to catch bugs before they happen.\nAsync First: Built on top of Julia's Tasks and Channels for non-blocking I/O.","title":"Features"},{"category":"section","location":"#Installation","page":"Home","text":"using Pkg\nPkg.add(\"Accord\")","title":"Installation"},{"category":"section","location":"#Quick-Start","page":"Home","text":"using Accord\n\nclient = [`Client`](@ref)(ENV[\"DISCORD_TOKEN\"];\n    intents = [`IntentGuilds`](@ref) | [`IntentGuildMessages`](@ref) | [`IntentMessageContent`](@ref)\n)\n\nAccord.on(client, [`ReadyEvent`](@ref)) do c, event\n    @info \"Bot is online as $(event.user.username)!\"\nend\n\n@slash_command client \"ping\" \"Check latency\" function(ctx)\n    [`respond`](@ref)(ctx; content=\"Pong!\")\nend\n\nAccord.on(client, [`ReadyEvent`](@ref)) do c, event\n    [`sync_commands!`](@ref)(c, c.command_tree)\nend\n\nAccord.start(client)","title":"Quick Start"},{"category":"section","location":"#Next-Steps","page":"Home","text":"Browse the Cookbook for step-by-step recipes\nCheck the API Reference for detailed documentation","title":"Next Steps"},{"category":"section","location":"#Getting-Help","page":"Home","text":"Documentation: Use the search bar or browse the API Reference.\nDiscord API: Refer to the official Discord Developer Portal for API details.\nIssues: Report bugs or request features on GitHub.","title":"Getting Help"},{"category":"section","location":"cookbook/05-voice/#Recipe-05-—-Voice:-Playback,-Recording-and-Transcription","page":"Voice","text":"Difficulty: Advanced What you will build: A voice bot that plays audio, records speech, and transcribes it with the Whisper API.\n\nPrerequisites: Recipe 03, ffmpeg installed, IntentGuildVoiceStates enabled\n\nwarning: Voice needs libdave\nSince March 1, 2026, Discord only admits clients that implement the DAVE end-to-end encryption protocol into voice calls. Accord implements DAVE on top of Discord's libdave, which is not bundled yet: build it as a shared library and point Accord at it before connecting.git clone https://github.com/discord/libdave && cd libdave/cpp\ngit submodule update --init vcpkg\n./vcpkg/bootstrap-vcpkg.sh -disableMetrics && make shared\nexport ACCORD_LIBDAVE=$PWD/build/libdave.so   # .dylib on macOSWithout it, connect! fails with close code 4017 and a log line telling you to set ACCORD_LIBDAVE. Accord sends audio only; the transcription section below needs a receive path (with DAVE decryption) that Accord does not have yet.\n\n\n\nwarning: System Dependencies for Voice\nAccord.jl's voice support requires:Opus_jll and libsodium_jll — bundled automatically via JLL packages\nFFmpeg — must be installed on your system and available in PATH for FFmpegSourceInstall FFmpeg:Ubuntu/Debian: sudo apt-get install ffmpeg\nmacOS: brew install ffmpeg\nWindows: Download from https://ffmpeg.org/download.html","title":"Recipe 05 — Voice: Playback, Recording & Transcription"},{"category":"section","location":"cookbook/05-voice/#1.-Prerequisites","page":"Voice","text":"client = Client(token;\n    intents = IntentGuilds | IntentGuildVoiceStates\n)\n\nnote: Voice Connection Timeout Behavior\nVoice connections may take several seconds to establish as they require:Gateway handshake (VOICESTATEUPDATE)\nVoice server assignment (VoiceServerUpdate event)\nVoice WebSocket connection\nUDP IP discovery\nEncryption negotiationIf connect! hangs, verify IntentGuildVoiceStates is enabled and the bot has permission to connect to the voice channel.","title":"1. Prerequisites"},{"category":"section","location":"cookbook/05-voice/#2.-Connecting-to-Voice","page":"Voice","text":"using Accord\n\nvc = [`VoiceClient`](@ref)(client, guild_id, voice_channel_id)\n\n# Full handshake: gateway → voice WS → UDP → ready\nAccord.connect!(vc)\n\n# Later, disconnect\nAccord.disconnect!(vc)\n\nThe connect! flow:\n\nSends VOICE_STATE_UPDATE to the gateway\nWaits for VoiceStateUpdateEvent and VoiceServerUpdate events\nConnects to the voice WebSocket\nPerforms IP discovery via UDP\nSelects encryption mode and establishes the session","title":"2. Connecting to Voice"},{"category":"section","location":"cookbook/05-voice/#3.-Playing-Audio","page":"Voice","text":"","title":"3. Playing Audio"},{"category":"section","location":"cookbook/05-voice/#From-Any-File-(via-FFmpeg)","page":"Voice","text":"source = [`FFmpegSource`](@ref)(\"song.mp3\")\nAccord.play!(vc, source)\n\nFFmpegSource handles any format ffmpeg supports: MP3, FLAC, OGG, WAV, M4A, URLs, etc.\n\n# Play from a URL\nsource = [`FFmpegSource`](@ref)(\"https://example.com/stream.mp3\")\nAccord.play!(vc, source)\n\n# Adjust volume at the ffmpeg level\nsource = [`FFmpegSource`](@ref)(\"song.mp3\"; volume=0.5)\nAccord.play!(vc, source)","title":"From Any File (via FFmpeg)"},{"category":"section","location":"cookbook/05-voice/#From-Raw-PCM","page":"Voice","text":"# Raw PCM Int16, 48kHz stereo\npcm_data = zeros(Int16, 48000 * 2 * 5)  # 5 seconds of silence\nsource = [`PCMSource`](@ref)(pcm_data)\nAccord.play!(vc, source)","title":"From Raw PCM"},{"category":"section","location":"cookbook/05-voice/#From-a-Raw-PCM-File","page":"Voice","text":"# File must be: 48kHz, 16-bit signed little-endian, stereo\nsource = [`FileSource`](@ref)(\"audio.raw\")\nAccord.play!(vc, source)","title":"From a Raw PCM File"},{"category":"section","location":"cookbook/05-voice/#Silence-(Keep-Alive)","page":"Voice","text":"# 5 seconds of silence to keep the voice connection alive\nsource = [`SilenceSource`](@ref)(5000)\nAccord.play!(vc, source)","title":"Silence (Keep-Alive)"},{"category":"section","location":"cookbook/05-voice/#4.-Playback-Control","page":"Voice","text":"player = vc.player\n\n# Pause/resume\nAccord.pause!(player)\nAccord.resume!(player)\n\n# Check status\nAccord.is_playing(player)  # true/false\n\n# Volume (0.0 to 2.0, applied to PCM before encoding)\nplayer.volume = 0.5   # 50%\nplayer.volume = 1.5   # 150%\n\n# Stop playback\nAccord.stop!(vc)","title":"4. Playback Control"},{"category":"section","location":"cookbook/05-voice/#5.-Opus-Encoding-Details","page":"Voice","text":"Discord requires Opus-encoded audio:\n\nSample rate: 48,000 Hz\nChannels: 2 (stereo)\nFrame duration: 20 ms\nFrame size: 960 samples per channel (1,920 total)\n\nAccord.jl handles this automatically when you use play!. For manual encoding:\n\nencoder = [`OpusEncoder`](@ref)()  # defaults: 48kHz, stereo, AUDIO application\n\npcm_frame = rand(Int16, 960 * 2)  # one 20ms frame\nopus_data = Accord.opus_encode(encoder, pcm_frame)\n\n# Decoding\ndecoder = [`OpusDecoder`](@ref)()\npcm_out = Accord.opus_decode(decoder, opus_data)","title":"5. Opus Encoding Details"},{"category":"section","location":"cookbook/05-voice/#6.-Voice-Transcription","page":"Voice","text":"This recipe captures incoming voice audio and sends it to OpenAI's Whisper API for transcription.","title":"6. Voice Transcription"},{"category":"section","location":"cookbook/05-voice/#Architecture","page":"Voice","text":"Discord Voice → UDP packets → Opus decode → PCM buffer\n                                              ↓\n                              Silence detected → WAV file\n                                              ↓\n                              Whisper API → Transcript → Text channel","title":"Architecture"},{"category":"section","location":"cookbook/05-voice/#PCM-to-WAV-Helper","page":"Voice","text":"function pcm_to_wav(pcm::Vector{Int16}; sample_rate=48000, channels=2)\n    data_size = length(pcm) * sizeof(Int16)\n    file_size = 36 + data_size\n\n    io = IOBuffer()\n    # RIFF header\n    write(io, b\"RIFF\")\n    write(io, UInt32(file_size))\n    write(io, b\"WAVE\")\n    # fmt chunk\n    write(io, b\"fmt \")\n    write(io, UInt32(16))          # chunk size\n    write(io, UInt16(1))           # PCM format\n    write(io, UInt16(channels))\n    write(io, UInt32(sample_rate))\n    write(io, UInt32(sample_rate * channels * sizeof(Int16)))  # byte rate\n    write(io, UInt16(channels * sizeof(Int16)))                 # block align\n    write(io, UInt16(16))          # bits per sample\n    # data chunk\n    write(io, b\"data\")\n    write(io, UInt32(data_size))\n    write(io, pcm)\n\n    return take!(io)\nend","title":"PCM to WAV Helper"},{"category":"section","location":"cookbook/05-voice/#Transcription-with-Whisper-API","page":"Voice","text":"import HTTP\nimport JSON3\n\nfunction transcribe_audio(wav_bytes::Vector{UInt8}; api_key=ENV[\"OPENAI_API_KEY\"])\n    # Build multipart form\n    body = HTTP.Forms.Form(Dict(\n        \"file\" => HTTP.Forms.File(wav_bytes, \"audio.wav\", \"audio/wav\"),\n        \"model\" => \"whisper-1\",\n        \"language\" => \"en\",\n    ))\n\n    resp = HTTP.post(\n        \"https://api.openai.com/v1/audio/transcriptions\",\n        [\"Authorization\" => \"Bearer $api_key\"],\n        body\n    )\n\n    result = JSON3.read(resp.body)\n    return result[\"text\"]\nend","title":"Transcription with Whisper API"},{"category":"section","location":"cookbook/05-voice/#Capture-and-Transcribe-Loop","page":"Voice","text":"This is a conceptual pattern for capturing voice data per user (SSRC):\n\n# Per-user audio buffers\nconst audio_buffers = Dict{UInt32, Vector{Int16}}()  # SSRC → PCM samples\nconst decoders = Dict{UInt32, OpusDecoder}()\nconst silence_counters = Dict{UInt32, Int}()\n\nconst SILENCE_THRESHOLD = 50     # ~1 second of silence (50 × 20ms frames)\nconst MIN_AUDIO_FRAMES = 25      # at least 0.5s of speech\n\nfunction process_voice_packet(ssrc::UInt32, opus_data::Vector{UInt8})\n    dec = get!(decoders, ssrc) do; OpusDecoder() end\n    buf = get!(audio_buffers, ssrc) do; Int16[] end\n\n    pcm = Accord.opus_decode(dec, opus_data)\n\n    # Simple energy-based silence detection\n    energy = sum(abs.(Float64.(pcm))) / length(pcm)\n    if energy < 100.0\n        silence_counters[ssrc] = get(silence_counters, ssrc, 0) + 1\n\n        if silence_counters[ssrc] >= SILENCE_THRESHOLD && length(buf) > MIN_AUDIO_FRAMES * 960 * 2\n            # Silence detected after speech — transcribe\n            wav = pcm_to_wav(buf)\n            audio_buffers[ssrc] = Int16[]\n            silence_counters[ssrc] = 0\n\n            @async begin\n                try\n                    text = transcribe_audio(wav)\n                    if !isempty(strip(text))\n                        create_message(client, text_channel_id;\n                            content=\"**SSRC $ssrc**: $text\")\n                    end\n                catch e\n                    @error \"Transcription failed\" exception=e\n                end\n            end\n            return\n        end\n    else\n        silence_counters[ssrc] = 0\n    end\n\n    append!(buf, pcm)\n    audio_buffers[ssrc] = buf\nend","title":"Capture and Transcribe Loop"},{"category":"section","location":"cookbook/05-voice/#7.-Slash-Commands-for-Voice","page":"Voice","text":"tree = CommandTree()\n\nregister_command!(tree, \"join\", \"Join your voice channel\", function(ctx)\n    Accord.defer(ctx)\n\n    guild_id = ctx.interaction.guild_id\n    user_id = ctx.interaction.member.user.id\n\n    # Find user's voice channel from state\n    guild_vs = get(ctx.client.state.voice_states, guild_id, nothing)\n    if isnothing(guild_vs)\n        Accord.respond(ctx; content=\"You're not in a voice channel!\")\n        return\n    end\n    vs = get(guild_vs, user_id, nothing)\n    if isnothing(vs) || isnothing(vs.channel_id)\n        Accord.respond(ctx; content=\"You're not in a voice channel!\")\n        return\n    end\n\n    vc = VoiceClient(ctx.client, guild_id, vs.channel_id)\n    Accord.connect!(vc)\n    Accord.respond(ctx; content=\"Joined <#$(vs.channel_id)>!\")\nend)\n\nregister_command!(tree, \"leave\", \"Leave voice channel\", function(ctx)\n    # Assumes you store the VoiceClient somewhere accessible\n    Accord.disconnect!(vc)\n    Accord.respond(ctx; content=\"Disconnected from voice.\")\nend)\n\nregister_command!(tree, \"play\", \"Play audio\", function(ctx)\n    url = Accord.get_option(ctx, \"url\", \"\")\n    Accord.defer(ctx)\n\n    source = FFmpegSource(url)\n    Accord.play!(vc, source)\n    Accord.respond(ctx; content=\"Now playing!\")\nend; options=[\n    Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"url\", description=\"Audio URL or path\", required=true),\n])\n\nregister_command!(tree, \"stop\", \"Stop playback\", function(ctx)\n    Accord.stop!(vc)\n    Accord.respond(ctx; content=\"Playback stopped.\")\nend)\n\n\n\nNext steps: Recipe 06 — Permissions to add permission checks to your commands.","title":"7. Slash Commands for Voice"},{"category":"section","location":"cookbook/08-sharding/#Recipe-08-—-Sharding","page":"Sharding","text":"Difficulty: Advanced What you will build: Multi-shard bots for scaling beyond 2,500 guilds.\n\nPrerequisites: Recipe 01, Recipe 07\n\n","title":"Recipe 08 — Sharding"},{"category":"section","location":"cookbook/08-sharding/#1.-When-Do-You-Need-Sharding?","page":"Sharding","text":"note: Discord's 2500-Guild Shard Requirement\nDiscord requires sharding when your bot joins 2,500 or more guilds. Each shard handles a subset of guilds. Without sharding, your bot will receive gateway close code 4011 (\"Sharding required\") and cannot connect.\n\nDiscord requires sharding when your bot joins 2,500+ guilds. Each shard handles a subset of guilds:\n\nShard 0: guilds where (guild_id >> 22) % num_shards == 0\nShard 1: guilds where (guild_id >> 22) % num_shards == 1\n...","title":"1. When Do You Need Sharding?"},{"category":"section","location":"cookbook/08-sharding/#2.-Basic-Sharding-Setup","page":"Sharding","text":"using Accord\n\ntoken = ENV[\"DISCORD_TOKEN\"]\n\n# 4 shards\nclient = Client(token;\n    intents = IntentGuilds | IntentGuildMessages | IntentMessageContent,\n    num_shards = 4,\n)\n\nAccord.on(client, [`ReadyEvent`](@ref)) do c, event\n    shard_info = ismissing(event.shard) ? \"N/A\" : \"$(event.shard[1])/$(event.shard[2])\"\n    @info \"Shard ready!\" shard=shard_info guilds=length(event.guilds)\nend\n\nAccord.on(client, [`MessageCreate`](@ref)) do c, event\n    msg = event.message\n    ismissing(msg.content) && return\n    msg.content == \"!ping\" && create_message(c, msg.channel_id; content=\"Pong!\")\nend\n\nAccord.start(client)\n\nAccord.jl starts shards with a 5-second delay between them (Discord's required rate limit).\n\nwarning: Shard Count is Immutable After Connection\nThe number of shards (num_shards) cannot be changed while the bot is running. To change shard count, you must restart the bot. Plan your shard count based on current guild count plus expected growth.","title":"2. Basic Sharding Setup"},{"category":"section","location":"cookbook/08-sharding/#3.-How-Shards-Work-Internally","page":"Sharding","text":"struct ShardInfo\n    id::Int          # 0-indexed shard ID\n    total::Int       # total number of shards\n    task::[`Task`](@ref)        # the async gateway connection task\n    session::[`GatewaySession`](@ref)\n    events::Channel{[`AbstractEvent`](@ref)}   # shared across all shards\n    commands::Channel{[`GatewayCommand`](@ref)}\n    ready::Base.Event\nend\n\nKey design:\n\nAll shards share a single events channel — your handlers see events from all shards\nThe Client routes gateway commands (voice state, presence) to the correct shard automatically\nShard assignment: shard_for_guild(guild_id, num_shards) uses (guild_id >> 22) % num_shards","title":"3. How Shards Work Internally"},{"category":"section","location":"cookbook/08-sharding/#4.-Auto-Detecting-Shard-Count","page":"Sharding","text":"Discord's /gateway/bot endpoint tells you the recommended shard count:\n\ninfo = get_gateway_bot(\"Bot $token\")\n\nprintln(\"Gateway URL: \", info.url)\nprintln(\"Recommended shards: \", info.shards)\nprintln(\"Session start limit: \", info.session_start_limit)\n\n# Use the recommended count\nclient = Client(token; num_shards=info.shards)\n\nThe session_start_limit tells you how many session starts you have left (resets daily). This is important because each shard start costs one session.","title":"4. Auto-Detecting Shard Count"},{"category":"section","location":"cookbook/08-sharding/#5.-Shard-Aware-Operations","page":"Sharding","text":"The Client automatically routes to the correct shard:\n\n# This sends VOICE_STATE_UPDATE to the shard handling this guild\nupdate_voice_state(client, guild_id; channel_id=voice_channel_id)\n\n# This sends to ALL shards (presence is global)\nupdate_presence(client; status=\"online\", activities=[\n    Dict(\"name\" => \"with $(client.num_shards) shards\", \"type\" => ActivityTypes.GAME)\n])\n\n# This routes to the correct shard\nrequest_guild_members(client, guild_id; query=\"\", limit=100)\n\nThe routing formula:\n\nshard_id = shard_for_guild(guild_id, client.num_shards)\nshard = client.shards[shard_id + 1]  # 1-indexed Julia array","title":"5. Shard-Aware Operations"},{"category":"section","location":"cookbook/08-sharding/#6.-Multi-Process-Sharding","page":"Sharding","text":"For very large bots (50k+ guilds), you may want separate Julia processes per shard cluster. Here's a pattern:","title":"6. Multi-Process Sharding"},{"category":"section","location":"cookbook/08-sharding/#Launcher-Script","page":"Sharding","text":"# launcher.jl — starts one process per shard cluster\nusing Distributed\n\ninfo = get_gateway_bot(\"Bot $(ENV[\"DISCORD_TOKEN\"])\")\ntotal_shards = info.shards\nshards_per_process = 4\n\nfor cluster_start in 0:shards_per_process:(total_shards - 1)\n    cluster_end = min(cluster_start + shards_per_process - 1, total_shards - 1)\n    shard_ids = cluster_start:cluster_end\n\n    @info \"Launching cluster\" shards=shard_ids\n    run(`julia --project=. shard_worker.jl\n        --total-shards=$total_shards\n        --shard-start=$cluster_start\n        --shard-end=$cluster_end`; wait=false)\nend","title":"Launcher Script"},{"category":"section","location":"cookbook/08-sharding/#Shard-Worker","page":"Sharding","text":"# shard_worker.jl — runs a subset of shards\nusing Accord\n\ntotal = parse(Int, ARGS[findfirst(a -> a == \"--total-shards\", ARGS) + 1])\nshard_start = parse(Int, ARGS[findfirst(a -> a == \"--shard-start\", ARGS) + 1])\nshard_end = parse(Int, ARGS[findfirst(a -> a == \"--shard-end\", ARGS) + 1])\nnum_local = shard_end - shard_start + 1\n\n@info \"Worker starting\" shards=\"$shard_start-$shard_end\" total=total\n\nclient = Client(ENV[\"DISCORD_TOKEN\"];\n    intents = IntentGuilds | IntentGuildMessages,\n    num_shards = total,\n    # Only connect the shards assigned to this process\n    # (requires custom shard range support)\n)\n\n# Register handlers...\nAccord.start(client)","title":"Shard Worker"},{"category":"section","location":"cookbook/08-sharding/#7.-Monitoring-Shard-Health","page":"Sharding","text":"function shard_status(client)\n    for shard in client.shards\n        status = if isnothing(shard.task)\n            \"not started\"\n        elseif istaskdone(shard.task)\n            istaskfailed(shard.task) ? \"failed\" : \"stopped\"\n        else\n            \"running\"\n        end\n        @info \"Shard $(shard.id)/$(shard.total)\" status=status session_connected=shard.session.connected\n    end\nend\n\n# Call periodically\nAccord.on(client, ReadyEvent) do c, event\n    @async begin\n        while c.running\n            sleep(60)\n            shard_status(c)\n        end\n    end\nend","title":"7. Monitoring Shard Health"},{"category":"section","location":"cookbook/08-sharding/#8.-Guild-Count-Across-Shards","page":"Sharding","text":"Accord.on(client, MessageCreate) do c, event\n    msg = event.message\n    ismissing(msg.content) && return\n\n    if msg.content == \"!guilds\"\n        total = length(c.state.guilds)\n        create_message(c, msg.channel_id;\n            content=\"I'm in **$total** guilds across **$(c.num_shards)** shards.\")\n    end\nend\n\n\n\nNext steps: Recipe 09 — Auto-Moderation or Recipe 11 — Architectural Patterns for production structure.","title":"8. Guild Count Across Shards"},{"category":"section","location":"cookbook/03-slash-commands/#Recipe-03-—-Slash-Commands","page":"Slash Commands","text":"Difficulty: Intermediate What you will build: Slash commands with options, autocomplete, subcommands, deferred responses, and followup messages.\n\nPrerequisites: Recipe 01\n\n","title":"Recipe 03 — Slash Commands"},{"category":"section","location":"cookbook/03-slash-commands/#1.-How-Slash-Commands-Work-in-Accord.jl","page":"Slash Commands","text":"The interaction flow:\n\nYou create a CommandTree and register commands on it\nOn ReadyEvent, call sync_commands! to push definitions to Discord\nOn InteractionCreate, call dispatch_interaction! to route to handlers\nEach handler receives an InteractionContext with helper methods","title":"1. How Slash Commands Work in Accord.jl"},{"category":"section","location":"cookbook/03-slash-commands/#2.-Basic-Slash-Command","page":"Slash Commands","text":"using Accord\n\ntoken = ENV[\"DISCORD_TOKEN\"]\nclient = Client(token; intents=IntentGuilds)\n\n# Register a simple command using the macro\n@slash_command client \"hello\" \"Say hello!\" function(ctx)\n    Accord.respond(ctx; content=\"Hello, <@$(ctx.interaction.member.user.id)>!\")\nend\n\n# Sync commands when ready\nAccord.on(client, ReadyEvent) do c, event\n    @info \"Bot ready, syncing commands...\"\n    sync_commands!(c, c.command_tree)\nend\n\nAccord.start(client)\n\nNote that Client automatically handles interaction dispatch to its internal command_tree.","title":"2. Basic Slash Command"},{"category":"section","location":"cookbook/03-slash-commands/#3.-Commands-with-Options","page":"Slash Commands","text":"Use command_option() to define typed parameters:\n\noptions = [\n    Accord.command_option(\n        type=ApplicationCommandOptionTypes.STRING,\n        name=\"name\",\n        description=\"Who to greet\",\n        required=true,\n    ),\n    Accord.command_option(\n        type=ApplicationCommandOptionTypes.INTEGER,\n        name=\"times\",\n        description=\"How many times to greet\",\n        required=false,\n        min_value=1,\n        max_value=5,\n    ),\n]\n\n@slash_command client \"greet\" \"Greet someone\" options function(ctx)\n    name = Accord.get_option(ctx, \"name\", \"World\")\n    times = Accord.get_option(ctx, \"times\", 1)\n    greeting = join(fill(\"Hello, $name!\", times), \"\\n\")\n    Accord.respond(ctx; content=greeting)\nend","title":"3. Commands with Options"},{"category":"section","location":"cookbook/03-slash-commands/#Option-Type-Reference","page":"Slash Commands","text":"Constant Value Julia type returned\nApplicationCommandOptionTypes.STRING 3 String\nApplicationCommandOptionTypes.INTEGER 4 Int\nApplicationCommandOptionTypes.BOOLEAN 5 Bool\nApplicationCommandOptionTypes.USER 6 Snowflake string\nApplicationCommandOptionTypes.CHANNEL 7 Snowflake string\nApplicationCommandOptionTypes.ROLE 8 Snowflake string\nApplicationCommandOptionTypes.MENTIONABLE 9 Snowflake string\nApplicationCommandOptionTypes.NUMBER 10 Float64\nApplicationCommandOptionTypes.ATTACHMENT 11 Attachment ID","title":"Option Type Reference"},{"category":"section","location":"cookbook/03-slash-commands/#4.-Static-Choices","page":"Slash Commands","text":"options = [\n    Accord.command_option(\n        type=ApplicationCommandOptionTypes.STRING,\n        name=\"color\",\n        description=\"Pick a color\",\n        required=true,\n        choices=[\n            Dict(\"name\" => \"Red\", \"value\" => \"red\"),\n            Dict(\"name\" => \"Green\", \"value\" => \"green\"),\n            Dict(\"name\" => \"Blue\", \"value\" => \"blue\"),\n        ]\n    ),\n]\n\n@slash_command client \"color\" \"Pick a color\" options function(ctx)\n    color = Accord.get_option(ctx, \"color\", \"red\")\n    hex = Dict(\"red\" => 0xED4245, \"green\" => 0x57F287, \"blue\" => 0x5865F2)[color]\n    e = Accord.embed(title=\"You picked $color!\", color=hex)\n    Accord.respond(ctx; embeds=[e])\nend","title":"4. Static Choices"},{"category":"section","location":"cookbook/03-slash-commands/#5.-Autocomplete","page":"Slash Commands","text":"For dynamic suggestions, mark an option as autocomplete=true and register an autocomplete handler:\n\nconst FRUITS = [\"apple\", \"apricot\", \"avocado\", \"banana\", \"blueberry\",\n                \"cherry\", \"coconut\", \"dragonfruit\", \"fig\", \"grape\",\n                \"kiwi\", \"lemon\", \"mango\", \"orange\", \"papaya\",\n                \"peach\", \"pear\", \"pineapple\", \"raspberry\", \"strawberry\"]\n\noptions = [\n    Accord.command_option(\n        type=ApplicationCommandOptionTypes.STRING,\n        name=\"fruit\",\n        description=\"Pick a fruit\",\n        required=true,\n        autocomplete=true,\n    ),\n]\n\n@slash_command client \"fruit\" \"Search for a fruit\" options function(ctx)\n    fruit = Accord.get_option(ctx, \"fruit\", \"\")\n    Accord.respond(ctx; content=\"You picked: **$fruit**\")\nend\n\n@autocomplete client \"fruit\" function(ctx)\n    query = lowercase(Accord.get_option(ctx, \"fruit\", \"\"))\n    matches = filter(f -> startswith(f, query), FRUITS)\n    choices = [Dict(\"name\" => f, \"value\" => f) for f in first(matches, 25)]\n\n    body = Dict(\n        \"type\" => InteractionCallbackTypes.APPLICATION_COMMAND_AUTOCOMPLETE_RESULT,\n        \"data\" => Dict(\"choices\" => choices)\n    )\n    Accord.create_interaction_response(ctx.client, ctx.interaction.id, ctx.interaction.token;\n        body)\nend","title":"5. Autocomplete"},{"category":"section","location":"cookbook/03-slash-commands/#6.-Subcommands-and-Subcommand-Groups","page":"Slash Commands","text":"Subcommands are options of type SUB_COMMAND:\n\noptions = [\n    Accord.command_option(\n        type=ApplicationCommandOptionTypes.SUB_COMMAND,\n        name=\"add\",\n        description=\"Add a tag\",\n        options=[\n            Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"name\", description=\"Tag name\", required=true),\n            Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"content\", description=\"Tag content\", required=true),\n        ]\n    ),\n    Accord.command_option(\n        type=ApplicationCommandOptionTypes.SUB_COMMAND,\n        name=\"get\",\n        description=\"Get a tag\",\n        options=[\n            Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"name\", description=\"Tag name\", required=true),\n        ]\n    ),\n]\n\n# In-memory tag storage\nconst tags = Dict{String, String}()\n\n@slash_command client \"tag\" \"Manage tags\" options function(ctx)\n    data = ctx.interaction.data\n    ismissing(data) && return\n    ismissing(data.options) && return\n\n    sub = data.options[1]\n    sub_opts = Dict{String, Any}()\n    if !ismissing(sub.options)\n        for opt in sub.options\n            !ismissing(opt.value) && (sub_opts[opt.name] = opt.value)\n        end\n    end\n\n    if sub.name == \"add\"\n        tags[sub_opts[\"name\"]] = sub_opts[\"content\"]\n        Accord.respond(ctx; content=\"Tag **$(sub_opts[\"name\"])** created!\", ephemeral=true)\n    elseif sub.name == \"get\"\n        name = sub_opts[\"name\"]\n        content = get(tags, name, nothing)\n        if isnothing(content)\n            Accord.respond(ctx; content=\"Tag **$name** not found.\", ephemeral=true)\n        else\n            Accord.respond(ctx; content=content)\n        end\n    end\nend","title":"6. Subcommands and Subcommand Groups"},{"category":"section","location":"cookbook/03-slash-commands/#7.-Guild-vs-Global-Commands","page":"Slash Commands","text":"note: Command Sync Delay\nGlobal commands take up to 1 hour to propagate across all Discord servers. If you update a global command, users may see the old version for a while.\n\n# Global commands — available everywhere, up to 1 hour to propagate\n@slash_command client \"ping\" \"Check latency\" function(ctx)\n    Accord.respond(ctx; content=\"Pong!\")\nend\n\ntip: Use Guild Commands During Development\nGuild commands update instantly (within a few seconds). During development, sync commands to a specific guild for rapid iteration:\n\n# Guild command — instant, only in one server\nGUILD_ID = 123456789012345678\n@slash_command client GUILD_ID \"debug\" \"Debug info\" function(ctx)\n    Accord.respond(ctx; content=\"Debug mode active\", ephemeral=true)\nend\n\n# Or sync everything to a specific guild for development\nAccord.on(client, [`ReadyEvent`](@ref)) do c, event\n    sync_commands!(c, c.command_tree; guild_id=[`Snowflake`](@ref)(GUILD_ID))  # instant during dev\nend","title":"7. Guild vs Global Commands"},{"category":"section","location":"cookbook/03-slash-commands/#8.-Deferred-Responses","page":"Slash Commands","text":"If your command takes more than 3 seconds, defer first:\n\n@slash_command client \"slow\" \"A slow operation\" function(ctx)\n    Accord.defer(ctx)  # shows \"Bot is thinking...\"\n\n    # Do expensive work\n    sleep(5)\n    result = \"Done after 5 seconds!\"\n\n    # Edit the deferred response\n    Accord.respond(ctx; content=result)\nend","title":"8. Deferred Responses"},{"category":"section","location":"cookbook/03-slash-commands/#Ephemeral-Deferred-Response","page":"Slash Commands","text":"@slash_command client \"secret\" \"Private slow operation\" function(ctx)\n    Accord.defer(ctx; ephemeral=true)  # only visible to the user\n\n    sleep(3)\n    Accord.respond(ctx; content=\"Secret result!\")\nend","title":"Ephemeral Deferred Response"},{"category":"section","location":"cookbook/03-slash-commands/#9.-Followup-Messages","page":"Slash Commands","text":"Send additional messages after the initial response:\n\n@slash_command client \"multi\" \"Multiple responses\" function(ctx)\n    Accord.respond(ctx; content=\"First response!\")\n\n    sleep(1)\n    Accord.followup(ctx; content=\"Here's a followup!\")\n\n    sleep(1)\n    Accord.followup(ctx; content=\"And another one!\", ephemeral=true)\nend","title":"9. Followup Messages"},{"category":"section","location":"cookbook/03-slash-commands/#10.-Edit-the-Original-Response","page":"Slash Commands","text":"@slash_command client \"countdown\" \"Countdown timer\" function(ctx)\n    Accord.defer(ctx)\n\n    for i in 3:-1:1\n        edit_response(ctx; content=\"**$i**...\")\n        sleep(1)\n    end\n\n    edit_response(ctx; content=\"**Go!**\")\nend\n\n","title":"10. Edit the Original Response"},{"category":"section","location":"cookbook/03-slash-commands/#Complete-Example","page":"Slash Commands","text":"using Accord\n\ntoken = ENV[\"DISCORD_TOKEN\"]\nclient = Client(token; intents=IntentGuilds)\n\n# Simple command\n@slash_command client \"ping\" \"Check bot latency\" function(ctx)\n    t = time()\n    Accord.defer(ctx)\n    ms = round(Int, (time() - t) * 1000)\n    Accord.respond(ctx; content=\"Pong! API latency: **$(ms) ms**\")\nend\n\n# Command with options\noptions = [\n    Accord.command_option(type=ApplicationCommandOptionTypes.STRING, name=\"text\", description=\"Text to echo\", required=true),\n    Accord.command_option(type=ApplicationCommandOptionTypes.BOOLEAN, name=\"ephemeral\", description=\"Only visible to you?\"),\n]\n\n@slash_command client \"echo\" \"Echo a message\" options function(ctx)\n    text = Accord.get_option(ctx, \"text\", \"\")\n    eph = Accord.get_option(ctx, \"ephemeral\", false)\n    Accord.respond(ctx; content=text, ephemeral=eph)\nend\n\nAccord.on(client, ReadyEvent) do c, event\n    @info \"Syncing commands...\"\n    sync_commands!(c, c.command_tree)\n    @info \"Bot ready!\"\nend\n\nAccord.start(client)\n\n\n\nNext steps: Recipe 04 — Buttons, Selects & Modals to add interactive components to your messages.","title":"Complete Example"}]
}
